window.__D("text/kuntres-umaayan/c000",{"p":[[4401900030,"<h2>מַאֲמָר א.</h2>\nוּמַעְיָן מִבֵּית ד' יֵצֵא וְהִשְׁקָה אֶת נַחַל הַשִּׁטִּים (יוֹאֵל ד. יח) הִנֵּה בְּמִדְרָשׁ רַבָּה (בָּלָק פַּרְשָׁה כ) מְפָרֵשׁ שִׁטִּים לְשׁוֹן שְׁטוּת.\n<b>דְּהִנֵּה</b> בְּסֵפֶר הַשָּׁרָשִׁים בְּשֹׁרֶשׁ שִׁטָּה פֵּירֵשׁ שִׁטִּים מִלְּשׁוֹן הַטָּיָה וּכְמוֹ כִּי תִשְׂטֶה אִשְׁתּוֹ פֵּירֵשׁ רַשִׁ''י כִּי תִשְׂטֶה תֵּט מִדַּרְכֵי הַצְּנִיעוּת. וְהַתַּרְגּוּם עַל וַיֵּט אֵלֶיהָ (בְּרֵאשִׁית לח. טז) וּסְטָא לְוָותַהּ\nוְעַל שֵׁם זֶה נִקְרָא הַיֵּצֶר הָרָע שָׂטָן עַל שֵׁם שֶׁמַּשְׂטֶה וּמַטֶּה אֶת הָאָדָם מִדֶּרֶךְ הַטּוֹב וְאַחַר כַּךְ מַשְׂטִין לְמַעְלָה וְנוֹטֶה אֶל הַקִּטְרוּג.\n<b>וְזֶהוּ</b> גַם כֵּן מַה שֶּׁמְּפָרֵשׁ בַּמִּדְרָשׁ שִׁטִּים לְשׁוֹן שְׁטוּת כִּי עִנְיַן הַשְּׁטוּת הוּא הַהַטָּיָה מִדֶּרֶךְ הָאֱמֶת וְכֵן מָצִינוּ בְּדִבְרֵי רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה שֶׁחִבְּרוּ ב' עִנְיָנִים אֵלּוּ, וְכִדְאִיתָא בִּגְמָרָא (סוֹטָה ג. א) עַל פָּסוּק כִּי תִשְׂטֶה אִשְׁתּוֹ אֵין אָדָם עוֹבֵר עֲבֵירָה אֶלָּא אִם כֵּן נִכְנַס בּוֹ רוּחַ שְׁטוּת, הֲרֵי שֶׁהַשִּׁטָּה וּשְׁטוּת הוּא עִנְיָן אֶחָד, שֶׁהוּא הַהַטָּיָה מִדֶּרֶךְ הָאֱמֶת וְדֶרֶךְ הַטּוֹב (וְעַיֵּן מַה שֶּׁכָּתוּב בְּמַהַרְשָׁ\"א בְּחִדּוּשֵׁי אַגָּדוֹת עַל מַאֲמָר הַנִּזְכָּר לְעֵיל).\n<b>וְהָעִנְיָן</b> הוּא דְּהִנֵּה מַה שֶּׁהָאָדָם בָּא לַעֲבוֹר עַל דַּרְכֵי הַתּוֹרָה וּלְהִמָּשֵׁךְ אַחֲרֵי תַּאֲווֹת לִבּוֹ לְהִתְעַנֵּג בְּתַעֲנוּגֵי בְּנֵי אָדָם (אֲפִילוּ בִּדְבָרִים הַמּוּתָּרִים, כַּאֲשֶׁר מְעַנֵּג נַפְשׁוֹ בְּתַעֲנוּגֵי וְתַפְנוּקֵי בְּנֵי אָדָם יוֹתֵר מִמַּה שֶּׁמּוּכְרָח לוֹ לְצוֹרֶךְ קִיּוּם גּוּפוֹ, הֲרֵי זֶה גַּם כֵּן הַעֲבָרָה עַל דַּרְכֵי הַתּוֹרָה שֶׁמְּחוּיָּיב כָּל אֶחָד וְאֶחָד לְקַדֵּשׁ אֶת עַצְמוֹ בְּמוּתָּר לוֹ, כְּמוֹ שֶׁכָּתַב הַחִנּוּךְ שֶׁהוּא מִצְוַת עֲשֵׂה דְּאוֹרַיְיתָא וְכֵן הִסְכִּים בְּסֵפֶר שֶׁל בֵּינוֹנִים (פֶּרֶק למ\"ד),\nוְלֹא הוּתַּר רַק מַה שֶּׁהוּא לְצוֹרֶךְ קִיּוּם גּוּפוֹ, וְגַם זֶה לֹא יִרְצֶה בְּהַתַּעֲנוּג גַּשְׁמִי שֶׁבְּהַמַּאֲכָל עַל דֶּרֶךְ מָשָׁל, כִּי אִם בִּכְדֵי שֶׁיּוּכַל לַעֲבוֹד אֶת בּוֹרְאוֹ בְּכֹחַ הָאֲכִילָה הַהִיא, וְכֵן בְּכָל דָּבָר צָרִיךְ לִהְיוֹת כַּוָּונָה לְשֵׁם שָׁמַיִם, אֲבָל כְּשֶׁמְּכַוֵּון לְהַנָּאַת וְתַעֲנוּג נַפְשׁוֹ וְכָל שֶׁכֵּן מַה שֶּׁהוּא לוֹ לְמוֹתָר וְרַק לְעִידּוּן וּלְתַעֲנוּג, הִנֵּה כְּשֶׁנִּמְשָׁךְ אַחַר זֶה הֲרֵי זֶה הַעֲבָרָה עַל דַּרְכֵי הַתּוֹרָה, וְהוּא רַע גָּמוּר לְפִי שָׁעָה כו' כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר שֶׁל בֵּינוֹנִים (חֵלֶק א פֶּרֶק ז),\nוְסִיבַּת הַהַמְשָׁכָה אַחֲרֵי הַתַּאֲווֹת וְתַעֲנוּגִים גַּשְׁמִים) הוּא עַל יְדֵי הֲסָתַת הַיֵּצֶר הָרָע לוֹמַר לוֹ כִּי טוֹב לְפָנָיו דָּבָר זֶה וְכִי תַאֲוָה הוּא לָעֵינַיִם, וּכְמוֹ שֶׁכָּתוּב בְּחֵטְא עֵץ הַדַּעַת (בְּרֵאשִׁית ג. ו) וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְכִי תַאֲוָה הוּא לָעֵינַיִם כו' וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל וַתִּתֵּן גַּם לְאִישָׁהּ עִמָּהּ וַיֹּאכַל.\nקִיצּוּר.\nשִׁטִּים שָׁרְשׁוֹ שִׁטָּה, וּבוֹ שְׁנֵי פֵירוּשִׁים א) הַטָּיָה ב) שְׁטוּת. הַתַּעֲנוּג גַּם בִּדְבָרִים הַמּוּתָּרִים הוּא הַעֲבָרָה עַל דַּרְכֵי הַתּוֹרָה, הַבָּאָה בְּסִבַּת הַיֵּצֶר הָרָע שֶׁמַּטֶּה אֶת הָאָדָם מִדֶּרֶךְ הָאֱמֶת וְגַם עוֹלֶה וּמְקַטְרֵג וְהוּא הַשָּׂטָן."],[4401900031,"וּבֶאֱמֶת הוּא שְׁטוּת נוֹרָא וְכִי זֶהוּ הַטּוֹב אֲשֶׁר אֵלָיו יִמְשׁוֹךְ הָאָדָם בְּחִיר הַנִּבְרָאִים, כִּי הִנֵּה יֵשׁ כַּמָּה מִינֵי תַעֲנוּגִים, וּכְמוֹ הַתַּעֲנוּג בְּמַאֲכָל עָרֵב וּמָתוֹק לַחֵיךְ שֶׁזֶּהוּ תַּעֲנוּג הַיּוֹתֵר שָׁפָל וּפָחוּת, וּכְמוֹ בְּדֶרֶךְ כְּלָל הַתַּעֲנוּג בְּעִנְיָנִים גַּשְׁמִים וְגוּפְנִיִּים שֶׁזֶּהוּ תַּעֲנוּג בַּהֲמִי מַמָּשׁ, שֶׁהַבְּהֵמָה נִמְשֶׁכֶת אַחֲרֵי דְּבָרִים הַטּוֹבִים וְהָעֲרֵבִים לְפִי טִבְעָהּ וְאֵינָהּ יוֹדַעַת מִטּוֹב אַחֵר כִּי אִם מֵהַטּוֹב הַזֶּה וְאַחֲרָיו הִיא נִמְשֶׁכֶת,\nוּלְמַעְלָה מִזֶּה הוּא כְּמוֹ הַתַּעֲנוּג בְּקוֹל עָרֵב שֶׁהוּא תַּעֲנוּג רוּחָנִי יוֹתֵר, וּלְמַעְלָה מִזֶּה הוּא הַתַּעֲנוּג בְּעִנְיָנֵי הַמִּדּוֹת, וּכְמוֹ בְּמִדַּת הַטּוֹב וְהַחֶסֶד שֶׁעוֹשֶׂה עִם זוּלָתוֹ שֶׁיֵּשׁ בָּזֶה תַּעֲנוּג נִפְלָא לְהָאִישׁ הַטּוֹב. וְהִנֵּה יֵשׁ בָּזֶה גַּם כֵּן מַדְרֵיגוֹת שֶׁאִם הַטּוֹב שֶׁלּוֹ הוּא רַק מִצַּד הַטִּבְעִי לְבָד בְּלִי הַבְחָנַת הַשֵּׂכֶל, וְהַיְינוּ שֶׁעוֹשֶׂה טוֹב וָחֶסֶד עִם כָּל הַבָּא לְיָדוֹ בְּלִי הַבְחָנָה בֵּין טוֹב לָרַע, וּבְלִי שׁוּם כַּוָּונָה פְנִימִית בַּעֲשִׂיַּית הַטּוֹב אִתּוֹ הֲרֵי הַתַּעֲנוּג בָּזֶה הוּא גַם כֵּן תַּעֲנוּג בַּהֲמִי שֶׁהוּא הִתְגַּבְּרוּת הָאַהֲבָה הַטִּבְעִית, וּכְיָדוּעַ שֶׁהַבְּהֵמָה עִיקָּרָהּ הוּא בִּבְחִינַת הַמִּדּוֹת לְבָד וְאֵין לָהּ דַּעַת כְּלָל, וְכַאֲשֶׁר הָאָדָם מִתְנַהֵג וּמִתְעַנֵּג בִּפְעוּלַּת הַמִּדּוֹת לְבָד בְּלִי הַנְהָגַת הַשֵּׂכֶל, הֲרֵי הוּא כַּבְּהֵמָה, כִּי אִם כָּל מִדַּת בְּנֵי אָדָם צָרִיךְ לִהְיוֹת עַל פִּי הַשֵּׂכֶל,\nוּכְמוֹ בְּמִדַּת הַחֶסֶד לְהַבְחִין בֵּין טוֹב לָרַע. וְלִפְעָמִים צְרִיכִים לְהַשְׁפִּיעַ חֶסֶד גַּם לְמִי שֶׁאֵינוֹ רָאוּי, אַךְ בִּשְׁבִיל הַכַּוָּונָה וְהַתּוֹעֶלֶת שֶׁיִּהְיֶה מִזֶּה, וּכְמוֹ אַבְרָהָם אָבִינוּ עָלָיו הַשָּׁלוֹם שֶׁהָיָה מַאֲכִיל וּמַשְׁקֶה גַּם לְעַרְבִיִּים, וְהָיָה הַכַּוָּונָה בִּכְדֵי לְהוֹדִיעַ אֱלֹקוּתוֹ יִתְבָּרֵךְ בָּעוֹלָם וּלְקָרֵב אֶת הַבְּרִיּוֹת לֵאלֹקוּת. וְכִדְאִיתָא בִּגְמָרָא (סוֹטָה י. סוֹף עַמּוּד א) עַל פָּסוּק וַיִּקְרָא שָׁם בְּשֵׁם ה' אֵל עוֹלָם אָמַר רֵישׁ לָקִישׁ אַל תִּקְרֵי וַיִּקְרָא אֶלָּא וַיַּקְרִיא (לִמֵּד לַבְּרִיּוֹת לִקְרוֹא שָׁם בְּשֵׁם ה' אֵל עוֹלָם. רַשִׁ\"י) שֶׁהִקְרִיא אַבְרָהָם אָבִינוּ לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּפִי כָּל עוֹבֵר וְשָׁב כֵּיצַד לְאַחַר שֶׁאָכְלוּ וְשָׁתוּ עָמְדוּ לְבָרְכוֹ (לְאַבְרָהָם) אָמַר לָהֶם וְכִי מִשֶּׁלִּי אֲכַלְתֶּם מִשֶּׁל אֱלֹקֵי עוֹלָם אֲכַלְתֶּם הוֹדוּ וְשַׁבְּחוּ וּבָרְכוּ לְמִי שֶׁאָמַר וְהָיָה הָעוֹלָם,\nוְזֶה הָיָה תַּכְלִית כַּוָּונַת הַחֶסֶד לֹא מִצַּד הַחֶסֶד הַטִּבְעִי כִּי אִם בִּכְדֵי לְקָרֵב עַל יְדֵי זֶה אֶת הַבְּרִיּוֹת לֵאלֹקוּת,\nוּבְמִדְרָשׁ רַבָּה (וַיֵּרָא פַּרְשָׁה מ\"ט) אִיתָא אַבְרָהָם הָיָה מְקַבֵּל אֶת הָעוֹבְרִים וְאֶת הַשָּׁבִים מִשֶּׁהָיוּ אוֹכְלִים וְשׁוֹתִים אָמַר לָהֶם בָּרְכוּ אָמְרוּ לוֹ מַה נֹּאמַר אָמַר לָהֶם אִמְרוּ בָּרוּךְ אֵל עוֹלָם שֶׁאָכַלְנוּ מִשֶּׁלּוֹ, אִם מְקַבֵּל עָלָיו וּבָרִיךְ הֲוָה אָכִיל וְשָׁתֵי וְאָזִיל, וְאִי לָא הֲוָה מְקַבֵּל עֲלֵיהּ וּבָרִיךְ הֲוָה אָמַר לוֹ הַב מַה דַּעֲלָךְ וְאָמַר מָה אִית לָךְ עָלַי הֲוָה אָמַר לֵיהּ חַד קְסִיט (פֵּירֵשׁ הֶעָרוּךְ כְּלִי שֶׁל חֶרֶס אוֹ מַתָּכוֹת אוֹ מִכָּל דָּבָר, מַתְּנוֹת כְּהֻנָּה) דַּחֲמַר (יַיִן) בְּי' פּוֹלָרִין (מִין מַטְבֵּעַ, מַתְּנוֹת כְּהֻנָּה) וְחַד לִיטְרָא דְּקוֹפָר (לִיטְרָא בָּשָׂר, מַתְּנוֹת כְּהֻנָּה) בְּי' פּוֹלָרִין וְחַד עִיגּוּל דְּרִיפְתָּא (לֶחֶם, מַתְּנוֹת כְּהֻנָּה) בְּי' פּוֹלָרִין. מַאן יָהִיב לָךְ חַמְרָא בְּמַדְבְּרָא, מַאן יָהִיב לָךְ קוֹפָר בְּמַדְבְּרָא, מַאן יָהִיב לָךְ עִיגּוּלָא בְּמַדְבְּרָא (מִי נָתַן לְךָ מֵעוֹלָם בַּמִּדְבָּר בָּשָׂר וְלֶחֶם וְיַיִן, מַתְּנוֹת כְּהֻנָּה) מִן דַּהֲוָה חָמֵי הַהִיא עַקְתָא דַּהֲוָה עָקֵי לֵיהּ (מִשֶּׁהָיָה רוֹאֶה הָאוֹרֵחַ הַצָּרָה הַהִיא שֶׁהָיָה מֵיצֵר לוֹ, מַתְּנוֹת כְּהֻנָּה) הֲוָה אָמַר בָּרוּךְ אֵל עוֹלָם שֶׁאָכַלְנוּ מִשֶּׁלּוֹ.\n<b>וְכֵן</b> כָּל הַמִּדּוֹת צְרִיכִים לִהְיוֹת עַל פִּי הַנְהָגַת הַשֵּׂכֶל דַּוְקָא.\nקִיצּוּר.\nבְּתַעֲנוּגִים יֵשׁ סֵדֶר וְהַדְרָגָה זֶה לְמַעְלָה מִזֶּה, הַתַּעֲנוּג בְּמַאֲכָל עָרֵב וְהַדּוֹמֶה בְּתַעֲנוּגֵי הַגּוּף הוּא תַּעֲנוּג הַיּוֹתֵר שָׁפָל וְהוּא תַּעֲנוּג בַּהֲמִי, הַתַּעֲנוּג בְּקוֹל עָרֵב, הַתַּעֲנוּג בְּמִדּוֹת שֶׁעַל פִּי הַשֵּׂכֶל לְהֵטִיב לְהָרָאוּי וְלִפְעָמִים גַּם לְבִלְתִּי רָאוּי לְשָׁעָה מִפְּנֵי הַתּוֹעֶלֶת הַבָּאָה."],[4401900032,"וְהִנֵּה לְמַעְלָה מִכָּל הַתַּעֲנוּגִים הַנַ\"ל הוּא הַתַּעֲנוּג שֶׁבְּשֵׂכֶל וְחָכְמָה וּכְמוֹ בְּהַמְצָאַת אֵיזֶה הַשְׂכָּלָה חֲדָשָׁה שֶׁיֵּשׁ בָּזֶה תַּעֲנוּג נִפְלָא, וְכֵן בְּהַשָּׂגָה וַהֲבָנָה כְּשֶׁלּוֹמֵד אֵיזֶה עִנְיָן וּמְבִינוֹ בְּטוֹב, שֶׁיֵּשׁ בָּזֶה תַּעֲנוּג הַנֶּפֶשׁ, וְזֶהוּ הַטּוֹב וְהַתַּעֲנוּג אֲמִיתִּי וְהַנַּעֲלֶה בֶּאֱמֶת (וּבִתְנַאי שֶׁהַחָכְמָה עַצְמָהּ טוֹבָה וַאֲמִיתִּית הִיא, כִּי אִם הַחָכְמָה הִיא רַע מִצַּד עַצְמָהּ הֲרֵי הִיא מִכְּלַל הַדְּבָרִים הָאֲסוּרִים שֶׁאָסוּר לַעֲסוֹק בָּהּ) וְהָאָדָם בַּאֲשֶׁר הוּא בְּחִיר הַנִּבְרָאִים צָרִיךְ לִהְיוֹת הַטּוֹב וְהַתַּעֲנוּג שֶׁלּוֹ בְּעִנְיָינִים הָרוּחָנִים דַּוְקָא, וּבִפְרָט בְּעִנְיְנֵי הַחָכְמָה, וּבָזֶה דַוְקָא יִהְיֶה עוֹנֶג נַפְשׁוֹ כִּי זוֹהִי מַעֲלָתוֹ עַל כָּל הַנִּבְרָאִים בְּהַשֵּׂכֶל שֶׁנִּיתַּן לוֹ וְנַפְשׁוֹ הִיא נֶפֶשׁ הַמַּשְׂכֶּלֶת, וּבִפְרָט מִצַּד הַנֶּפֶשׁ הָאֱלֹקִית שֶׁבּוֹ שֶׁהִיא מִבְּחִינַת הַחָכְמָה הָעֶלְיוֹנָה כְּיָדוּעַ, וְצָרִיךְ לִהְיוֹת כָּל הַמְשָׁכַת נַפְשׁוֹ וְכָל חֶפְצוֹ וּמְגַמָּתוֹ בְּעֵסֶק חָכְמַת הַתּוֹרָה וּבָזֶה תִּתְעַנֵּג נַפְשׁוֹ וְעַל יְדֵי זֶה תִּתְעַלֶּה נַפְשׁוֹ בְּעִילּוּי הַמַּעֲלָה וְהַמַּדְרֵיגָה אֲשֶׁר לְכַךְ הוּא נִבְרָא.\n<b>דְּהִנֵּה</b> כָּל דָּבָר שֶׁנִּבְרָא בָּעוֹלָם הוּא לְצוֹרֶךְ אֵיזֶה תַּכְלִית, וְתַכְלִית כָּל דָּבָר הוּא כְּשֶׁעוֹלֶה לְמַעְלָה מִמַּדְרֵיגַת עַצְמוֹ, וּכְמוֹ תַּכְלִית הַצּוֹמֵחַ הוּא כְּשֶׁנִּכְלָל בְּחַי, וְתַכְלִית הַחַי הוּא כְּשֶׁנִּכְלָל בִּמְדַבֵּר וְתַכְלִית הַמְדַבֵּר הוּא כַּאֲשֶׁר רוּחוֹ עוֹלֶה לְמַעְלָה וְנִכְלָל בְּמַדְרֵיגוֹת הָרוּחָנִיּוֹת שֶׁלְּמַעְלָה מִמֶּנּוּ, וּכְמוֹ בְּעָסְקוֹ בַּתּוֹרָה שֶׁהִיא חָכְמָתוֹ וּרְצוֹנוֹ יִתְבָּרֵךְ וְאוֹרַיְיתָא וְקוּדְשָׁא בְּרִיךְ הוּא כּוֹלָּא חַד וְכַאֲשֶׁר הָאָדָם עוֹסֵק בַּתּוֹרָה וּמְעַיֵּין הֵיטֵב לְהָבִין הַדְּבָרִים לַאֲמִיתָּתָן הֲרֵי הוּא מִתְיַיחֵד עִם חָכְמָתוֹ וּרְצוֹנוֹ יִתְבָּרֵךְ בִּבְחִינַת יִחוּד עָצוּם, וּכְמוֹ שֶׁכָּתוּב בְּסֵפֶר שֶׁל בֵּינוֹנִים (חֵלֶק א פֶּרֶק ה).\n<b>וּבָזֶה</b> תִּתְעַלֶּה נַפְשׁוֹ שֶׁמִּתְקַשֶּׁרֶת וְנִכְלֶלֶת בְּחָכְמָתוֹ יִתְבָּרֵךְ, הֵן בְּעֵסֶק הַנִּגְלֶה דְּתוֹרָה שֶׁהִיא מַהוּת חָכְמָתוֹ וּרְצוֹנוֹ יִתְבָּרֵךְ, שֶׁכַּךְ חִיְּיבָה חָכְמָתוֹ יִתְבָּרֵךְ שֶׁזֶּה כָּשֵׁר וְזֶה פָּסוּל כו', וְכָל מַה שֶּׁתַּלְמִיד וָתִיק עָתִיד לְחַדֵּשׁ הַכֹּל נֶאֱמַר לְמֹשֶׁה מִסִּינַי וְהֵן הֵמָּה כָּל הַהֲלָכוֹת דְּתוֹרָה שֶׁבְּעַל פֶּה וְהַטְּעָמִים וְהַסְּבָרוֹת בָּהֶן הַכֹּל הוּא בְּחִינַת חָכְמָתוֹ יִתְבָּרֵךְ מַמָּשׁ, וּכְשֶׁהָאָדָם עוֹסֵק בָּהֶם הֲרֵי הוּא מִתְיַיחֵד וְנִכְלָל בָּזֶה כַּנַ\"ל,\nוְהֵן בְּעֵסֶק פְּנִימִיּוּת הַתּוֹרָה שֶׁהִיא יְדִיעַת וְהַשָּׂגַת אֱלֹקוּת שֶׁמַּה שֶּׁגִּילּוּ לָנוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בָּזֶה הוּא בְּחִינַת פְּנִימִיּוּת חָכְמָתוֹ יִתְבָּרֵךְ, וּכְשֶׁעוֹסֵק בָּזֶה הֲרֵי הוּא מִתְקַשֵּׁר בִּבְחִינַת פְּנִימִיּוּת חָכְמָתוֹ יִתְבָּרֵךְ שֶׁלְּמַעְלָה מַּעְלָה מִבְּחִינַת הַחִיצוֹנִיּוּת.\n<b>וְעוֹד</b> יֵשׁ מַעֲלָה נוֹסֶפֶת בִּידִיעָה זֹאת דִּפְנִימִיּוּת הַתּוֹרָה בִּפְעוּלָּתָהּ בַּנֶּפֶשׁ, דְּעִם הֱיוֹת שֶׁזּוֹהִי יְדִיעַת הַמְּצִיאוּת לְבָד מִכָּל מָקוֹם הֲרֵי הוּא יוֹדֵעַ וּמַשִּׂיג עַל כָּל פָּנִים בְּחִינַת מְצִיאוּת הָרוּחָנִית שֶׁנִּרְגָּשׁ בְּנַפְשׁוֹ וּמִתְקַשֵּׁר וְנִדְבָּק בָּזֶה, וְעַל יְדֵי זֶה הוּא יוֹצֵא מִגַּשְׁמִיּוּתוֹ וּבָא לְמַעֲלַת וּמַדְרֵיגַת הַדַּקּוּת וְהָרוּחָנִיּוּת, הֵן בְּנַפְשׁוֹ בְּעַצְמוֹ וְהֵן בְּכָל עִנְיָנָיו וּפְרָטֵי עֲשִׂיּוֹתָיו הַכֹּל הוּא בִּבְחִינַת הַדַּקּוּת וְהָרוּחָנִיּוּת בִּלְתִּי נִתְפָּס בְּגֶשֶׁם בְּעֶצֶם וּבְלִי הַרְגָּשַׁת עַצְמוֹ (אַז אִיטְלֶעכֶע זַאךְ, ווָאס עֶר טוּט, הֵן בְּלִימּוּד הַתּוֹרָה וְהֵן בְּעֵסֶק הַמִּצְוֹת וְעַנְפֵיהֶן אִיז דָאס אֵיידֶעל, נִיט גְרָאבּ בְּעֶצֶם אוּן נִיט מוּרְגָּשׁ, אָהן בְּלִיטוּת אוּן אָהן הַחֲזָקַת טוֹבָה לְעַצְמוֹ, וּמִכָּל שֶׁכֵּן עֶס זָאל נִיט נִיכָּר זַיְין פַאר דֶעם אַנְדֶערֶען, וּמִי יֹאמַר שֶׁיַּעֲשֶׂה בִּשְׁבִיל הַזּוּלַת) וּבְעִנְיָנִים הַגַּשְׁמִים מוּבָן בְּמִכָּל שֶׁכֵּן שֶׁנִּפְשָׁט מִגַּשְׁמִיוּתוֹ שֶׁאֵינוֹ מִתְאַוֶּוה עִנְיָנִים הַגַּשְׁמִים כְּלָל וּכְלָל וְאֵינוֹ חָפֵץ בָּהֶם כִּי אִם כָּל חֶפְצוֹ וּרְצוֹנוֹ הוּא בֵּאלֹקוּת.\nקִיצּוּר.\nהָאָדָם שֶׁהוּא בַּעַל נֶפֶשׁ מַשְׂכֶּלֶת וֵאלֹקִית צָרִיךְ לְהִתְעַנֵּג בְּחָכְמַת הַתּוֹרָה, תַּכְלִית כָּל נִבְרָא לַעֲלוֹת לְמַעְלָה מִמֶּנּוּ, וְעַל יְדֵי לִימּוּד גַלְיָא שֶׁבַּתּוֹרָה מִתְיַיחֵד בְּחָכְמָתוֹ וּרְצוֹנוֹ יִתְבָּרֵךְ, וְעַל יְדֵי עֵסֶק הַחֲסִידוּת מִתְקַשֵּׁר בִּפְנִימִיּוּתָם אוּן עֶר ווֶערְט אֵיידֶעל בְּכָל הָעִנְיָנִים."],[4401900033,"וְהִנֵּה עוֹד יִתְרוֹן בִּידִיעַת וְהַשָּׂגַת פְּנִימִיּוּת הַתּוֹרָה שֶׁעַל יְדֵי זֶה הוּא בָא לִידֵי אַהֲבָה וְיִרְאָה, שֶׁזֶּהוּ מַה שֶּׁכָּתוּב (דְּבָרִים ד. לט) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ כו' שֶׁמְּבִיאָה לְלֵב שָׁלֵם כו', וּכְמוֹ שֶׁכָּתוּב מִזֶּה בְּאִגֶּרֶת הַקֹּדֶשׁ בְּסוֹפוֹ בְּדִבּוּר הַמַּתְחִיל לְהָבִין מַה שֶּׁכָּתוּב בִּפְרִי עֵץ חַיִּים וּבְלִקּוּטֵי תוֹרָה בְּהַבֵּיאוּר דִּוְלֹא תַשְׁבִּית, וְאֵין כַּאן מָקוֹם לְהַאֲרִיךְ בָּזֶה, וְאַחַר הַטּוֹב הַזֶּה צָרִיךְ הָאָדָם לִהְיוֹת נִמְשָׁךְ, וּבָזֶה יִהְיֶה כָּל חֶפְצוֹ וּמְגַמָּתוֹ, וּבָזֶה יִהְיֶה עוֹנֶג נַפְשׁוֹ, לְפִי שֶׁהַטּוֹב הַזֶּה הוּא לְפִי מַעֲלַת מַהוּתוֹ, וּבָזֶה נִשְׁלָם הַכַּוָּונָה שֶׁבָּא אֶל הַתַּכְלִית שֶׁבִּשְׁבִילוֹ נִבְרָא,\nמַה שֶּׁאֵין כֵּן כְּשֶׁנִּמְשָׁךְ אַחֲרֵי הָעִנְיָנִים הַגַּשְׁמִים וְהַגּוּפְנִים, הֲרֵי לֹא זוֹ בִּלְבָד שֶׁלֹּא נִשְׁלַם הַכַּוָּונָה וְהַתַּכְלִית שֶׁנִּבְרָא בִּשְׁבִיל זֶה, הֲרֵי אַדְרַבָּה הוּא מוֹרִיד נַפְשׁוֹ מִמַּעֲלָתוֹ וּמַהוּתוֹ הַנַּעֲלָה וְיוֹרֵד לְמַדְרֵיגַת הַבַּעַל חַי הַגָּרוּעַ וּפָחוּת מִמֶּנּוּ בְּאֵין עֲרוֹךְ, וְהוּא בִּשְׁנֵי דְבָרִים, הָא' כְּיָדוּעַ שֶׁכָּל דָּבָר שֶׁהָאָדָם מִתְקַשֵּׁר בּוֹ הֲרֵי הוּא נַעֲשֶׂה כְּמַהוּת אוֹתוֹ הַדָּבָר וּכְשֶׁמְּקַשֵּׁר נַפְשׁוֹ וּרְצוֹנוֹ בְּדוֹמֵם אוֹ בְצוֹמֵחַ אוֹ בְחַי לְהִתְעַנֵּג מֵהֶם, הֲרֵי הוּא נַעֲשֶׂה כְּמוֹהֶם (וְעוֹד לְמַטָּה מֵהֶם שֶׁהֲרֵי הוּא מְקַבֵּל מֵהֶם, וְהוּא הַתַּעֲנוּג שֶׁמִּתְעַנֵּג מֵהֶם) וַהֲרֵי הוּא יוֹרֵד מִמַּעֲלַת הַמְדַבֵּר לְמַדְרֵיגַת הַדּוֹמֵם צוֹמֵחַ חַי, שֶׁזֶּה יְרִידָה גְדוֹלָה מְאֹד,\nוְהַב' שֶׁמִּצַּד מַעֲלָתוֹ (מַעֲלַת הַמְדַבֵּר) הֲרֵי שִׁפְלוּתוֹ הוּא בְיוֹתֵר, דְּבִירִידַת וְהַמְשָׁכַת נַפְשׁוֹ שֶׁנִּמְשָׁךְ אַחֲרֵי עִנְיָנִים פְּחוּתִים וּשְׁפָלִים, וּבָהֶם הוּא מוֹצֵא תַּעֲנוּג נַפְשׁוֹ, הֲרֵי הוּא גָרוּעַ מֵהַבְּהֵמָה שֶׁהַבְּהֵמָה אֵין לָהּ דַּעַת וְאֵינָהּ יוֹדַעַת מֵעִנְיָנִים נַעֲלִים כְּלָל, אֲבָל הָאָדָם שֶׁנִּיתַּן לוֹ שֵׂכֶל וָדַעַת כְּשֶׁעוֹשֶׂה מַעֲשֵׂה בְהֵמָה הֲרֵי הוּא גָרוּעַ מִמֶּנָּה (וּבִפְרָט לְפִי מַה שֶּׁנִּתְבָּאֵר לְעֵיל (פֶּרֶק א) דְּקַדֵּשׁ עַצְמְךָ בְּמוּתָּר לְךָ הוּא מִצְוַת עֲשֵׂה דְאוֹרַיְיתָא וּכְשֶׁעוֹשֶׂה עִנְיָנִים הַגַּשְׁמִים בִּשְׁבִיל הַנָּאָתוֹ וְתַעֲנוּג נַפְשׁוֹ הֲרֵי הוּא יוֹרֵד בְּרַע גָּמוּר לְפִי שָׁעָה עַד אֲשֶׁר יָשׁוּב וְיַחֲזוֹר לַעֲבוֹדַת ה' וּלְתוֹרָתוֹ כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר שֶׁל בֵּינוֹנִים (פֶּרֶק ז הַנַ\"ל פֶּרֶק א) הֲרֵי עַל יְדֵי תַּאֲווֹת נַפְשׁוֹ הוּא גָרוּעַ עוֹד גַּם מִבַּעֲלֵי חַיִּים הַטְּמֵאִים כו' וּכְמוֹ שֶׁיִּתְבָּאֵר), וְאִם כֵּן הֲרֵי הֲסָתַת הַיֵּצֶר הָרָע שֶׁמְּסִיתוֹ בִּדְבָרִים הַנַ\"ל, הֲרֵי זֶה שְׁטוּת נוֹרָא שֶׁמַּטֵּהוּ מִדֶּרֶךְ הָאֱמֶת וְהַצֶּדֶק, וְרַק מְסַמֵּא וּמְעַוֵּור עֵינָיו,\nוְכַאֲשֶׁר מְסִיתוֹ לוֹמַר שֶׁזֶּה טוֹב לְפָנָיו, זֹאת יָשִׂים אֶל לִבּוֹ, הֲכִי זֶהוּ הַטּוֹב שֶׁלִּי לְפִי מַעֲלַת וּמַדְרֵיגַת נַפְשִׁי הַנִּיתַּן לִי, וְכִי זֶהוּ כַּוָּונַת בְּרִיאָתִי בָּעוֹלָם, וְאַדְרַבָּא בְּמַה שֶּׁאוֹמֵר לוֹ שֶׁתַּאֲוָה הוּא לָעֵינַיִם, הֲרֵי מִפְּנֵי זֶה עַצְמוֹ צָרִיךְ לְהִתְרַחֵק מִזֶּה בְּתַכְלִית שֶׁלֹּא לְהוֹרִיד נַפְשׁוֹ חַס וְשָׁלוֹם כַּנַ\"ל, כִּי אִם הַטּוֹב שֶׁלּוֹ יִהְיֶה בְּעִנְיָנִים רוּחָנִים וְנַעֲלִים, שֶׁהֵם טוֹבִים בֶּאֱמֶת, וּבִפְרָט בְּעֵסֶק הַתּוֹרָה שֶׁזֶּהוּ טוֹב וְתַעֲנוּג אֲמִיתִּי, וּבָזֶה נִשְׁלָם כַּוָּונַת בְּרִיאָתוֹ כו'.\nקִיצּוּר.\nהָאָדָם לְפִי מַעֲלַת מַהוּתוֹ תַּכְלִיתוֹ עֲבוֹדַת ה' בְּאַהֲבָה וְיִרְאָה. וּכְשֶׁהָאָדָם נִמְשָׁךְ אַחַר תַּעֲנוּגִים גּוּפְנִים מוֹרִיד נַפְשׁוֹ לְהִתְקַשֵּׁר בְּמַה שֶּׁפָּחוּת מִמֶּנּוּ לְקַבֵּל מֵאִתּוֹ וְגָרוּעַ מִבַּעֲלֵי חַיִּים שֶׁאֵין לָהֶם דַּעַת, וְהַתַּאֲוָה עוֹשָׂה גַּם אֶת הַמּוּתָּר לְרַע לְשָׁעָה, וְכָל זֶה בָּא בְּסִבַּת הַיֵּצֶר הָרָע הָעוֹשֶׂה אוֹתוֹ לְשׁוֹטֶה."],[4401900034,"<h2>מַאֲמָר ב.</h2>\nוְהִנֵּה כָּל זֶה הוּא בִּדְבָרִים הַמּוּתָּרִים. אָמְנָם לִפְעָמִים מֵסִית הַיֵּצֶר הָרָע גַּם בִּדְבָרִים הָאֲסוּרִים, וְהוּא גַם כֵּן בְּמַה שֶּׁמַּרְאֶה לוֹ טוּב הַדָּבָר וְהַתַּעֲנוּג שֶׁיֵּשׁ בָּזֶה, וּמְעוֹרֵר רוּחַ תַּאֲוָתוֹ עַד שֶׁאֵינוֹ יָכוֹל לַעֲמוֹד עַל נַפְשׁוֹ וְנִכְשָׁל בָּזֶה רַחֲמָנָא לִצְּלָן. וְאוֹפֶן הַדֶּרֶךְ שֶׁמֵּבִיא הַיֵּצֶר הָרָע לִדְבָרִים אֵלּוּ הוּא כְּמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (שַׁבָּת קח. ב) כַּךְ הִיא אוּמָּנֻתוֹ שֶׁל יֵצֶר הָרָע הַיּוֹם אוֹמֵר לוֹ עֲשֵׂה כַךְ וּמָחָר אוֹמֵר לוֹ עֲשֵׂה כַךְ, עַד שֶׁאוֹמֵר לוֹ לֵךְ וַעֲבוֹד עֲבוֹדָה זָרָה, דְּבַתְּחִלָּה מְסִיתוֹ בִּדְבָרִים הַמּוּתָּרִים, שֶׁבָּזֶה נָקָל יוֹתֵר לְהַעֲבִיר אֶת הָאָדָם אַךְ עַל יְדֵי זֶה מִתְעַבֶּה וּמִתְגַּשֵּׁם נַפְשׁוֹ, שֶׁהָרְצוֹנוֹת דְּנֶפֶשׁ הַבַּהֲמִית מִתְגַּדְּלִים וּמִתְרַבִּים לִרְצוֹת בְּכָל דָּבָר. וְהָרָצוֹן הוּא בְּתוֹקֶף מְאֹד שֶׁמִּתְאַוֶּה מְאֹד בְּכָל דְּבַר תַּאֲוָה.\n<b>דְּהִנֵּה</b> יֵשׁ כַּמָּה חִלּוּקֵי מַדְרֵיגוֹת בְּטֶבַע הַנֶּפֶשׁ הַבַּהֲמִית. יֵשׁ מִי שֶׁהַנֶּפֶשׁ הַבַּהֲמִית שֶׁלּוֹ אֵינוֹ חָזָק כָּל כַּךְ, וְהַיְינוּ שֶׁיֵּשׁ דְּבָרִים שֶׁמִּתְאַוֶּה לָהֶם וְיֵשׁ דְּבָרִים שֶׁאֵינוֹ רוֹצֶה וּמִתְאַוֶּה כְּלָל, וּמַה שֶּׁמִּתְאַוֶּה גַם כֵּן אֵינוֹ בְּתוֹקֶף גָּדוֹל כָּל כַּךְ (עֶס אִיז רֶעכְט, אַז נִיט אוֹיךְ), וְיֵשׁ מִי שֶׁהַנֶּפֶשׁ הַבַּהֲמִית שֶׁלּוֹ הוּא בְּתוֹקֶף גָּדוֹל, דְּהַיְינוּ כָּל מַה שֶּׁעֵינָיו רוֹאוֹת וְכָל הַיָּדוּעַ לוֹ שֶׁיֵּשׁ מְצִיאוּת דְּבַר תַּאֲוָה הֲרֵי הוּא מִתְאַוֶּה לָזֶה (עֶר ווִיל אַלְץ) וְהַתַּאֲוָה הִיא בְּתוֹקֶף גָּדוֹל בְּהִתְעוֹרְרוּת גְּדוֹלָה וְלֹא יָנוּחַ וְלֹא יִשְׁקוֹט עַד שֶׁמְּמַלֵּא תַּאֲוַת לִבּוֹ,\nוְיָכוֹל לִהְיוֹת שֶׁגַּם כְּשֶׁהַנֶּפֶשׁ הַבַּהֲמִית אֵינוֹ בְּתוֹקֶף גָּדוֹל מִצַּד עַצְמוֹ הֲרֵי הוּא נַעֲשֶׂה בְּתוֹקֶף עַל יְדֵי רִיבּוּי הַשִּׁיקּוּעַ רַחֲמָנָא לִצְּלָן בְּעִנְיְנֵי הַתַּאֲוֹת, שֶׁנַּעֲשֶׂה עַל יְדֵי זֶה עָב וְגַס בְּעֶצֶם, שֶׁעִם הֱיוֹת שֶׁבְּעֶצֶם אֵינוֹ בְּתוֹקֶף כָּל כַּךְ, אָמְנָם עַל יְדֵי רִיבּוּי הַפְּעָמִים שֶׁמְּמַלֵּא תַאֲוָתוֹ נַעֲשֶׂה עַל יְדֵי זֶה תּוֹקֶף הַנֶּפֶשׁ הַבַּהֲמִית בְּיוֹתֵר לִרְצוֹת בְּכָל דָּבָר וּבְתוֹקֶף מְאֹד,\nוְיָדוּעַ דְּהַתּוֹקֶף דְּנֶפֶשׁ הַבַּהֲמִית גּוֹרֵם חֲלִישׁוּת הַנֶּפֶשׁ הָאֱלֹקִית, וּכְמַאֲמָר תּוּקְפָא דְגוּפָא חוּלְשָׁא דְנִשְׁמְתָא, דְּתוֹקֶף הַחוּמְרִיּוּת דְּהַנֶּפֶשׁ הַבַּהֲמִית גּוֹרֵם חֲלִישׁוּת הַנֶּפֶשׁ הָאֱלֹקִית, דְּלָא מִיבָּעֲיָא שֶׁמִּתְרַחֵק מְאֹד מִתּוֹרָה וַעֲבוֹדָה שֶׁבְּלֵב זוֹ תְפִלָּה, דְּאֵינוֹ שַׁיָּיךְ כְּלָל שֶׁיָּבִין אֵיזֶה עִנְיָן אֱלֹקִי, וְיִתְבּוֹנֵן בּוֹ וְיוּרְגַּשׁ הָעִנְיָן הָאֱלֹקִי בְּנַפְשׁוֹ עַד שֶׁיִּתְפָּעֵל בִּבְחִינַת הַמְשָׁכַת הַלֵּב לְדָבְקָה בוֹ וּלְהִכָּלֵל בֵּאלֹקוּת כו' דִּלְכָל זֶה אֵינוֹ שַׁיָּיךְ כְּלָל וּכְלָל,\nאֶלָּא שֶׁגַּם זֹאת שֶׁאֵין פַּחַד אֱלֹקִים נֶגֶד עֵינָיו וְשׁוֹכֵחַ עַל אֱלֹקוּת עַד שֶׁמַּה שֶּׁהַדָּבָר הַהוּא הוּא נֶגֶד רְצוֹן הוי', אֵינוֹ מוֹנֵעַ וּמְעַכֵּב אוֹתוֹ מֵעֲשִׂיָּיתוֹ, מִפְּנֵי שֶׁאֵין הָאֱלֹקוּת וּרְצוֹנוֹ יִתְבָּרֵךְ נִרְגָּשׁ בְּנַפְשׁוֹ לְהִתְפָּעֵל מִזֶּה, וְעִם הֱיוֹת שֶׁאֵינוֹ כוֹפֵר חַס וְשָׁלוֹם בַּה' וְתוֹרָתוֹ וְיוֹדֵעַ שֶׁהַתּוֹרָה אֱמֶת וְשֶׁזֶּה אָסוּר עַל פִּי הַתּוֹרָה, אָמְנָם גַּם כֵּן אֵינוֹ נִרְגָּשׁ בְּנַפְשׁוֹ הָאִיסּוּר, שֶׁזֶּה יִהְיֶה לוֹ מְנִיעָה וְעִיכּוּב וְשֶׁיּוּכַל לַעֲמוֹד נֶגֶד רוּחַ תַּאֲוָותוֹ כו',\nוְכָל זֶה הוּא מִפְּנֵי רִיבּוּי הַשִּׁיקּוּעַ בְּתַאֲווֹת הֶיתֵּר הֲרֵי הַנֶּפֶשׁ הַבַּהֲמִית שֶׁלּוֹ נִתְגַּבֵּר בְּיוֹתֵר, וְהַנֶּפֶשׁ הָאֱלֹקִית נֶחֱלַשׁ בְּיוֹתֵר, וְלָזֹאת כְּשֶׁהַנֶּפֶשׁ הַבַּהֲמִית מְסִיתוֹ וּמַרְאֶה לוֹ טוּב הַדָּבָר, הִנֵּה עִם הֱיוֹתוֹ דְּבַר אִיסּוּר מַמָּשׁ הֲרֵי הוּא נִמְשָׁךְ אַחֲרָיו וְנִכְשָׁל בָּזֶה רַחֲמָנָא לִצְּלָן, וּבָזֶה מוּבָן בִּפְשִׁיטוּת אֵיךְ הוּא זֶה שֶׁמַּשְׁטֶה אֶת עַצְמוֹ בְּטוּב הַדָּבָר שֶׁהֲרֵי הוּא רַע גָּמוּר וּמוֹרִיד אֶת נַפְשׁוֹ מְאֹד עַל יְדֵי זֶה רַחֲמָנָא לִצְּלָן וּכְמוֹ שֶׁיִּתְבָּאֵר.\n<b>אָמְנָם</b> בְּעִנְיַן הַהֲסָתָה בִּדְבָרִים הָאֲסוּרִים רַחֲמָנָא לִצְּלָן, יֵשׁ עוֹד דָּבָר שֶׁמְּסִיתוֹ שֶׁגַּם אִם יַעֲשֶׂה הַדָּבָר הָרָע הַזֶּה עִם כָּל זֶה אֵינֶנּוּ נִפְרָד כְּלָל מֵאַחְדּוּתוֹ יִתְבָּרֵךְ. דְּהִנֵּה בְּנִשְׁמוֹת יִשְׂרָאֵל יֵשׁ בְּטֶבַע נַפְשָׁם שֶׁאֵינָם יְכוֹלִים לִהְיוֹת נִפְרָדִים מֵאֱלֹקוּת מִשּׁוּם כִּי אַתָּה אָבִינוּ, וּמִשּׁוּם זֶה גַּם קַל שֶׁבְּקַלִּים וּפוֹשְׁעֵי יִשְׂרָאֵל מוֹסֵר נַפְשׁוֹ עַל קִדּוּשׁ הַשֵּׁם, וְהַיְינוּ דְּכַאֲשֶׁר אֲפִילוּ נוֹטְלִים אֶת נַפְשׁוֹ מִמֶּנּוּ לֹא יַעֲבוֹד עֲבוֹדָה זָרָה חַס וְשָׁלוֹם, מִפְּנֵי שֶׁאֵינוֹ יָכוֹל לִהְיוֹת נִפְרָד מִיִּחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ, וְאִלּוּ הָיָה יוֹדֵעַ שֶׁעַל יְדֵי מַעֲשֶׂה הָרָע נַעֲשֶׂה נִפְרָד מֵאֱלֹקוּת לֹא הָיָה עוֹשֶׂה זֹּאת בְּשׁוּם אוֹפֶן, אֶלָּא שֶׁהַיֵּצֶר הָרָע מְסִיתוֹ שֶׁעִם כָּל זֶה אֵינוֹ נַעֲשֶׂה נִפְרָד מֵאֱלֹקוּת, וַהֲרֵי הוּא כְּכָל בַּר יִשְׂרָאֵל הַנֶּאֱמָן עִם אֱלֹקָיו, וְגַם מַבְטִיחוֹ כִּי יִהְיֶה טוֹב לוֹ וּכְמוֹ שֶׁכָּתוּב (דְּבָרִים כט. יח) וְהִתְבָּרֵךְ בִּלְבָבוֹ לֵאמֹר שָׁלוֹם יִהְיֶה לִּי כִּי בִּשְׁרִירוּת לִבִּי אֵלֵךְ, שֶׁגַּם אִם יֵלֵךְ בִּשְׁרִירוּת לִבּוֹ עִם כָּל זֶה שָׁלוֹם יִהְיֶה לּוֹ, וְעַל יְדֵי זֶה בָּא וְנִכְשָׁל בְּכַמָּה דְבָרִים.\nקִיצּוּר.\nהַנֶּפֶשׁ הַבַּהֲמִית יֵשׁ שֶׁהוּא בְּטֶבַע הַחֲלִישׁוּת, וְיֵשׁ שֶׁהוּא בְּטֶבַע הַתּוֹקֶף אֲשֶׁר כָּל דְּבַר תַּאֲוָה הַיְדוּעָה לוֹ עוֹשֶׂה הַכֹּל בִּשְׁבִיל לְהַשִּׂיגוֹ, וַאֲפִילוּ תַּאֲוַת הֶיתֵּר פְּעָמִים רַבּוֹת מְעַבֶּה שֶׁאֵין פַּחַד אֱלֹקִים נֶגֶד עֵינָיו, וְהַיֵּצֶר הָרָע מְסִיתוֹ שֶׁגַּם בְּתַאֲוַת אִיסּוּר עוֹדֶנּוּ כְּכָל בַּר יִשְׂרָאֵל."],[4401900035,"וּבֶאֱמֶת כָּל זֶה הוּא מִשְּׁטוּתֵי הַיֵּצֶר שֶׁמַּטֵּהוּ וּמְכַסֶּה עַל הָאֱמֶת (ה' יִשְׁמְרֵנוּ מִזֶּה). דְּהִנֵּה מַה שֶּׁמַּרְאֶה לוֹ וּמְסִיתוֹ מִטּוּב הַדָּבָר הַהוּא, הֲרֵי בֶּאֱמֶת לִהְיוֹתוֹ מִדְּבָרִים הָאֲסוּרִים הֲרֵי זֶה מָוֶת וְרַע מַמָּשׁ, וּכְמוֹ שֶׁכָּתוּב (דְּבָרִים ל. טו) רְאֵה נָתַתִּי לְפָנֶיךָ הַיּוֹם אֶת הַחַיִּים וְאֶת הַטּוֹב וְאֶת הַמָּוֶת וְאֶת הָרָע, וּמוֹרִיד וּמְאַבֵּד נַפְשׁוֹ רַחֲמָנָא לִצְּלָן בְּזֶה שֶׁמּוֹרִידָהּ בִּשְׁאוֹל תַּחְתִּית וּבִמְקוֹם הַקְּלִיפּוֹת וְסִטְרָא אָחֳרָא מִשָּׁלֹשׁ קְלִיפּוֹת הַטְּמֵאוֹת לְגַמְרֵי, וְעוֹד לְמַטָּה מֵהֶם, וּכְמוֹ שֶׁכָּתוּב בְּסֵפֶר שֶׁל בֵּינוֹנִים בַּאֲרִיכוּת, דְּהִנֵּה הַקְּלִיפּוֹת וְסִטְרָא אָחֳרָא מְקַבְּלִים גַּם כֵּן חַיּוּתָם וְקִיּוּמָם מִדְּבַר ה' וְרוּחַ פִּיו יִתְבָּרֵךְ, אֲבָל הוּא בִּבְחִינַת הֶסְתֵּר פָּנִים וִירִידַת הַמַּדְרֵיגוֹת, וְלָכֵן נִקְרָאִים אֱלֹקִים אֲחֵרִים מִפְּנֵי שֶׁיְּנִיקָתָם וְחַיּוּתָם אֵינָהּ מִבְּחִינַת פָּנִים, אֶלָּא מִבְּחִינַת אֲחוֹרַיִים דִּקְדוּשָּׁה, וּפֵירוּשׁ אֲחוֹרַיִים כְּאָדָם הַנּוֹתֵן דָּבָר לְשׂוֹנְאוֹ שֶׁלֹּא בִרְצוֹנוֹ שֶׁמַּשְׁלִיכוֹ לוֹ כִּלְאַחַר כְּתֵפוֹ, כִּי מַחֲזִיר פָּנָיו מִמֶּנּוּ מִשִּׂנְאָתוֹ אוֹתוֹ.\n<b>כַּך</b> לְמַעְלָה בְּחִינַת פָּנִים הוּא פְּנִימִית הָרָצוֹן הָעֶלְיוֹן וְחֶפְצוֹ הָאֲמִיתִּי אֲשֶׁר חָפֵץ ה' לְהַשְׁפִּיעַ חַיּוּת לְכָל הַקָּרוֹב אֵלָיו מִסִּטְרָא דִקְדוּשָּׁה, אֲבָל הַסִּטְרָא אָחֳרָא וְהַטּוּמְאָה הִיא תּוֹעֲבַת ה' אֲשֶׁר שָׂנֵא, וְאֵינוֹ מַשְׁפִּיעַ לָהּ חַיּוּת מִפְּנִימִית הָרָצוֹן וְחֶפְצוֹ הָאֲמִיתִּי, אֲשֶׁר בָּהּ חָפֵץ חַס וְשָׁלוֹם, כִּי אִם כְּמַאן דְּשָׁדֵי בָּתַר כַּתְפּוֹי לְשׂוֹנְאוֹ שֶׁלֹּא בִרְצוֹנוֹ (רַק כְּדֵי לְהַעֲנִישׁ אֶת הָרְשָׁעִים וְלִיתֵּן שָׂכָר טוֹב לַצַּדִּיקִים דְּאַכְפָּיָין לְסִטְרָא אָחֳרָא),\nוּלְפִי שֶׁבְּחִינַת פָּנִים דְּרָצוֹן הָעֶלְיוֹן אֵינוֹ שׁוֹרֶה כְּלָל עַל הַסִּטְרָא אָחֳרָא וְגַם בְּחִינַת אֲחוֹרַיִים שֶׁל רָצוֹן הָעֶלְיוֹן אֵינוֹ מְלוּבָּשׁ בְּתוֹכָהּ מַמָּשׁ אֶלָּא מַקִּיף עָלֶיהָ מִלְמַעְלָה, לְכַךְ הִיא מְקוֹם הַמִּיתָה וְהַטּוּמְאָה ה' יִשְׁמְרֵנוּ, כִּי אֲמִיתַּת הַחַיּוּת הוּא אֱלֹקוּת שֶׁהוּא בְּחִינַת אֱלֹקִים חַיִּים וּכְמוֹ שֶׁכָּתוּב (יִרְמְיָה י. י) וַה' אֱלֹקִים אֱמֶת הוּא אֱלֹקִים חַיִּים כו', פֵּירוּשׁ לִהְיוֹת שֶׁהוּא אֱלֹקִים אֱמֶת הֲרֵי הוּא אֱלֹקִים חַיִּים.\n<b>דְּהִנֵּה</b> אֱמֶת הוּא שֶׁאֵינוֹ נִפְסָק לְעוֹלָם, וּמַה שֶּׁיֵּשׁ בּוֹ הֶפְסֵק נִקְרָא כָּזָב, וּכְמוֹ נְהָרוֹת הַמְכַזְּבִין (מִשְׁנָה ט פֶּרֶק ח דְּפָרָה) שֶׁנִּקְרָאִים כָּזָב לְפִי שֶׁנִּפְסָקִים לִפְעָמִים, כִּי אֱמֶת הוּא דָבָר שֶׁאֵינוֹ נִפְסָק לְעוֹלָם, וְזֶהוּ גַם כֵּן הַנִּקְרָא חַיִּים, דְּמִשּׁוּם זֶה נְהָרוֹת הַמְכַזְּבִין פְּסוּלִין לְקִידּוּשׁ מֵי חַטָּאת שֶׁאֵינָן נִקְרָאִים מַיִם חַיִּים, דְּדַוְקָא דָּבָר אֲמִיתִּי שֶׁאֵינוֹ נִפְסָק לְעוֹלָם הוּא הַנִּקְרָא חַי. וְזֶהוּ וַה' אֱלֹקִים אֱמֶת הוּא אֱלֹקִים חַיִּים, דְּלִהְיוֹת שֶׁהוּא אֱלֹקִים אֱמֶת, שֶׁאֵין בָּזֶה כִּלָּיוֹן וְהֶפְסֵד חַס וְשָׁלוֹם, הוּא אֱלֹקִים חַיִּים, בְּחִינַת חַי וְקַיָּים מִצַּד עַצְמוֹ שֶׁחַי וְקַיָּים לָעַד, בָּרוּךְ חַי לָעַד וְקַיָּים לָנֶצַח, וְכָל הַדָּבוּק לֵאלֹקוּת הוּא גַם כֵּן בִּבְחִינַת חַי, לְפִי שֶׁהָאֱלֹקוּת מֵאִיר בְּתוֹכוֹ בְּגִילּוּי וּמִתְיַיחֵד בּוֹ, וְהוּא בָּטֵל אֶל הָאֱלֹקוּת הַמִּתְלַבֵּשׁ בְּתוֹכוֹ וְדָבוּק בּוֹ, כְּמוֹ שֶׁיִּתְבָּאֵר, מִשּׁוּם זֶה נִקְרָא גַם כֵּן חַיִּים.\n<b>וְזֶהוּ</b> מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (אָבוֹת דְּרַבִּי נָתָן פֶּרֶק ל\"ד) עֲשָׂרָה נִקְרָאִים חַיִּים, הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנֶּאֱמַר (יִרְמְיָה י. י) וַה' אֱלֹקִים אֱמֶת הוּא אֱלֹקִים חַיִּים, הַתּוֹרָה נִקְרֵאת חַיִּים שֶׁנֶּאֱמַר (מִשְׁלֵי ג. יח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ וְתֹמְכֶיהָ מְאוּשָּׁר, יִשְׂרָאֵל נִקְרָאִים חַיִּים שֶׁנֶּאֱמַר (דְּבָרִים ד. ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹקֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם,\nדְּלִהְיוֹתָם דְּבוּקִים בַּה' מִשּׁוּם זֶה נִקְרָאִים חַיִּים.\nקִיצּוּר.\nהַקְּדוּשָּׁה וְהַטּוֹב מְקַבְּלִים חַיּוּתָם מִפְּנִימִיּוּת רְצוֹנוֹ יִתְבָּרֵךְ. הַקְּלִיפָּה וְסִטְרָא אָחֳרָא מְקַבְּלִים חַיּוּתָם מֵחִיצוֹנִיּוּת רְצוֹנוֹ יִתְבָּרֵךְ הַבִּלְתִּי מִתְלַבֵּשׁ בָּהֶם רַק עוֹמֵד עֲלֵיהֶם בְּמַקִּיף, וְהַדְּבָרִים הָאֲסוּרִים מְקַבְּלִים חַיּוּתָם מֵהֶם, וְלָכֵן הֵם מָוֶת וְרַע. הַדָּבוּק בֵּאלֹקוּת הוּא חַי כִּי אֱמֶת אֵין לוֹ הֶפְסֵק."],[4401900036,"<h2>מַאֲמָר ג.</h2>\nוְכָל זֶה הוּא בְּמַדְרֵיגַת הַקְּדוּשָּׁה, שֶׁאֱלֹקוּת מֵאִיר בְּגִילּוּי בִּבְחִינַת הִתְלַבְּשׁוּת, וְהַמְלַבֵּשׁ בָּטֵל וְדָבוּק בּוֹ, אֲבָל בְּסִטְרָא אָחֳרָא שֶׁאֵין הָאֱלֹקוּת מִתְלַבֵּשׁ בְּתוֹכָהּ בִּפְנִימִית, כִּי אִם מַקִּיף עָלֶיהָ מִלְמַעְלָה לְבָד, כִּי מֵאַחַר שֶׁהֵן תּוֹעֲבַת ה' אֲשֶׁר שָׂנֵא וְהַהַשְׁפָּעָה לָהֶם הִיא רַק כְּמַאן דְּשָׁדֵי בָּתַר כַּתְפּוֹי שֶׁלֹּא מֵרְצוֹנוֹ מִמֵּילָא אֵינוֹ בִּבְחִינַת הִתְלַבְּשׁוּת פְּנִימִי,\nוּכְמוֹ עַל דֶּרֶךְ מָשָׁל בָּאָדָם לְמַטָּה כְּשֶׁרוֹצֶה בְּאֵיזֶה דָבָר, הֲרֵי הוּא מִתְלַבֵּשׁ בְּהַדָּבָר הַהוּא בִּפְנִימִיּוּתוֹ (עֶר טוּט זִיךְ אָן אִין דֶעם) וּמִתְקַשֵּׁר וּמִתְאַחֵד בּוֹ, וּכְמוֹ אָב הַלּוֹמֵד עִם בְּנוֹ וְרַב עִם תַּלְמִידוֹ, הֲרֵי מִצַּד הָאַהֲבָה אֶל הַבֵּן אוֹ אֶל הַתַּלְמִיד וּרְצוֹנוֹ בּוֹ שֶׁרוֹצֶה שֶׁיָּבִין הֵיטֵב, הֲרֵי הוּא מִתְלַבֵּשׁ וּמִתְקַשֵּׁר בּוֹ לְהַשְׁפִּיעַ לוֹ הַשֵּׂכֶל בְּגִילּוּי מַמָּשׁ (לְפִי עֶרְכּוֹ) וְשֶׁיִּתְקַבֵּל בּוֹ הָעִנְיָן הֵיטֵב בִּכְלֵי שִׂכְלוֹ, שֶׁיֵּדַע וְיָבִין אֶת הָעִנְיָן שִׂכְלִי, מַה שֶּׁאֵין כֵּן בְּדָבָר שֶׁאֵינוֹ רוֹצֶה בּוֹ אֵינוֹ מִתְלַבֵּשׁ בּוֹ כְּלָל וְעוֹמֵד בְּרָחוֹק מִמֶּנּוּ,\nוְכַךְ יוּבַן לְמַעְלָה, דִּבְסִטְרָא דִקְדוּשָּׁה נִמְשָׁךְ מִבְּחִינַת פָּנִים דְּרָצוֹן הָעֶלְיוֹן שֶׁהוּא בְּחִינַת גִּילּוּי וְנִמְשָׁךְ בִּבְחִינַת הִתְלַבְּשׁוּת פְּנִימִי בְּתוֹכָם מַמָּשׁ וּמִתְאַחֵד עִמָּהֶם, מַה שֶּׁאֵין כֵּן בְּסִטְרָא אָחֳרָא אֲשֶׁר שָׂנֵא ה' אֵינוֹ מִתְלַבֵּשׁ בָּהֶם בִּבְחִינַת פְּנִימִי, כִּי אִם בִּבְחִינַת מַקִּיף לְבָד, שֶׁמּוּבְדָּל וּמְרוּחָק מֵהֶם לְגַמְרֵי, וְאֵינוֹ מִתְעָרֵב עִמָּהֶם, כָּל שֶׁכֵּן שֶׁאֵינוֹ מִתְאַחֵד עִמָּהֶם כְּלָל וּכְלָל, וּמֵאַחַר שֶׁהָאֱלֹקוּת מוּבְדָּל וּמְרוּחָק לְגַמְרֵי מֵהַסִּטְרָא אָחֳרָא, לָכֵן הִיא בְּעֶצֶם בְּחִינַת מָוֶת מַמָּשׁ, וְגַם מְעַט מִזְּעֵיר אוֹר וְחַיּוּת שֶׁיּוֹנֶקֶת וּמְקַבֶּלֶת לְתוֹכָהּ מִבְּחִינַת אֲחוֹרַיִים דִּקְדוּשָּׁה שֶׁלְּמַעְלָה הוּא בִּבְחִינַת גָּלוּת מַמָּשׁ בְּתוֹכָהּ בְּסוֹד גָּלוּת הַשְּׁכִינָה,\nוּמִשּׁוּם זֶה נִקְרָאִים גַּם כֵּן אֱלֹקִים אֲחֵרִים, (לְעֵיל מַאֲמָר ב פֶּרֶק ב נִתְבָּאֵר הַטַּעַם שֶׁנִּקְרָאִים אֱלֹקִים אֲחֵרִים מִצַּד שֹׁרֶשׁ יְנִיקָתָם, וְכַאן מְבָאֵר מִצַּד עַצְמָם, וְהָא בְּהָא תַּלְיָא), שֶׁהִיא עֲבוֹדָה זָרָה מַמָּשׁ וּכְפִירָה בְּאַחְדּוּתוֹ שֶׁל מֶלֶךְ מַלְכֵי הַמְּלָכִים הַקָּדוֹשׁ בָּרוּךְ הוּא, כִּי מֵאַחַר שֶׁאוֹר וְחַיּוּת דִּקְדוּשָּׁה הוּא בִּבְחִינַת גָּלוּת בְּתוֹכָהּ אֵינָהּ בְּטֵלָה כְּלָל לְגַבֵּי קְדוּשַּׁת הַקָּדוֹשׁ בָּרוּךְ הוּא, כִּי בְּסִטְרָא דִקְדוּשָּׁה שֶׁמֵּאִיר גִּילּוּי אֱלֹקוּת לָכֵן הֵם בִּבְחִינַת בִּיטּוּל אֶל הָאוֹר וְהַחַיּוּת הָאֱלֹקִי,\nוּכְמוֹ עַל דֶּרֶךְ מָשָׁל בְּאוֹר וְחַיּוּת הַנֶּפֶשׁ שֶׁמִּתְלַבֵּשׁ בְּאֵבְרֵי הַגּוּף, הֲרֵי הָאֵבָרִים בְּטֵלִים אֶל הַנֶּפֶשׁ, וּלְכָל אֲשֶׁר יַחְפּוֹץ יַטֶּנּוּ, וְהַיְינוּ לְפִי שֶׁהָאוֹר וְחַיּוּת הַנֶּפֶשׁ מֵאִיר בְּגִילּוּי מַמָּשׁ בְּאֵבְרֵי הַגּוּף וְנִרְגָּשׁ בָּהֶם, מִשּׁוּם זֶה הֵמָּה בְּטֵלִים אֶל הָאוֹר וְהַחַיּוּת, אֲבָל כְּשֶׁאֵינוֹ מֵאִיר בְּגִילּוּי מִמֵּילָא אֵין הַמְלַבֵּשׁ בָּטֵל אֵלָיו, וּכְמוֹ אָדָם הַקָּשׁוּר בְּשַׂק אֵין הַשַּׂק בָּטֵל אֶל הָאָדָם, וּכְמוֹ כֵן הוּא בְּעִנְיַן הַגִּלְגּוּלִים, כַּאֲשֶׁר נֶפֶשׁ הָאָדָם מִתְגַּלְגֵּל בְּגוּף הַבְּהֵמָה אֵין הַבְּהֵמָה בְּטֵלָה אֶל נֶפֶשׁ הָאָדָם מִפְּנֵי שֶׁאֵינוֹ מִתְגַּלֶּה בָּהּ, כִּי אִם הוּא אָסוּר וְקָשׁוּר שָׁם כְּמוֹ אָדָם הַקָּשׁוּר בְּשַׂק וּכְמוֹ בְּבֵית הָאֲסוּרִים, וְזֶהוּ הַנִּקְרָא גָּלוּת שֶׁאֵינוֹ מִתְגַּלֶּה שָׁם כִּי אִם אָסוּר וְקָשׁוּר לְבָד, וּמִשּׁוּם זֶה אֵין גּוּף הַבְּהֵמָה בָּטֵל אֶל נֶפֶשׁ הָאָדָם,\nוְכֵן יוּבַן לְמַעְלָה, דִּבְסִטְרָא דִקְדוּשָּׁה שֶׁהָאוֹר וְהַחַיּוּת אֱלֹקִי מֵאִיר בְּגִילּוּי וְנִרְגָּשׁ בָּהֶם הָאוֹר וְהַחַיּוּת הָאֱלֹקִי לָכֵן הֵם בְּטֵלִים אֶל הָאֱלֹקוּת, אֲבָל בְּסִטְרָא אָחֳרָא שֶׁאֵינוֹ מֵאִיר שָׁם גִּילּוּי הָאוֹר וְהַחַיּוּת כִּי אִם הוּא בִּבְחִינַת גָּלוּת בָּהֶם לָכֵן אֵינָם בְּטֵלִים אֶל אֱלֹקוּת.\nקִיצּוּר.\nבִּקְדוּשָּׁה אֱלֹקוּת מִתְלַבֵּשׁ בִּפְנִימִית וּמֵאִיר בְּגִילּוּי כְּמוֹ הָאָב הַמִּתְקַשֵּׁר עִם בְּנוֹ בְּלָמְדוֹ עִמּוֹ, וּבְסִטְרָא אָחֳרָא עוֹמֵד בְּמַקִּיף מִלְמַעְלָה וְהַהֶאָרָה הַמְחַיָּה אוֹתָם כְּמַאן דְּשָׁדֵי בָּתַר כַּתְפּוֹי וּבְגָלוּת אֶצְלָם כְּמוֹ אָדָם הַקָּשׁוּר בְּשַׂק וּכְמוֹ בְּעִנְיַן הַגִּלְגּוּלִים רַחֲמָנָא לִצְּלָן."],[4401900037,"וְהִנֵּה סִבַּת הַדָּבָר שֶׁאֵין הָאוֹר דִּקְדוּשָּׁה מִתְגַּלֶּה בָּהֶם הוּא מִפְּנֵי שֶׁאֵינָם כֵּלִים לֵאלֹקוּת, דִּבְסִטְרָא דִקְדוּשָּׁה שֶׁהֵן בְּעֶצֶם כֵּלִים לֵאלֹקוּת מִשּׁוּם זֶה הָאוֹר וְהַחַיּוּת אֱלֹקִי מֵאִיר בָּהֶם בְּגִילּוּי, וּכְמוֹ עַל דֶּרֶךְ מָשָׁל הַנַ\"ל בְּנֶפֶשׁ הָאָדָם שֶׁמִּתְלַבֵּשׁ בְּאֵבְרֵי הַגּוּף הוּא בְּגוּף הָאָדָם דַּוְקָא, לְפִי שֶׁהוּא כְּלִי מוּכָן לְקַבֵּל צוּרַת נֶפֶשׁ הָאָדָם, לָכֵן אוֹר וְחַיּוּת הַנֶּפֶשׁ מֵאִיר בּוֹ בְּגִילּוּי לִהְיוֹת נִרְגָּשׁ בּוֹ וּלְפִי שֶׁמֵּאִיר בּוֹ בְּגָלוּי מִשּׁוּם זֶה הַגּוּף בָּטֵל אֶל הַנֶּפֶשׁ, וְעַל יְדֵי זֶה הוּא מִתְגַּלֶּה וּמִתְלַבֵּשׁ בּוֹ מַמָּשׁ עַד שֶׁהַגּוּף חַי מִמֶּנּוּ בִּבְחִינַת חַיּוּת גָּלוּי מַמָּשׁ, וּבְגוּף הַבְּהֵמָה לְפִי שֶׁאֵינוֹ מוּכָן לְקַבֵּל צוּרַת נֶפֶשׁ הָאָדָם, לָכֵן אֵין הַנֶּפֶשׁ מִתְגַּלֶּה שָׁם וּמִמֵּילָא אֵין הַבְּהֵמָה בְּטֵלָה כַּנַ\"ל,\nוּכְמוֹ כֵן יוּבַן דִּבְסִטְרָא דִקְדוּשָּׁה שֶׁהֵן כֵּלִים בְּעֶצֶם לֵאלֹקוּת לָכֵן הָאוֹר הָאֱלֹקִי מְאִירָה בָהֶם בְּגִילּוּי מַמָּשׁ, וּמִשּׁוּם זֶה הֵם בְּטֵלִים לֵאלֹקוּת וְעַל יְדֵי זֶה מִתְגַּלֶּה בָהֶם הָאוֹר בְּיוֹתֵר וּמִתְלַבֵּשׁ מַמָּשׁ בִּפְנִימִיּוּתָם וּמִתְאַחֵד עִמָּהֶם, אֲבָל בְּסִטְרָא אָחֳרָא שֶׁבְּעֶצֶם אֵינָם כֵּלִים לֵאלֹקוּת כְּלָל (וְהַיְינוּ מִצַּד עֶצֶם מְקוֹר וְאוֹפֶן הִתְהַוּוּתָם, שֶׁאֵין בָּהֶם הַבִּיטּוּל וְהַהֲכָנָה כְּלָלִית לָאוֹר הָאֱלֹקִי, כְּמוֹ שֶׁכָּתוּב בְּמָקוֹם אַחֵר, וְעַיֵּן מַה שֶּׁכָּתוּב בְּתוֹרָה אוֹר וְהוֹסָפוֹת פַּרְשָׁה בְּרֵאשִׁית דְּרוּשׁ הַמַּתְחִיל לְהָבִין עִנְיַן הַבְּרָכוֹת פֶּרֶק ז' וְח') לָכֵן אֵין הָאוֹר דִּקְדוּשָּׁה מֵאִיר בָּהֶם בְּגִילּוּי כִּי אִם נִמְצָא בְּתוֹכָם בִּבְחִינַת גָּלוּת, וּמִשּׁוּם זֶה אֵין הַסִּטְרָא אָחֳרָא בְּטֵלָה לֵאלֹקוּת\nוְאַדְרַבָּה מַגְבִּיהַּ עַצְמָהּ כַּנֶּשֶׁר לוֹמר אֲנִי וְאַפְסִי עוֹד (יְשַׁעְיָה מז. ח) וּכְמוֹ שֶׁכָּתוּב (יְחֶזְקֵאל כט. ט) יְאֹר לִי וַאֲנִי עֲשִׂיתִנִי. וְלָכֵן אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (סוֹטָה ד. ב) שֶׁגַּסּוּת הָרוּחַ שְׁקוּלָה כַּעֲבוֹדָה זָרָה מַמָּשׁ, כִּי עִיקַּר וְשֹׁרֶשׁ עֲבוֹדָה זָרָה הוּא מַה שֶּׁנֶּחְשָׁב לְדָבָר בִּפְנֵי עַצְמוֹ נִפְרָד מִקְּדוּשָּׁתוֹ שֶׁל מָקוֹם וְלֹא כְּפִירָה בַּה' לְגַמְרֵי, כִּדְאִיתָא בִּגְמָרָא דְּקָרוּ לֵיהּ אֱלָקָא דֶאֱלָקַיָּא,\nאֶלָּא שֶׁגַּם הֵם מַחְשִׁיבִים עַצְמָם לְיֵשׁ וְדָבָר בִּפְנֵי עַצְמוֹ וּבָזֶה מַפְרִידִים אֶת עַצְמָם מִקְּדוּשָּׁתוֹ שֶׁל מָקוֹם בָּרוּךְ הוּא, מֵאַחַר שֶׁאֵין בְּטֵלִים לוֹ יִתְבָּרֵךְ, כִּי אֵין קְדוּשָּׁה עֶלְיוֹנָה שׁוֹרָה אֶלָּא עַל מַה שֶּׁבָּטֵל לוֹ יִתְבָּרֵךְ, וְלָכֵן נִקְרָאִים טוּרָא דִפְרוּדָא בְּזֹהַר הַקָּדוֹשׁ, וַהֲרֵי זוֹ כְּפִירָה בְּאַחְדּוּתוֹ הָאֲמִיתִּית דְּכוֹלָּא קַמֵּיהּ כְּלָא חֲשִׁיב וּבָטֵל בֶּאֱמֶת לוֹ יִתְבָּרֵךְ וְלִרְצוֹנוֹ הַמְחַיֶּה אֶת כֻּלָּם וּמְהַוֶּוה אוֹתָם מֵאַיִן לְיֵשׁ תָּמִיד.\nקִיצּוּר.\nגּוּף הָאָדָם הַרְכָּבָתוֹ מִזְגוֹ וּתְכוּנָתוֹ הוּא כְּלִי לְקַבֵּל צוּרַת נֶפֶשׁ הָאָדָם וְלָכֵן הַגּוּף בָּטֵל וְנִמְשָׁךְ אֶל הַנֶּפֶשׁ. גּוּף הַבְּהֵמָה אֵינוֹ מוּכָן לְקַבֵּל צוּרַת נֶפֶשׁ הָאָדָם, כֵּן הַקְּדוּשָּׁה כֵּלִים לֵאלֹקוּת וְהָאוֹר מֵאִיר בְּגִילּוּי, וְהַסִּטְרָא אָחֳרָא שֶׁמְּחַשְּׁבִים עַצְמָם לִמְצִיאוּת כּוֹפְרִים בְּאַחְדּוּתוֹ יִתְבָּרֵךְ."],[4401900038,"וְהִנֵּה כְּמוֹ שֶׁהוּא בְּסִטְרָא אָחֳרָא כֵּן הוּא הָעִנְיָן בִּשְׁסָ\"ה מִצְוֹת לֹא תַעֲשֶׂה דְּאוֹרַיְיתָא וְכָל אִיסּוּרֵי דְרַבָּנָן, מֵאַחַר שֶׁהֵם נֶגֶד רְצוֹנוֹ וְחָכְמָתוֹ יִתְבָּרֵךְ וְהֶפְכָּם מַמָּשׁ, הֵם נִפְרָדִים מִיִּחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ בְּתַכְלִית הַפֵּירוּד מַמָּשׁ, כְּמוֹ הַסִּטְרָא אָחֳרָא וְהַקְּלִיפָּה הַנִּקְרֵאת עֲבוֹדָה זָרָה וֵאלֹקִים אֲחֵרִים מֵחֲמַת הֶסְתֵּר פָּנִים שֶׁל הָרָצוֹן עֶלְיוֹן כַּנַ\"ל פֶּרֶק ב,\nוְכֵן ג' לְבוּשֵׁי הַנֶּפֶשׁ שֶׁמִּקְּלִיפַּת נוֹגַהּ שֶׁבְּיִשְׂרָאֵל שֶׁהֵם מַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה הַמְלוּבָּשִׁים בִּשְׁסָ\"ה מִצְוֹת לֹא תַעֲשֶׂה דְאוֹרַיְיתָא וּדְרַבָּנָן, וְכֵן מַהוּת הַנֶּפֶשׁ עַצְמָהּ הַמְלוּבֶּשֶׁת בִּלְבוּשֶׁיהָ כּוּלָּם מְיוּחָדִים מַמָּשׁ בְּסִטְרָא אָחֳרָא וּקְלִיפָּה זוֹ הַנִּקְרֵאת עֲבוֹדָה זָרָה,\nוְלֹא עוֹד אֶלָּא שֶׁבְּטֵלִים וּטְפֵלִים אֵלֶיהָ וּגְרוּעִים וּפְחוּתִים מִמֶּנָּה מְאֹד, כִּי הִיא אֵינָהּ מְלוּבֶּשֶׁת בְּגוּף חוּמְרִי וְיוֹדַעַת אֶת רִבּוֹנָהּ וְאֵינָהּ מוֹרֶדֶת בּוֹ לִפְעוֹל פְּעוּלָּתָהּ בְּמִשְׁלַחַת מַלְאֲכֵי רָעִים שֶׁלָּהּ שֶׁלֹּא בִּשְׁלִיחוּתוֹ שֶׁל מָקוֹם בָּרוּךְ הוּא חַס וְשָׁלוֹם, וּכְמַאֲמַר בִּלְעָם לֹא אוּכַל לַעֲבֹר אֶת פִּי ה' (בַּמִּדְבָּר כד. יג) וְאַף שֶׁנִּקְרָא עֲבוֹדָה זָרָה הָא קָרוּ לֵיהּ אֱלָקָא דֶאֱלָקַיָּא, וְאֵינָם יְכוֹלִים לַעֲבוֹר כְּלָל עַל רְצוֹנוֹ יִתְבָּרֵךְ כִּי יוֹדְעִים וּמַשִּׂיגִים שֶׁהוּא חַיּוּתָם וְקִיּוּמָם שֶׁיּוֹנְקִים מִבְּחִינַת אֲחוֹרַיִים דַּאֲחוֹרַיִים שֶׁל רָצוֹן הָעֶלְיוֹן בָּרוּךְ הוּא הַמַּקִּיף עֲלֵיהֶם, אֶלָּא שֶׁיְּנִיקָתָם וְחַיּוּתָם שֶׁבְּתוֹכָם הִיא בִּבְחִינַת גָּלוּת בְּתוֹכָם לְהַחֲשִׁיב עַצְמָן אֱלֹקוּת, וַהֲרֵי זוֹ כְּפִירָה בְּאַחְדּוּתוֹ אֲבָל מִכָּל מָקוֹם אֵינָן כּוֹפְרִים וְכוֹחֲשִׁים בַּה' לְגַמְרֵי וְלוֹמַר לֹא הוּא, אֶלָּא דְּקָרוּ לֵיהּ אֱלָקָא דֶאֱלָקַיָּא, דְּהַיְינוּ חַיּוּתָם וְקִיּוּמָם הַנִּמְשָׁךְ וְיוֹרֵד עֲלֵיהֶם מֵרְצוֹנוֹ יִתְבָּרֵךְ, וְלָכֵן אֵינָן עוֹבְרִין רְצוֹנוֹ יִתְבָּרֵךְ לְעוֹלָם,\nוְאִם כֵּן הָאָדָם הָעוֹבֵר עַל רְצוֹנוֹ יִתְבָּרֵךְ הוּא גָרוּעַ וּפָחוּת הַרְבֵּה מְאֹד מֵהַסִּטְרָא אָחֳרָא וְהַקְּלִיפָּה הַנִּקְרֵאת עֲבוֹדָה זָרָה וֵאלֹקִים אֲחֵרִים, וְהוּא בְּתַכְלִית הַפֵּירוּד מִיִּחוּדוֹ וְאַחְדּוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מִמֶּנָּה, וּכְאִלּוּ כּוֹפֵר בְּאַחְדּוּתוֹ יוֹתֵר מִמֶּנָּה חַס וְשָׁלוֹם.\nקִיצּוּר.\nהַשְּׁסָ\"ה מִצְוֹת לֹא תַעֲשֶׂה וְאִיסּוּרֵי דְרַבָּנָן הֵם נִפְרָדִים מֵאַחְדּוּתוֹ יִתְבָּרֵךְ כְּמוֹ הַסִּטְרָא אָחֳרָא שֶׁנִּקְרֵאת עֲבוֹדָה זָרָה, וְלָכֵן הַחוֹטֵא הֲרֵי מַחֲשַׁבְתּוֹ וְדִבּוּר וּמַעֲשֶׂה שֶׁלּוֹ וּכְלָלוּת נַפְשׁוֹ מְלוּבָּשִׁים בְּהַסִּטְרָא אָחֳרָא, וְהוּא גָרוּעַ מִמֶּנָּה שֶׁכּוֹפֵר בְּאַחְדּוּתוֹ יִתְבָּרֵךְ יוֹתֵר מִמֶּנָּה."],[4401900039,"<h2>מַאֲמָר ד.</h2>\nוְאַחַר כָּל זֶה יוּבַן דְּמַה שֶּׁהַיֵּצֶר הָרָע מְסִיתוֹ שֶׁגַּם אִם יַעֲשֶׂה מַעֲשֶׂה הָרָע אֵינוֹ נִפְרָד מֵאַחְדּוּתוֹ יִתְבָּרֵךְ, הוּא רַק רוּחַ שְׁטוּת הַמְכַסֶּה עַל הָאֱמֶת. וְזֶהוּ מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (סוֹטָה ג. א) עַל פָּסוּק כִּי תִשְׂטֶה אִשְׁתּוֹ אֵין אָדָם עוֹבֵר עֲבֵירָה אֶלָּא אִם כֵּן נִכְנַס בּוֹ רוּחַ שְׁטוּת, דַּאֲפִילוּ אִשָּׁה הַמְנָאֶפֶת שֶׁדַּעְתָּהּ קַלָּה הָיְתָה מוֹשֶׁלֶת בְּרוּחַ תַּאֲוָתָהּ לוּלֵי רוּחַ שְׁטוּת שֶׁבָּהּ הַמְכַסֶּה וּמַסְתִּיר וּמַעְלִים אֶת הָאַהֲבָה מְסוּתֶּרֶת שֶׁבְּנַפְשָׁהּ הָאֱלֹקִית לְדָבְקָה בֶּאֱמוּנַת ה' וְיִחוּדוֹ וְאַחְדּוּתוֹ וְלֹא לִיפָּרֵד חַס וְשָׁלוֹם מֵאַחְדּוּתוֹ אֲפִילוּ נוֹטְלִים אֶת נַפְשָׁהּ מִמֶּנָּה לַעֲבוֹד עֲבוֹדָה זָרָה חַס וְשָׁלוֹם (וּכְמוֹ שֶׁנִּתְבָּאֵר מַאֲמָר ב פֶּרֶק א שֶׁיֵּשׁ בְּטֶבַע בְּנִשְׁמוֹת יִשְׂרָאֵל שֶׁאֵינָם יְכוֹלִים לִהְיוֹת נִפְרָדִים מֵאֱלֹקוּת וְהַיְינוּ מִצַּד הָאַהֲבָה מְסוּתֶּרֶת שֶׁבָּהֶם, וְלָכֵן גַּם הַקַּל שֶׁבְּקַלִּים מוֹסֵר נַפְשׁוֹ עַל קִידּוּשׁ הַשֵּׁם כו' כַּנַ\"ל) וַאֲפִילוּ בְּהִשְׁתַּחֲוָאָה לְבַדָּהּ בְּלִי שׁוּם אֱמוּנָה בְלֵב כְּלָל, וְכָל שֶׁכֵּן לִכְבּוֹשׁ הַיֵּצֶר וְתַאֲוַת הַנִּיאוּף שֶׁהֵם יִסּוּרִים קַלִּים מִמִּיתָה ה' יִשְׁמְרֵנוּ, וְהַהֶפְרֵשׁ שֶׁאֶצְלָהּ בֵּין אִיסּוּר נִיאוּף לְאִיסּוּר הִשְׁתַּחֲוָאָה לַעֲבוֹדָה זָרָה הוּא גַם כֵּן שְׁטוּת דִּקְלִיפָּה הַמַּלְבֶּשֶׁת לְנֶפֶשׁ הָאֱלֹקִית,\nוְהַיְינוּ שֶׁנִּדְמֶה לָהּ דְּבָזֶה אֵינֶנָּה נַעֲשָׂה נִפְרָד מִיִּחוּדוֹ יִתְבָּרֵךְ וְעוֹדֶנָּה בְּיַהֲדוּתָהּ, אֲבָל בֶּאֱמֶת לַאֲמִתּוֹ אֲפִילוּ עֲבֵירָה קַלָּה הֲרֵי הָעוֹבְרָהּ עוֹבֵר עַל רָצוֹן הָעֶלְיוֹן בָּרוּךְ הוּא, וְהוּא בְּתַכְלִית הַפֵּירוּד מִיִּחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ יוֹתֵר מִסִּטְרָא אָחֳרָא וּקְלִיפָּה הַנִּקְרֵאת אֱלֹקִים אֲחֵרִים וַעֲבוֹדָה זָרָה מַמָּשׁ, וְיוֹתֵר מִכָּל הַדְּבָרִים הַנִּשְׁפָּעִים מִמֶּנָּה בָּעוֹלָם הַזֶּה, שֶׁהֵם בְּהֵמוֹת טְמֵאוֹת וְחַיּוֹת וְעוֹפוֹת טְמֵאִים וּשְׁקָצִים וּרְמָשִׂים,\nוּכְמַאֲמָר (סַנְהֶדְרִין לח. א) יַתּוּשׁ קְדָמָךְ, פֵּירוּשׁ דְּאַף יַתּוּשׁ שֶׁמַּכְנִיס וְאֵינוֹ מוֹצִיא שֶׁהִיא קְלִיפָּה הַיּוֹתֵר תַּחְתּוֹנָה וּרְחוֹקָה מִבְּחִינַת הַקְּדוּשָּׁה הַמַּשְׁפַּעַת בְּתַכְלִית הָרִיחוּק, קוֹדֶמֶת לְאִישׁ הַחוֹטֵא בְּהִשְׁתַּלְשְׁלוּת וִירִידַת הַחַיּוּת מֵרָצוֹן הָעֶלְיוֹן בָּרוּךְ הוּא (שֶׁהַחַיּוּת שֶׁל הָאִישׁ הַחוֹטֵא הוּא בִּבְחִינַת הֶסְתֵּר פָּנִים וּבִבְחִינַת רִיחוּק הַרְבֵּה יוֹתֵר מֵהַחַיּוּת הַנִּשְׁפָּע לְהַיַּתּוּשׁ) וְכָל שֶׁכֵּן שְׁאָר הַבַּעֲלֵי חַיִּים הַטְּמֵאִים וַאֲפִילוּ חַיּוֹת רָעוֹת, שֶׁכּוּלָּם אֵינָם מְשַׁנִּים תַּפְקִידָם וּפְקוּדָּתוֹ יִתְבָּרֵךְ שָׁמְרָה רוּחָם, וְאַף עַל גַּב דְּאִיהוּ לָא חָזֵי, כְּלוֹמַר בְּלִי הַרְגָּשָׁתָם, וּכְמוֹ שֶׁכָּתוּב (בְּרֵאשִׁית ט. ב) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וגו' וְכִדְפֵירְשׁוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (שַׁבָּת קנא. ב) אֵין חַיָּה רָעָה שׁוֹלֶטֶת בָּאָדָם עַד שֶׁנִּדְמֶה לָהּ כַּבְּהֵמָה, וְהַצַּדִּיקִים שֶׁאֵין צֶלֶם אֱלֹקִים מִסְתַּלֵּק מֵעַל פְּנֵיהֶם כָּל חַיּוֹת רָעוֹת אִתְכַּפְיָין קַמַּיְיהוּ, כְּמוֹ שֶׁכָּתוּב בְּזֹהַר גַּבֵּי דָּנִיֵּאל בְּגוֹב אֲרָיוֹת,\nוְאִם כֵּן הַחוֹטֵא וְעוֹבֵר רְצוֹנוֹ יִתְבָּרֵךְ אֲפִילוּ בַּעֲבֵירָה קַלָּה, בְּשַׁעַת מַעֲשֶׂה הוּא בְּתַכְלִית הָרִיחוּק מִקְּדוּשָּׁה הָעֶלְיוֹנָה שֶׁהִיא יִחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ, יוֹתֵר מִכָּל בַּעֲלֵי חַיִּים הַטְּמֵאִים וּשְׁקָצִים וּרְמָשִׂים הַמּוּשְׁפָּעִים מִסִּטְרָא אָחֳרָא וּקְלִיפַּת עֲבוֹדָה זָרָה.\n<b>וּלְבַד</b> כָּל הַנַ\"ל בִּבְחִינַת הַפֵּירוּד וְהָרִיחוּק מְאֹד שֶׁנַּעֲשֶׂה עַל יְדֵי מַעֲשֵׂה הָעֲבֵירָה רַחֲמָנָא לִצְּלָן, הִנֵּה עַל יְדֵי זֶה גַם כֵּן נִפְגָּם נַפְשׁוֹ וְנִפְסָק מֵאֱלֹקוּת וּכְמוֹ שֶׁכָּתוּב בְּאִגֶּרֶת הַתְּשׁוּבָה (פֶּרֶק ה) בְּפֵירוּשׁ יַעֲקֹב חֶבֶל נַחֲלָתוֹ, שֶׁהוּא חֶבֶל הַמְקַשֵּׁר הַנְּשָׁמָה לֵאלֹקוּת, וּכְמוֹ חֶבֶל שֶׁרֹאשׁוֹ אֶחָד קָשׁוּר לְמַעְלָה וְקָצֵהוּ לְמַטָּה, וְהוּא הַמְשָׁכַת הַנְּשָׁמָה מִשָּׁרְשָׁהּ מֵהֵ\"א תַתָּאָה דְּשֵׁם הוי', דְּמִשָּׁם נִמְשֶׁכֶת וְיוֹרֶדֶת לָעוֹלָם הַזֶּה לְהִתְלַבֵּשׁ בְּגוּף הָאָדָם כו'.\n<b>וּכְמוֹ</b> עַל דֶּרֶךְ מָשָׁל מֵחֶבֶל עָב שָׁזוּר מִתַּרְיַ\"ג חֲבָלִים דַּקִּים, כָּכָה חֶבֶל הַהַמְשָׁכָה הַנַ\"ל כָּלוּל מִתַּרְיַ\"ג מִצְוֹת וּכְשֶׁעוֹבֵר חַס וְשָׁלוֹם עַל אַחַת מֵהֵנָּה נִפְסָק חֶבֶל הַדַּק וּמִמֵּילָא נַעֲשָׂה חֲלִישׁוּת גַּם בִּכְלָלוּת הַחֶבֶל, וּבְחַיְּיבֵי כְרִיתוֹת רַחֲמָנָא לִצְּלָן נִפְסָק הַחֶבֶל לְגַמְרֵי וְנִכְרָת נַפְשׁוֹ רַחֲמָנָא לִצְּלָן, וְנִמְצָא מַה שֶּׁעַל יְדֵי הֲסָתָה הַנַ\"ל נִכְשָׁל בְּמַעֲשֵׂה הַחֵטְא הוּא רַק מִצַּד הָרוּחַ שְׁטוּת שֶׁמְּכַסֶּה וּמַעֲבִירוֹ עַל דַּעְתּוֹ, אֲבָל אִם לֹא הָיָה נִפְתֶּה לְפִתּוּי הַיֵּצֶר, וְהָיָה רוֹאֶה אֶת הָאֱמֶת כְּמוֹ שֶׁהוּא, שֶׁעַל יְדֵי מַעֲשֵׂה הַחֵטְא יִפָּרֵד מֵאַחְדּוּתוֹ יִתְבָּרֵךְ וְיִתְרַחֵק בְּתַכְלִית הָרִיחוּק בְּעִמְקֵי שְׁאוֹל לְמַטָּה מַּטָּה תַּחַת טוּמְאַת הַסִּטְרָא אָחֳרָא וּקְלִיפַּת עֲבוֹדָה זָרָה, ה' יִשְׁמְרֵנוּ, וְיִפָּגֵם נַפְשׁוֹ רַחֲמָנָא לִצְּלָן כַּנַ\"ל, הִנֵּה מִצַּד הָאַהֲבָה מְסוּתֶּרֶת שֶׁבּוֹ שֶׁאֵינוֹ יָכוֹל לִהְיוֹת נִפְרָד מֵאֱלֹקוּת לֹא הָיָה נִכְשָׁל כְּלָל בְּמַעֲשֵׂה הַחֵטְא בְּשׁוּם אוֹפֶן.\nקִיצּוּר.\nהַחוֹטֵא גָּרוּעַ מִיַּתּוּשׁ גַּם מִבַּעֲלֵי חַיִּים הַטְּמֵאִים וְחַיּוֹת רָעוֹת שֶׁשּׁוֹמְרִים פְּקוּדָּתוֹ יִתְבָּרֵךְ גַּם נֶגֶד טִבְעָם, נוֹסָף לָזֶה שֶׁהוּא נִפְרָד מֵאַחְדּוּתוֹ יִתְבָּרֵךְ וּפוֹגֵם בְּנִימֵי נִשְׁמָתוֹ בִּפְסִיקַת חוּט הַחֶבֶל וּלְסִבַּת הָרוּחַ שְׁטוּת אֵין הָאָדָם מַרְגִּישׁ בָּזֶה."],[4401900040,"<h2>מַאֲמָר ה.</h2>\nוְהִנֵּה מַה שֶּׁהַיֵּצֶר הָרָע מַבְטִיחוֹ שֶׁגַּם אִם יַעֲשֶׂה מַעֲשֶׂה הָרָע מִכָּל מָקוֹם טוֹב יִהְיֶה לוֹ, וּכְמוֹ שֶׁכָּתוּב (דְּבָרִים כט. יח) וְהִתְבָּרֵךְ בִּלְבָבוֹ לֵאמֹר גו', גַּם זֶה מִפִּתּוּי הַיֵּצֶר אֲשֶׁר נוֹפֶת תִּטּוֹפְנָה שִׂפְתֵי זָרָה גו' וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה (מִשְׁלֵי ה. ג-ד).\n<b>וְהִנֵּה</b> צָרִיךְ לְהַקְדִּים תְּחִלָּה פֵּירוּשׁ הַפָּסוּק וְהִתְבָּרֵךְ בִּלְבָבוֹ לֵאמֹר שָׁלוֹם יִהְיֶה לִּי כִּי בִּשְׁרִירוּת לִבִּי אֵלֵךְ לְמַעַן סְפוֹת הָרָוָה אֶת הַצְּמֵאָה וּמַשְׁמָעוּת הַפָּסוּק דְּכִי בִּשְׁרִירוּת לִבִּי הוּא נְתִינַת טַעַם עַל מַה שֶּׁכָּתוּב קוֹדֶם וְהִתְבָּרֵךְ בִּלְבָבוֹ, דְּמִשּׁוּם זֶה שָׁלוֹם יִהְיֶה לִּי לְפִי שֶׁבִּשְׁרִירוּת לִבִּי אֵלֵךְ, וְלִכְאוֹרָה אֵינוֹ מוּבָן כְּלָל, דְּאֵיךְ יְדַמֶּה בְנַפְשׁוֹ דְּדַוְקָא כַּאֲשֶׁר יֵלֵךְ בִּשְׁרִירוּת לִבּוֹ עַל יְדֵי זֶה יִהְיֶה שָׁלוֹם לוֹ, וְגַם מַהוּ פֵּירוּשׁ לְמַעַן סְפוֹת הָרָוָה כו'.\n<b>וְרַשִׁ\"י</b> (סַנְהֶדְרִין עו. ב) פֵּירֵשׁ סְפוֹת לְשׁוֹן חִיבּוּר, וּכְמוֹ סְפוּ שָׁנָה עַל שָׁנָה (יְשַׁעְיָה כט. א)\nוְהָרְדַ\"ק [רַבִּי דָּוִד קִמְחִי] פֵּירֵשׁ לְשׁוֹן תּוֹסֶפֶת וּכְמוֹ לִסְפּוֹת עוֹד (בַּמִּדְבָּר לב. יד) עֹלוֹתֵיכֶם סְפוּ עַל זִבְחֵיכֶם (יִרְמְיָה ז. כא)\nוּפֵירוּשׁ רָוָה וּצְמֵאָה פֵּרֵשׁ רַשִׁ\"י (שָׁם) רָוָה עַכּוּ\"ם [עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת] שֶׁשְּׂבֵעִים וְאֵינָן צְמֵאִים לְיוֹצְרָם. צְמֵאָה זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁצְּמֵאָה וּתְאֵבָה לְיִרְאַת יוֹצְרָהּ וּלְקַיֵּים מִצְוֹתָיו. וְהִנֵּה יָדוּעַ דִּכְנֶסֶת יִשְׂרָאֵל לְמַעְלָה שֶׁהוּא בְּחִינַת מַלְכוּת הִיא נִשְׁמוֹת יִשְׂרָאֵל שֶׁלְּמַטָּה וְנִקְרֵאת גַּם כֵּן הַצְּמֵאָה שֶׁצְּמֵאָה לְיוֹצְרָהּ.\n<b>וְהָעִנְיָן</b> הוּא דְּהִנֵּה בְּחִינַת מַלְכוּת הִיא מָקוֹר הַמְהַוֶּוה וּמְחַיֶּה עוֹלָמוֹת וּכְמוֹ שֶׁכָּתוּב (תְּהִלִּים קמה. יג) מַלְכוּתְךָ מַלְכוּת כָּל עוֹלָמִים, דְּכָל עוֹלָמִים שֹׁרֶשׁ הִתְהַוּוּתָם מִבְּחִינַת מַלְכוּת,\nוּכְתִיב (נְחֶמְיָה ט. ו) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם, וְאַתָּה הֵן הָאוֹתִיּוֹת מֵא' עַד ת', וְהֵן אוֹתִיּוֹת הַדִּבּוּר דִּבְחִינַת מַלְכוּת שֶׁמֵּהֶם נִמְשָׁךְ חַיּוּת הָעוֹלָמוֹת, וְאַל תִּקְרֵי מְחַיֶּה אֶלָּא מְהַוֶּוה כו' כְּמוֹ שֶׁכָּתוּב בְּמָקוֹם אַחֵר, וְיָדוּעַ דִּבְחִינָה זוֹ שֶׁהוּא מָקוֹר הַמְהַוֶּוה וּמְחַיֶּה עוֹלָמוֹת הוּא רַק הֶאָרָה לְבָד שֶׁבְּאֵין עֲרוֹךְ לְגַבֵּי עַצְמוּת, דַּהֲרֵי מֵעַצְמוּת אוֹר אֵין סוֹף לֹא הָיָה אֶפְשָׁר לִהְיוֹת הִתְהַוּוּת הָעוֹלָמוֹת וְנִבְרָאִים בַּעֲלֵי גְבוּל, לְפִי שֶׁגְּבוּל וּבִלְתִּי בַּעַל גְּבוּל הֵם בְּאֵין עֲרוֹךְ כְּלָל כו', וּכְמוֹ שֶׁכָּתוּב בְּכַמָּה דוּכְתֵּי בַּאֲרִיכוּת, כִּי אִם רַק מֵהֶאָרָה לְבָד נַעֲשׂוּ וְנִתְהַוּוּ הָעוֹלָמוֹת,\nוְזֶהוּ מַה שֶּׁבְּחִינַת מַלְכוּת הוּא בְּחִינַת שֵׁם, מֶלֶךְ שְׁמוֹ נִקְרָא עֲלֵיהֶם, דְּהַשֵּׁם הוּא רַק הֶאָרָה בִּלְבָד, וּכְמוֹ שֵׁם הָאָדָם שֶׁאֵינוֹ עַצְמוּת הָאָדָם, וּכְמוֹ כֵן בְּחִינַת הַחַיּוּת שֶׁל הָעוֹלָמוֹת הוּא רַק בְּחִינַת שֵׁם וְהֶאָרָה לְבָד.\nקִיצּוּר.\nמֵהֶמְשֵׁךְ הַכָּתוּב כִּי בִּשְׁרִירוּת לִבִּי אֵלֵךְ מַשְׁמָע שֶׁהוּא נְתִינַת טַעַם עַל וְהִתְבָּרֵךְ שָׁלוֹם יִהְיֶה לִּי, וּמַהוּ סְפוֹת הָרָוָה אֶת הַצְּמֵאָה, רָוָה עַכּוּ\"ם, צְמֵאָה נִשְׁמוֹת יִשְׂרָאֵל דְּשָׁרְשָׁם מִסְּפִירַת הַמַּלְכוּת מְקוֹר הָעוֹלָמוֹת וְהַנִּבְרָאִים, שֶׁהִיא הֶאָרָה לְבָד שֶׁבְּאֵין עֲרוֹךְ לְהָעַצְמוּת וְלָכֵן נִקְרֵאת שֵׁם."],[4401900041,"וְהִנֵּה לִהְיוֹת שֶׁהַמָּקוֹר לְהִתְהַוּוּת הָעוֹלָמוֹת הוּא רַק הֶאָרָה לְבָד וּמִתְּחִלָּה הָיְתָה הֶאָרָה הַזֹּאת כְּלוּלָה בִּמְקוֹרָהּ, שֶׁזֶּהוּ מַה דְּאִיתָא בְּפִרְקֵי דְרַבִּי אֱלִיעֶזֶר עַד שֶׁלֹּא נִבְרָא הָעוֹלָם הָיָה הוּא וּשְׁמוֹ בִּלְבָד, שֶׁזֶּהוּ בְּחִינַת הַשֵּׁם וְהַהֶאָרָה כְּמוֹ שֶׁהִיא כְלוּלָה בְּעַצְמוּת אוֹר אֵין סוֹף קוֹדֶם שֶׁנִּבְרָא הָעוֹלָם, וּלְאַחַר שֶׁנִּבְרָא הָעוֹלָם הוּא שֶׁנִּפְרַשׁ וְנִבְדַּל הֶאָרָה לְהַחֲיוֹת הָעוֹלָמוֹת, וְלָכֵן הֶאָרָה הַלֵּזוּ הִיא תָּמִיד בִּבְחִינַת רָצוֹא, לִהְיוֹת כִּי חֶפְצָהּ וּתְשׁוּקָתָהּ לִיכָּלֵל בְּאוֹר אֵין סוֹף מְקוֹרָהּ וְשָׁרְשָׁהּ,\nוּכְטֶבַע כָּל דָּבָר לִהְיוֹת רוֹצֶה לִיכָּלֵל בְּשָׁרְשׁוֹ, וּכְמוֹ טֶבַע הָאֵשׁ לַעֲלוֹת לְמַעְלָה לְשָׁרְשׁוֹ הָאֵשׁ הַיְסוֹדִי וְלָכֵן בִּלְתִּי שֶׁמֶן וּפְתִילָה אוֹ שְׁאָרֵי דְבָרִים הַמַּחֲזִיקִים אֶת הָאֵשׁ אִי אֶפְשָׁר לְהַחֲזִיק כְּלָל אֶת הָאֵשׁ, וְאַף גַּם שֶׁמַּחֲזִיקִים אוֹתוֹ עַל יְדֵי שֶׁמֶן וּפְתִילָה הִנֵּה הוּא תָּמִיד בַּעֲלִיּוֹת וִירִידוֹת, וּכְמוֹ כֵן הוּא בְּהַהֶאָרָה שֶׁמְּחַיָּה אֶת הָעוֹלָמוֹת לְפִי שֶׁהִיא הֶאָרָה בִּלְבָד, לָכֵן הִיא תָּמִיד בִּבְחִינַת רָצוֹא, וְלָכֵן נִקְרֵאת צְמֵאָה שֶׁהִיא צְמֵאָה תָמִיד לַעֲלוֹת לְמַעְלָה, וּכְמוֹ שֶׁכָּתוּב (תְּהִלִּים ל. יג) לְמַעַן יְזַמֶּרְךָ כָבוֹד וְלֹא יִדּוֹם נְהוֹרָא תַתָּאָה קָארֵי תָּדִיר לִנְהוֹרָא עִילָּאָה וְלָא שָׁכִיךְ\nוְזֶהוּ עִנְיַן הַצְּמֵאָה ה' צְמֵאָה, דִּבְחִינַת מַלְכוּת שֶׁהִיא בְּחִינַת ה' אַחֲרוֹנָה דְשֵׁם הוי', וְעַל זֶה אָמְרוּ בְּמִדְרָשׁ רַבָּה (בְּרֵאשִׁית פַּרְשָׁה יב) בְּהִבָּרְאָם בְּה' בְּרָאָם, הִנֵּה אוֹת ה' זֶה צְמֵאָה, שֶׁהִיא רוֹצָה וּמִשְׁתּוֹקֶקֶת תָּמִיד לַחֲזוֹר לְאַיִן וּלְהִכָּלֵל בְּשָׁרְשָׁהּ כו'. וְעַל זֶה נֶאֱמַר (יִרְמְיָה כג. כט) הֲלֹא כֹה דְבָרִי כָּאֵשׁ, דִּכְמוֹ טֶבַע הָאֵשׁ לַעֲלוֹת לְמַעְלָה כַּנַ\"ל, כְּמוֹ כֵן דְּבַר הוי' בְּחִינַת בְּה' בְּרָאָם הוּא רוֹצֶה לְהִסְתַּלֵּק לְמַעְלָה.\n<b>דְּהִנֵּה</b> אוֹת ה' לְמַעְלָה אֵינוֹ חַס וְשָׁלוֹם כְּדִבּוּר הָאָדָם שֶׁאֵין בּוֹ רָצוֹן, דְּהָאוֹתִיּוֹת לְמַטָּה הֵם דּוֹמְמִים שֶׁאֵין בָּהֶם מִצַּד עַצְמָם לֹא רָצוֹן וְלֹא חָכְמָה, וְהֵן רַק כֵּלִים לְבָד לְהִתְלַבֵּשׁ בָּהֶם אֵיזֶה כֹחַ כו', אֲבָל לְמַעְלָה חַס וְשָׁלוֹם לֵאמֹר כֵּן, אֶלָּא הַדִּבּוּר שֶׁלְּמַעְלָה יֵשׁ בְּהָאוֹתִיּוֹת רָצוֹן וְחָכְמָה, שֶׁהֲרֵי מִדִּבּוּר הָעֶלְיוֹן נִתְהַוָּוה מְקוֹר הַחָכְמָה שֶׁבְּגַן עֵדֶן הָעֶלְיוֹן וְהַיְינוּ מַה שֶּׁמַּלְכוּת דַּאֲצִילוּת נַעֲשָׂה עַתִּיק לִבְרִיאָה, וְכִדְאִיתָא בְּמִדְרָשׁ (אֵיכָה פּתִיחְתָּא כד) הָאוֹתִיּוֹת בָּאוּ לְהָעִיד כו' וְכִדְאִיתָא בְזֹהַר (הַקְדָּמַת הַזֹּהַר) שֶׁבָּאוּ הָאוֹתִיּוֹת לִבְרוֹא בָהֶן אֶת הָעוֹלָם כו' וּבְהַקְדָּמַת תִּקּוּנֵי זֹהַר בְּסוֹפָהּ אִיתָא וְהַמַּשְׂכִּילִים יַזְהִירוּ אִלֵּין אִינּוּן אַתְוָון דַּהֲוָה לוֹן שֵׂכֶל לְאַעָלָא קֳדָם מַלְכָּא כָּל חַד עַל תִּקּוּנֵיהּ כו' וּפֵירֵשׁ בְּכִסֵּא מֶלֶךְ שֶׁלָּכֵן נִקְרְאוּ הָאוֹתִיּוֹת מַשְׂכִּילִים עַיֵּן שָׁם.\n<b>וְלָכֵן</b> שַׁיָּיךְ לוֹמַר שֶׁהָאוֹת ה' רוֹצֶה לְהִסְתַּלֵּק וְלַעֲלוֹת לְמַעְלָה לְשָׁרְשׁוֹ. וְזֶהוּ דְּאִיתָא בְזֹהַר (חֵלֶק ג קצא. א) בְּשַׁעְתָּא דְּאִיהוּ גוֹ רְחִימוּ סַגִּיא כו' מִגּוֹ דְחִיקוּ דִרְחִימוּ דְּלָא יָכְלָא לְמִסְבַּל אַזְעֵירַת גַּרְמָהּ בִּזְעִירוּ סַגִּי עַד דְּלָא אִתְחֲזִיאַת מִינָּהּ אֶלָּא זְעִירוּ דִּנְקוּדָּא חֲדָא וּמַאי אִיהִי יוּ\"ד, וְהַיְינוּ שֶׁמֵּהֵ\"א נַעֲשֶׂה יוּ\"ד וְהַיּוּ\"ד זֶהוּ עִנְיַן הִתְכַּלְלוּתוֹ בְּאַיִן.\nקִיצּוּר.\nעַד שֶׁלֹּא נִבְרָא הָעוֹלָם הָיָה הוּא וּשְׁמוֹ בִּלְבָד, שֶׁמְּקוֹר חַיּוּת הָעוֹלָמוֹת וְהַנִּבְרָאִים כָּלוּל בִּמְקוֹרוֹ, לָכֵן כְּשֶׁמִּתְגַּלֶּה לְהַחֲיוֹת הִנֵּה הוּא תָּמִיד בְּטֶבַע הָרָצוֹא כְּטֶבַע הָאֵשׁ לַעֲלוֹת, וְזֶהוּ הַצְּמֵאָה ה' צְמֵאָה, שֶׁהָאוֹתִיּוֹת שֶׁלְּמַעְלָה יֵשׁ בָּהֶם רָצוֹן וְחָכְמָה."],[4401900042,"וְעוֹד יֵשׁ טַעַם לְסִבַּת הַצִּמָּאוֹן דִּבְחִינַת מַלְכוּת מִצַּד הַיְרִידָה שֶׁיָּרְדָה לִהְיוֹת מָקוֹר לְנִבְרָאִים שֶׁלְּמַטָּה, מִשּׁוּם זֶה נַעֲשֶׂה בָּהּ תּוֹקֶף הָרָצוֹא וְהַצִּמָּאוֹן לַעֲלוֹת מִירִידָתָהּ. וְזֶהוּ גַּם כֵּן עִנְיַן מַה שֶּׁכָּתוּב בְּזֹהַר (שָׁם) דְּמֵהֵ\"א נַעֲשֶׂה יוּ\"ד, כִּי בְּיוּ\"ד נִבְרָא עוֹלָם הַבָּא, וְהַיְינוּ שֶׁהַיּוּ\"ד הוּא מְקוֹר חַיֵּי הַנְּשָׁמוֹת וְלֹא חַיֵּי הַגּוּפִים, וְלָכֵן אוֹת ה' שֶׁיָּרַד לִהְיוֹת מְקוֹר חַיֵּי עוֹלָם הַזֶּה, שֶׁהוּא חַיֵּי הַגּוּפִים רְצוֹנוֹ לְהִסְתַּלֵּק מִירִידָה זוֹ לְשָׁרְשָׁהּ,\nוַהֲרֵי זֶה עַל דֶּרֶךְ מַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה מַיִם תַּחְתּוֹנִים בּוֹכִין אֲנַן בָּעִינַן לְמֶהֱוֵי קֳדָם מַלְכָּא, דְּמַיִם מַצְמִיחִים כָּל מִינֵי תַעֲנוּג, וּבְחִינַת מַיִם תַּחְתּוֹנִים הַיְינוּ שֶׁהֵן מְקוֹר הַתַּעֲנוּגים גַּשְׁמִים, שֶׁזֶּהוּ יְרִידָה גְדוֹלָה לְהָאוֹר הָאֱלֹקִי לִהְיוֹת מָקוֹר לְתַעֲנוּגִים גַּשְׁמִים, וְלָכֵן הֲרֵי הֵן בּוֹכִין עַל יְרִידָתָן וְרוֹצִים לִהְיוֹת קֳדָם מַלְכָּא לַעֲלוֹת מִירִידָתָן לְמַעְלָה כו'.\n<b>כִּי</b> הִנֵּה אוֹת ה' שֶׁהוּא חַיּוּת כָּל הָעוֹלָמוֹת נִקְרָא שְׁכִינָה לְפִי שֶׁיּוֹרֶדֶת וּמִתְלַבֶּשֶׁת בִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה, וּכְמוֹ שֶׁכָּתוּב (שְׁמוֹת כה. ח) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם, הַיְינוּ שֶׁבְּהֵיכַל קֹדֶשׁ הַקֳּדָשִׁים הָיָה עִיקַּר הַגִּילּוּי וּמִשָּׁם נִמְשָׁךְ הֶאָרָתָהּ לְהַחֲיוֹת כָּל הָעוֹלָם,\nוּכְמוֹ עַל דֶּרֶךְ מָשָׁל חַיּוּת הַנְּשָׁמָה הַמְחַיָּה אֶת הַגּוּף עִיקַּר הַשְׁרָאָתָהּ הוּא בְּהַלֵּב, וּמִשָּׁם נִמְשָׁךְ לְכָל רְמַ\"ח אֵבָרִים, וְהֵיכַל קֹדֶשׁ הַקֳּדָשִׁים הוּא הַלֵּב שֶׁל כָּל הָעוֹלָם, כְּמוֹ שֶׁכָּתוּב בְּזֹהַר (חֵלֶק ג קסא. ב) עַל כֵּן הָיָה בוֹ הַשְׁרָאַת הַשְּׁכִינָה, וְכֵן בְּהֵיכַל קֹדֶשׁ הַקֳּדָשִׁים דִּבְרִיאָה יְצִירָה וַעֲשִׂיָּה כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר שֶׁל בֵּינוֹנִים פֶּרֶק נ\"ב.\n<b>וְזֶהוּ</b> עִנְיַן לְכִי וּמַעֲטִי אֶת עַצְמֵךְ (חוּלִּין ס. ב), שֶׁהַמִּיעוּט הוּא עִנְיַן יְרִידָתָהּ לִהְיוֹת רֹאשׁ לַשּׁוּעָלִים לֵירֵד בִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה וּלְהַחֲיוֹתָם, וְלֹא רָצְתָה לֵירֵד וּלְמַעֵט אֶת עַצְמָהּ מֵחֲמַת שֶׁהָעוֹלָמוֹת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה הֵם מְעוֹרָבִים טוֹב וָרָע, וּמַה גַּם בַּעֲשִׂיָּה שֶׁהַבְּחִירָה נִיתְּנָה לָאָדָם וְיוּכַל חַס וְשָׁלוֹם לִבְחוֹר גַּם בָּרָע וְעַל יְדֵי זֶה יָכוֹל לְהַמְשִׁיךְ גַּם כֵּן חַיּוּת אֱלֹקוּת בְּכָל הַדְּבָרִים עַל דֶּרֶךְ רַגְלֶיהָ יוֹרְדוֹת מָוֶת (מִשְׁלֵי ה. ה) וּכְתִיב (וַיִּקְרָא טז. טז) הַשֹּׁכֵן אִתָּם בְּתוֹךְ טֻמְאֹתָם. וְעַל כֵּן נֶאֱמַר (שָׁם) וְכִפֶּר עַל הַקֹּדֶשׁ מִטּוּמְאֹת בְּנֵי יִשְׂרָאֵל. וְזֶהוּ אֶת מִשְׁכַּן ה' טִמֵּא (בַּמִּדְבָּר יט. יג). (וְעַיֵּן מַה שֶּׁכָּתוּב בְּזֹהַר חֵלֶק ג עט. א-ב)\nוְזֶהוּ עִנְיַן גָּלוּת הַשְּׁכִינָה שֶׁנַּעֲשָׂה עַל יְדֵי מַעֲשִׂים הָרָעִים שֶׁל הָאָדָם לְמַטָּה, וּכְמוֹ שֶׁכָּתוּב (יְשַׁעְיָה נ. א) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. דְּהַיְינוּ שֶׁיָּרְדָה הַשְׁפָּעַת בְּחִינַת ה' הַנַ\"ל, וְנִשְׁתַּלְשְׁלָה מִמַּדְרֵיגָה לְמַדְרֵיגָה לְמַטָּה מַּטָּה עַד שֶׁנִּתְלַבְּשָׁה הַשְׁפָּעָתָהּ בְּי' סְפִירוֹת דְּנוֹגַהּ, הַמַּשְׁפַּעַת שֶׁפַע וְחַיּוּת עַל יְדֵי הַמַּזָּלוֹת וְכָל צְבָא הַשָּׁמַיִם וְהַשָּׂרִים שֶׁעֲלֵיהֶם לְכָל חַי הַגַּשְׁמִי שֶׁבָּעוֹלָם הַזֶּה כו'. וּמִשּׁוּם זֶה לֹא רָצְתָה לֵירֵד וּלְמַעֵט אֶת עַצְמָהּ.\nקִיצּוּר.\nאוֹת י' מְקוֹר חַיֵּי הַנְּשָׁמוֹת, אוֹת ה' מְקוֹר חַיּוּת הָעוֹלָמוֹת נִקְרֵאת שְׁכִינָה, הֵיכַל קֹדֶשׁ הַקֳּדָשִׁים לֵב הָעוֹלָם, לְכִי וּמַעֲטִי עַצְמֵךְ וְלָרֶדֶת בְּמַדְרֵיגוֹת הַיּוֹתֵר נְמוּכוֹת, וּמִזֶּה נַעֲשֶׂה תּוֹקֶף הָרָצוֹא, וְעַל יְדֵי מַעֲשֶׂה רָע גּוֹרְמִים גָּלוּת הַשְּׁכִינָה."],[4401900043,"<h2>מַאֲמָר ו.</h2>\nוְהִנֵּה הַפִּיּוּס עַל זֶה שֶׁאָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְכִי וּמַעֲטִי אֶת עַצְמֵךְ הוּא צַדִּיקִים יִקָּרְאוּ עַל שְׁמֵךְ, שְׁמוּאֵל הַקָּטָן, דָּוִד הַקָּטָן. וְהָעִנְיָן הוּא דִּכְמוֹ כֵן בִּירִידַת הַנְּשָׁמָה לְהִתְלַבֵּשׁ בַּגּוּף וְנֶפֶשׁ הַבַּהֲמִית אֲשֶׁר הוּא עָלוּל לְהִתְגָּאֵל כו' וְכָל הַדְּרָכִים בְּחֶזְקַת סַכָּנָה, כִּי לַפֶּתַח חַטָּאת רוֹבֵץ, וְאַף עַל פִּי כֵן כְּדַאי יְרִידָה זוֹ בִּשְׁבִיל הָעֲלִיָּה הַנִּפְלָאָה שֶׁנַּעֲשָׂה עַל יְדֵי זֶה,\nשֶׁעַל יְדֵי שֶׁהוּא מְלוּבָּשׁ בַּגּוּף וְנֶפֶשׁ הַבַּהֲמִית, אֲשֶׁר עָלוּל לְהִתְגָּאֵל חַס וְשָׁלוֹם וּמִכָּל מָקוֹם עוֹמֵד בְּנִסָּיוֹן בְּכָל פְּרָט וְכוֹבֵשׁ רוּחַ תַּאֲוָתוֹ, שֶׁאֵינוֹ נִמְשָׁךְ אַחַר הֲסָתַת הַיֵּצֶר וְהוּא נִזְהָר בְּסוּר מֵרָע וַעֲשֵׂה טוֹב בְּכָל פְּרָטֵיהֶן וְדִקְדּוּקֵיהֶן, וְעִנְיְנֵי הָעוֹלָם הַזֶּה אֵינָם מוֹנְעִים וּמְעַכְּבִים אוֹתוֹ מִתּוֹרָה וַעֲבוֹדָה, אַדְרַבָּא, כָּל עִנְיָנָיו הַגַּשְׁמִים שֶׁמּוּכְרָח בָּהֶם הֵם בְּכַוָּונָה לְשֵׁם שָׁמַיִם, כְּמוֹ בַּאֲכִילָה שֶׁאֵינָהּ לְמַלֹּאות תַּאֲוַת נַפְשׁוֹ כִּי אִם לְקִיּוּם גּוּפוֹ, וּבִכְדֵי שֶׁבְּכֹחַ הָאֲכִילָה הַהִיא יוּכַל לִלְמוֹד וּלְהִתְפַּלֵּל וְהוּא לוֹמֵד וּמִתְפַּלֵּל בֶּאֱמֶת, וְכֵן בְּעֵסֶק מַשָּׂא וּמַתָּן, שֶׁעוֹשֶׂה כָּל דָּבָר בְּתַכְלִית הַהֶכְשֵׁר, וְאֵינוֹ מְשׁוּקָּע וּמוּטְרָד בָּזֶה, בְּאוֹפֶן שֶׁאֵינוֹ מוֹנֵעַ אוֹתוֹ מִתּוֹרָה וּתְפִלָּה, וְכַוָּונַת הַמַּשָּׂא וּמַתָּן הוּא כְּדֵי לְהַרְוִיחַ וְלִיתֵּן צְדָקָה וְשֶׁיִּהְיֶה לוֹ פְּנַאי לַעֲסוֹק בְּתוֹרָה וַעֲבוֹדָה,\nעַל יְדֵי זֶה נַעֲשָׂה עֲלִיָּה בְּהַנְּשָׁמָה הַרְבֵּה יוֹתֵר מִכְּמוֹ שֶׁהָיְתָה קוֹדֶם הִתְלַבְּשׁוּתָהּ בַּגּוּף וְנֶפֶשׁ הַבַּהֲמִית, שֶׁלֹּא הָיָה לָהּ דְּבָרִים הַמּוֹנְעִים כְּלָל וְלֹא יָדְעָה כְּלָל מֵהַהֵיפֶךְ, וּמִמֵּילָא לֹא הָיָה עֲבוֹדָה כְּלָל, וּבְהִתְלַבְּשׁוּתָהּ בַּגּוּף כְּשֶׁעוֹבֶדֶת עֲבוֹדָתָהּ לְהַכְנִיעַ אֶת הַגּוּף וְהַנֶּפֶשׁ הַבַּהֲמִית לִהְיוֹת שָׁלֵם בַּעֲבוֹדָתָהּ כַּנַ\"ל, עַל יְדֵי זֶה נַעֲשָׂה עֲלִיָּה גְדוֹלָה לְהַנְּשָׁמָה וְנַעֲשָׂה מִזֶּה תַּעֲנוּג גָּדוֹל לְמַעְלָה, וּכְמוֹ שֶׁכָּתוּב (בְּרֵאשִׁית כא. ו) צְחֹק עָשָׂה לִי אֱלֹקִים, דְּדַוְקָא עַל יְדֵי שֵׁם אֱלֹקִים, שֶׁעַל יְדֵי זֶה נַעֲשָׂה מְצִיאוּת הַיֵּשׁ וְכָל עִנְיְנֵי הָעוֹלָם הַגַּשְׁמִי וְהַחוּמְרִי אֲשֶׁר הַכֹּל הוּא מִשֵּׁם אֱלֹקִים, כְּמוֹ שֶׁכָּתוּב (בְּרֵאשִׁית א. א) בְּרֵאשִׁית בָּרָא אֱלֹקִים, וְכֵן הַנֶּפֶשׁ הַבַּהֲמִית שָׁרְשׁוֹ מִשֵּׁם אֱלֹקִים כְּיָדוּעַ וּמְבוֹאָר בְּמָקוֹם אַחֵר, הִנֵּה עַל יְדֵי עֲבוֹדָה לְמַטָּה בְּהַכְנָעַת הַחוֹמֶר בְּכָל הָעִנְיָנִים הַגַּשְׁמִים, וְלִהְיוֹת סוּר מֵרָע וַעֲשֵׂה טוֹב בְּפוֹעַל מַמָּשׁ מִזֶּה דַוְקָא נַעֲשֶׂה הַצְּחוֹק וְהַתַּעֲנוּג הָעֶלְיוֹן,\nוּכְמוֹ כֵן הוּא בִּבְחִינַת מַלְכוּת שֶׁעַל יְדֵי יְרִידָתָהּ לִבְרִיאָה-יְצִירָה-עֲשִׂיָּה, הֲרֵי הִיא מְבָרֶרֶת בֵּירוּרִים דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה, בְּדוּגְמָא כְּמוֹ שֶׁהִתְלַבְּשׁוּת הַנְּשָׁמָה בַּגּוּף שֶׁפּוֹעֶלֶת הַהַכְנָעָה וְהַבִּיטּוּל כַּנַ\"ל כְּמוֹ כֵן הוּא בְּהִתְלַבְּשׁוּת דִּבְחִינַת מַלְכוּת בִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה, הִיא מְבָרֶרֶת בֵּירוּרִים דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה. וּכְמוֹ שֶׁכָּתוּב (מִשְׁלֵי לא. טו) וַתִּתֵּן טֶרֶף לְבֵיתָהּ, טֶרֶ\"ף בְּגִימַטְרִיָּא רפ\"ח עִם הַכּוֹלֵל, וְהַיְינוּ שֶׁמְּבָרֶרֶת הָרפ\"ח נִיצוֹצוֹת בִּירִידָתָהּ לְמַטָּה,\nוְעַל יְדֵי זֶה נִתּוֹסֵף בָּהּ רִיבּוּי אוֹר עַד שֶׁלֶּעָתִיד תִּהְיֶה אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ, שֶׁבְּחִינַת מַלְכוּת תִּהְיֶה בִּבְחִינַת מַשְׁפִּיעַ בְּהַסְּפִירוֹת שֶׁלְּמַעְלָה. וּכְמוֹ שֶׁכָּתוּב (זְכַרְיָה יד. ח) וְהָיָה בַּיּוֹם הַהוּא יֵצְאוּ מַיִם חַיִּים מִירוּשָׁלַיִם (בְּחִינַת מַלְכוּת) חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי (יַם הַחָכְמָה) כו' וְזֶה יִהְיֶה בִּגְמַר הַבֵּירוּרִים שֶׁיִּתְבָּרְרוּ עוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה.\nקִיצּוּר.\nעַל יְדֵי יְרִידַת הַנְּשָׁמָה לְהִתְלַבֵּשׁ בַּגּוּף וְנֶפֶשׁ הַבַּהֲמִית שֶׁעָלוּל לְהִתְגָּאֵל גַּם בִּדְבָרִים אֲסוּרִים וְעוֹמֵד בְּנִסָּיוֹן, דְּכָל עִנְיָנִים הַגַּשְׁמִים שֶׁמּוּכְרָח בָּהֶם יִהְיוּ לְשֵׁם שָׁמַיִם, נַעֲשָׂה הָעֲלִיָּה בְּהַנְּשָׁמָה וְתַעֲנוּג לְמַעְלָה, וְכֵן הוּא בִּסְפִירַת הַמַּלְכוּת שֶׁעַל יְדֵי הַבֵּירוּרִים שֶׁלְּמַטָּה נִתּוֹסֵף בָּהּ רִיבּוּי אוֹר."],[4401900044,"אָמְנָם עַכְשָׁיו הִנֵּה סְפִירַת הַמַּלְכוּת הִיא צְמֵאָה, מִצַּד יְרִידָתָהּ שֶׁיָּרְדָה וְנִתְלַבְּשָׁה בִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה הִיא בִּבְחִינַת צִמָּאוֹן לַעֲלוֹת מִירִידָתָהּ וְלִיכָּלֵל בְּשָׁרְשָׁהּ, וְכֵן הוּא גַּם בַּנְּשָׁמוֹת, שֶׁעַל יְדֵי הִתְלַבְּשׁוּתָם בַּגּוּף וְנֶפֶשׁ הַבַּהֲמִית, שֶׁיָּרְדָה הַנְּשָׁמָה מִמַּדְרֵיגָתָהּ מִכְּמוֹ שֶׁהָיְתָה קוֹדֶם הִתְלַבְּשׁוּתָהּ בַּגּוּף, שֶׁהָיְתָה בִּבְחִינַת תַּכְלִית הָרוּחָנִיּוּת וְלֹא הָיְתָה שַׁיֶּיכֶת לְיֵשׁוּת וְגַשְׁמִיּוּת כְּלָל וּכְלָל, וּמִכָּל שֶׁכֵּן שֶׁלֹּא הָיְתָה עֲלוּלָה חַס וְשָׁלוֹם לֵירֵד וּלְהִתְגָּאֵל לִהְיוֹת הֵיפֶךְ מֵאֱלֹקוּת חַס וְשָׁלוֹם, וּבִירִידָתָהּ בַּגּוּף הֲרֵי גַם כְּשֶׁעוֹבֶדֶת עֲבוֹדָתָהּ כַּנַ\"ל וּפוֹעֶלֶת הַכְנָעַת הַחוֹמֶר וּבִיטּוּל הַיֵּשׁ מִכָּל מָקוֹם הֲרֵי הִיא שַׁיָּיכָה לְיֵשׁוּת וְגַשְׁמִיּוּת, שֶׁהֲרֵי הִיא בִּבְחִינַת הִתְלַבְּשׁוּת מַמָּשׁ בְּנֶפֶשׁ הַבַּהֲמִית,\nוּכְמוֹ שֶׁפּוֹעֶלֶת פְּעוּלּוֹת גַּשְׁמִיּוֹת לְהַשְׂכִּיל בְּעִנְיָנִים גַּשְׁמִים, וְהַשְׂכָּלָה וְהַשָּׂגָה גַּשְׁמִיּוֹת, שֶׁכָּל זֶה לֹא הָיָה בָהּ קוֹדֶם הִתְלַבְּשׁוּתָהּ בַּגּוּף שֶׁהָיָה הַשְׂכָּלָתָהּ וְהַשָּׂגָתָהּ בְּתַכְלִית הָרוּחָנִיּוּת וְהַדַּקּוּת, וּבְעִנְיָנִים רוּחָנִיִּים וְנַעֲלִים מְאֹד, וְעִנְיָנִים גַּשְׁמִים, רְצוֹנִי לוֹמַר, גַּם עִנְיָנִים שִׂכְלִים אֶלָּא שֶׁהֵם גַּשְׁמִים לֹא יָדְעָה מִזֶּה כְּלָל, וּבִירִידָתָהּ בַּגּוּף הֲרֵי הַשָּׂגָתָהּ הִיא בְהַגְשָׁמָה, וּמַשֶּׂגֶת עִנְיָנִים וְשִׂכְלִים גַּשְׁמִים, וְכָל זֶה הוּא מִצַּד הַהִתְלַבְּשׁוּת בְּנֶפֶשׁ הַטִּבְעִי הַבַּהֲמִי, כְּמוֹ כֵן מִצַּד זֶה בִּכְלָלוּתָהּ נַעֲשָׂה לָהּ שַׁיָּיכוּת לְיֵשׁוּת וְגַשְׁמִיּוּת, אֲשֶׁר מִקּוֹדֶם לֹא הָיְתָה לָהּ שַׁיָּיכוּת לָזֶה כְּלָל, עַד שֶׁיָּכוֹל לִהְיוֹת חַס וְשָׁלוֹם יְרִידָה מַמָּשׁ לְהִתְגָּאֵל חַס וְשָׁלוֹם,\nוּמִשּׁוּם זֶה נַעֲשָׂה תּוֹקֶף הַצִּמָּאוֹן בְּהַנְּשָׁמָה לַעֲלוֹת מִירִידָתָהּ וּלְהִכָּלֵל לְמַעְלָה, שֶׁהַצִּמָּאוֹן הַזֶּה גַּם כֵּן לֹא הָיָה בְּהַנְּשָׁמָה קוֹדֶם, אֶלָּא דַּוְקָא עַל יְדֵי יְרִידָתָהּ בַּגּוּף וְנֶפֶשׁ הַבַּהֲמִית מִצַּד הַיְרִידָה כַּנַ\"ל נַעֲשֶׂה בָּהּ תּוֹקֶף הָרָצוֹא וְהַצִּמָּאוֹן,\nוּכְמוֹ כֵן הוּא בִּבְחִינַת מַלְכוּת, שֶׁעַל יְדֵי יְרִידָתָהּ לִבְרִיאָה-יְצִירָה-עֲשִׂיָּה עַל יְדֵי זֶה הִיא בִּבְחִינַת צִמָּאוֹן לַעֲלוֹת לְמַעְלָה כו'.\n<b>וְרָוָה</b> נִקְרָא מַה שֶּׁרוֹצֶה לְמַלֹּאות תַּאֲוָתוֹ הַגַּשְׁמִית וְאֵין לוֹ רָצוֹן וְצִמָּאוֹן לֵאלֹקוּת, כִּי אִם עִיקַּר חֶפְצוֹ וְחֶשְׁקוֹ הוּא בְּתַעֲנוּגִים גַּשְׁמִים וּבָהֶם מְרַוֶּה צִמְאוֹנוֹ, וְגַם יָכוֹל לְרַוּוֹת צִמְאוֹנוֹ בָּזֶה לְפִי שֶׁהֵן מְזוּמָּנִים לְפָנָיו, כִּי הַנֶּפֶשׁ הָאֱלֹקִית צִמְאוֹנָהּ וְחֶשְׁקָהּ לֵאלֹקוּת וְאֵינָהּ מְרַוָּוה צִמְאוֹנָהּ חַס וְשָׁלוֹם בִּדְבָרִים הַגַּשְׁמִים כִּי אִם חֶפְצָהּ וְחֶשְׁקָהּ לֵאלֹקוּת, וַהֲרֵי הִיא בִּבְחִינַת צְמֵאָה בִּירִידָתָהּ לְמַטָּה וְתָמִיד הִיא בְּצִמָּאוֹן זֶה וְלֹא תוּכַל לְרַוּוֹת צִמְאוֹנָהּ, כִּי אֱלֹקוּת אֵינוֹ מֵאִיר וּמִתְגַּלֶּה עַתָּה בְּגִילּוּי מַמָּשׁ כִּי אִם בְּדֶרֶךְ יְדִיעַת הַמְּצִיאוּת לֹא הַשָּׂגַת הַמַּהוּת מַמָּשׁ, עַד לֶעָתִיד לָבֹא דִּכְתִיב (יְשַׁעְיָה ל. כ) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ, שֶׁאָז יִתְגַּלֶּה בְּחִינַת הַמַּהוּת מַמָּשׁ, אֲבָל עַתָּה אֵינוֹ מִתְגַּלֶּה הַמַּהוּת, וְלָכֵן הִיא בִּבְחִינַת צְמֵאָה תָּמִיד,\nאֲבָל הַנֶּפֶשׁ הַבַּהֲמִית חֶשְׁקָהּ וְצִמְאוֹנָהּ לִדְבָרִים גַּשְׁמִיִּים וּבָזֶה הִיא מְרַוָּוה צִמְאוֹנָהּ וּבְאֶפְשָׁרָהּ לְרַוּוֹת צִמְאוֹנָהּ בָּזֶה שֶׁמְּזוּמָּנִים לְפָנֶיהָ, וְעַל דֶּרֶךְ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (שַׁבָּת קנה. ב) לֵית עַתִּיר מֵחֲזִירָא, לְפִי שֶׁמַּאֲכָלוֹ פְּסוֹלֶת, וְלָכֵן מַאֲכָלוֹ מוּכָן וּמְזוּמָּן לְפָנָיו תָּמִיד וּבְנָקָל לְהַשִּׂיג מְבוּקָּשׁוֹ וְתַאֲוָותוֹ, וּכְמוֹ כֵן הוּא בַּתַּעֲנוּגִים הַגַּשְׁמִים דְּיָדוּעַ שֶׁהֵן פְּסוֹלֶת הַתַּעֲנוּגִים הָעֶלְיוֹנִים וּבְנָקָל לְהַשִּׂיגָם וּמְרַוָּוה צִמְאוֹנָהּ וְעַל כֵּן נִקְרָא רָוָה.\nקִיצּוּר.\nסְפִירַת הַמַּלְכוּת בִּירִידָתָהּ מִתְגַּבֵּר צִמְאוֹן הַהִתְכַּלְלוּת בִּמְקוֹרָהּ, הַנְּשָׁמוֹת לְמַעְלָה הֵן בְּתַכְלִית הָרוּחָנִיּוּת, וּמוּשְׁלָלָה גַּם מִידִיעַת מוּשְׂכָּלוֹת הָעֲמוּקִים הַסְּבוּכִים בְּגֶשֶׁם, וּבִירִידָתָהּ בַּגּוּף הִיא שַׁיֶּיכֶת לְיֵשׁוּת וִיכוֹלָה לְהִתְגָּאֵל אָז מִתְגַּבֵּר הַצִּמָּאוֹן, אֲבָל הַנֶּפֶשׁ הַבַּהֲמִית שֶׁעִיקָּרוֹ חוּמְרִיּוּת נִקְרָא רָוָה."],[4401900045,"וְזֶהוּ וְהִתְבָּרֵךְ בִּלְבָבוֹ לֵאמֹר שָׁלוֹם יִהְיֶה לִּי, אַף עַל פִּי שֶׁבִּשְׁרִירוּת לִבִּי אֵלֵךְ מִכָּל מָקוֹם שָׁלוֹם יִהְיֶה לִּי לְמַעַן סְפוֹת הָרָוָה אֶת הַצְּמֵאָה, שֶׁיְּחַבֵּר הָרָוָה אֶל הַצְּמֵאָה וְהַיְינוּ שֶׁיַּמְשִׁיךְ חַיּוּת מִצְּמֵאָה לָרָוָה בְּסוֹד רַגְלֶיהָ יוֹרְדוֹת מָוֶת, וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר ה פֶּרֶק ג) שֶׁמּוֹרִידִים בְּחִינַת הַהַשְׁפָּעָה מֵהֵ\"א תַתָּאָה, בְּחִינַת ה' דְּהַצְּמֵאָה אֶל הַי' סְפִירוֹת דְּנוֹגַהּ, וְנִמְשָׁךְ הַשֶּׁפַע וּמִתְלַבֶּשֶׁת בְּהָע' שָׂרִים שֶׁזֶּהוּ בְּחִינַת רָוָה, וּמִשָּׁם נִמְשָׁךְ הַהַשְׁפָּעָה גַּם לְאִישׁ הַחוֹטֵא,\nוּכְמוֹ שֶׁכָּתוּב בְּאִגֶּרֶת הַתְּשׁוּבָה (פֶּרֶק ו) דִּלְאַחַר הַחוּרְבָּן שֶׁגָּרְמוּ בַּעֲווֹנוֹתֵיהֶם שֶׁיָּרְדָה הַשְׁפָּעַת בְּחִינַת ה' תַתָּאָה כַּנַ\"ל, אֲזַי יָכוֹל גַּם הַחוֹטֵא וּפוֹשְׁעֵי יִשְׂרָאֵל לְקַבֵּל חַיּוּת לְגוּפָם וְנַפְשָׁם הַבַּהֲמִית כְּמוֹ שְׁאָרֵי בַּעֲלֵי חַיִּים מַמָּשׁ כְּמוֹ שֶׁכָּתוּב (תְּהִלִּים מט. יג) נִמְשַׁל כַּבְּהֵמוֹת נִדְמוּ,\nוּבֶאֱמֶת אֶפְשָׁר שֶׁיִּהְיֶה לוֹ שָׁלוֹם, אֲבָל זֶה אֵינוֹ כִּי אִם בְּעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁהֵם מְקַבְּלִים שִׁפְעוֹ יִתְבָּרֵךְ מֵאֲחוֹרַיִים, כְּמַאן דְּשָׁדֵי בָּתַר כַּתְפּוֹי אֲבָל עַל יִשְׂרָאֵל נֶאֱמַר לֹא יֹאבֶה ה' סְלוֹחַ לוֹ, דְּהַיְינוּ הַמְשָׁכַת הָרָצוֹן וּכְיָדוּעַ שֶׁזֶּהוּ עִנְיַן הַסְּלִיחָה שֶׁהוּא הַמְשָׁכַת וְהַטָּיַית הָרָצוֹן אֵלָיו. וְעַל זֶה אוֹמֵר לֹא יֹאבֶה ה' סְלוֹחַ לוֹ, כִּי אַדְרַבָּא אָז יֶעְשַׁן אַף ה' וְקִנְאָתוֹ כו' וְהַיְינוּ שֶׁנִּמְשָׁךְ עָלָיו הַכַּעַס שֶׁהוּא סִילּוּק הָרָצוֹן מִמֶּנּוּ רַחֲמָנָא לִצְּלָן,\nוַהֲגַם שֶׁבְּאִגֶּרֶת הַתְּשׁוּבָה פֶּרֶק הַנַ\"ל כָּתוּב שֶׁהָאִישׁ הַחוֹטֵא יָכוֹל גַּם כֵּן לְקַבֵּל חַיּוּת כו', וּמְבוֹאָר שָׁם בְּסוֹף הַפֶּרֶק דְּמִפְּנֵי שֶׁהוּא הוּא הַמַּמְשִׁיךְ לָהֶם הַהַשְׁפָּעָה לָכֵן הוּא נוֹטֵל חֵלֶק בָּרֹאשׁ, וּמִכָּל מָקוֹם יֵשׁ לוֹמַר דְּסוֹף כָּל סוֹף בְּהֶכְרַח שֶׁתּוּפְסַק הַהַשְׁפָּעָה.\nקִיצּוּר.\nמִתְבָּרֵךְ בִּלְבָבוֹ דְּאַף שֶׁהוֹלֵךְ בִּשְׁרִירוּת לִבּוֹ בְּכָל זֶה שָׁלוֹם יִהְיֶה לוֹ, עַל יְדֵי שֶׁיְּחַבֵּר הָרָוָה דְנֶפֶשׁ הַבַּהֲמִית אֶל הַצְּמֵאָה דְנֶפֶשׁ הָאֱלֹקִית, שֶׁהִיא הַמְשָׁכַת שֶׁפַע הַקְּדוּשָּׁה בְּי' סְפִירוֹת דְּנוֹגַהּ וְנוֹטֵל מֵהַסִּטְרָא אָחֳרָא חֵלֶק בָּרֹאשׁ."],[4401900046,"<h2>מַאֲמָר ז.</h2>\nוְהִנֵּה הָעַכּוּ\"ם הִנֵּה כָּל קַבָּלַת שִׁפְעָם הוּא מֵאֲחוֹרַיִים אֲבָל יִשְׂרָאֵל מְקַבְּלִים שִׁפְעָם מֵהַפְּנִימִית, אָמְנָם מִי שֶׁחָטָא וּפָשַׁע וְגָרַם סִילּוּק הָרָצוֹן מִמֶּנּוּ וְאָז מְקַבֵּל שִׁפְעוֹ כְּדוּגְמַת הַבַּעֲלֵי חַיִּים וְנוֹטֵל חֵלֶק בָּרֹאשׁ מִמַּה שֶּׁהִמְשִׁיךְ לְסִטְרָא אָחֳרָא, אֲבָל הַשְׁפָּעָה זוֹ נִפְסֶקֶת.\n<b>וְיוּבַן</b> זֶה עַל פִּי מַה שֶּׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר ב פֶּרֶק ב) בְּעִנְיַן פָּנִים וְאָחוֹר שֶׁבִּבְחִינַת רָצוֹן הָעֶלְיוֹן, דִּבְחִינַת פָּנִים הוּא מַה שֶּׁהוּא פְּנִימִית רְצוֹנוֹ וְחֶפְצוֹ הָאֲמִיתִּי שֶׁחָפֵץ בָּזֶה וְהַיְינוּ בְּכָל סִטְרָא דִקְדוּשָּׁה, אֲבָל לְסִטְרָא אָחֳרָא נִמְשָׁךְ מִבְּחִינַת אֲחוֹרַיִים, הַיְינוּ שֶׁאֵינוֹ חָפֵץ בָּהֶם וְאַדְרַבָּא הֵן תּוֹעֲבַת ה' אֲשֶׁר שָׂנֵא וּמַשְׁפִּיעַ לָהֶם שֶׁלֹּא בִרְצוֹנוֹ, כִּי אִם כְּמַאן דְּשָׁדֵי בָּתַר כַּתְפּוֹי,\nוּבֵיאוּר הָעִנְיָן יוּבַן עַל דֶּרֶךְ מָשָׁל כַּאֲשֶׁר הַמֶּלֶךְ עוֹשֶׂה סְעוּדָּה וּמִשְׁתֶּה לְכָל שָׂרָיו וַעֲבָדָיו וּמוֹצִיא מָמוֹן רַב מֵאוֹצְרוֹתָיו עַל הַמִּשְׁתֶּה הַזֶּה, וּבְוַדַּאי אֵין כַּוָּונָתוֹ וּרְצוֹנוֹ הַפְּנִימִי בַּפִּיזּוּר הַזֶּה הַגָּדוֹל רַק בִּשְׁבִיל הַשָּׂרִים הַגְּדוֹלִים וַעֲבָדִים הַחֲשׁוּבִים שֶׁיֹּאכְלוּ וְיִשְׁתּוּ וְיִשְׁכְּרוּ וְיִתְעַנְּגוּ מִכָּל מַאֲכַל שֻׁלְחַן הַמֶּלֶךְ מִכַּמָּה מִינֵי מַעֲדַנֵּי הַמֶּלֶךְ כו'. וְהִנֵּה יִמָּצְאוּ לְמִשְׁתֵּה הַמֶּלֶךְ גַּם פְּחוּתֵי עֶרֶךְ, כְּמוֹ עֲבָדִים וּשְׁפָחוֹת הַקְּטַנִּים וְהַשְּׁפָלִים שֶׁאַחֲרֵי הָרֵחַיִים, שֶׁיֹּאכְלוּ מִן הַשִּׁירַיִים שֶׁיִּשְׁתַּיְּירוּ מִסְּעוּדַּת חֲשׁוּבֵי הַשָּׂרִים אוֹ כְּמוֹ הָעֲצָמוֹת שֶׁמַּשְׁלִיכִים לְמַטָּה שֶׁאוֹכְלִים הַכְּלָבִים וּכְהַאי גַּוְונָא, הֲרֵי אִי אֶפְשָׁר לוֹמַר שֶׁהָיָה כַּוָּונַת הַפִּיזּוּר הַגָּדוֹל הַזֶּה בִּשְׁבִיל שִׁירַיִים הַלָּלוּ שֶׁיֹּאכְלוּ פְּחוּתֵי הָעֲבָדִים וְהַשְּׁפָחוֹת שֶׁאַחַר הָרֵחַיִים וְהַכְּלָבִים וּכְהַאי גַּוְונָא, הֲלֹא וַדַּאי לֹא כִוֵּון הַמֶּלֶךְ לְהוֹצִיא בִּשְׁבִילָם אֲפִילוּ פְּרוּטָה אַחַת, רַק כַּאֲשֶׁר פִּיזֵּר מָמוֹן רַב בְּרָצוֹן וְחֵפֶץ פְּנִימִי בִּשְׁבִיל סְעוּדַּת הַשָּׂרִים הַחֲשׁוּבִים, אֲזַי נִשְׁפָּע גַּם כֵּן בְּחִינַת חִיצוֹנִיּוּת שֶׁהֵן הַשִּׁירַיִים גַּם לַעֲבָדִים הַקְּטַנִּים, וַהֲרֵי זֶה נִקְרָא הַשְׁפָּעָה שֶׁבָּאָה בִּבְחִינַת חִיצוֹנִיּוּת בְּדֶרֶךְ אַגַּב בִּלְבָד כְּמַאן דְּשָׁדֵי בָּתַר כַּתְפּוֹי.\nקִיצּוּר.\nסִטְרָא אָחֳרָא וְעַכּוּ\"ם מְקַבְּלִים שִׁפְעָם מֵאֲחוֹרַיִים, בִּקְדוּשָּׁה לְיִשְׂרָאֵל נִמְשָׁךְ שֶׁפַע הַפְּנִימִית, אֲחוֹרַיִים כְּמַאן דְּשָׁדֵי בָּתַר כַּתְפּוֹי, פְּנִימִית בִּרְצוֹנוֹ וְחֶפְצוֹ. וְהַמָּשָׁל בָּזֶה מֵהַמֶּלֶךְ שֶׁעוֹשֶׂה מִשְׁתֶּה לְשָׂרָיו וַעֲבָדָיו הַגְּדוֹלִים שֶׁהֵם עִיקַּר רְצוֹנוֹ וְחֶפְצוֹ וְנֶהֱנִים גַּם הָעֲבָדִים הַקְּטַנִּים וְדֶרֶךְ אַגַּב מֵהַשִּׁירַיִים נֶהֱנִים גַּם הַכְּלָבִים."],[4401900047,"וְהַנִּמְשָׁל מִכָּל זֶה יוּבַן לַמַּשְׂכִּיל לְמַעְלָה, בִּהְיוֹת שֶׁבְּחִינַת פְּנִימִית שֶׁבְּרָצוֹן הָעֶלְיוֹן הוּא הַמֵּאִיר לְיִשְׂרָאֵל דַּוְקָא כְּמוֹ שֶׁכָּתוּב (בַּמִּדְבָּר ו. כה) יָאֵר ה' פָּנָיו אֵלֶיךָ, אֵלֶיךָ דַוְקָא, וְהַיְינוּ עַל יְדֵי הַמְשָׁכַת בְּחִינַת רָצוֹן הָעֶלְיוֹן הַמֵּאִיר בְּתוֹרָה וּמִצְוֹת דַּוְקָא, דְּהִנֵּה כָּל עִיקַּר חָכְמַת הַתּוֹרָה נִמְשְׁכָה מִבְּחִינַת פְּנִימִית רָצוֹן הָעֶלְיוֹן, שֶׁהֲרֵי כָּל עִנְיַן הַתּוֹרָה הוּא הַחָכְמָה אֵיךְ שֶׁיִּהְיֶה בְּחִינַת הַמְשָׁכַת עַצְמוּת אוֹר אֵין סוֹף בָּרוּךְ הוּא, בְּחִינַת אוֹר הַסּוֹבֵב (שֶׁהוּא בְּחִינַת רָצוֹן הָעֶלְיוֹן) מִן הַהֶעְלֵם לְגִילּוּי בָּעוֹלָמוֹת, דְּהַיְינוּ בְּאֵיזֶה אוֹפֶן תִּתְעוֹרֵר הַמְשָׁכַת אוֹר אֵין סוֹף בָּרוּךְ הוּא,\nוְהַיְינוּ מַה שֶּׁגָּזְרָה חָכְמָתוֹ יִתְבָּרֵךְ בְּחָכְמָה שֶׁבַּתּוֹרָה בְּעִנְיַן רְמַ\"ח מִצְוֹת עֲשֵׂה, שֶׁבָּהֶם דַּוְקָא יִהְיֶה גִּלּוּי בְּחִינַת אוֹר אֵין סוֹף לְמַטָּה, כַּיָּדוּעַ שֶׁרְמַ\"ח מִצְוֹת עֲשֵׂה הֵן רְמַ\"ח הַמְשָׁכוֹת מֵאוֹר אֵין סוֹף בְּחִינַת רָצוֹן הָעֶלְיוֹן לְהָאִיר אוֹרוֹת בְּכֵלִים מִכֵּלִים שׁוֹנִים, כְּמוֹ עַל יְדֵי תְּפִילִּין יִהְיֶה נִמְשָׁךְ בְּחִינַת רָצוֹן הָעֶלְיוֹן בְּד' מוֹחִין חָכְמָה וּבִינָה וְדַעַת שֶׁנֶּחֱלָק לְחֶסֶד וּגְבוּרָה עַל יְדֵי הַד' פַּרְשִׁיּוֹת, וְהַמְשָׁכָה זוֹ הִיא בַּאֲצִילוּת וּבָעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה עַד שֶׁנִּמְשָׁךְ וּמֵאִיר גַּם בְּהָאָדָם לְמַטָּה הָעוֹשֶׂה אֶת הַמִּצְוָה וּמֵנִיחַ תְּפִילִּין, וּבְמִצְוַת צִיצִית יִהְיֶה גִּילּוּי אוֹר אֵין סוֹף בְּל\"ב נְתִיבוֹת חָכְמָה, וּבְמִצְוַת צְדָקָה יָאִיר אוֹר אֵין סוֹף בָּרוּךְ הוּא בְּמִדַּת הַחֶסֶד, וּכְהַאי גַּוְונָא בִּשְׁאָר הַמִּצְוֹת כְּמוֹ עַל יְדֵי סוּכָּה בְּמַקִּיפִים דְּאִימָּא וּבְאֶתְרוֹג בִּבְחִינַת מַלְכוּת וְכַיּוֹצֵא,\nוְכָל זֶה הוּא רַק עַל פִּי הַחָכְמָה שֶׁבַּתּוֹרָה שֶׁגָּזְרָה לַעֲשׂוֹת הַסּוּכָּה וְהַתְּפִילִּין וְהָאֶתְרוֹג בְּאוֹתוֹ אוֹפֶן שֶׁעַל יְדֵי זֶה יִהְיֶה דַוְקָא הַמְשָׁכַת גִּילּוּי אוֹר אֵין סוֹף וְלֹא עַל אוֹפֶן אַחֵר זוּלָתוֹ,\nוּכְמוֹ כֵן גָּזְרָה חָכְמָה שֶׁבַּתּוֹרָה אוֹפַנִּים פְּרָטִים בִּשְׁסָ\"ה לֹא תַעֲשֶׂה, שֶׁהֵן כַּמָּה וְכַמָּה דְבָרִים פְּרָטִים שֶׁמּוֹנְעִים וּמַסְתִּירִים לִהְיוֹת גִּילּוּי אוֹר אֵין סוֹף בָּרוּךְ הוּא, וְצָרִיךְ לְהַעֲבִיר אֶת הַמּוֹנֵעַ מִכָּל צַד, וְהֵן הָאוֹפַנִּים פְּרָטִים שֶׁבְּמִצְוֹת לֹא תַעֲשֶׂה כְּמוֹ לֹא תִלְבַּשׁ שַׁעַטְנֵז (דְּבָרִים כב. יא) וְלֹא תֹאכַל חֵלֶב וְכַדּוֹמֶה בְּכָל הַשְּׁסָ\"ה לֹא תַעֲשֶׂה, שֶׁעַל יְדֵי הַכְּפִיָּה בְּהֶעְדֵּר עֲשִׂיַּית הַדָּבָר וּבִזְהִירוּת בָּזֶה, הֲרֵי הוּא מֵסִיר אֶת הַקְּלִיפּוֹת וְסִטְרָא אָחֳרָא הַמּוֹנְעִים וּמַסְתִּירִים אֶת הַגִּילּוּיִם דְּאוֹר אֵין סוֹף בָּרוּךְ הוּא.\nקִיצּוּר.\nפְּנִימִית הָרָצוֹן נִמְשָׁךְ לְיִשְׂרָאֵל וְהוּא עַל יְדֵי תּוֹרָה וּמִצְוֹת, דְּכָל עִנְיַן הַתּוֹרָה הוּא הַמְשָׁכַת אוֹר הַסּוֹבֵב בָּעוֹלָמוֹת, רְמַ\"ח מִצְוֹת עֲשֵׂה הֵם הַמְשָׁכוֹת בַּכֵּלִים, תְּפִילִּין וְצִיצִית, צְדָקָה סוּכָּה אֶתְרוֹג, וּמִצְוֹת לֹא תַעֲשֶׂה לְהָסִיר הַקְּלִיפּוֹת וְסִטְרָא אָחֳרָא הַמּוֹנְעִים גִּילּוּי אוֹר אֵין סוֹף."],[4401900048,"וְהִנֵּה עוֹד זֹאת בְּמִצְוֹת לֹא תַעֲשֶׂה שֶׁהֵן שׁוֹמְרוֹת שֶׁלֹּא יוּמְשַׁךְ אוֹר הָאֱלֹקִי לְמָקוֹם שָׂנאוּי שֶׁנִּקְרָא תּוֹעֲבַת ה', כִּי לֹא יְגוּרְךָ רָע כְּתִיב (תְּהִלִּים ה. ה) וּבָאָדָם הוּא גַם כֵּן עַל יְדֵי הִבָּדְלוֹ מִדְּבָרִים הָאֲסוּרִים וּקְשׁוּרִים בִּידֵי הַחִיצוֹנִים שֶׁאֵין לָהֶם עֲלִיָּה לְמַעְלָה, כִּי לֹא יִשְׁכּוֹן בָּהֶם אוֹר הָאֱלֹקִי, וּכְמוֹ שֶׁכָּתוּב (יְשַׁעְיָה מב. ח) וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן, הִנֵּה הוּא נִשְׁמָר מִן הָרָע וְנַעֲשֶׂה כְּלִי אֶל הַקְּדוּשָּׁה,\nאִם כֵּן הֲרֵי מוּבָן שֶׁעִיקַּר עִנְיַן חָכְמַת הַתּוֹרָה הִיא הַחָכְמָה אֵיךְ שֶׁיִּהְיֶה גִּילּוּי אוֹר אֵין סוֹף לְמַטָּה עַל יְדֵי הָרְמַ\"ח מִצְוֹת עֲשֵׂה, וּלְהָסִיר כָּל מוֹנֵעַ עַל יְדֵי שְׁסָ\"ה לֹא תַעֲשֶׂה, שֶׁזֶּהוּ עִנְיַן בְּחִינַת פְּנִימִית רָצוֹן הָעֶלְיוֹן בִּכְלָל שֶׁיִּהְיֶה גִּילּוּי אוֹר אֵין סוֹף לְמַטָּה עַל יְדֵי קִיּוּם הַמִּצְוֹת בִּרְמַ\"ח מִצְוֹת עֲשֵׂה, וּבַהֲסָרַת הַמּוֹנְעִים עַל יְדֵי שְׁסָ\"ה לֹא תַעֲשֶׂה, שֶׁבָּזֶה נִשְׁלָם הַכַּוָּונָה וְהָרָצוֹן דְּנִתְאַוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לִהְיוֹת לוֹ דִירָה בַּתַּחְתּוֹנִים, וּבְדֶרֶךְ פְּרָט הִנֵּה יֵשׁ בְּכָל מִצְוָה וּמִצְוָה הֶאָרָה פְּרָטִית מֵרָצוֹן הַכְּלָלִי הַזֶּה. וְעַל זֶה אוֹמֵר (בַּמִּדְבָּר ו. כה) יָאֵר ה' פָּנָיו אֵלֶיךָ, לְיִשְׂרָאֵל דַּוְקָא שֶׁמְּקַיְּימִים הַמִּצְוֹת שֶׁזֶּהוּ בְּחִינַת פְּנִימִית רָצוֹן הָעֶלְיוֹן, לִהְיוֹת גִּילּוּי אוֹר אֵין סוֹף לְמַטָּה.\n<b>אַךְ</b> כַּאֲשֶׁר נִמְשָׁךְ בְּחִינַת פְּנִימִית הָרָצוֹן לְיִשְׂרָאֵל עַל יְדֵי תּוֹרָה וּמִצְוֹת כַּנַ\"ל, נִמְשָׁךְ גַּם כֵּן בְּחִינַת אֲחוֹרַיִים וְחִיצוֹנִיּוּת הָרָצוֹן הָעֶלְיוֹן שֶׁנִּקְרֵאת בְּחִינַת עוֹרֶף וְלֹא פָנִים לְעַכּוּ\"ם, שֶׁשָּׁרְשָׁם מֵע' שָׂרִים הָעֶלְיוֹנִים שֶׁמְּקַבְּלִים הַשֶּׁפַע בִּבְחִינַת חִיצוֹנִיּוּת וַאֲחוֹרַיִים שֶׁעַל כֵּן נִקְרָאִים אֱלֹקִים אֲחֵרִים כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר ב פֶּרֶק ב), וְעִנְיַן קַבָּלָתָם הוּא רַק בְּדֶרֶךְ אַגַּב לְבָד, דְּהַיְינוּ עַל דֶּרֶךְ מָשָׁל הַנַ\"ל (פֶּרֶק א) בְּמִשְׁתֵּה הַשָּׂרִים, שֶׁלְּאַחַר שֶׁכְּבָר נִמְשַׁךְ הַשֶּׁפַע לְמִי שֶׁרָאוּי שֶׁבּוֹ פְּנִימִית הָרָצוֹן, אָז יְקַבְּלוּ גַּם אוֹתָם שֶׁאֵינָן רְאוּיִם מִבְּחִינַת הַשִּׁירַיִים בְּדֶרֶךְ אַגַּב, גַּם שֶׁלֹּא הָיְתָה הַכַּוָּונָה אֲלֵיהֶם כְּלָל, כַּךְ מְקַבְּלִים גַּם הַחִיצוֹנִים יְנִיקָה וְחַיּוּת מֵאוֹר הָאֱלֹקִי בִּבְחִינַת הַשִּׁירַיִים וְהַחִיצוֹנִיּוּת שֶׁבְּרָצוֹן הָעֶלְיוֹן, לְאַחַר שֶׁכְּבָר נִמְשָׁךְ הָאוֹר וְהַשֶּׁפַע הַפְּנִימִית מִפְּנִימִית רָצוֹן הָעֶלְיוֹן לְסִטְרָא דִקְדוּשָּׁה בְּהַמְשָׁכַת אוֹרוֹת בַּכֵּלִים עַל יְדֵי הַמִּצְוֹת שֶׁהוּא עִנְיַן יָאֵר ה' פָּנָיו אֵלֶיךָ כַּנַ\"ל,\nוְנִמְצָא שֶׁהַהַשְׁפָּעָה לַחִיצוֹנִים מִבְּחִינַת אֲחוֹרַיִים, הֲרֵי זֶה מַמָּשׁ כְּמַאן דְּשָׁדֵי בָּתַר כַּתְפּוֹי, בְּדֶרֶךְ אַגַּב וְטָפֵל בְּשָׁעָה שֶׁמַּשְׁפִּיעַ לַפְּנִימִי בִּבְחִינַת פָּנִים, וְאֵין בְּהַשְׁפָּעָה לַחִיצוֹנִים שׁוּם הֶאָרָה פְנִימִית מִפְּנִימִית רָצוֹן הָעֶלְיוֹן כְּלָל וּכְלָל, וְעַל כֵּן אֵינָם מְקַבְּלִים רַק מִבְּחִינַת הַתַּמְצִית וְהַשְּׁמָרִים הַנּוֹפְלִים כְּיָדוּעַ, וְדַוְקָא לְאַחַר שֶׁנִּתְעוֹרֵר הַשֶּׁפַע מִבְּחִינַת פָּנִים לְסִטְרָא דִקְדוּשָּׁה, אֲזַי גַּם הֵם מְקַבְּלִים בְּחִינַת הַתַּמְצִית, אֲבָל כְּשֶׁאֵין נִמְשָׁךְ מִבְּחִינַת פָּנִים לְסִטְרָא דִקְדוּשָּׁה בִּבְחִינַת גִּילּוּי (וְהַיְינוּ בְּהַזְּמַנִּים שֶׁאָז עֲלִיּוֹת הָעוֹלָמוֹת) אָז אֵין לָהֶם יְנִיקָה כְּלָל, וְנִמְצָא דְּדַוְקָא כְּשֶׁיֵּשׁ הַמְשָׁכָה בְּחִינַת פְּנִימִית בְּסִטְרָא דִקְדוּשָּׁה אָז נִמְשָׁךְ בְּחִינַת תַּמְצִית הַשְּׁמָרִים וְהַפְּסוֹלֶת לְסִטְרָא אָחֳרָא.\nקִיצּוּר.\nמִצְוֹת לֹא תַעֲשֶׂה שׁוֹמְרוֹת שֶׁלֹּא יוּמְשַׁךְ אוֹר אֱלֹקִי בְּמָקוֹם הַשָּׂנאוּי. פְּנִימִית הָרָצוֹן תּוֹרָה מִצְוֹת עֲשֵׂה וּמִצְוֹת לֹא תַעֲשֶׂה רַק לְיִשְׂרָאֵל, וְדֶרֶךְ אַגַּב נִמְשָׁךְ הֶאָרַת חִיצוֹנִיּוּת רָצוֹן הָעֶלְיוֹן לְהָע' שָׂרִים וְעַל יָדָם הַפְּסוֹלֶת לְסִטְרָא אָחֳרָא."],[4401900049,"וְהִנֵּה הַמּוּרָם מִכָּל הָאָמוּר שֶׁפְּנִימִית רָצוֹן הָעֶלְיוֹן נִמְשָׁךְ עַל יְדֵי הַתּוֹרָה וּמִצְוֹת רַק לְיִשְׂרָאֵל, וּלְהַסִּטְרָא אָחֳרָא נִמְשָׁךְ תַּמְצִית הַשְּׁמָרִים וְהַפְּסוֹלֶת דְּחִיצוֹנִיּוּת רָצוֹן הָעֶלְיוֹן, הִנֵּה לְפִי זֶה מוּבָן דְּמַה שֶּׁהָאִישׁ הַחוֹטֵא מַמְשִׁיךְ רַחֲמָנָא לִצְּלָן תּוֹסֶפֶת חַיּוּת וִינִיקָה לְסִטְרָא אָחֳרָא, הוּא מִצַּד שֶׁבְּעֶצֶם שַׁיָּיךְ אֶל הַפְּנִימִית, וְאַף שֶׁנּוֹטֵל חֵלֶק בָּרֹאשׁ בְּכָל זֶה הִנֵּה נִפְסָק וְאַדְרַבָּה הַסִּטְרָא אָחֳרָא נוֹקְמִים מִמֶּנּוּ, וְהַיְינוּ דְּאַף עַל פִּי שֶׁחָטָא יִשְׂרָאֵל הוּא וּמִצַּד נִשְׁמָתוֹ הוּא מִפְּנִימִית הַקְּדוּשָּׁה וְעַל יְדֵי הַמִּצְוֹת שֶׁקִּיֵּים קוֹדֶם שֶׁחָטָא הֲרֵי הִמְשִׁיךְ בְּחִינַת פְּנִימִית רָצוֹן הָעֶלְיוֹן בְּסִטְרָא דִקְדוּשָּׁה, הִנֵּה כְּשֶׁחוֹטֵא רַחֲמָנָא לִצְּלָן הֲרֵי הוּא מַמְשִׁיךְ תּוֹסֶפֶת הֶאָרָה מִבְּחִינַת הַפְּנִימִית אֶל הַקְּלִיפּוֹת וְסִטְרָא אָחֳרָא, וּכְמוֹ שֶׁכָּתוּב בְּסֵדֶר הַנְּזִיפָה שֶׁהַמַּיִם הַיּוֹצְאִים מִבֵּית ה' הוֹלִיכָם לִמְקוֹם הַטִּינוֹפֶת אֵשֶׁת הַזִּימָּה כו', וְהוּא נוֹטֵל חֵלֶק בָּרֹאשׁ בְּהַשְׁפָּעוֹת גַּשְׁמִיּוֹת לְפִי שֶׁהוּא הוּא הַמַּמְשִׁיךְ לָהֶם תּוֹסֶפֶת הַהֶאָרָה,\nאֲבָל לַכֹּל זְמַן וָעֵת, וְכַאֲשֶׁר כְּבָר אָבַד רַחֲמָנָא לִצְּלָן חֵלֶק נִשְׁמָתוֹ וְחֵלֶק הַטּוֹב שֶׁבּוֹ, ה' יִשְׁמְרֵנוּ, אָז אֵינוֹ מְקַבֵּל עוֹד מֵהֶם שֶׁפַע חַיּוּת, כִּי בְּעֶצֶם מִצַּד הֱיוֹתוֹ יִשְׂרָאֵל צָרִיךְ לִהְיוֹת אוֹפֶן קַבָּלַת חַיּוּתוֹ מִבְּחִינַת הַפְּנִימִיּוּת דְּרָצוֹן הָעֶלְיוֹן דַּוְקָא, הַיְינוּ מִבְּחִינַת הַפָּנִים דְּרָצוֹן הָעֶלְיוֹן, שֶׁנִּמְשָׁךְ בָּעוֹלָמוֹת עַל יְדֵי תּוֹרָה וּמִצְוֹת כַּנַ\"ל וּכְמוֹ שֶׁיִּתְבָּאֵר, אֶלָּא שֶׁעַל יְדֵי שֶׁנָּפַל בַּקְּלִיפּוֹת רַחֲמָנָא לִצְּלָן עַל יְדֵי הַחֵטְא הֲרֵי הוּא מְקַבֵּל עַל יָדָן מֵהַתּוֹסֶפֶת חַיּוּת שֶׁהִמְשִׁיךְ לָהֶם כַּנַ\"ל, וְזֶה רַק לְפִי שָׁעָה אֲבָל אַחַר כַּךְ אֵינוֹ מְקַבֵּל עַל יָדָן, שֶׁאֵין זֶה מְקוֹמוֹ לְקַבֵּל מִבְּחִינַת אֲחוֹרַיִים כִּי אִם עַכּוּ\"ם מְקַבְּלִים תָּמִיד שִׁפְעָם מִשָּׁם, אֲבָל יִשְׂרָאֵל הַחוֹטֵא רַחֲמָנָא לִצְּלָן רַק לְפִי שָׁעָה נוֹטֵל מֵהֶם חֶלְקוֹ שֶׁהִמְשִׁיךְ לָהֶם, ה' יִשְׁמְרֵנוּ מִזֶּה, אֲבָל אַחַר כַּךְ אֵינוֹ מְקַבֵּל מֵהֶם שֶׁפַע חַיּוּתוֹ וּבְהֶכְרַח שֶׁתּוּפְסַק הַהַשְׁפָּעָה.\n<b>וְהִנֵּה</b> גַּם אִם לוֹמֵד תּוֹרָה וְעוֹשֶׂה מִצְוֹת בָּעֵת הַהִיא וּכְמַאֲמָר (בְּרָכוֹת נז. א) אֲפִילוּ רֵיקָנִים שֶׁבָּךְ מְלֵאִים מִצְוֹת כָּרִמּוֹן, הִנֵּה קוֹדֶם שֶׁעָשָׂה תְשׁוּבָה אֵין תּוֹרָתוֹ וְקִיּוּם מִצְוֹתָיו רְצוּיִם וּמְקוּבָּלִים לְמַעְלָה, כְּמוֹ שֶׁכָּתוּב (תְּהִלִּים נ. טז) וְלָרָשָׁע אָמַר אֱלֹקִים מַה לְּךָ לְסַפֵּר חֻקָּי וַתִּשָּׂא בְרִיתִי (תּוֹרָתִי. רַשִׁ\"י) עֲלֵי פִיךָ וְאַתָּה שָׂנֵאתָ מוּסָר וַתַּשְׁלֵךְ דְּבָרַי אַחֲרֶיךָ, הֲלֹא בְּלֵב אַתָּה שׂוֹנֵא הַמּוּסָר וְהִשְׁלַכְתָּ דְבָרַי אַחֲרֵי גַוֶּךָ כְּדֶרֶךְ שֶׁמַּשְׁלִיךְ הָאָדָם דָּבָר אֲשֶׁר לֹא יַחְפּוֹץ לִרְאוֹתוֹ, וְלָכֵן אֵינוֹ מַמְשִׁיךְ הַמְשָׁכַת אֱלֹקוּת עַל יְדֵי לִימּוּד הַתּוֹרָה וְקִיּוּם הַמִּצְוֹת, וְכִדְאִיתָא בְּרֵאשִׁית חָכְמָה (שַׁעַר הַתְּשׁוּבָה סוֹף פֶּרֶק ב) וְזֶה לְשׁוֹנוֹ מִי שֶׁהוּא מָלֵא מִסִּרְחוֹן צוֹאַת עֲווֹנוֹתָיו אֵין תּוֹרָתוֹ נַחַת לְבוֹרְאוֹ. וְהַטַּעַם כִּי בְּעֵסֶק הַתּוֹרָה הָאָדָם מוֹשֵׁךְ הַשְּׁכִינָה עָלָיו וּבִהְיוֹתוֹ נָקִי מֵחֵטְא מָצְאָה הַשְּׁכִינָה כִּסֵּא וּמוֹשָׁב שֶׁבּוֹ תֵּשֵׁב וְתָנוּחַ כו' אֲבָל בִּהְיוֹת הָאָדָם מְלוּכְלָךְ בְּכִתְמֵי עֲווֹנוֹתָיו אֵין הַתּוֹרָה שׁוֹרָה בוֹ כִּי אֵין בּוֹ כִּסֵּא לִשְׁרוֹת לֹא הַתּוֹרָה וְלֹא הַשְּׁכִינָה, עַד כַּאן לְשׁוֹנוֹ. וּמֵאַחַר שֶׁהוּא אֵינוֹ כְּלִי לְהָאוֹר, הִנֵּה מוּבָן דְּעַל יְדֵי לִימּוּד הַתּוֹרָה וְקִיּוּם הַמִּצְוֹת בְּלֹא תְשׁוּבָה מִתְּחִלָּה הֲרֵי אֵינוֹ מַמְשִׁיךְ הַגִּילּוּי אוֹר לְמַעְלָה גַם כֵּן, וּמִי שֶׁמּוֹסֵר אֶת עַצְמוֹ חַס וְשָׁלוֹם אֶל הַקְּלִיפּוֹת הֵם עַצְמָם נוֹקְמִים מִמֶּנּוּ, כִּמְבוֹאָר בַּאֲרוּכָה בְּזֹהַר (חֵלֶק א קמח א-ב בְּסִתְרֵי תוֹרָה), וְהַשֵּׁם יִתְבָּרֵךְ יִשְׁמְרֵנוּ מֵהֶם וְיִתֵּן בְּלִבֵּנוּ לְעָבְדוֹ בֶּאֱמֶת וּבְתָמִים תָּמִיד כָּל הַיָּמִים.\nקִיצּוּר.\nכָּל יִשְׂרָאֵל מִצַּד נִשְׁמָתָם וּמִצַּד קִיּוּם הַתּוֹרָה וּמִצְוֹת הֵם מִפְּנִימִית רָצוֹן הָעֶלְיוֹן, וּבְחֶטְאוֹ מַמְשִׁיךְ תּוֹסֶפֶת הֶאָרָה מֵהַפְּנִימִית וְנוֹטֵל חֵלֶק בָּרֹאשׁ אֲבָל נִפְסֶקֶת, וְקוֹדֶם שֶׁעוֹשֶׂה תְשׁוּבָה הִנֵּה גַּם מֵהַתּוֹרָה וּמִצְוֹת שֶׁלּוֹ אֵין נַחַת לְמַעְלָה, וְאֵינוֹ מַמְשִׁיךְ גִּילּוּי אוֹר, וְהַמּוֹסֵר עַצְמוֹ רַחֲמָנָא לִצְּלָן לְהַסִּטְרָא אָחֳרָא נוֹקְמִים מִמֶּנּוּ."],[4401900050,"<h2>מַאֲמָר ח.</h2>\nוְהִנֵּה כָּל מַה שֶּׁנִּתְבָּאֵר בְּעִנְיַן לְמַעַן סְפוֹת הָרָוָה אֶת הַצְּמֵאָה, שֶׁעַל יְדֵי זֶה שֶׁסְּפִירַת הַמַּלְכוּת רַגְלֶיהָ יוֹרְדוֹת בִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה הִנֵּה מְחַבֵּר רָוָה שֶׁהִיא הַסִּטְרָא אָחֳרָא עִם הַצְּמֵאָה בְּחִינַת מַלְכוּת לְקַבֵּל תּוֹסֶפֶת חַיּוּת מֵהַקְּדוּשָּׁה, זֶהוּ לְפֵירוּשׁ רַשִׁ\"י שֶׁמְּפָרֵשׁ סְפוֹת לְשׁוֹן חִבּוּר.\n<b>אָמְנָם</b> לְפִי פֵּירוּשׁ הָרְדַ\"ק שֶׁמְּפָרֵשׁ לְשׁוֹן רִיבּוּי מַהוּ עִנְיַן שֶׁהָרָוָה מַרְבֶּה עוֹד עַל בְּחִינַת צְמֵאָה.\n<b>הָעִנְיָן</b> הוּא דְּהִנֵּה יָדוּעַ שֶׁיְּנִיקַת הַחִיצוֹנִים הִיא עַל ב' אוֹפַנִּים, אוֹ שֶׁמְּקַבְּלִים מִבְּחִינַת אֲחוֹרַיִים וְחִיצוֹנִיּוּת, דְּהַיְינוּ מִבְּחִינַת רִיבּוּי הַצִּמְצוּמִים דִּבְחִינַת חִיצוֹנִיּוּת הַכֵּלִים דְּמַלְכוּת. וְאוֹפֶן הַב' הוּא שֶׁמְּקַבְּלִים מִבְּחִינַת הַמַּקִּיף עֶלְיוֹן (וְהוּא גַם כֵּן מִבְּחִינַת אֲחוֹרַיִים וְחִיצוֹנִיּוּת הַמַּקִּיף).\n<b>וְהָעִנְיָן</b> הוּא דְּהִנֵּה אָמְרוּ (אָבוֹת פֶּרֶק ה) עֲשָׂרָה דוֹרוֹת מֵאָדָם עַד נֹחַ וּמִנֹּחַ עַד אַבְרָהָם לְהוֹדִיעַ כַּמָּה אֶרֶךְ אַפַּיִם לְפָנָיו שֶׁכָּל הַדּוֹרוֹת הָיוּ מַכְעִיסִין וּבָאִין כו', הַיְינוּ שֶׁכָּל הַדּוֹרוֹת הָאֵלּוּ קִבְּלוּ מִבְּחִינַת אֶרֶךְ אַפַּיִם, וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (עֵירוּבִין כב. א) מַאי דִּכְתִיב אֶרֶךְ אַפַּיִם, אֶרֶךְ אַף מִבָּעֵי לֵיהּ אֶלָּא אֶרֶךְ אַפַּיִם לַצַּדִּיקִים אֶרֶךְ אַפַּיִם לָרְשָׁעִים, וּפֵרֵשׁ רַשִׁ\"י אַפַּיִם מַשְׁמָע פָּנִים בֵּין שׂוֹחֲקוֹת בֵּין זְעוּמוֹת, אַפַּיִם שׂוֹחֲקוֹת מַאֲרִיךְ וּמְאַחֵר לַצַּדִּיקִים לֶעָתִיד לָבֹא וְאַפַּיִם זְעוּמוֹת מַאֲרִיךְ לָרְשָׁעִים וּמְאַחֵר פּוּרְעָנוּתָם לָעוֹלָם הַבָּא.\n<b>וְהָעִנְיָן</b> הוּא דְּהִנֵּה יָדוּעַ דְּאוֹר אֵין סוֹף הוּא קָדוֹשׁ וּמוּבְדָּל מֵעוֹלָמוֹת שֶׁאֵינוֹ בְּעֶרֶךְ הָעוֹלָמוֹת כְּלָל, וְלָכֵן אֲנִי ה' לֹא שָׁנִיתִי (מַלְאָכִי ג. ו) שֶׁלֹּא יֵשׁ שׁוּם שִׁינּוּי בֵּין קוֹדֶם הַבְּרִיאָה לְאַחַר הַבְּרִיאָה, מִפְּנֵי שֶׁאֵינוֹ תּוֹפֵס מָקוֹם כְּלָל. וְזֶהוּ גַם כֵּן מַה שֶּׁכָּתוּב (אִיּוֹב לה. ו-ז) אִם חָטָאתָ מַה תִּפְעָל בּוֹ וְרַבּוּ פְשָׁעֶיךָ מַה תַּעֲשֶׂה לּוֹ אִם צָדַקְתָּ מַה תִּתֶּן לוֹ אוֹ מַה מִּיָּדְךָ יִקָּח, דְּכָל זֶה הוּא מִפְּנֵי שֶׁמַּעֲשֵׂה הַתַּחְתּוֹנִים אֵינָם תּוֹפְסִים מָקוֹם כְּלָל,\nוּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בְּמִדְרָשׁ רַבָּה (לֶךְ לְךָ פַּרְשָׁה מ\"ד) הָאֵל תָּמִים דַּרְכּוֹ אִמְרַת ה' צְרוּפָה מָגֵן הוּא לְכֹל הַחוֹסִים בּוֹ, אִם דְּרָכָיו תְּמִימִים הוּא עַל אַחַת כַּמָּה וְכַמָּה, רַב אָמַר לֹא נִתְּנוּ הַמִּצְוֹת אֶלָּא לְצָרֵף בָּהֶן אֶת הַבְּרִיּוֹת, וְכִי מָה אִיכְפַּת לֵיהּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְמִי שֶׁשּׁוֹחֵט מִן הַצַּוָּאר אוֹ מִי שֶׁשּׁוֹחֵט מִן הָעוֹרֶף הָוֵי לֹא נִתְּנוּ הַמִּצְוֹת אֶלָּא לְצָרֵף בָּהֶם אֶת הַבְּרִיּוֹת, אֲבָל לְגַבֵּי אוֹר אֵין סוֹף אֵין הָעִנְיָן נוֹגֵעַ כְּלָל,\nוּמַה שֶּׁכָּתוּב (שְׁמוֹת כג. כה) וַעֲבַדְתֶּם אֵת ה' אֱלֹקֵיכֶם, וּמְבוֹאָר בְּמָקוֹם אַחֵר עַל פָּסוּק זֶה דַּעֲבוֹדָה הִיא צוֹרֶךְ גָּבוֹהַּ, זֶהוּ בְּסֵדֶר הִשְׁתַּלְשְׁלוּת וְהַיְינוּ בְּעֶשֶׂר סְפִירוֹת דַּאֲצִילוּת דְּרֵאשִׁיתָן הִיא חָכְמָה שָׁם נוֹגֵעַ עֲבוֹדַת הַתַּחְתּוֹנִים כְּמוֹ שֶׁכָּתוּב בְּמָקוֹם אַחֵר וּכְמוֹ שֶׁיִּתְבָּאֵר בְּסָמוּךְ. אֲבָל בְּאוֹר אֵין סוֹף שֶׁלְּמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת אֵינָם תּוֹפְסִים מָקוֹם מַעֲשֵׂה הַתַּחְתּוֹנִים. וְזֶהוּ שֶׁאָמְרוּ בַּמִּשְׁנָה לְהוֹדִיעַ כַּמָּה אֶרֶךְ אַפַּיִם לְפָנָיו שֶׁכָּל הַדּוֹרוֹת הָיוּ מַכְעִיסִין וּבָאִין כו', שֶׁאַף עַל פִּי שֶׁהָיוּ מַכְעִיסִין מִכָּל מָקוֹם נִמְשַׁךְ לָהֶם הַשְׁפָּעַת הַחַיּוּת מִבְּחִינַת אֶרֶךְ אַפַּיִם שֶׁהוּא בְּחִינַת אוֹר אֵין סוֹף שֶׁלְּמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת, לְפִי שֶׁשָּׁם אֵינוֹ נוֹגֵעַ מַעֲשֵׂה הַתַּחְתּוֹנִים וִיכוֹלִים הַכֹּל לְקַבֵּל.\n<b>וְזֶהוּ</b> שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (פְּסָחִים קיח. א) אָמַר רַבִּי יְהוֹשֻׁעַ בֶּן לֵוִי הַנִי כ\"ו הוֹדוּ כְּנֶגֶד מִי, כְּנֶגֶד כ\"ו דּוֹרוֹת שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעוֹלָמוֹ וְלֹא נָתַן לָהֶם תּוֹרָה וְזָן אוֹתָם בְּחַסְדּוֹ, וְהַיְינוּ שֶׁאַף עַל פִּי שֶׁהָיוּ עוֹבְדֵי עֲבוֹדָה זָרָה כְּמוֹ דּוֹרוֹ שֶׁל אֱנוֹשׁ הָיוּ נִיזּוֹנִין בְּחַסְדּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הַיְינוּ בְּחִינַת רַב חֶסֶד דַּאֲרִיךְ אַנְפִּין, שֶׁמִּשָּׁם נִמְשָׁכָה הַהַשְׁפָּעָה גַּם לְעוֹבְרֵי רְצוֹנוֹ. וְזֶהוּ וְלֹא נָתַן לָהֶם תּוֹרָה וְזָן אוֹתָם בְּחַסְדּוֹ, דְּעַל פִּי הַתּוֹרָה אֵינוֹ מַגִּיעַ לָהֶם הַהַשְׁפָּעָה, דְּאוֹרַיְיתָא מֵחָכְמָה נָפְקַת וּבְחָכְמָה יֵשׁ הַגְבָּלָה, לִהְיוֹת נִמְשָׁךְ הַחֶסֶד דַּוְקָא בְּאוֹפֶן כָּזֶה וְלֹא בְּאוֹפֶן אַחֵר, וְהַיְינוּ כַּאֲשֶׁר עוֹשֶׂה רְצוֹנוֹ שֶׁל מָקוֹם תּוּמְשַׁךְ לוֹ הַשְׁפָּעַת הַחֶסֶד וּבְאוֹפֶן אַחֵר לֹא תוּמְשַׁךְ, אֲבָל אוֹתָן כ\"ו דּוֹרוֹת אַף שֶׁהָיוּ עוֹבְרֵי רְצוֹנוֹ נִמְשְׁכָה לָהֶם הַהַשְׁפָּעָה שֶׁלֹּא עַל פִּי הַתּוֹרָה כִּי אִם מֵחַסְדּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּחִינַת רַב חֶסֶד.\nקִיצּוּר.\nיְנִיקַת הַסִּטְרָא אָחֳרָא א) מֵרִיבּוּי הַצִּמְצוּמִים, ב) מֵהַמַּקִּיף הָעֶלְיוֹן. הָעֲשָׂרָה דוֹרוֹת מֵאָדָם עַד נֹחַ, מִנֹּחַ וְעַד אַבְרָהָם נִיזּוֹנִין בְּחַסְדּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אֶרֶךְ אַפַּיִם, אוֹר אֵין סוֹף שֶׁלְּמַעְלָה מֵהִשְׁתַּלְשְׁלוּת דְּאֵין מַעֲשֵׂה הַתַּחְתּוֹנִים נוֹגֵעַ, וְהַשְׁפָּעָתָם אֵינָהּ עַל פִּי מִשְׁפַּט הַתּוֹרָה אֶלָּא מֵרַב חֶסֶד."],[4401900051,"וְהִנֵּה הַהַשְׁפָּעָה מִבְּחִינַת רַב חֶסֶד הִיא הַשְׁפָּעָה בְּרִיבּוּי, וְזֶהוּ מַה שֶּׁיֵּשׁ לָהֶם עוֹשֶׁר וְכָבוֹד בְּרִיבּוּי מְאֹד שֶׁלֹּא עַל פִּי חֶשְׁבּוֹן כְּלָל, כְּמוֹ שֶׁכָּתוּב (קֹהֶלֶת ט. יו\"ד) כִּי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה בִּשְׁאוֹל וגו', וְהַיְינוּ שֶׁמְּקַבְּלִים שֶׁלֹּא עַל פִּי הַחֶשְׁבּוֹן.\n<b>דְּהִנֵּה</b> אִיתָא בִּמְאוֹרֵי אוֹר (אוֹת ח' סְעִיף עה) חֶשְׁבּוֹן נִקְרֵאת הַחָכְמָה עַל שֵׁם הַמַּחֲשָׁבָה. וּבִגְמָרָא (בָּבָא בַתְרָא עח. ב) דָּרְשׁוּ עַל פָּסוּק עַל כֵּן יֹאמְרוּ הַמּוֹשְׁלִים בֹּאוּ חֶשְׁבּוֹן (בַּמִּדְבָּר כא. כז) בֹּאוּ וְנַחְשׁוֹב חֶשְׁבּוֹנוֹ שֶׁל עוֹלָם הֶפְסֵד מִצְוָה נֶגֶד שְׂכָרָהּ וּשְׂכַר עֲבֵירָה נֶגֶד הֶפְסֵדָהּ,\nדְּחֶשְׁבּוֹן זֶה הוּא מִבְּחִינַת הַחָכְמָה דְּאוֹרַיְיתָא מֵחָכְמָה נָפְקַת וְהוּא בְּחִינַת קַו הַמִּדָּה, שֶׁמִּשָּׁם נִמְשֶׁכֶת הַמִּדָּה וְהַקִּצְבָה עַל כָּל הַשְׁפָּעוֹת רוּחָנִיּוֹת וְגַשְׁמִיּוֹת. וְעִנְיַן הַמִּשְׁקָל וְהַמִּדָּה הוּא בְּאוֹפֶן הַהִתְכַּלְלוּת דְּחֶסֶד וּגְבוּרָה, שֶׁזֶּהוּ עַל פִּי הַחָכְמָה שֶׁמּוֹדֶדֶת אֵיךְ וּבְאֵיזֶה אוֹפֶן תִּהְיֶה הַהִתְכַּלְלוּת דְּחֶסֶד וּגְבוּרָה בְּהִתְגַּבְּרוּת דְּמִדָּה אַחַת עַל זוּלָתָהּ, וּמִזֶּה נִמְשֶׁכֶת הַמְּדִידָה בְּהַשְׁפָּעַת הַמִּדּוֹת הַנַ\"ל, כְּמוֹ בְּהַשְׁפָּעַת בָּנֵי חַיֵּי וּמְזוֹנֵי כַּמָּה תִהְיֶה הַהַשְׁפָּעָה וּבְאֵיזֶה אוֹפֶן, וּכְמוֹ מְזוֹנוֹתָיו שֶׁל אָדָם קְצוּבִים לוֹ מֵרֹאשׁ הַשָּׁנָה (בֵּיצָה טז. א) וְכֵן אָדָם נִידּוֹן בְּכָל יוֹם [שָׁעָה] (רֹאשׁ הַשָּׁנָה טז. א) שֶׁהַדִּין וְהַמִּשְׁפָּט הוּא עַל פִּי מַעֲשָׂיו וַעֲבוֹדָתוֹ שֶׁבְּאוֹפֶן כָּזֶה נִמְשָׁכָה לוֹ הַהַשְׁפָּעָה עַל פִּי הַמִּשְׁקָל דְּחֶסֶד וּגְבוּרָה, אִם בְּהִתְגַּבְּרוּת הַחֲסָדִים אוֹ כו' חַס וְשָׁלוֹם,\nוּכְמוֹ שֶׁכָּתוּב (אִיּוֹב לז. יב) וְהוּא מְסִבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלוֹתָיו לְפָעֳלָם וּפֵירֵשׁ רַשִׁ\"י שֶׁזֶּהוּ כְּמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (רֹאשׁ הַשָּׁנָה יז. ב) הֲרֵי שֶׁהָיוּ יִשְׂרָאֵל צַדִּיקִים בְּרֹאשׁ הַשָּׁנָה וּפָסְקוּ עֲלֵיהֶם גְּשָׁמִים מְרוּבִּים לְסוֹף חָזְרוּ כו' מוֹרִידָן שֶׁלֹּא בִזְמַנָּן עַל הָאָרֶץ שֶׁאֵינָהּ צְרִיכָה לָהֶם, וְכַאֲשֶׁר לֹא הָיוּ מוּכְשָׁרִים וּפָסְקוּ עֲלֵיהֶם גְּשָׁמִים מוּעָטִים לְסוֹף חָזְרוּ כו' מוֹרִידָן בִּזְמַנָּן עַל הָאָרֶץ הַצְּרִיכָה לָהֶם.\n<b>וּבְזֹהַר</b> (חֵלֶק א קט. ב) עַל פָּסוּק זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא מְסַבֵּב סִבּוּבִין וְאַיְיתִי עוֹבָדִין בְּעָלְמָא לְאִתְקַיָּימָא וּלְבָתַר דַּחֲשִׁיבוּ בְּנֵי נָשָׁא דְּיִתְקַיְּימוּ אִינּוּן עוֹבָדִין, קוּדְשָׁא בְּרִיךְ הוּא מְהַפֵּךְ לוֹן לְאִינּוּן עוֹבָדִין מִכְּמָה דַּהֲוָה בְּקַדְמֵיתָא (הַיְינוּ שֶׁקּוֹרֵא הַדּוֹרוֹת וּבוֹרְאָן לְהִתְקַיֵּים כְּגוֹן דּוֹר הַמַּבּוּל וְהֵם חָשְׁבוּ שֶׁיִּהְיוּ קַיָּימִים לְעוֹלָם וְקִלְקְלוּ מַעֲשֵׂיהֶם וּבִטְּלָם וַהֲפָכָם מֵהַקִּיּוּם אֶל הַהֶעְדֵּר. אוֹר הַחַמָּה) בְּתַחְבּוּלֹתָו חָסֵר י' כו' דְּאִיהוּ טִקְלָא דְּאִסְתַּחֲרַת קַמֵּיהּ כו'. אִי מְטִיבִין בְּנֵי נָשָׁא עוֹבָדֵיהוֹן הַהִיא טִקְלָא דְּסָחֲרָא אַסְחָרַת לוֹן לְיַמִּינָא וּכְדֵין אִתְעֲבִידוּ עוֹבָדִין בְּעָלְמָא לְאוֹטָבָא לוֹן כו'. אָתוּ בְּנֵי נָשָׁא לְאַבְאָשָׁא כו' קוּדְשָׁא בְּרִיךְ הוּא אַסְחַר לֵיהּ בְּסִטְרָא דִשְׂמָאלָא וּמְהַפֵּךְ מְסִבּוֹת כו' וְאִתְעֲבִידוּ עוֹבָדִין בְּעָלְמָא לְאַבְאָשָׁא לוֹן לִבְנֵי נָשָׁא כו' עַד דִּבְנֵי נָשָׁא תָּיְיבִין לְאוֹטָבָא עוֹבָדֵיהֶן כו'.\n<b>וְהָעִנְיָן</b> הוּא דְּהִנֵּה טִקְלָא הוּא בְּחִינַת מַלְכוּת דַּאֲצִילוּת שֶׁהִיא מְקוֹר הַהַשְׁפָּעָה לִבְרִיאָה-יְצִירָה-עֲשִׂיָּה, וְהִיא מִסְתַּחָרַת כְּפוּם עוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא, דְּאִם מְטִיבִין מַעֲשֵׂיהֶם אֲזַי הַהוּא טִקְלָא דְּסָחֲרָא אַסְחָרַת לוֹן לְיַמִּינָא, הַיְינוּ שֶׁאָז מְקַבֶּלֶת הַמַּלְכוּת מִבְּחִינַת קַו הַיָּמִין דַּאֲצִילוּת שֶׁהוּא חָכְמָה-חֶסֶד-נֶצַח, וְאָז הוּא בְּחִינַת הִתְגַּבְּרוּת הַחֲסָדִים וְנִמְשָׁךְ טוֹב וָחֶסֶד בָּעוֹלָם לְמַטָּה, וְאִם חַס וְשָׁלוֹם לֵיכָּא אִתְעֲרוּתָא דִלְתַתָּא וְאֵין עוֹשֵׂה טוֹב כו', אֲזַי גּוֹרְמִים בְּמַעֲשֵׂיהֶם שֶׁתְּקַבֵּל הַמַּלְכוּת מִבְּחִינַת קַו הַשְּׂמֹאל כו', דְּהַכֹּל תָּלוּי בְּמַעֲשֵׂה הַתַּחְתּוֹנִים.\nקִיצּוּר.\nהַהַשְׁפָּעָה דְּרַב חֶסֶד הוּא בְּרִיבּוּי שֶׁלֹּא עַל פִּי הַחֶשְׁבּוֹן, חֶשְׁבּוֹן חָכְמָה בֹּאוּ וְנַחְשׁוֹב חֶשְׁבּוֹנוֹ שֶׁל עוֹלָם, כָּל הַהַשְׁפָּעוֹת בָּעוֹלָם עַל פִּי קַו הַמִּדָּה דְּתוֹרָה. אָדָם נִידּוֹן בְּכָל יוֹם (שָׁעָה) לְפִי מַעֲשָׂיו, שֶׁבָּזֶה תָּלוּי הַקַּבָּלָה וְהַהַשְׁפָּעָה דִסְפִירַת הַמַּלְכוּת אִם לְיָמִין וְטוֹב אוֹ לִשְׂמֹאל וְרָע."],[4401900052,"וְהִנֵּה הַמֵּנִיעַ אֶת הַטִּקְלָא וּמְסַבֵּב סִיבּוּב הַגַּלְגַּל שֶׁיִּהְיֶה מִתְהַפֵּךְ לְפָעֳלָם דִּבְנֵי נָשָׁא, הוּא בְּחִינַת קַו הַמִּדָּה דְחָכְמָה שֶׁהוּא הַמְהַפֵּךְ אֶת הַגַּלְגַּל לְפִי הָאִתְעֲרוּתָא דִלְתַתָּא, לְפִי שֶׁבְּחָכְמָה הִיא הַמְּדִידָה שֶׁיִּהְיֶה בְּאוֹפֶן כַּךְ וְכַךְ דַּוְקָא, הַיְינוּ שֶׁיִּהְיֶה קִיּוּם הַתּוֹרָה וּמִצְוֹת לִהְיוֹת סוּר מֵרָע בִּשְׁסָ\"ה לֹא תַעֲשֶׂה וְעַנְפֵיהֶן וְלִהְיוֹת וַעֲשֵׂה טוֹב בְּקִיּוּם רְמַ\"ח מִצְוֹת עֲשֵׂה וְעַנְפֵיהֶן, וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר ז פֶּרֶק ב) וְלָכֵן נִמְשָׁךְ מִשָּׁם תְּנוּעַת הַגַּלְגַּל, דְּאִם מְקַיְּימִים תּוֹרָה וּמִצְוֹת אָז תְּקַבֵּל הַמַּלְכוּת מִקַּו הַיָּמִין וְתִהְיֶה הַשְׁפָּעַת הַטּוֹב, וְהַיְינוּ שֶׁתִּהְיֶה הַהַנְהָגָה בִּבְחִינַת חֶסֶד, וְכַאֲשֶׁר חַס וְשָׁלוֹם לָא אִכְשִׁיר דָּרָא תִּהְיֶה הַהַנְהָגָה בִּבְחִינַת גְּבוּרָה כו'.\n<b>וְזֶהוּ</b> עִנְיַן הַחֶשְׁבּוֹן בְּב' דְּבָרִים, הָא' בְּעוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא לְמַטָּה אִם מוּכְשָׁרִים מַעֲשֵׂיהֶם עַל פִּי הַמְּדִידָה דְחָכְמַת הַתּוֹרָה, וְהַב' הַחֶשְׁבּוֹן בְּאוֹפֶן הַהִתְכַּלְלוּת דְּחֶסֶד וּגְבוּרָה, אִם תִּהְיֶה הִתְגַּבְּרוּת קַו הַיָּמִין שֶׁתִּהְיֶה הַהַנְהָגָה בִּבְחִינַת חֶסֶד אוֹ חַס וְשָׁלוֹם כו'.\n<b>וְזֶהוּ</b> דְּאִיתָא בְּמִשְׁנָה (אָבוֹת סוֹף פֶּרֶק ד) וְדַע שֶׁהַכֹּל לְפִי הַחֶשְׁבּוֹן, וּפֵרֵשׁ רַשִׁ\"י אַחַת לְאַחַת לִמְצוֹא חֶשְׁבּוֹן, פְּרוּטָה וּפְרוּטָה מִצְטָרֶפֶת לְחֶשְׁבּוֹן גָּדוֹל, וְכֵן יֵשׁ חֶשְׁבּוֹן לְהֵיפֶךְ, וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (חֲגִיגָה ה. ב הוּבָא בְּמִדְרַשׁ שְׁמוּאֵל עַל מִשְׁנָה זוֹ) עַל פָּסוּק וּמַגִּיד לְאָדָם מַה שֵּׂיחוֹ (עָמוֹס ד. יג) שֶׁאֲפִילוּ עַל שִׂיחָה שֶׁבֵּין אִישׁ לְאִשְׁתּוֹ, עֲבֵירוֹת שֶׁאָדָם דָּשׁ בַּעֲקֵבָיו, הַכֹּל בָּא לְפִי הַחֶשְׁבּוֹן כו'.\n<b>וְיֵשׁ</b> מְפָרְשִׁים הַמִּשְׁנָה וְדַע שֶׁהַכֹּל לְפִי הַחֶשְׁבּוֹן, שֶׁאִם ב' אֲנָשִׁים יֶחֶטְאוּ חֵטְא אֶחָד אֵין עוֹנְשָׁם וּפְגָמָם שָׁוֶה, שֶׁכְּפִי גּוֹדֶל יִקְרַת עֶרֶךְ הַנְּשָׁמָה שֶׁל זֶה יִהְיֶה פְגָמוֹ יוֹתֵר גָּדוֹל מִשֶּׁל חֲבֵירוֹ כו'.\n<b>וְכָל</b> זֶה הוּא עַל פִּי סֵדֶר הִשְׁתַּלְשְׁלוּת, וְהַיְינוּ הַחֶשְׁבּוֹן וְהַדִּין וּמִשְׁפָּט שֶׁנִּמְשָׁךְ מִן הַחָכְמָה שֶׁהִיא רֵאשִׁית הַהִשְׁתַּלְשְׁלוּת,\nאֲבָל מִצַּד אוֹר אֵין סוֹף שֶׁלְּמַעְלָה מֵהִשְׁתַּלְשְׁלוּת שָׁם אֵין דִּין וְחֶשְׁבּוֹן, לְפִי שֶׁאֵינוֹ תּוֹפֵס מָקוֹם מַעֲשֵׂה הַתַּחְתּוֹנִים וְנִמְשֶׁכֶת הַהַשְׁפָּעָה גַּם לְעוֹבְרֵי רְצוֹנוֹ בְּרִיבּוּי הַשֶּׁפַע שֶׁלֹּא עַל פִּי הַחֶשְׁבּוֹן כְּלָל. וְזֶהוּ הַטַּעַם אֲשֶׁר דֶּרֶךְ רְשָׁעִים צָלֵחָה, לְפִי שֶׁהוּא מַאֲרִיךְ אַף, שֶׁמְּקַבְּלִים מִבְּחִינַת אֶרֶךְ אַפַּיִם שֶׁלְּמַעְלָה מִבְּחִינַת חֶשְׁבּוֹן, שֶׁנִּמְשָׁךְ לָהֶם הַהַשְׁפָּעָה גַּם שֶׁאֵינָם רְאוּיִם, וּמִמֵּילָא נִמְשָׁךְ רִיבּוּי הַשְׁפָּעָה לְפִי שֶׁהִיא בִּבְחִינַת בְּלִי גְבוּל וּכְמוֹ שֶׁיִּתְבָּאֵר בְּסָמוּךְ.\nקִיצּוּר.\nתְּנוּעַת הַטִּקְלָא לְיָמִין בְּהַשְׁפָּעַת הַחֶסֶד וְלִשְׂמֹאל בְּהַשְׁפָּעַת הַגְּבוּרָה הוּא בְּחֶשְׁבּוֹן מְדוּיָּיק, א) לְפִי קִיּוּם הַתּוֹרָה וּמִצְוֹת. ב) בְּאוֹפֶן הַהִתְכַּלְלוּת דְּחֶסֶד וּגְבוּרָה, וְהַחֶשְׁבּוֹן בְּקִיּוּם הַתּוֹרָה וּמִצְוֹת וְהֶפְכּוֹ הוּא לְפִי חֲשִׁיבוּת הַפְּרָטִי שֶׁל כָּל נְשָׁמָה, דֶּרֶךְ רְשָׁעִים צָלֵחָה שֶׁמְּקַבְּלִים מִלְמַעְלָה מֵהִשְׁתַּלְשְׁלוּת."],[4401900053,"<h2>מַאֲמָר ט.</h2>\nוְהִנֵּה שֹׁרֶשׁ הָעִנְיָן הוּא, דְּהִנֵּה יָדוּעַ דְּסֵדֶר הִשְׁתַּלְשְׁלוּת הוּא בְּחִינַת אוֹר פְּנִימִי, וְהַיְינוּ הִתְלַבְּשׁוּת אוֹרוֹת בַּכֵּלִים דַּוְקָא, וְרֵאשִׁית הַכֵּלִים הוּא בִּבְחִינַת הַחָכְמָה, וּכְמוֹ עַל דֶּרֶךְ מָשָׁל בָּאָדָם לְמַטָּה, הֲרֵי כֹּחַ הַחָכְמָה הוּא הַכֹּחַ הָרִאשׁוֹן שֶׁמְּלוּבָּשׁ בַּכֵּלִים וְאֵבְרֵי הַגּוּף, דְּהָרָצוֹן שֶׁלְּמַעְלָה מֵהַחָכְמָה אֵין לוֹ כְּלִי מְיוּחֶדֶת בְּאֵבְרֵי הַגּוּף וְהוּא נִמְצָא בְּכָל הַגּוּף בְּשָׁוֶה, וְאַף שֶׁהוּא נִרְגָּשׁ יוֹתֵר בַּמּוֹחַ שֶׁבָּרֹאשׁ, הַיְינוּ מַה שֶּׁהַשֵּׂכֶל שֶׁבַּמּוֹחַ מַרְגִּישׁ אֶת הָרָצוֹן בְּהֶרְגֵּשׁ פְּנִימִי יוֹתֵר מֵהָרֶגֶל, אֲבָל הָרָצוֹן מִצַּד עַצְמוֹ נִמְצָא בָרֶגֶל כְּמוֹ בָרֹאשׁ, וְהָרְאָיָה שֶׁהֲרֵי כְּשֶׁעוֹלֶה בִּרְצוֹנוֹ לְנַעֲנֵעַ בְּרַגְלוֹ הוּא מְנַעֲנֵעַ תֵּכֶף וּמִיָּד בְּלִי שׁוּם שְׁהִיַּת זְמַן כְּלָל, וְאִם נֹאמַר שֶׁהָרָצוֹן מִשְׁכָּנוֹ בַּמּוֹחַ שֶׁבָּרֹאשׁ (כְּמוֹ הַשֵּׂכֶל שֶׁמִּשְׁכָּנוֹ בָּרֹאשׁ) הָיָה צָרִיךְ לִהְיוֹת שְׁהִיַּת זְמַן עַד שֶׁיָּבוֹא מִן הַמּוֹחַ לִפְעוֹל בְּהָרֶגֶל, וּכְמוֹ בִּפְעוּלּוֹת שֶׁמִּן כֹּחַ הַשֵּׂכֶל בָּרֶגֶל, כְּמוֹ אִימּוּן רַגְלָיו בְּהִילּוּךְ יָשָׁר אוֹ כְּמוֹ בְּרִיקּוּד עַל פִּי כַּוָּונַת הַשֵּׂכֶל לְפִי תְּנוּעַת הַנִּיגּוּן וְכַדּוֹמֶה, צָרִיךְ שְׁהִיַּת זְמַן וְאִימּוּן וְלֹא יָבֹא בְּדֶרֶךְ מִמֵּילָא, וְזֶהוּ לְפִי שֶׁבָּא דֶּרֶךְ הִשְׁתַּלְשְׁלוּת בְּהִתְלַבְּשׁוּת בְּדֶרֶךְ אוֹר פְּנִימִי, וְהַיְינוּ שֶׁבַּמּוֹחַ שֶׁבָּרֹאשׁ הוּא בְּדֶרֶךְ הִתְלַבְּשׁוּת מַמָּשׁ, שֶׁשָּׁם מִשְׁכַּן הַשֵּׂכֶל וּמִשְׁתַּלְשֵׁל מִכֹּחַ לַכֹּחַ כְּמוֹ מִן הַשֵּׂכֶל אֶל הַמִּדּוֹת עַד שֶׁבָּא אֶל כֹּחַ הַתְּנוּעָה שֶׁבָּרֶגֶל, וְהַכֹּל בְּדֶרֶךְ הִתְלַבְּשׁוּת שֶׁאוֹר הַשֵּׂכֶל מִתְלַבֵּשׁ מַמָּשׁ בְּכֹחַ הַתְּנוּעָה שֶׁבָּרֶגֶל, וְלָזֹאת צְרִיכִים לָזֶה הִשְׁתַּדְּלוּת וְהִתְעַסְּקוּת וּשְׁהִיַּת זְמַן, וְאִם הָיָה הָרָצוֹן גַּם כֵּן מְלוּבָּשׁ בְּאֵיזֶה כְלִי הָיוּ צְרִיכִים לָזֶה גַם כֵּן הִתְעַסְּקוּת וּשְׁהִיַּת זְמַן עַד שֶׁיִּפְעוֹל בָּרֶגֶל, וְאָנוּ רוֹאִין שֶׁהָרָצוֹן פּוֹעֵל הַתְּנוּעָה בְּהָרֶגֶל תֵּיכֶף בְּלִי שׁוּם שְׁהִיַּת זְמַן וּבְלִי שׁוּם הִתְעַסְּקוּת כְּלָל, וְהַיְינוּ לְפִי שֶׁהָרָצוֹן אֵין לוֹ כְּלִי מְיוּחָד בַּגּוּף וְנִמְצָא בָרֶגֶל כְּמוֹ בָרֹאשׁ, וְהַכֹּחַ הָרִאשׁוֹן שֶׁמִּתְלַבֵּשׁ בִּכְלִי הוּא כֹּחַ הַחָכְמָה שֶׁמִּתְלַבֵּשׁ בַּמּוֹחַ, וּתְלָת מוֹחִין אִינּוּן שֶׁהֵם כֵּלִים לְג' כֹּחוֹת חָכְמָה-בִּינָה-דַּעַת, וְהַמִּדּוֹת מִשְׁכָּנָם בַּלֵּב, וְכֵן כָּל הַכֹּחוֹת יֵשׁ לָהֶם כֵּלִים וְאֵבָרִים מְיוּחָדִים.\nקִיצּוּר.\nכֹּחוֹת פְּנִימִים מִתְלַבְּשִׁים בְּכֵלִים פְּרָטִים וּבָאִים בְּהִשְׁתַּלְשְׁלוּת וְכֹחַ הָרִאשׁוֹן הוּא כֹּחַ הַחָכְמָה, כֹּחַ הָרָצוֹן הוּא כֹּחַ מַקִּיף שֶׁנִּמְצָא בְּכָל הָאֵבָרִים וְאֵינוֹ בָּא בְּהִשְׁתַּלְשְׁלוּת, לָכֵן פְּעוּלַּת הַשֵּׂכֶל בָּאָה בְּהִתְעַסְּקוּת וְנִמְשָׁךְ שְׁהִיַּת זְמַן וּפְעוּלַּת הָרָצוֹן בְּלִי הִתְעַסְּקוּת וּבְלִי שְׁהִיַּת זְמַן."],[4401900054,"וְהַדּוּגְמָא מִזֶּה יוּבַן לְמַעְלָה דְּעֶשֶׂר סְפִירוֹת דַּאֲצִילוּת הֵן בְּחִינַת הִתְלַבְּשׁוּת אוֹרוֹת בַּכֵּלִים, וְרֵאשִׁיתָן הִיא סְפִירַת הַחָכְמָה וְנִקְרֵאת רֵאשִׁית לְפִי שֶׁהִיא רֵאשִׁית הַהִשְׁתַּלְשְׁלוּת וּמִסְּפִירַת הַחָכְמָה מִשְׁתַּלְשֵׁל לִסְפִירַת הַבִּינָה, דִּכְשֵׁם שֶׁהוּא בְּכֹחוֹת הַנֶּפֶשׁ אֲשֶׁר נְקוּדַּת הַחָכְמָה מְאִירָה בְּהַשָּׂגָה דְבִינָה וּבִינָה הִיא אֵם הַבָּנִים שֶׁמּוֹלִידָה אֶת הַמִּדּוֹת, הִנֵּה כֵּן הוּא בִּסְפִירוֹת הָעֶלְיוֹנוֹת שֶׁמֵּהַחָכְמָה מִשְׁתַּלְשֵׁל אֶל הַבִּינָה וּמִן הַמּוֹחִין אֶל הַמִּדּוֹת, וְהַכֹּל בְּהִתְלַבְּשׁוּת אוֹרוֹת בַּכֵּלִים,\nאֲבָל אוֹר אֵין סוֹף שֶׁלְּמַעְלָה מֵהִשְׁתַּלְשְׁלוּת הוּא בְּחִינַת אוֹר מַקִּיף שֶׁאֵינוֹ מִתְלַבֵּשׁ בַּכֵּלִים כְּלָל, וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל (פֶּרֶק א) בְּמָשָׁל כֹּחַ הָרָצוֹן שֶׁבַּנֶּפֶשׁ שֶׁאֵין לוֹ כְּלִי מְיוּחָד בַּגּוּף, וְאִם כֵּן אֵינוֹ בָא בִּבְחִינַת אוֹר פְּנִימִי כִּי אִם בְּאוֹר מַקִּיף. וּכְמוֹ כֵן יוּבַן הַדּוּגְמָא לְמַעְלָה בְּאוֹר אֵין סוֹף שֶׁלְּמַעְלָה מֵהִשְׁתַּלְשְׁלוּת שֶׁאֵינוֹ מִתְלַבֵּשׁ בַּכֵּלִים כִּי אִם הוּא בְּחִינַת אוֹר מַקִּיף,\nוְעַל פִּי זֶה מוּבָן מַה שֶּׁבְּסֵדֶר הִשְׁתַּלְשְׁלוּת יֵשׁ דִּין וְחֶשְׁבּוֹן בְּהַהַשְׁפָּעָה וּמִלְמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת נִמְשָׁךְ שֶׁלֹּא עַל פִּי דִין וְחֶשְׁבּוֹן, כִּי הִנֵּה בְּסֵדֶר הִשְׁתַּלְשְׁלוּת, לִהְיוֹת שֶׁהוּא אוֹר פְּנִימִי הִתְלַבְּשׁוּת אוֹרוֹת בַּכֵּלִים, הֲרֵי צָרִיךְ כְּלִי שֶׁיִּהְיֶה רָאוּי לְגִילּוּי הָאוֹר, וּמַה שֶּׁאֵינוֹ רָאוּי לְגִילּוּי אוֹר לֹא יוּכַל לְקַבֵּל, וְהַכְּלִי הָרָאוּי לְגִילּוּי אוֹר הוּא הַבִּיטּוּל, דְּמַה שֶּׁבָּטֵל לֵאלֹקוּת הוּא הַכְּלִי הָרָאוּי לְקַבֵּל גִּילּוּי אוֹר, וּכְיָדוּעַ דְּאוֹר אֵין סוֹף שׁוֹרֶה בִּמְקוֹם הַבִּיטּוּל דַּוְקָא (וְלָכֵן עִיקַּר הַשְׁרָאַת אוֹר אֵין סוֹף הוּא בְּחָכְמָה דַוְקָא, לְפִי שֶׁחָכְמָה הִיא כֹּחַ מָה שֶׁהוּא בְּחִינַת הַבִּיטּוּל וּכְמוֹ שֶׁכָּתוּב בְּסֵפֶר שֶׁל בֵּינוֹנִים פֶּרֶק ל\"ה בְּהַגָּהָ\"ה),\nאֲבָל מַה שֶּׁהוּא בִּבְחִינַת יֵשׁוּת אֵין אֲנִי וָהוּא יְכוֹלִים לָדוּר, שֶׁאֵינוֹ כְּלִי לְגִילּוּי אוֹר וְחַיּוּת אֱלֹקִי כִּי אִם מִי שֶׁבָּטֵל דַּוְקָא וְהַיְינוּ כָּל סִטְרָא דִקְדוּשָּׁה שֶׁהֵם בִּבְחִינַת בִּיטּוּל שָׁם שׁוֹרֶה קְדוּשָּׁתוֹ יִתְבָּרֵךְ וּכְמוֹ שֶׁכָּתוּב בְּסֵפֶר שֶׁל בֵּינוֹנִים (חֵלֶק א פֶּרֶק ו) יְעוּיַּן שָׁם.\n<b>וְזֶהוּ</b> שֶׁבְּסֵדֶר הִשְׁתַּלְשְׁלוּת שָׁם יֵשׁ דִּין וְחֶשְׁבּוֹן, אִם הוּא רָאוּי לְהָאוֹר וְהַחַיּוּת הָאֱלֹקִי, דְּמַה שֶּׁאֵינוֹ בָּטֵל אֶצְלוֹ יִתְבָּרֵךְ, אֶלָּא הוּא דָּבָר נִפְרָד בִּפְנֵי עַצְמוֹ אֵינוֹ מְקַבֵּל מִקְּדוּשָּׁתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (רַק מִבְּחִינַת אֲחוֹרַיִים וְחִיצוֹנִיּוּת כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל מַאֲמָר ב פֶּרֶק ב וּמַאֲמָר ז פֶּרֶק א בְּעִנְיַן קַבָּלַת הַחַיּוּת דְּסִטְרָא אָחֳרָא שֶׁנִּקְרָאִים אֱלֹקִים אֲחֵרִים), כִּי אִם מִי שֶׁבָּטֵל אֵלָיו יִתְבָּרֵךְ וּמְקַיֵּים רְצוֹנוֹ יִתְבָּרֵךְ הוּא הָרָאוּי לְהַשְׁפָּעַת הַחַיּוּת מֵאוֹר קְדוּשָּׁתוֹ יִתְבָּרֵךְ.\nקִיצּוּר.\nעֶשֶׂר סְפִירוֹת דַּאֲצִילוּת הֵם אוֹרוֹת פְּנִימִים הַמִּתְלַבְּשִׁים בְּכֵלִים מַתְאִימִים וּבָאִים בְּהִשְׁתַּלְשְׁלוּת, וְהַסְּפִירָה הָרִאשׁוֹנָה הִיא חָכְמָה כֹּחַ מָה, וְהַהַשְׁפָּעָה בָּאָה בְּחֶשְׁבּוֹן לְפִי אוֹפֶן הַבִּיטּוּל, דְּבִיטּוּל הִיא כְּלִי רְאוּיָה לְהַשְׁרָאַת קְדוּשָּׁתוֹ יִתְבָּרֵךְ."],[4401900055,"אָמְנָם כָּל עִנְיַן הַדִּין וְהַחֶשְׁבּוֹן הוּא רַק מִצַּד סֵדֶר הִשְׁתַּלְשְׁלוּת, דְּכַךְ הִיא הַמִּדָּה בְּהִשְׁתַּלְשְׁלוּת שֶׁמּוּכְרָח שֶׁיִּהְיֶה בְּדִין וְחֶשְׁבּוֹן מְדוּיָּק מִצַּד אַרְבָּעָה טְעָמִים, הָא' לִהְיוֹתוֹ אוֹר פְּנִימִי, ב' מִצַּד עִנְיַן הַסֵּדֶר, ג' לִהְיוֹתוֹ אוֹר בִּכְלִי, ד' מִצַּד הַהִשְׁתַּלְשְׁלוּת לְדַרְגָּא שֶׁלְּמַטָּה מִמֶּנּוּ.\n<b>כָּל</b> אוֹר אֵיזֶה שֶׁהוּא בֵּין אוֹר הַמּוֹחִין בֵּין אוֹר הַמִּדּוֹת הֲרֵי יֵשׁ לוֹ טִבְעוֹ הָעַצְמִי בְּמַה שֶּׁהוּא, דְּאוֹר הַמּוֹחִין הוּא בְּטֶבַע הַהִתְיַישְּׁבוּת וְהַמְּנוּחָה וְאוֹר הַמִּדּוֹת בְּטֶבַע הַהִתְרַגְּשׁוּת וְהַהִתְפַּעֲלוּת, כֵּן הוּא בְּאוֹר הַפְּנִימִי שֶׁיֵּשׁ לוֹ טִבְעוֹ הָעַצְמִי בְּמַה שֶּׁהוּא מְחוּשְׁבָּן וּמְדוּיָּק,\nטֶבַע הַסֵּדֶר הוּא טֶבַע הַחֶשְׁבּוֹן וְהַדִּיּוּק בְּכַמּוּת וּבְאֵיכוּת.\n<b>וְאוֹרוֹת</b> הַמִּתְלַבְּשִׁים בַּכֵּלִים הִנֵּה אַף גַּם כַּאֲשֶׁר כְּלָלוּת הַכֵּלִים מַתְאִימִים אֶל הָאוֹרוֹת, כְּמוֹ חוֹמֶר הַמּוֹחַ שֶׁהוּא בִּכְלָלוּתוֹ כְּלִי אֶל הַשְׁרָאַת הַשֵּׂכֶל וְחוֹמֶר הַלֵּב שֶׁהוּא בִּכְלָלוּתוֹ כְּלִי אֶל מִשְׁכַּן הַמִּדּוֹת, בְּכָל זֶה הֲרֵי בְּהֶכְרַח שֶׁתִּהְיֶה מְדִידָה בְּאוֹר הַשֵּׂכֶל בְּאוֹפֶן הַשְׁרָאָתוֹ בְּמוֹחַ שֶׁבָּרֹאשׁ, וְכֵן בְּעִנְיַן הַמִּדּוֹת, דְּאִם לֹא כֵן הֲרֵי הַכֵּלִים דְּחוֹמֶר הַמּוֹחַ וְחוֹמֶר הַלֵּב לֹא יָכִילוּ אֶת הָאוֹר הַמְרוּבֶּה וּמִתְקַלְקְלִים רַחֲמָנָא לִצְּלָן, וּכְמוֹ שֶׁאָנוּ רוֹאִים בְּמוּחָשׁ רַחֲמָנָא לִצְּלָן בְּכַמָּה חוֹלִים בְּחוֹלִי הַמּוֹחַ וְחוֹלִי הַלֵּב שֶׁבָּא בְּסִבַּת רִיבּוּי הָאוֹר וּמִיעוּט הַכֵּלִים,\nוְאוֹר שֶׁעִנְיָנוֹ לְהִשְׁתַּלְשֵׁל לְדַרְגָּא שֶׁלְּמַטָּה מִמֶּנּוּ, הֲרֵי בְּהֶכְרַח שֶׁהָאוֹר יִהְיֶה מְחוּשְׁבָּן וּמְדוּיָּק לְפִי גּוֹדֶל וְרוֹחַב הַכְּלִי, דְּלוּלֵא זֹאת הִנֵּה לֹא זוֹ בִּלְבָד שֶׁהַכְּלִי לֹא יְקַבֵּל אֶת הָאוֹר, אֶלָּא עוֹד זֹאת שֶׁהָאוֹר מְאַבֵּד אֶת הַכְּלִי וּמְשַׁבְּרוֹ, כְּמוֹ שֶׁאָנוּ רוֹאִים בְּמוּחָשׁ בְּהַשְׁפָּעַת הַשֵּׂכֶל מֵהָרַב לְתַלְמִידוֹ, דְּכַאֲשֶׁר הַהַשְׁפָּעָה אֵינָהּ לְפִי עֶרֶךְ כְּלֵי שֵׂכֶל הַתַּלְמִיד, הִנֵּה לֹא זוֹ בִּלְבָד שֶׁהַתַּלְמִיד אֵינוֹ מְקַבֵּל אֶת הַשֵּׂכֶל הַנִּשְׁפָּע לוֹ, אֶלָּא עוֹד זֹאת שֶׁכְּלֵי שִׂכְלוֹ מִתְבַּלְבְּלִים, וְטַעַם הַדָּבָר הוּא דְּכָל אוֹר הַמִּשְׁתַּלְשֵׁל מִדַּרְגָּא לְדַרְגָּא שֶׁלְּמַטָּה הֵימֶנּוּ צָרִיךְ לִהְיוֹת לְפִי עֶרֶךְ הַדַּרְגָּא הַהִיא,\nוְהַדּוּגְמָא מִזֶּה יוּבַן לְמַעְלָה בִּסְפִירוֹת הָעֶלְיוֹנוֹת הַמִּשְׁתַּלְשְׁלוֹת, אֲבָל מִצַּד אוֹר אֵין סוֹף שֶׁלְּמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת שֶׁנִּמְשָׁךְ בִּבְחִינַת מַקִּיף וְאֵינוֹ מִתְלַבֵּשׁ בַּכֵּלִים, הֲרֵי אֵינוֹ נוֹגֵעַ אִם הוּא רָאוּי לְגִילּוּי הָאוֹר וְהַחַיּוּת, אוֹ שֶׁאֵינוֹ רָאוּי, מֵאַחַר שֶׁאֵינוֹ צָרִיךְ לַכֵּלִים כְּלָל, הֲרֵי נִמְשָׁךְ גַּם לְמָקוֹם שֶׁאֵינוֹ רָאוּי (הַיְינוּ שֶׁאֵינוֹ כְלִי) כְּמוֹ לְמָקוֹם הָרָאוּי. וְזֶהוּ שֶׁגַּם הַקְּלִיפּוֹת וְהַסִּטְרָא אָחֳרָא וְעוֹבְרֵי רְצוֹנוֹ יְכוֹלִים לְקַבֵּל מִשָּׁם אַף שֶׁאֵינָם כֵּלִים הָרְאוּיִם כְּלָל, לְפִי שֶׁאֵינוֹ צָרִיךְ לַכֵּלִים כְּלָל, אֵינוֹ שַׁיָּיךְ בּוֹ עִנְיַן הַסֵּדֶר וְנִמְשָׁךְ מִשָּׁם רִיבּוּי שֶׁפַע וְחַיּוּת בְּיוֹתֵר לִהְיוֹת שֶׁהוּא בִּבְחִינַת בְּלִי גְבוּל,\nדְּהָאוֹר דְּסֵדֶר הִשְׁתַּלְשְׁלוּת מֵאַחַר שֶׁהוּא אוֹר פְּנִימִי וּמִתְלַבֵּשׁ בִּכְלִי הֲרֵי הוּא מוּגְבָּל לְפִי אוֹפֶן הַכֵּלִים וְשַׁיָּיךְ בּוֹ עִנְיַן הַסֵּדֶר וְעִנְיַן הַהִשְׁתַּלְשְׁלוּת, אֲבָל הָאוֹר שֶׁלְּמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת מֵאַחַר שֶׁהוּא אוֹר מַקִּיף אֵינוֹ מוּגְבָּל וְלָזֹאת נִמְשָׁךְ מִשָּׁם רִיבּוּי שֶׁפַע,\nוְזֶהוּ שֶׁכָּתוּב (עוֹבַדְיָה א. ד) אִם תַּגְבִּיהַּ כַּנֶּשֶׁר, כְּמוֹ דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם (מִשְׁלֵי ל. יט) כְּמוֹ כֵן הַקְּלִיפּוֹת וְהַסִּטְרָא אָחֳרָא מַגְבִּיהִים אֶת עַצְמָם לְקַבֵּל מִבְּחִינַת הַמַּקִּיף עֶלְיוֹן לְפִי שֶׁמִּשָּׁם נִמְשָׁךְ בְּלִי דִין וְחֶשְׁבּוֹן הַיְינוּ גַּם שֶׁאֵינָם בְּטֵלִים כְּלָל לֵאלֹקוּת, וְאַדְרַבָּא עוֹבְרִים רְצוֹנוֹ יִתְבָּרֵךְ לְגַמְרֵי, וְנִמְשָׁךְ מִשָּׁם הַשֶּׁפַע בְּרִיבּוּי בְּיוֹתֵר. וְזֶהוּ הַטַּעַם בְּהַצְלָחַת הָעַכּוּ\"ם בְּרִיבּוּי עוֹשֶׁר וְכָבוֹד בָּעוֹלָם הַזֶּה, וְגַם הֵמָּה שׁוֹלְטִים עַל יִשְׂרָאֵל, וְהַיְינוּ מִפְּנֵי שֶׁשֹּׁרֶשׁ קַבָּלָתָם הוּא מִבְּחִינָה שֶׁלְּמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת, דְּהַשְׁפָּעָה לְיִשְׂרָאֵל הִיא עַל יְדֵי תּוֹרָה וּמִצְוֹת וּבָאָה בְּסֵדֶר הִשְׁתַּלְשְׁלוּת, וְהַהַשְׁפָּעָה לְעַכּוּ\"ם הִיא מִלְמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת וְהִיא בְּלִי חֶשְׁבּוֹן וּגְבוּל.\nקִיצּוּר.\nמִסְּפִירַת הַחָכְמָה וּלְמַטָּה בָּא בַחֶשְׁבּוֹן מִד' טְעָמִים. א) אוֹר פְּנִימִי. ב) סֵדֶר. ג) מִתְלַבֵּשׁ בִּכְלִי. ד) מִשְׁתַּלְשֵׁל לְמַטָּה מִמַּדְרֵיגָתוֹ, לְמַעְלָה מִן הַחָכְמָה הוּא לְמַעְלָה מֵהִשְׁתַּלְשְׁלוּת אֵינוֹ בָּא בַחֶשְׁבּוֹן, וּמֵהַאי טַעֲמָא הַסִּטְרָא אָחֳרָא מַגְבִּיהַּ עַצְמָהּ לְקַבֵּל מִשָּׁם לִהְיוֹתָהּ בְּלִי דִיּוּק וּבְרִיבּוּי."],[4401900056,"<h2>מַאֲמָר י.</h2>\nוְזֶהוּ דִּכְתִיב (דְּבָרִים כט. יח) וְהִתְבָּרֵךְ בִּלְבָבוֹ לֵאמֹר שָׁלוֹם יִהְיֶה לִּי כִּי בִּשְׁרִירוּת לִבִּי אֵלֵךְ שֶׁהָעוֹבֵר עֲבֵירָה מִתְבָּרֵךְ בִּלְבָבוֹ שֶׁיִּהְיֶה שָׁלוֹם לוֹ בְּהַשְׁפָּעַת הַחַיּוּת וְכָל הַטּוֹב, וְאַדְרַבָּא בְּרִיבּוּי הַהַשְׁפָּעָה, כִּי בִּשְׁרִירוּת לִבִּי אֵלֵךְ דִּלְפִי שֶׁהוֹלֵךְ בִּשְׁרִירוּת לִבּוֹ שֶׁלֹּא עַל פִּי הַתּוֹרָה דַּוְקָא עַל יְדֵי זֶה יְדַמֶּה בְנַפְשׁוֹ לְקַבֵּל רִיבּוּי הַשְׁפָּעָה מִבְּחִינַת מַקִּיף עֶלְיוֹן שֶׁלֹּא עַל פִּי חֶשְׁבּוֹן כְּמוֹ הַקְּלִיפּוֹת וְסִטְרָא אָחֳרָא, וְזֶהוּ כִּי בִּשְׁרִירוּת לִבִּי אֵלֵךְ, שֶׁהוּא כְּמוֹ נְתִינַת טַעַם עַל וְהִתְבָּרֵךְ כו' שָׁלוֹם יִהְיֶה כו' שֶׁעַל יְדֵי זֶה יְקַבֵּל מִבְּחִינַת הַמַּקִּיף שֶׁלֹּא עַל יְדֵי סֵדֶר הִשְׁתַּלְשְׁלוּת,\nלְמַעַן סְפוֹת הָרָוָה אֶת הַצְּמֵאָה, דִּסְפוֹת הוּא לְשׁוֹן רִיבּוּי, וְהַיְינוּ שֶׁבְּהָרָוָה שֶׁהִיא הַסִּטְרָא אָחֳרָא נִמְשָׁךְ רִיבּוּי הַשְׁפָּעָה יוֹתֵר (כַּנַ\"ל מַאֲמָר ט פֶּרֶק ג) מִכְּמוֹ בְּהַצְּמֵאָה שֶׁהוּא סִטְרָא דִקְדוּשָּׁה שֶׁנִּמְשֶׁכֶת הַהַשְׁפָּעָה עַל יְדֵי סֵדֶר הִשְׁתַּלְשְׁלוּת שֶׁהוּא בִּבְחִינַת גְּבוּל, אֲבָל הָרָוָה מְקַבֶּלֶת מִלְמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת בְּלִי דִין וְחֶשְׁבּוֹן,\nוְעַל זֶה אוֹמֵר (שָׁם כט. יט) לֹא יֹאבֶה ה' סְלוֹחַ לוֹ, דְּדַוְקָא עַכּוּ\"ם יְכוֹלִים לְקַבֵּל מִבְּחִינַת הַמַּקִּיף שֶׁלֹּא עַל יְדֵי סֵדֶר הִשְׁתַּלְשְׁלוּת אֲבָל לֹא יִשְׂרָאֵל, כִּי יִשְׂרָאֵל הֵם בְּעֶצֶם מִבְּחִינַת הַפְּנִימִית וּכְמוֹ שֶׁכָּתוּב (דְּבָרִים לב. ט) כִּי חֵלֶק ה' עַמּוֹ, וְיָדוּעַ דְּשֵׁם הוי' הוּא בְּסֵדֶר הִשְׁתַּלְשְׁלוּת י' בְּחָכְמָה, ה' בְּבִינָה ו' בְּזָ\"א [בִּזְעֵיר אַנְפִּין] ה' אַחֲרוֹנָה בְּמַלְכוּת, וּבְכָל מָקוֹם שֵׁם הוי' הוּא בִּבְחִינַת הַפְּנִימִית דַּוְקָא, וּכְתִיב (דְּבָרִים יד. ב) וּבְךָ בָּחַר ה', כִּי יַעֲקֹב בָּחַר לוֹ יָהּ (תְּהִלִּים קלה. ד) וְעִנְיַן הַבְּחִירָה הוּא הַבֵּירוּר שֶׁמְּבָרֵר וּבוֹחֵר בָּזֶה דַוְקָא כִּדְאִיתָא בְּמִדְרָשׁ רַבָּה (בַּמִּדְבָּר פַּרְשָׁה כ) מֶלֶךְ שֶׁבֵּירֵר לְעַצְמוֹ מָנָה וְעָמַד אֶחָד וְאָמַר גְּנַאי עָלֶיהָ כְּלוּם יֵשׁ לוֹ חַיִּים, וְאֵלּוּ (יִשְׂרָאֵל) חֶבְלָתוֹ וְנַחֲלָתוֹ וּסְגוּלָּתוֹ שֶׁנֶּאֱמַר (דְּבָרִים לב. ט) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ (שְׁמוֹת יט. ה) וִהְיִיתֶם לִי סְגוּלָּה, וְזֶהוּ הַבְּחִירָה מַה שֶּׁבֵּירֵר יִשְׂרָאֵל לְעַצְמוֹ דְּזֶה שַׁיָּיךְ בִּבְחִינַת פְּנִימִית דַּוְקָא,\nוּכְמוֹ כֵן נִשְׁמוֹת יִשְׂרָאֵל בָּחֲרוּ בַה', וּכְמוֹ שֶׁכָּתוּב (אֵיכָה ג. כד) חֶלְקִי ה' אָמְרָה נַפְשִׁי, וְאִיתָא בְּמִדְרָשׁ רַבָּה (אֵיכָה עַל פָּסוּק זֶה) רַבִּי אַבוּהָ בְּשֵׁם רַבִּי יוֹחָנָן אָמַר לַמֶּלֶךְ שֶׁנִּכְנַס לַמְּדִינָה וְהָיוּ עִמּוֹ דּוּכְסִין וְאִיפַרְכִין וְאִיסְטַרְטִילוּטִין וְהָיוּ גְּדוֹלֵי מְדִינָה יוֹשְׁבִים בְּאֶמְצַע הַמְּדִינָה, חַד אָמַר אֲנָא נָסִיב דּוּכְסִין לְגַבִּי, חַד אָמַר אֲנָא נָסִיב אִיפַרְכִין לְגַבִּי, וְחַד אָמַר אֲנָא נָסִיב אִיסְטַרְטִילוּטִין לְגַבִּי, הָיָה פִּקֵּחַ אֶחָד לְשָׁם אָמַר אֲנָא נָסִיב לְמַלְכָּא דְּכוּלְּהוּ מִתְחַלְּפִין וּמַלְכָּא אֵינוֹ מִתְחַלֵּף, כַּךְ עַכּוּ\"ם מֵהֶן עוֹבְדִין לְחַמָּה מֵהֶן עוֹבְדִין לִלְבָנָה וּמֵהֶן עוֹבְדִין לְעֵץ וָאֶבֶן אֲבָל יִשְׂרָאֵל אֵינָן עוֹבְדִין אֶלָּא לְהַקָּדוֹשׁ בָּרוּךְ הוּא הֲדָא הוּא דִכְתִיב חֶלְקִי ה' אָמְרָה נַפְשִׁי.\n<b>וְזֶהוּ</b> שֶׁהַתּוֹרָה נִיתְּנָה לָנוּ, דְּאוֹרַיְיתָא מֵחָכְמָה נָפְקַת, דְּעִנְיַן הַתּוֹרָה וּמִצְוֹת הוּא מִצַּד הַפְּנִימִית שֶׁשָּׁם הוּא הַחֶשְׁבּוֹן וְהַמְּדִידָה שֶׁצָּרִיךְ לִהְיוֹת בְּאוֹפֶן כַּךְ וְכַךְ דַּוְקָא, וְנִיתְּנָה הַתּוֹרָה לְיִשְׂרָאֵל דַּוְקָא לְפִי שֶׁהֵם מִבְּחִינַת פְּנִימִית.\nקִיצּוּר.\nהַחוֹטֵא הַחוֹשֵׁב דִּכְשֶׁיֵּלֵךְ בִּשְׁרִירוּת לִבּוֹ שָׁלוֹם יִהְיֶה לוֹ בְּדוּגְמַת הַסִּטְרָא אָחֳרָא שֶׁמְּקַבֶּלֶת מֵהַמַּקִּיף שֶׁפַע מְרוּבֶּה טוֹעֶה הוּא, לִהְיוֹת דְּיִשְׂרָאֵל הֵם מֵהַפְּנִימִית, וְהַיְינוּ דְּהֵן בְּחִירַת הָעַצְמוּת כִּבְיָכוֹל בְּיִשְׂרָאֵל וְהֵן בְּחִירַת יִשְׂרָאֵל בְּעַצְמוּת בָּרוּךְ הוּא הוּא מִצַּד הַפְּנִימִיּוּת."],[4401900057,"וּבֶאֱמֶת הִנֵּה בִּפְנִימִית וְעַצְמוּת אוֹר אֵין סוֹף הָעִיקָּר הֵן מְקַיְּימֵי תּוֹרָה וּמִצְוֹת, וּמַה שֶּׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר ט פֶּרֶק ג) דְּמִבְּחִינַת הַמַּקִּיף יְכוֹלִים הַכֹּל לְקַבֵּל, גַּם הַקְּלִיפּוֹת וְהַסִּטְרָא אָחֳרָא, זֶהוּ בִּבְחִינַת חִיצוֹנִיּוּת הַמַּקִּיף לְבָד, אֲבָל בִּבְחִינַת פְּנִימִית הַמַּקִּיף שָׁם הַכַּוָּונָה שֶׁיִּהְיֶה קִיּוּם תּוֹרָה וּמִצְוֹת דַּוְקָא,\nוְכִדְאִיתָא בְּמִדְרָשׁ רַבָּה (בְּרֵאשִׁית פַּרְשָׁה ב) וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ אֵלּוּ מַעֲשֵׂיהֶן שֶׁל רְשָׁעִים וַיֹּאמֶר אֱלֹקִים יְהִי אוֹר אֵלּוּ מַעֲשֵׂיהֶן שֶׁל צַדִּיקִים אֲבָל אֵינִי יוֹדֵעַ בְּאֵיזֶה מֵהֶן חָפֵץ אִם בְּמַעֲשֵׂה אֵלּוּ וְאִם בְּמַעֲשֵׂה אֵלּוּ, כֵּיוָן דִּכְתִיב וַיַּרְא אֱלֹקִים אֶת הָאוֹר כִּי טוֹב הָוֵי בְּמַעֲשֵׂיהֶן שֶׁל צַדִּיקִים חָפֵץ וְאֵינוֹ חָפֵץ בְּמַעֲשֵׂיהֶן שֶׁל רְשָׁעִים,\nוְיָדוּעַ דְּחֵפֶץ הוּא פְּנִימִית הָרָצוֹן, וּבִבְחִינַת פְּנִימִית הָרָצוֹן שֶׁהוּא בְּחִינַת פְּנִימִית הַמַּקִּיף חָפֵץ בְּמַעֲשֵׂיהֶם שֶׁל צַדִּיקִים דַּוְקָא, וּמִשָּׁם נִמְשָׁךְ שֹׁרֶשׁ הַהַמְשָׁכָה בִּבְחִינַת פְּנִימִית שֶׁהוּא בְּחִינַת סֵדֶר הַהִשְׁתַּלְשְׁלוּת, דַּהֲגַם דְּסֵדֶר הַהִשְׁתַּלְשְׁלוּת שֶׁמֵּהַחָכְמָה וּלְמַטָּה הוּא לְמַטָּה בְּמַדְרֵיגָה מִבְּחִינַת הַמַּקִּיף שֶׁלְּמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת, הִנֵּה שָׁרְשׁוֹ הוּא לְמַעְלָה מִבְּחִינַת הַמַּקִּיף עֶלְיוֹן, וְהַיְינוּ בִּבְחִינַת פְּנִימִית הַמַּקִּיף,\nוּלְפִי זֶה מוּבָן דְּנִשְׁמוֹת יִשְׂרָאֵל שֶׁמְּקַבְּלִים עַל יְדֵי תּוֹרָה וּמִצְוֹת מִבְּחִינַת אוֹר פְּנִימִי דְּסֵדֶר הִשְׁתַּלְשְׁלוּת שֹׁרֶשׁ הַהַמְשָׁכָה הוּא מִבְּחִינַת פְּנִימִית וְעַצְמוּת לְמַעְלָה בְּאֵין עֲרוֹךְ מִבְּחִינַת הַמַּקִּיף עֶלְיוֹן. וְיִתְרוֹן הַמַּעֲלָה בָּזֶה שֶׁהָאוֹר נִמְשָׁךְ בִּבְחִינַת פְּנִימִית וּמִתְאַחֵד עִמָּהֶם, דְּהִנֵּה הַסִּטְרָא אָחֳרָא כְּשֶׁמַּגְבִּיהִים אֶת עַצְמָם לְקַבֵּל מִבְּחִינַת הַמַּקִּיף עֶלְיוֹן הֲרֵי הָאוֹר אֵינוֹ מִתְאַחֵד עִמָּהֶם חַס וְשָׁלוֹם שֶׁהֲרֵי אֵין קֹדֶשׁ מִתְעָרֵב בַּחוֹל, וּבִפְרָט שֶׁהוּא אוֹר מַקִּיף הֲרֵי הָאוֹר מוּבְדָּל מֵהֶם לְגַמְרֵי וְאֵין לָהֶם שׁוּם שַׁיָּיכוּת אֶל הָאוֹר כְּלָל וּכְלָל, אֲבָל בְּנִשְׁמוֹת יִשְׂרָאֵל הֲרֵי הָאוֹר מֵאִיר בִּבְחִינַת פְּנִימִית מַמָּשׁ וּמִתְאַחֵד עִמָּהֶם וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל, וְאִם כֵּן מוּבָן דְּשֹׁרֶשׁ הַהַמְשָׁכָה הוּא לְמַעְלָה הַרְבֵּה מִבְּחִינַת הַמַּקִּיף.\n<b>וְזֶהוּ</b> לֹא יֹאבֶה ה' סְלוֹחַ לוֹ דְּדַוְקָא עַכּוּ\"ם שֶׁהֵם מִבְּחִינַת אֲחוֹרַיִים וְחִיצוֹנִיּוּת לְבָד לָכֵן יְכוֹלִים לְקַבֵּל גַּם מִבְּחִינַת חִיצוֹנִיּוּת הַמַּקִּיף שֶׁנִּמְשֶׁכֶת לָהֶם הַהַשְׁפָּעָה מִשָּׁם, אֲבָל לְיִשְׂרָאֵל אֵינוֹ נִמְשָׁךְ מִבְּחִינָה זוֹ דַּאֲחוֹרַיִים כִּי אִם מִבְּחִינַת הַפְּנִימִיּוּת, וּבַפְּנִימִיּוּת צָרִיךְ לִהְיוֹת כְּלִי הָרָאוּי דַּוְקָא לְקַבָּלַת הָאוֹר וְהַחַיּוּת.\nקִיצּוּר.\nבִּפְנִימִית אוֹר אֵין סוֹף הָעִיקָּר הֵן מְקַיְּימֵי תּוֹרָה וּמִצְוֹת, קְלִיפּוֹת וְסִטְרָא אָחֳרָא מְקַבְּלִים מֵחִיצוֹנִיּוּת הַמַּקִּיף וְהָאוֹר מוּבְדָּל מֵהֶם, וּלְיִשְׂרָאֵל הַהַמְשָׁכָה מִפְּנִימִית הַמַּקִּיף וּבָאָה בְּהִשְׁתַּלְשְׁלוּת וְהָאוֹר מִתְאַחֵד עִמָּהֶם, וְשֹׁרֶשׁ הַהַמְשָׁכָה מֵהָעַצְמוּת שֶׁלְּמַעְלָה מֵהַמַּקִּיף."],[4401900058,"וְהִנֵּה זֶהוּ הַטַּעַם מַה שֶּׁיִּשְׂרָאֵל נְתוּנִים בַּגָּלוּת וּמוּכְנָעִים וּמוּשְׁפָּלִים שֶׁזֶּהוּ עַל יְדֵי הַחֲטָאִים וַעֲווֹנוֹת, דְּבִזְמַן שֶׁהָיוּ עוֹשִׂים רְצוֹנוֹ שֶׁל מָקוֹם בְּקִיּוּם הַתּוֹרָה וּמִצְוֹת כְּמוֹ בִּזְמַן הַבַּיִת הָיוּ בְּמַעֲלָה עֶלְיוֹנָה מְאֹד וְהָיָה לָהֶם רִיבּוּי הַשְׁפָּעָה בְּגַשְׁמִיּוּת שֶׁהָיוּ אִישׁ תַּחַת גַּפְנוֹ וְאִישׁ תַּחַת תְּאֵנָתוֹ, וּבִזְמַן הַגָּלוּת חֲסֵרִים מִכָּל טוֹב בְּגַשְׁמִיּוּת וְנִכְנָעִים וּמוּשְׁפָּלִים מְאֹד שֶׁזֶּהוּ בְּסִבַּת הַחֲטָאִים וַעֲווֹנוֹת אֲשֶׁר מָלֵא מִזֶּה בְּכָל דִּבְרֵי הַנְּבִיאִים,\nוְלִכְאוֹרָה אֵינוֹ מוּבָן לָמָה אֵינָם מְקַבְּלִים הַשְׁפָּעַת חַיּוּתם מִבְּחִינַת הַמַּקִּיף שֶׁשָּׁם אֵין הַחֵטְא וְעָוֹן תּוֹפֵס מָקוֹם כַּנַ\"ל, אֶלֶּא זֶהוּ מִפְּנֵי שֶׁיִּשְׂרָאֵל הֵם בְּעֶצֶם בְּחִינַת פְּנִימִית וְהַשְׁפָּעַת הַחַיּוּת שֶׁלָּהֶם הוּא מִבְּחִינַת אוֹר פְּנִימִי עַל יְדֵי קִיּוּם הַתּוֹרָה וּמִצְוֹת, וּכְמוֹ שֶׁכָּתוּב (וַיִּקְרָא כו. ג-ד) אִם בְּחֻקֹּתַי תֵּלֵכוּ וגו' וְנָתַתִּי גִשְׁמֵיכֶם בְּעִתָּם וְנָתְנָה הָאָרֶץ יְבוּלָהּ גו' שֶׁכָּל הַיִּעוּדִים הַגַּשְׁמִים הַכֹּל הוּא עַל יְדֵי קִיּוּם הַתּוֹרָה וּמִצְוֹת, וְגַם בָּזֶה יֵשׁ רִיבּוּי הַשְׁפָּעָה, דְּשֹׁרֶשׁ אוֹר פְּנִימִי הוּא מִבְּחִינַת פְּנִימִית וְעַצְמוּת אוֹר אֵין סוֹף, וְלִפְעָמִים מֵאִיר גִּילּוּי אוֹר עֶלְיוֹן יוֹתֵר מִבְּחִינַת עַצְמוּת אוֹר אֵין סוֹף בְּסֵדֶר הִשְׁתַּלְשְׁלוּת, וּכְמוֹ בִּזְמַן הַבַּיִת שֶׁהָיָה מֵאִיר אָז יוֹתֵר מִלְמַעְלָה מֵהִשְׁתַּלְשְׁלוּת בְּסֵדֶר הִשְׁתַּלְשְׁלוּת עַל יְדֵי הָעֲבוֹדָה דְקִיּוּם הַתּוֹרָה וּמִצְוֹת בִּכְלָל וְעַל יְדֵי עֲבוֹדַת הַקָּרְבָּנוֹת בִּפְרָט, וּמִמֵּילָא הָיְתָה הַהַשְׁפָּעָה בְּגַשְׁמִיּוּת גַּם כֵּן בְּרִיבּוּי יוֹתֵר אֲבָל מִבְּחִינַת הַפְּנִימִית דַּוְקָא\nוְשָׁם מַגִּיעַ גַּם כֵּן הַצַּעַר וְיִסּוּרִים שֶׁל יִשְׂרָאֵל, וּכְמוֹ שֶׁכָּתוּב (יְשַׁעְיָה סג. ט) בְּכָל צָרָתָם לוֹ צָר, וְאִיתָא בְּזֹהַר (חֵלֶק א קכ. ב) כְּתִיב לֹא בְּאָלֶף וּקְרִי בְּוָאו בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא עִמְּהוֹן בְּעָקוּ, לֹא בְּאָלֶף אֲתַר עִילָּאָה יַתִּיר (בְּחִינַת עַתִּיק וּכְמוֹ שֶׁכָּתוּב בְּזֹהַר חֵלֶק ג בְּאִדְּרָא זוּטָא רצב סוֹף עַמּוּד ב אֲבָל לְעַתִּיקָא קַדִּישָׁא סְתִימָאָה לֹא נִתְכְּנוּ) אַף עַל גַּב דְּלַאו בְּהַהוּא אֲתַר רוּגְזָא וְעָקוּ לְהָתָם לְעֵילָּא מָטוּ עַקְתָא דְיִשְׂרָאֵל.\n<b>וּבִגְמָרָא</b> (חֲגִיגָה ה. ב) אִיתָא עַל פָּסוּק (יִרְמְיָה יג. יז) בְּמִסְתָּרִים תִּבְכֶּה נַפְשִׁי מִפְּנֵי גֵוָה, מָקוֹם יֵשׁ לוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא וּמִסְתָּרִים שְׁמוֹ, מַאי מִפְּנֵי גֵוָה אָמַר רַבִּי שְׁמוּאֵל בַּר יִצְחָק מִפְּנֵי גַאֲוָתָן שֶׁל יִשְׂרָאֵל שֶׁנִּיטְּלָה מֵהֶן כו' וּמִי אִיכָּא בְּכִיָּה קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא וְהָאָמַר רַב פָּפָּא אֵין עַצְבוּת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כו' לָא קַשְׁיָא הָא בְּבָתֵּי גַוָּאֵי הָא בְּבָתֵּי בְרָאֵי\nוּפֵרֵשׁ רַשִׁ\"י בְּבָתֵּי גַוָּאֵי אִיכָּא דִּכְתִיב בְּמִסְתָּרִים, הֲרֵי דִּבְבָתֵּי גַוָּאֵי דַוְקָא דְּהַיְינוּ בִּבְחִינַת פְּנִימִית וְעַצְמוּת אוֹר אֵין סוֹף שָׁם הַבְּכִיָּה כִּבְיָכוֹל עַל גַּאֲוָתָן שֶׁל יִשְׂרָאֵל שֶׁנִּיטְּלָה כו', וְהַיְינוּ מִפְּנֵי שֶׁנִּשְׁמוֹת יִשְׂרָאֵל יֵשׁ לָהֶן שַׁיָּיכוּת לִבְחִינַת הַפְּנִימִית גַּם בִּבְחִינַת עַצְמוּת אוֹר אֵין סוֹף דִּפְנִימִית חֶפְצוֹ יִתְבָּרֵךְ הוּא בִּמְקַיְּימֵי מִצְוֹת דַּוְקָא,\nוְלָכֵן עַל יְדֵי צְעָקָה דִכְנֶסֶת יִשְׂרָאֵל כְּשֶׁצּוֹעֲקִים בְּעֵת צָרָתָם מְעוֹרְרִים בְּחִינַת רַחֲמִים רַבִּים עֲלֵיהֶם, וּכְמוֹ (שמות ב. כג) וַיֵּאָנְחוּ בְנֵי יִשְׂרָאֵל מִן הָעֲבוֹדָה וַיִּזְעָקוּ שֶׁעַל יְדֵי זֶה הָיְתָה הַתְחָלַת הַגְּאוּלָּה, וּכְתִיב (תְּהִלִּים קז. יט) וַיִּזְעֲקוּ אֶל ה' בַּצַּר לָהֶם וכו' אֶלָּא שֶׁצְּרִיכָה לִהְיוֹת הַצְּעָקָה מֵעוּמְקָא דְלִיבָּא דַוְקָא שֶׁמַּגַּעַת וּמְעוֹרֶרֶת בִּבְחִינַת פְּנִימִיּוּת וְעַצְמוּת אוֹר אֵין סוֹף בָּרוּךְ הוּא.\nקִיצּוּר.\nבִּזְמַן הַבַּיִת שֶׁהָיוּ יִשְׂרָאֵל שְׁלֵמִים בְּקִיּוּם הַתּוֹרָה וּמִצְוֹת הָיוּ יִשְׂרָאֵל מוּשְׁפָּעִים בְּשֶׁפַע רַב בְּגַשְׁמִיּוּת נוֹסָף עַל הָאֱלֹקוּת שֶׁהֵאִיר בְּגִילּוּי, וּבִזְמַן הַגָּלוּת מִפְּנֵי הַחֲטָאִים יִשְׂרָאֵל הֵם בְּשִׁפְלוּת, וּבְכָל צָרָתָם לוֹ צָר שֶׁמַּגִּיעַ בַּפְּנִימִיּוּת, וְעַל יְדֵי תְּשׁוּבָה מֵעוּמְקָא דְלִיבָּא מְעוֹרְרִים אֶת הַפְּנִימִיּוּת."],[4401900059,"<h2>מַאֲמָר יא.</h2>\nוְזֶהוּ שֶׁכָּתוּב (נְחֶמְיָה ט. ד) וַיִּזְעֲקוּ בְּקוֹל גָּדוֹל אֶל ה' אֱלֹקֵיהֶם, דְּלִכְאוֹרָה אֵינוֹ מוּבָן מַהוּ עִנְיַן קוֹל גָּדוֹל וַהֲלֹא אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (בְּרָכוֹת כד. ב) הַמַּשְׁמִיעַ קוֹלוֹ בִּתְפִלָּתוֹ הֲרֵי זֶה מִקְּטַנֵּי אֲמָנָה, הַמַּגְבִּיהַּ קוֹלוֹ בִּתְפִלָּתוֹ הֲרֵי זֶה מִנְּבִיאֵי הַשֶּׁקֶר וּפֵרֵשׁ רַשִׁ\"י דִּכְתִיב (מְלָכִים א יח. כח) וַיִּקְרְאוּ בְּקוֹל גָּדוֹל, וּמִכָּל מָקוֹם בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים נָהֲגוּ לְהַשְׁמִיעַ קוֹלָם וּכְמוֹ שֶׁכָּתַב הַבֵּית-יוֹסֵף בְּאוֹרַח חַיִּים סִימָּן קא. וּבְסֵפֶר מָגֵן דָּוִד לְהָרַדְבַּ\"ז [רַבִּי דָּוִד בֶּן זִמְרָא] זִכְרוֹנוֹ לִבְרָכָה אוֹת ט כָּתַב וְזֶה לְשׁוֹנוֹ וְהִנֵּה אוֹדִיעֲךָ עִנְיָן נִפְלָא מְאֹד הֵבַנְתִּי מִתּוֹךְ דִּבְרֵי רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, כִּי הַדָּבָר הַיּוֹצֵא מִפִּי הָאָדָם הוּא נִרְשָׁם בָּאֲוִיר וּבוֹקֵעַ כַּמָּה אֲוִירִים וּרְקִיעִים וְעוֹלֶה לְמַעְלָה אִם טוֹב וְיָשָׁר הוּא וְיוֹצֵא בִּקְדוּשָּׁה אֲזַי מַקְרִיבִין אוֹתוֹ לִפְנֵי מִי שֶׁאָמַר וְהָיָה הָעוֹלָם כו' וְעַל כֵּן נָהֲגוּ כָּל יִשְׂרָאֵל בְּצַעֲקָתָם עַל הַצָּרָה לִקְרֹא בְּקוֹל גָּדוֹל לַעֲשׂוֹת רוֹשֶׁם גָּדוֹל וְיִבְקְעוּ הָאֲוִירִים עַד כַּאן לְשׁוֹנוֹ,\nהֲרֵי חִילֵּק דְּלִפְעָמִים צְרִיכִים לִקְרֹא בְּקוֹל גָּדוֹל דַּוְקָא וְעַל יְדֵי זֶה עוֹשִׂים רוֹשֶׁם גָּדוֹל.\n<b>וְהָעִנְיָן</b> הוּא דְּהִנֵּה כְּלָלוּת עִנְיַן הָאוֹתִיּוֹת הוּא עִנְיַן הַגִּילּוּי, וּכְמוֹ (יְשַׁעְיָה כא. יב) אָתָא בֹקֶר, דְּקוֹדֶם לָזֶה הָיָה חֹשֶׁךְ וְהֶעְלֵם שֶׁהוּא עִנְיַן הַלַּיְלָה וּכְשֶׁבָּא הָאוֹר שֶׁהוּא בֹקֶר אוֹמֵר אָתָא בֹקֶר שֶׁבָּא הַגִּילּוּי,\nוְלִהְיוֹת שֶׁיֵּשׁ כַּמָּה אוֹפַנֵּי גִילּוּיִם כְּמוֹ גִילּוּי אוֹר הָעוֹנֶג, גִּילּוּי אוֹר הָרָצוֹן, גִּילּוּי אוֹר הַשֵּׂכֶל, גִּילּוּי אוֹר הַמִּדּוֹת שֶׁהֵם גִּילּוּיִם עֲצוּמִים לְפִי עֶרֶךְ מַהוּתָם, וְיֵשׁ גִּילּוּיֵי אוֹרוֹת לְבוּשֵׁי הַנֶּפֶשׁ בְּמַחֲשָׁבָה וְדִבּוּר, דְּכָל הַגִּילּוּיִם הֵם אוֹתִיּוֹת כֹּחוֹת וּלְבוּשֵׁי הַנֶּפֶשׁ,\nוּכְשֵׁם שֶׁבְּאוֹתִיּוֹת הַכְּתָב הֲרֵי בִּכְלָלוּת ג' מִינֵי אוֹתִיּוֹת הֵן גְּדוֹלוֹת בֵּינוֹנִיּוֹת וּקְטַנּוֹת, אֲשֶׁר בִּסְפִירוֹת הָעֶלְיוֹנוֹת הֵן בְּדַרְגּוֹת חֲלוּקוֹת כְּמַאֲמָר אַתְוָון רַבְרְבִין בִּסְפִירַת הַבִּינָה אַתְוָון בֵּינוֹנִין בִּסְפִירַת זָ\"א וְאַתְוָון זְעֵירִין בִּסְפִירַת הַמַּלְכוּת, הֲרֵי מַה שֶּׁהָאוֹת נִכְתֶּבֶת גְּדוֹלָה יוֹתֵר מוֹרֶה שֶׁהוּא בִּבְחִינָה עֶלְיוֹנָה יוֹתֵר אַף שֶׁהַכֹּל תְּמוּנָה אַחַת,\nכְּמוֹ כֵן הוּא בְּקוֹל, דְּקוֹל גָּדוֹל מוֹרֶה עַל הַמַּעֲלָה שֶׁהוּא לְמַעְלָה בְּמַדְרֵיגָה, וְהַיְינוּ דְּהֵן מִלְמַעְלָה לְמַטָּה וּכְמוֹ בְּמַתַּן תּוֹרָה דִּכְתִיב (שְׁמוֹת יט. טז) וְקוֹל שׁוֹפָר חָזָק מְאֹד וּכְתִיב (דְּבָרִים ה. יט) קוֹל גָּדוֹל וְלֹא יָסָף כו' וְהֵן מִלְּמַטָּה לְמַעְלָה וּכְמוֹ (נְחֶמְיָה ט. ד) וַיִּזְעֲקוּ בְּקוֹל גָּדוֹל וּכְתִיב (יוֹנָה ג. ח) וְיִקְרְאוּ אֶל אֱלֹקִים בְּחָזְקָה, דְּקוֹל גָּדוֹל מַגִּיעַ לְמַעְלָה יוֹתֵר, לְפִי שֶׁהוּא מִפְּנִימִיּוּת הַלֵּב, דִּלְפִי שֶׁנּוֹגֵעַ לוֹ הָעִנְיָן בִּפְנִימִיּוּת לְבָבוֹ מִשּׁוּם זֶה הוּא צוֹעֵק בְּקוֹל גָּדוֹל.\n<b>וּמַה</b> שֶּׁבִּתְפִלָּה הַמַּשְׁמִיעַ קוֹלוֹ בִּתְפִלָּתוֹ הֲרֵי זֶה מִקְּטַנֵּי אֲמָנָה, שֶׁהַטַּעַם הוּא כְּפֵרוּשׁ רַשִׁ\"י כְּאִלּוּ אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ תְּפִלַּת לַחַשׁ וּמַגְבִּיהַּ הַרְבֵּה וְגַם שֶׁלֹּא לְבַלְבֵּל לַאֲחֵרִים הַמִּתְפַּלְלִים, כָּל זֶה הוּא בִּסְתָם תְּפִלָּה שֶׁצְּרִיכָה לִהְיוֹת בַּחֲשָׁאי, אֲבָל בְּעֵת צָרָה רַחֲמָנָא לִצְּלָן שֶׁאָז הִנֵּה הַנְּקוּדָּה הַפְּנִימִית, שֶׁהִיא נְקוּדַּת הַהִתְקַשְּׁרוּת בֵּאלֹקוּת הִיא בְּכָל אָדָם בְּהִתְגַּלּוּת בֶּאֱמוּנָה פְשׁוּטָה בַּה' עוֹשֵׂה פֶלֶא, וְהַטַּעַם דְּבִלְבּוּל לַאֲחֵרִים גַּם כֵּן אֵינוֹ שַׁיָּיךְ אָז וְאַדְרַבָּא הַהִתְעוֹרְרוּת מֵעוּמְקָא דְלִיבָּא מְעוֹרֶרֶת גַּם לַאֲחֵרִים לְהִתְעוֹרֵר בְּהִתְעוֹרְרוּת תְּשׁוּבָה, צָרִיךְ לִהְיוֹת צְעָקָה בְּקוֹל גָּדוֹל דַּוְקָא, וְכֵן בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים שֶׁצְּרִיכִים לְעוֹרֵר בִּבְחִינַת פְּנִימִית וְעַצְמוּת כְּמוֹ שֶׁכָּתוּב בְּמָקוֹם אַחֵר, צְרִיכִים לִהְיוֹת בְּהִתְעוֹרְרוּת פְּנִימִית הַלֵּב וּבְקוֹל גָּדוֹל.\nקִיצּוּר.\nאוֹת הוּא גִילּוּי אָתָא בֹקֶר, הַגִּילּוּיִם דְּכֹחוֹת וּלְבוּשֵׁי הַנֶּפֶשׁ הֵם אוֹתִיּוֹת. בְּאוֹתִיּוֹת הַכְּתָב ג' דַּרְגּוֹת גְּדוֹלוֹת בֵּינוֹנִיּוֹת וּקְטַנּוֹת כֵּן הוּא גַם בְּקוֹל, וּתְפִלָּה צְרִיכָה לִהְיוֹת בְּקוֹל גָּדוֹל מֵעוּמְקָא דְלִיבָּא שֶׁאָז הִיא הִתְגַּלּוּת נְקוּדַּת הַהִתְקַשְּׁרוּת וּמְעוֹרֵר גַּם אֲחֵרִים לִתְשׁוּבָה."],[4401900060,"וְהִנֵּה טַעַם וְסִבַּת הַדָּבָר מַה שֶּׁעַל יְדֵי הַצְּעָקָה בְּקוֹל גָּדוֹל מְעוֹרְרִים אֶת בְּחִינַת פְּנִימִית וְעַצְמוּת אוֹר אֵין סוֹף בָּרוּךְ הוּא, דְּלִכְאוֹרָה אֵינוֹ מוּבָן תּוֹכֶן עִנְיָן זֶה, דַּהֲלֹא לְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא הַכֹּל שָׁוִין וְאֵיזֶה הֶבְדֵּל אִם מִתְפַּלֵּל בְּלַחַשׁ אוֹ בְקוֹל וּמַהוּ הַיִּתְרוֹן דְּקוֹל גָּדוֹל הֲלֹא הָעִיקָּר הִיא הַתְּפִלָּה.\n<b>אַךְ</b> הָעִנְיָן הוּא דְּהִיא הַנּוֹתֶנֶת, שֶׁלִּהְיוֹת שֶׁהָעִיקָּר הִיא הַתְּפִלָּה וּתְפִלָּה עִנְיָנָהּ אִיחוּד וְהִתְקַשְּׁרוּת, וְהוּא שֶׁעַל יְדֵי הַתְּפִלָּה הִיא הִתְקַשְּׁרוּת הַנְּשָׁמָה בֵּאלֹקוּת, הִנֵּה מִטַּעַם זֶה עַצְמוֹ צְרִיכָה לִהְיוֹת תְּפִלָּתוֹ בְּקוֹל גָּדוֹל דְּזֶה מוֹרֶה עַל הִתְעוֹרְרוּת לְבָבוֹ בְּהִתְקַשְּׁרוּתוֹ לַה' בֶּאֱמֶת, דֶּאֱמֶת הוּא מַה שֶּׁמִּתְּחִלָּתוֹ וְעַד סוֹפוֹ הוּא בְּקַו אֶחָד יָשָׁר. דְּהִנֵּה כָּל הִתְגַּלּוּת הוּא רַק חֵלֶק יָדוּעַ מִמַּה שֶּׁבִּפְנִימִיּוּתוֹ הַנֶּעֱלָם, וְעִנְיַן הָאֱמֶת הוּא מַה שֶּׁהַפְּנִימִיּוּת הַנֶּעֱלֶמֶת מִתְגַּלָּה בְּכָל מַהוּתוֹ כְּמוֹ שֶׁהוּא בְּמַהוּתוֹ הָעַצְמִי, וְלִהְיוֹת שֶׁהַהִתְגַּלּוּת בָּאָה בְּהִתְרַגְּשׁוּת עוֹמֶק הַלֵּב וּפְנִימִיּוּתוֹ לָכֵן בָּאָה בְּקוֹל גָּדוֹל דַּוְקָא,\nוְאִיתָא בְּזֹהַר דְּרוּחַ אַיְיתִי רוּחַ וְאַמְשִׁיךְ רוּחַ, דְּלִהְיוֹת שֶׁזֶּהוּ כָּל הַפְּנִימִיּוּת שֶׁלּוֹ לָכֵן הִנֵּה הוּא קוֹרֵא וּמַמְשִׁיךְ בְּחִינַת פְּנִימִית וְעַצְמוּת אוֹר אֵין סוֹף בָּרוּךְ הוּא, וְהַיְינוּ דְּלִהְיוֹת דְּנִשְׁמוֹת יִשְׂרָאֵל שָׁרְשָׁם בִּבְחִינַת הַפְּנִימִית דַּוְקָא, הִנֵּה מִצַּד זֶה יֵשׁ בְּכֹחָם לְגַלּוֹת עוֹמֶק פְּנִימִית נְקוּדַּת לְבָבָם שֶׁתִּהְיֶה הַהִתְגַּלּוּת כְּמוֹ שֶׁהִיא בִּפְנִימִית הַנֶּעֱלֶמֶת, וּמִשּׁוּם זֶה יְכוֹלִים לְעוֹרֵר אֶת פְּנִימִית וְעַצְמוּת אוֹר אֵין סוֹף בָּרוּךְ הוּא הַיְינוּ לְקַבֵּל הַהַשְׁפָּעָה מִפְּנִימִית הַמַּקִּיף, אֲבָל מִבְּחִינַת חִיצוֹנִיּוּת הַמַּקִּיף אֵינָם יְכוֹלִים לְקַבֵּל, מִפְּנֵי שֶׁאֵינָם שַׁיָּיכִים לִבְחִינַת חִיצוֹנִית,\nוְדַוְקָא עַכּוּ\"ם יְכוֹלִים לְקַבֵּל מִבְּחִינַת חִיצוֹנִיּוּת הַמַּקִּיף לְפִי שֶׁכָּל עִיקַּר יְנִיקָתָם הוּא מִבְּחִינַת אֲחוֹרַיִים וְחִיצוֹנִיּוּת דַּוְקָא, אֲבָל יִשְׂרָאֵל עִיקָּרָם וְשָׁרְשָׁם מִבְּחִינַת הַפְּנִימִית וּמִשָּׁם הֵם מְקַבְּלִים הַשְׁפָּעָתָם וְאֵינָם מְקַבְּלִים מִבְּחִינַת חִיצוֹנִיּוּת, וְלָכֵן כְּשֶׁחוֹטְאִים מְקַבְּלִים עוֹנְשָׁם בְּגָלוּת וְהֵן נִכְנָעִים כו' עַד שֶׁיָּשׁוּבוּ אֶל ה' וְיִצְעֲקוּ בִּצְעָקָה פְנִימִית מֵעוּמְקָא דְלִיבָּא, אָז מְעוֹרְרִים בְּחִינַת רַחֲמִים רַבִּים מִמְּקוֹר הָרַחֲמִים בְּחִינַת פְּנִימִית הַמַּקִּיף כו',\nוְנִמְצָא מַה שֶּׁיִּתְבָּרֵךְ בִּלְבָבוֹ לֵאמֹר שָׁלוֹם יִהְיֶה לו כִּי בִּשְׁרִירוּת לִבּוֹ יֵלֵךְ, וְהַיְינוּ שֶׁיְּקַבֵּל מֵחִיצוֹנִיּוּת הַמַּקִּיף כְּמוֹ הַקְּלִיפּוֹת וְסִטְרָא אָחֳרָא שֶׁמַּגְבִּיהִים אֶת עַצְמָם לְקַבֵּל מִשָּׁם וּכְמוֹ עַכּוּ\"ם לְמַטָּה, שֶׁנִּמְשָׁךְ רִיבּוּי הַשְׁפָּעָה מִשָּׁם בְּלִי חֶשְׁבּוֹן, כֵּן יְדַמֶּה בְנַפְשׁוֹ לִהְיוֹת כְּמוֹהֶם, הוּא שֶׁקֶר גָּמוּר וְאֵינוֹ אֶלָּא רַק מַה שֶּׁהוּא מַטְעֶה אֶת עַצְמוֹ, עֶר נַארְט זִיךְ אַלֵיין אָפּ ווָאס עֶר רֶעכֶענְט אַז עֶר ווֶעט אוֹיךְ מְקַבֵּל זַיְין דִי הַשְׁפָּעָה פוּן חִיצוֹנִיּוּת הַמַּקִּיף, כִּי לְיִשְׂרָאֵל אִי אֶפְשָׁר לְקַבֵּל הַשְׁפָּעָה מִבְּחִינַת חִיצוֹנִיּוּת הַמַּקִּיף כִּי אִם מִבְּחִינַת הַפְּנִימִית דְּסֵדֶר הִשְׁתַּלְשְׁלוּת (וּבְשָׁרְשׁוֹ מִבְּחִינַת פְּנִימִית הַמַּקִּיף כַּנַ\"ל) וְשָׁם הַהַשְׁפָּעָה הִיא בִּבְחִינַת דִּין וְחֶשְׁבּוֹן, וּמִמֵּילָא בְּהֶכְרַח שֶׁיּוּפְסַק,\nוְכֵן אָנוּ רוֹאִים בְּמוּחָשׁ אֲשֶׁר כַּמָּה רְשָׁעִים שֶׁמַּצְלִיחִים בַּתְּחִלָּה וְאַחַר כַּךְ נִפְסֶקֶת הַצְלָחָתָם וְעָשְׁרָם כִּי הַכֹּל לְפִי הַחֶשְׁבּוֹן, וּמַה שֶּׁמַּצְלִיחִים בַּתְּחִלָּה הוּא לְב' טְעָמִים הָא' שֶׁזֶּהוּ עַל יְדֵי אֵיזֶה עֲשִׂיָּה טוֹבָה מֵאוֹתָם שֶׁאָדָם אוֹכֵל פֵּירוֹתֵיהֶן בָּעוֹלָם הַזֶּה וְהַקֶּרֶן קַיֶּימֶת לָעוֹלָם הַבָּא, וְהַב' דְּהִנֵּה נִתְבָּאֵר לְעֵיל (מַאֲמָר ז פֶּרֶק ד) דְּכָל זְמַן שֶׁלֹּא נֶאֱבַד חֵלֶק הַטּוֹב שֶׁלּוֹ הֲרֵי הַקְּלִיפּוֹת יוֹנְקוֹת עַל יְדֵי תּוֹסֶפֶת חַיּוּת מִן הַקְּדוּשָּׁה וְהוּא נוֹטֵל חֵלֶק בָּרֹאשׁ כַּנַ\"ל וּמִזֶּה נִמְשָׁךְ לוֹ רִיבּוּי הַשְׁפָּעָה בְּגַשְׁמִיּוּת, וְאַחַר כַּךְ נִפְסֶקֶת הַהַשְׁפָּעָה וְנַעֲשֶׂה עָנִי וּבַעַל יִסּוּרִים וּמְרוּחָק מִן הַבְּרִיּוֹת, כִּי רוֹב עֲשִׁירִים הֵם בַּעֲלֵי מִדּוֹת לֹא טוֹבוֹת אוֹ גַם רָעוֹת בְּאַהֲבַת עַצְמוֹ וְגַסּוּת הָרוּחַ, וְכָל זְמַן שֶׁהוּא בְעָשְׁרוֹ הִנֵּה רַבִּים אוֹהֲבֵי עָשִׁיר, וְאַף שֶׁהָרוֹב מֵהֶם יוֹדְעִים כִּי אֶת עָשְׁרָם יְכַבְּדוּ וְלֹא אוֹתָם, אֲבָל עִם זֶה הִנֵּה כָּכָה הֵם מוּטְעִים בְּמַהוּתָם עַד אֲשֶׁר יָעִיזוּ בְּהַוָּותָם, אֲבָל כַּאֲשֶׁר אוֹבְדִים אֶת עָשְׁרָם וְנַעֲשִׂים עֲנִיִּים אָז הֵם מַכִּירִים בְּמַהוּתָם הַמָּלֵא מִמּוּמֵי בְּנֵי אָדָם וְחֶסְרוֹנוֹתֵיהֶם,\nלִהְיוֹת כִּי הַהַשְׁפָּעָה לְיִשְׂרָאֵל הוּא מִבְּחִינַת הַפְּנִימִית שֶׁבָּא בְּדִין וְחֶשְׁבּוֹן, אִם לֹא שֶׁהוּא מֵאֵלֶּה שֶׁנֶּאֱמַר עֲלֵיהֶם (דְּבָרִים ז. י) וּמְשַׁלֵּם לְשֹׂנְאָיו עַל פָּנָיו לְהַאֲבִידוֹ כו', וְהַיְינוּ שֶׁאֵין לוֹ שׁוּם זְכוּת כְּלָל רַחֲמָנָא לִצְּלָן, אֲבָל אִם יֵשׁ לוֹ אֵיזֶה זְכוּת וּבִכְלַל יִשְׂרָאֵל יֵחָשֵׁב אִי אֶפְשָׁר לוֹ שֶׁיְּקַבֵּל הַשְׁפָּעָתוֹ בְּלִי חֶשְׁבּוֹן כִּי אִם הַכֹּל הוּא בְחֶשְׁבּוֹן דַּוְקָא מִצַּד בְּחִינַת הַפְּנִימִית דְּשָׁם הוּא שָׁרְשׁוֹ וּמְקוֹרוֹ.\nקִיצּוּר.\nתְּפִלָּה מְקַשֶּׁרֶת הַנְּשָׁמָה בֵּאלֹקוּת, כְּשֶׁהַהִתְגַּלּוּת הִיא כְּמוֹ הַפְּנִימִית הַנֶּעֱלֶמֶת הוּא אֱמֶת, וּבָאָה בְּצַעֲקַת קוֹל גָּדוֹל וּמְעוֹרֶרֶת אֶת הָעַצְמוּת, יִשְׂרָאֵל מְקַבְּלִים רַק מִן הַפְּנִימִית וְגַם אֵלּוּ שֶׁדַּרְכָם צָלֵחָה שֶׁלֹּא עַל פִּי תוֹרָה וְהַטַּעַם א) שָׂכָר ב) שֶׁפַע הַקְּלִיפּוֹת, הִנֵּה לְבַסּוֹף נִפְסָק."],[4401900061,"וְזֶהוּ דִכְתִיב (יְחֶזְקֵאל כ. לב-לג) וְהָעוֹלָה עַל רוּחֲכֶם (שֶׁעוֹלֶה עַל דַּעְתְּכֶם. רַשִׁ\"י) הָיוֹ לֹא תִהְיֶה, אֲשֶׁר אַתֶּם אוֹמְרִים נִהְיֶה כַגּוֹיִם (נִפְרוֹק עוּלּוֹ מֵעַל צַוָּארֵנוּ מֵאַחַר שֶׁשִּׁלַּח מֵעָלָיו. רַשִׁ\"י) כְּמִשְׁפְּחוֹת הָאֲרָצוֹת לְשָׁרֵת עֵץ וָאָבֶן חַי אָנִי נְאֻם ה' אֱלֹקִים אִם לֹא בְּיָד חֲזָקָה וּבִזְרוֹעַ נְטוּיָה וּבְחֵמָה שְׁפוּכָה (לְכַלּוֹת הַפּוֹשְׁעִים וְהַמּוֹרְדִים. רְדַ\"ק) אֶמְלוֹךְ עֲלֵיכֶם.\n<b>וּבְמִדְרַשׁ</b> תַּנְחוּמָא (נִצָּבִים פֶּרֶק ג) אִיתָא כְּשֶׁבִּקְשׁוּ (יִשְׂרָאֵל) לִפְרוֹק עוֹל שְׁבוּעָתוֹ (שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא) בִּימֵי יְחֶזְקֵאל מַה כְּתִיב שָׁם (יְחֶזְקֵאל כ. א) בָּאוּ אֲנָשִׁים מִזִּקְנֵי יִשְׂרָאֵל לִדְרֹשׁ אֶת ה' אָמְרוּ לוֹ בֶּן כֹּהֵן הַקּוֹנֶה אֶת הָעֶבֶד מַהוּ שֶׁיֹּאכַל בִּתְרוּמָה אָמַר לָהֶם אוֹכֵל, אָמְרוּ לוֹ אִם חָזַר כֹּהֵן וּמְכָרוֹ לְיִשְׂרָאֵל לֹא יָצָא מֵרְשׁוּתוֹ (בִּתְמִיָּה) אָמַר לָהֶם הֵן (שֶׁיּוֹצֵא מֵרְשׁוּת הַכֹּהֵן לִרְשׁוּת יִשְׂרָאֵל) אָמְרוּ לוֹ אַף אָנוּ כְּבָר יָצָאנוּ מֵרְשׁוּתוֹ נִהְיֶה כְּכָל הָאוּמּוֹת, אָמַר לָהֶם יְחֶזְקֵאל לְיִשְׂרָאֵל וְהָעוֹלָה עַל רוּחֲכֶם הָיוֹ לֹא תִהְיֶה וְאוֹמֵר חַי אָנִי נְאוּם ה' אֱלֹקִים אִם לֹא בְּיָד חֲזָקָה וגו' אָמַר לָהֶם כָּל זְמַן שֶׁלֹּא מְכָרוֹ בִּרְשׁוּתוֹ הוּא וְאַתֶּם לֹא נִמְכַּרְתֶּם בְּדָמִים שֶׁנֶּאֱמַר (יְשַׁעְיָה נב. ג) כִּי כֹה אָמַר ה' חִנָּם נִמְכַּרְתֶּם, (דְּבָרִים כט. יב) לְמַעַן הָקִים אוֹתְךָ הַיּוֹם לוֹ לְעָם וְהוּא יִהְיֶה לְּךָ לֵאלֹקִים כַּאֲשֶׁר דִּבֶּר לָךְ וְכַאֲשֶׁר נִשְׁבַּע לַאֲבוֹתֶיךָ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב שֶׁלֹּא אֶחֱזֹר בַּדָּבָר שֶׁנִּשְׁבַּעְתִּי לַאֲבוֹתֵיכֶם.\n<b>וְזֶהוּ</b> וְהָעוֹלָה עַל רוּחֲכֶם שֶׁיִּהְיוּ כְּכָל הַגּוֹיִם וִיקַבְּלוּ הַשְׁפָּעָתָם חַס וְשָׁלוֹם מִסִּטְרָא אָחֳרָא עַל יְדֵי יְנִיקָתָם מֵהַמַּקִּיף עֶלְיוֹן, הִנֵּה הָיוֹ לֹא תִהְיֶה, וְאוֹמֵר חַי אָנִי נְאֻם ה' אֱלֹקִים אִם לֹא בְּיָד חֲזָקָה אֶמְלוֹךְ עֲלֵיכֶם, כִּי הֲלֹא כְּבָר אַתֶּם עִמָּדִי בִּשְׁבוּעָה, שֶׁהֵן חֵלֶק ה' שֶׁבָּחַר בָּהֶם וְהֵם בָּחֲרוּ בוֹ יִתְבָּרֵךְ וַהֲרֵי הֵם שַׁיָּיכִים לִבְחִינַת הַפְּנִימִית דַּוְקָא. וְלָזֹאת אִי אֶפְשָׁר לָהֶם לְקַבֵּל חַיּוּתָם וְהַשְׁפָּעָתָם מִבְּחִינַת חִיצוֹנִיּוּת הַמַּקִּיף כְּכָל הַגּוֹיִם, כִּי אִם מִבְּחִינַת הַפְּנִימִית עַל יְדֵי קִיּוּם הַתּוֹרָה וּמִצְוֹת,\nוּמִצַּד הָאַהֲבָה פְנִימִית דִּבְחִינַת פְּנִימִית וְעַצְמוּת אוֹר אֵין סוֹף (בְּחִינַת פְּנִימִית הַמַּקִּיף כַּנַ\"ל) הוּא מַכְרִיחֵם שֶׁיְּקַבְּלוּ עֲלֵיהֶם עוֹל מַלְכוּתוֹ יִתְבָּרֵךְ דְּזֶהוּ שֶׁכָּתוּב אִם לֹא בְּיָד חֲזָקָה וגו'\nוְכִדְאִיתָא בְּמִדְרָשׁ רַבָּה (בַּמִּדְבָּר פַּרְשָׁה ב פִּיסְקָא טז) אַף עַל פִּי שֶׁאַתֶּם לֹא עַמִּי שֶׁתְּבַקְשׁוּ לְהִפָּרֵשׁ מִמֶּנִּי אֲנִי לֹא אֶהְיֶה לָכֶם אֵין דַּעְתִּי מִשְׁתַּוֵּוית עִמָּכֶם אֶלָּא בְּעַל כָּרְחֲכֶם תִּהְיוּ עַמִּי וְכֵן הוּא אוֹמֵר וְהָעוֹלָה עַל רוּחֲכֶם הָיוֹ לֹא תִהְיֶה כו' אִם לֹא בְּיָד חֲזָקָה כו' אֶמְלוֹךְ עֲלֵיכֶם הָא לָמַדְתָּ חִיבָּתָן שֶׁל יִשְׂרָאֵל לִפְנֵי הַמָּקוֹם,\nשֶׁזֶּה מִצַּד הָאַהֲבָה פְנִימִית דַּוְקָא דִּבְחִינָה זוֹ שַׁיֶּיכֶת לְיִשְׂרָאֵל דַּוְקָא, וּמִשָּׁם נִמְשָׁךְ לְהַכְרִיחָם לְטוֹבָתָם גַּם בְּאוֹפַנִּים קָשִׁים חַס וְשָׁלוֹם, וּכְמוֹ שֶׁאָמְרוּ (סַנְהֶדְרִין קה. א) אָמַר רַב נַחְמָן כָּל כִּי הַאי רִיתְחָא (מִי יִתֵּן וְיָבֹא לָנוּ זֶה הַכַּעַס בְּחֵימָה שְׁפוּכָה אֶמְלוֹךְ עֲלֵיכֶם שֶׁיִּגְאָלֵנוּ בְּעַל כָּרְחֵנוּ וְיִמְלוֹךְ עָלֵינוּ. רַשִׁ\"י) לִירְתַּח רַחֲמָנָא עֲלָן וְלִפְרוֹקִינָן,\nוְעַל יְדֵי צְעָקָה פְנִימִית מְעוֹרְרִים בְּחִינַת פְּנִימִית וְעַצְמוּת אוֹר אֵין סוֹף בָּרוּךְ הוּא דִּלְהָתָם מָטָא עַקְתָא דְיִשְׂרָאֵל כו'.\n<b>הַיּוֹצֵא</b> מִכָּל הַנַ\"ל דְּמַה שֶּׁיִּתְבָּרֵךְ בִּלְבָבוֹ לֵאמֹר שָׁלוֹם יִהְיֶה לִּי גַּם אִם יַעֲשֶׂה מַעֲשֵׂה הַחֵטְא, הוּא רַק מִפִּתּוּיֵי וַהֲסָתַת הַיֵּצֶר, רַק שֶׁמְּכַסֶּה וּמַטֵּהוּ מִדֶּרֶךְ הָאֱמֶת, וּמִי הָאִישׁ הֶחָפֵץ חַיִּים צָרִיךְ לִהְיוֹת לִבּוֹ בִּרְשׁוּתוֹ וְלֹא יִתְפַּתֶּה לְדִבְרֵי הֲבַאי שֶׁל הַיֵּצֶר הָרָע, וְיָבִין הֵיטֵב דַּרְכּוֹ וַאֲשֶׁר נוֹטֵל עָלָיו וְאָז יֵלֵךְ לָבֶטַח דַּרְכּוֹ בְּקִיּוּם הַתּוֹרָה וּמִצְוֹת וְלֹא יָסוּר יָמִין וּשְׂמֹאל עַל יְדֵי פִּתּוּיֵי הַיֵּצֶר וְלֹא יִשְׁמַע אֵלָיו, כִּי כָל דְּבָרָיו בְּשֶׁקֶר יְסוֹדָם וְהַכַּוָּונָה רַק לְנַסּוֹתוֹ, וּלְבָבוֹ יָבִין אֶת הָאֱמֶת וְיֵלֵךְ לָבֶטַח בְּדֶרֶךְ הַתּוֹרָה וּמִצְוֹת וְעַל יְדֵי זֶה יִחְיֶה בְּחַיִּים רוּחָנִים וְחַיִּים גַּשְׁמִים.\nקִיצּוּר.\nהָאוֹמְרִים נִהְיֶה כְּכָל הַגּוֹיִם לְקַבֵּל מֵחִיצוֹנִיּוּת הַמַּקִּיף נֶעֱנָשִׁים בְּיָד חֲזָקָה בִּכְדֵי שֶׁיַּחְזְרוּ בִּתְשׁוּבָה, וּמִצַּד הָאַהֲבָה פְנִימִית מַכְרִיחִים אוֹתָם עַל זֶה גַּם בְּאוֹפַנִּים קָשִׁים, לִירְתַּח רַחֲמָנָא עֲלָן וְלִפְרְקִינָן, יָבִין הֲסָתַת הַיֵּצֶר וְיִזָּהֵר בְּקִיּוּם הַתּוֹרָה וּמִצְוֹת וְיִחְיֶה בְּחַיִּים רוּחָנִים וְגַשְׁמִים."],[4401900062,"<h2>מַאֲמָר יב.</h2>\nעוֹד זֹאת הוּא מִפִּתּוּיֵי הַיֵּצֶר הָרָע שֶׁמְּפַתֵּהוּ שֶׁלֹּא יִרְאֶנּוּ אָדָם, כִּי הַבַּעַל עֲבֵירָה רַחֲמָנָא לִצְּלָן אֵינוֹ רוֹצֶה שֶׁיֵּדְעוּ בְּנֵי אָדָם רָעָתוֹ, וּכְמוֹ שֶׁאָמַר רַבָּן יוֹחָנָן בֶּן זַכַּאי לְתַלְמִידָיו (בְּרָכוֹת כח. ב) יְהִי רָצוֹן שֶׁתְּהֵא מוֹרָא שָׁמַיִם עֲלֵיכֶם כְּמוֹרָא בָּשָׂר וָדָם אָמְרוּ לוֹ תַּלְמִידָיו עַד כַּאן (בִּתְמִיָּה כְּלוֹמַר וְלֹא יוֹתֵר מִמּוֹרָא בָּשָׂר וָדָם, רַשִׁ\"י) אָמַר וּלְוַאי (שֶׁיְּהֵא כְּמוֹרָא בָּשָׂר וָדָם שֶׁאִם כֵּן תֶּחְדְּלוּ מֵעֲבֵירוֹת הַרְבֵּה. רַשִׁ\"י) תֵּדְעוּ כְּשֶׁאָדָם עוֹבֵר עֲבֵירָה (בְּסֵתֶר מִמּוֹרָא הַבְּרִיּוֹת וְיוֹדֵעַ שֶׁהַכֹּל הוּא גָלוּי לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְאֵינוֹ מַנִּיחַ בְּכַךְ. רַשִׁ\"י) אוֹמֵר שֶׁלֹּא יִרְאַנִי אָדָם,\nוּבָזֶה מְפַתֵּהוּ יִצְרוֹ שֶׁלֹּא יִרְאֶנּוּ אָדָם וְלֹא יֵדְעוּ עִנְיָנָיו הָרָעִים וּבֶאֱמֶת אֵינוֹ כֵן שֶׁהַכֹּל רוֹאִים וְיוֹדְעִים וּמַכִּירִים, כִּי לֹא יִמָּלֵט שֶׁיַּעֲשֶׂה אֵיזֶה דְבָרִים שֶׁיִּהְיוּ חֲשׁוּדִים בְּעֵינֵי הַבְּרִיּוֹת, כִּי בֶּאֱמֶת מֵרוֹב הַתַּאֲווֹת שֶׁמִּצַּד הֲסָתַת הַיֵּצֶר עוֹשֶׂה כַּמָּה שְׁטוּתִים אֲשֶׁר הַשֵּׂכֶל הַבָּרִיא לֹא יַסְכִּים עַל זֶה כְּלָל, רַק שֶׁהַיֵּצֶר הָרָע מַעֲבִירוֹ עַל דַּעְתּוֹ וְעַל דַּעַת קוֹנוֹ וְעוֹשֶׂה כַּמָּה עִנְיְנֵי שְׁטוּתים, שֶׁבָּזֶה נַעֲשֶׂה חָשׁוּד בְּעֵינֵי בְּנֵי אָדָם וְנוֹתְנִים דַּעְתָּם עָלָיו לֵידַע עִנְיָנָיו, וּכְמוֹ שֶׁאָנוּ רוֹאִים בְּמוּחָשׁ בְּכַמָּה עִנְיָנִים שׁוֹנִים בְּדִבּוּר וּבִתְנוּעוֹת שׁוֹנוֹת שֶׁהָאָדָם בְּעַצְמוֹ מְגַלֶּה עִנְיָנָיו הַפְּנִימִיִּים כִּי בְרָע הוּא, וְאֵין הַכַּוָּונָה עַל עִנְיְנֵי אִיסּוּר בְּדִבּוּר כְּמוֹ שֶׁקֶר רְכִילוּת וְלָשׁוֹן הָרָע וְדִבְרֵי נִיבּוּל בִּלְבָד, אֶלָּא הַכַּוָּונָה דְּגַם כְּשֶׁמְּסַפֵּר אֵיזֶה סִפּוּר דְּלִכְאוֹרָה אֵינוֹ אֶלָּא כְּמוֹ שְׂפַת יֶתֶר וְדִבּוּר שֶׁל בַּטָּלָה, אֲבָל בֶּאֱמֶת הִנֵּה בְּדִבּוּר זֶה יֵשׁ בּוֹ גִּילּוּי פְּנִימִית הָרָע,\nוְכֵן הוּא בְּעִנְיַן הָרְאִיָּה דְּלִפְעָמִים הִנֵּה בְּהַבָּטָה שֶׁל הִסְתַּכְּלוּת שֶׁמַּבִּיט בְּמָקוֹם שֶׁאֵין צְרִיכִים לְהַבִּיט הִנֵּה בָּזֶה הָאָדָם מְגַלֶּה אֶת כָּל עוֹמֶק הָרָע שֶׁבּוֹ,\nוְגַם אִם מִבְּנֵי אָדָם מוּסְתָּר וְנֶעְלָם מַעֲשָׂיו הָרָעִים, הֲלֹא לְפָנָיו יִתְבָּרֵךְ גָּלוּי וְיָדוּעַ הַכֹּל, וּכְמוֹ שֶׁכָּתוּב (יִרְמְיָה כג. כד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ וּכְמַאֲמָר הַכֹּל גָּלוּי וְיָדוּעַ לְפָנֶיךָ, אֵין דָּבָר נֶעְלָם מִמֶּךָּ וְאֵין נִסְתָּר מִנֶּגֶד עֵינֶיךָ כו' וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹדִיעַ וּמְגַלֶּה עִנְיָנָיו לַכֹּל, וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בְּמִשְׁנָה (אָבוֹת פֶּרֶק ד) כָּל הַמְחַלֵּל שֵׁם שָׁמַיִם בְּסֵתֶר נִפְרָעִין מִמֶּנּוּ בְּגָלוּי, וּפֵרֵשׁ רַשִׁ\"י הַמְחַלֵּל שֵׁם שָׁמַיִם בְּסֵתֶר שֶׁעוֹבֵר עֲבֵירָה בְּסֵתֶר (כִּי אִי אֶפְשָׁר לוֹמַר שֶׁהַכַּוָּונָה עַל חִילּוּל הַשֵּׁם מַמָּשׁ, דְּחִלּוּל הַשֵּׁם הוּא בְּפַרְהֶסְיָא דַוְקָא וְאֵיךְ שַׁיָּיךְ שֶׁמְּחַלֵּל שֵׁם שָׁמַיִם בְּסֵתֶר, אֶלָּא הַכַּוָּונָה שֶׁעוֹבֵר עֲבֵירָה בְּסֵתֶר) נִפְרָעִין מִמֶּנּוּ בְּגָלוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה לַכֹּל חֶרְפָּתוֹ שֶׁנֶּאֱמַר (מִשְׁלֵי כו. כו) תִּכַּסֶּה שִׂנְאָה בְּמַשָּׁאוֹן תִּגָּלֶה רָעָתוֹ בְקָהָל (הָעוֹשֶׂה מַעֲשָׂיו בְּמַחְשָׁךְ וּמְכַסֶּה בְּמַשָּׁאוֹן שֶׁהוּא שׁוֹאַת חֹשֶׁךְ אֶת הַדָּבָר הַשָּׂנאוּי לְהַקָּדוֹשׁ בָּרוּךְ הוּא סוֹף שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה רָעָתוֹ בְּקָהָל שֶׁיַּכִּירוּ בוֹ שֶׁהוּא רָשָׁע, פֵּרוּשׁ רַשִׁ\"י) וְכָל כַּךְ לָמָּה שֶׁלֹּא יִתְחַלֵּל שֵׁם שָׁמַיִם עַל יָדוֹ, שֶׁלֹּא יֹאמְרוּ רָאִיתָ פְלוֹנִי שֶׁהוּא חָכָם וְעוֹשֶׂה מַעֲשִׂים טוֹבִים וּפָגְעוּ בוֹ צָרוֹת כָּל כַּךְ, עַד כַּאן לְשׁוֹנוֹ,\nוּמַה שֶּׁמְּפַתֵּהוּ שֶׁלֹּא יִרְאֶנּוּ אָדָם הוּא רַק מִשְּׁטוּתֵי הַיֵּצֶר הָרָע, ה' יִשְׁמְרֵנוּ מֵהֶם, שֶׁאָנוּ רוֹאִים בְּמוּחָשׁ בְּטִבְעֵי בְּנֵי אָדָם דְּאֵלּוּ שֶׁהֵם בַּעֲלֵי מֶזֶג דַּק, אֵיידֶעלֶע מֶענְשֶׁען, וּבַעֲלֵי שֵׂכֶל אֵינָם עֲלוּלִים כָּל כַּךְ לְקַבֵּל עִנְיְנֵי שְׁטוּת כְּמוֹ בַּעֲלֵי מֶזֶג גַּס, גְרָאבֶּע מֶענְשֶׁען, וּבַעֲלֵי מִדּוֹת, שֶׁהֵם הַבַּעֲלֵי מִדּוֹת הִנֵּה בְּהִתְרַגְּשׁוּתָם וְגוֹדֶל הִתְפַּעֲלוּתָם עֲלוּלִים לְקַבֵּל עִנְיְנֵי הַשְּׁטוּת וְהַהַטְעָיָה שֶׁמַּטְעִים אֶת עַצְמָם, זֵיי נַארֶען זִיךְ אַלֵיין, וְהַיֵּצֶר הָרָע לִהְיוֹתוֹ בַּהֲמִי וּבַעַל מִדּוֹת הִנֵּה מְפַתֶּה אֶת הָאָדָם בְּכַמָּה עִנְיָנִים, וְרַחֲמָנָא לִצְּלָן הַמִּתְנַהֵג עַל פִּי הוֹרָאַת הַיֵּצֶר הָרָע מְקַבֵּל שְׁטוּתו וַהֲסָתַת הַיֵּצֶר הָרָע וְנִדְמֶה לוֹ שֶׁאֵין אִישׁ יוֹדֵעַ עִנְיָנָיו הַלֹּא טוֹבִים.\nקִיצּוּר.\nהָאָדָם בְּטִבְעוֹ יֵשׁ לוֹ מוֹרָא שֶׁהַזּוּלַת לֹא יֵדַע עִנְיָנָיו וּמַה גַּם עִנְיָנָיו הָרָעִים, מוֹרָא שָׁמַיִם כְּמוֹרָא בָּשָׂר וָדָם, הָאָדָם בְּדִבּוּרוֹ וּבִתְנוּעוֹתָיו מְגַלֶּה עוֹמֶק הָרָע שֶׁבּוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה חֶרְפָּתוֹ בָּרַבִּים, הַיֵּצֶר הָרָע בְּפַחֲזוּתוֹ מְקַבֵּל שְׁטוּתִים וּמְפַתֶּה אֶת הָאָדָם."],[4401900063,"<h2>מַאֲמָר יג.</h2>\nעוֹד זֹאת הִיא רָעָה חוֹלָה, מַה שֶּׁהָאָדָם מַצְדִּיק אֶת עַצְמוֹ עַל מַעֲשֵׂה הַחֵטְא שֶׁעָשָׂה, כִּי הִנֵּה הָאָדָם בְּטִבְעוֹ הִנֵּה כָּל דָּבָר, טוֹב אוֹ רָע, בֵּין עִנְיָן שֶׁל דֵּיעוֹת וּבֵין עִנְיָן שֶׁל מִדּוֹת וְהַנְהָגָה, בֵּין שֶׁיִּהְיֶה בְּדָבָר שֶׁבֵּין אָדָם לַמָּקוֹם וּבֵין שֶׁיִּהְיֶה בֵּין אָדָם לַחֲבֵרוֹ אוֹ בֵּין אָדָם לְעַצְמוֹ, אִם הַדָּבָר הוּא טוֹב הִנֵּה הוּא תּוֹלֶה וּמְיַיחֲסוֹ לְעַצְמוֹ וְאִם הַדָּבָר הוּא רַע הִנֵּה הוּא תּוֹלֶה וּמְיַיחֲסוֹ לְזוּלָתוֹ, וְטַעַם הַדָּבָר הוּא מִפְּנֵי אַהֲבַת עַצְמוֹ, דְּלִהְיוֹת הָאָדָם בְּטִבְעוֹ אוֹהֵב אֶת עַצְמוֹ הִנֵּה אַהֲבָתוֹ זֹאת לֹא זוֹ בִּלְבָד שֶׁמְּכַסָּה עַל פִּשְׁעֵי עַצְמוֹ שֶׁאֵינוֹ מַרְגִּישׁ כְּלָל אֲשֶׁר הוּא בְעַצְמוֹ הָאָשֵׁם בָּזֶה, אֶלָּא עוֹד זֹאת שֶׁהוּא מַצְדִּיק אֶת עַצְמוֹ,\nוְהִנֵּה אַף כִּי אֱמֶת הַדָּבָר אֲשֶׁר הַרְבֵּה יַלְדוּת עוֹשָׂה וְהַרְבֵּה חֲבֵרִים רָעִים עוֹשִׂים וּבִפְרָט שְׁנֵיהֶם יַחְדָּו, אֲבָל בֶּאֱמֶת הוּא בְעַצְמוֹ אָשֵׁם בְּזֶה שֶׁבָּחַר לוֹ חֲבֵרִים רָעִים וּסְבִיבָה רָעָה, וְעַל כָּל פָּנִים אֵינוֹ צָרִיךְ לְהַאֲשִׁים רַק אֶת זוּלָתוֹ וּבִפְרָט לְהַצְדִּיק אֶת עַצְמוֹ, וְאֵין זֶה אֶלָּא מִפְּנֵי טֶבַע הָאָדָם בְּאַהֲבַת עַצְמוֹ גּוֹרֵם לוֹ חִסָּרוֹן זֶה,\nדְּבִפְרָט זֶה נִכְשָׁלִים לִפְעָמִים גַּם בַּעֲלֵי תְשׁוּבָה, הֲגַם שֶׁהֵם בַּחֲרָטָה גְמוּרָה עַל עֲשִׂיַּית הַדָּבָר הַלֹּא טוֹב שֶׁעָשָׂה אוֹ שֶׁדִּיבֵּר אוֹ מַחְשְׁבוֹתָיו וְהִרְהוּרָיו הָרָעִים וּמִתְחָרֵט עֲלֵיהֶם בַּחֲרָטָה גְמוּרָה וּבוֹכֶה בְּמַר נַפְשׁוֹ, וְעִם כָּל זֶה עוֹלֶה בְדַעְתּוֹ לְהַצְדִּיק אֶת עַצְמוֹ עַל עֲשִׂיַּית הַדָּבָר הַזֶּה וּמוֹצֵא כַּמָּה סִבּוֹת בַּמֶּה לִתְלוֹת, לִפְעָמִים הוּא תוֹלֶה שֶׁכָּל זֶה בָּא לוֹ לְסִבַּת תִּגְבּוֹרֶת הַחוֹם הַטִּבְעִי, דְּלִהְיוֹתוֹ מְרוּתָּח בְּטִבְעוֹ לָכֵן בְּהִתְגַּבְּרוּת חוֹם הַטִּבְעִי יֵחַם לְבָבוֹ וְאֵינוֹ יָכוֹל לַעֲצוֹר בַּעֲדוֹ מִן הַכַּעַס וְהַדִּבּוּר אוֹ מַחֲשָׁבָה בְּדִבּוּרִים וְהִרְהוּרִים אֲסוּרִים וְכֵן בְּמַעֲשֶׂה בְּפוֹעַל, דַּהֲגַם שֶׁיּוֹדֵעַ כִּי אָסוּר הוּא, מְאַבֵּד אֶת נַפְשׁוֹ וְעַל הָרוֹב גַּם מַחֲלִישׁ גּוּפוֹ אֲבָל מִפְּנֵי גּוֹדֶל הַגְבָּרַת חוֹם הַטִּבְעִי אֵינוֹ יָכוֹל לַעֲמוֹד עַל עַצְמוֹ, וְלִפְעָמִים הִנֵּה הוּא תוֹלֶה כָּל עִנְיַן הָרָע שֶׁלּוֹ בְּזוּלָתוֹ כִּי פְּלוֹנִי הֱסִיתוֹ וְהִטָּהוּ מִדֶּרֶךְ הַטּוֹב וְהַיָּשָׁר וּבְעַצְמוֹ לֹא הָיָה עוֹשֶׂה כֵּן,\nדְּבֶאֱמֶת הִנֵּה כָּל עִיקַּר הִתְנַצְּלוּתוֹ אֵינוֹ אֶלָּא הַטָעָה שֶׁמַּטְעֶה עַצְמוֹ מִפְּנֵי אַהֲבָתוֹ לְעַצְמוֹ, וְרַק זוֹ הִיא הַסִּבָּה מַה שֶּׁמַּצְדִּיק עַצְמוֹ, דְּהִנֵּה הַטַּעֲנָה דְּהַגְבָּרַת חוֹם הַטִּבְעִי אֵינָהּ טַעֲנָה בֶּאֱמֶת, שֶׁהֲרֵי הַחוֹם הַטִּבְעִי הוּא מֵהַנֶּפֶשׁ הַטִּבְעִית הַבַּהֲמִית וְעַל זֶה נִיתְּנָה לוֹ הַנֶּפֶשׁ הָאֱלֹקִית שֶׁיִּתְגַּבֵּר עַל הַנֶּפֶשׁ הַטִּבְעִית, וְזֶה תַּכְלִית בְּרִיאָתוֹ בָּעוֹלָם לְהַגְבִּיר הַכֹּחוֹת דְּנֶפֶשׁ הָאֱלֹקִית וּלְהַכְנִיעַ הַכֹּחוֹת דְּנֶפֶשׁ הַטִּבְעִית, וְלוּלֵא הָעֲבוֹדָה הַזֹּאת בְּהַכְנָעַת הַנֶּפֶשׁ הַטִּבְעִית לֹא הָיָה נִבְרָא כְּלָל, דַּהֲרֵי יֵשׁ מַלְאָכִים שֶׁעוֹבְדִים אֶת ה' בְּאַהֲבָה וְיִרְאָה, וְעוֹמְדִים בְּבִיטּוּל תָּמִיד, וּבִשְׁבִיל מָה נִבְרָא הָאָדָם, אֶלָּא שֶׁהַמַּלְאָכִים אֵין בָּהֶם יֵצֶר הָרָע וְאֵין חִידּוּשׁ בַּעֲבוֹדָתָם, וּבִשְׁבִיל זֶה נִבְרָא הָאָדָם שֶׁיֵּשׁ בּוֹ יֵצֶר הָרָע וְיֵצֶר טוֹב שֶׁיַּגְבִּיר אֶת הַיֵּצֶר טוֹב עַל הַיֵּצֶר הָרָע וּבָזֶה הוּא גוֹרֵם תַּעֲנוּג לְמַעְלָה מִצַּד הַחִידּוּשׁ בַּעֲבוֹדָתוֹ כְּמוֹ שֶׁכָּתוּב בְּמָקוֹם אַחֵר, וְאִם הַנֶּפֶשׁ הַטִּבְעִית שֶׁלּוֹ שֶׁהוּא חוּמְרִי יוֹתֵר וְהַחוֹם הַטִּבְעִי הוּא בְּהִתְגַּבְּרוּת יְתֵרָה, בְּוַדַּאי גַּם בְּהַנֶּפֶשׁ הָאֱלֹקִית שֶׁלּוֹ יֵשׁ כֹּחוֹת חֲזָקִים יוֹתֵר, וְיֵשׁ בְּכֹחוֹ לְהִתְגַּבֵּר עַל הַחוֹם הַטִּבְעִי שֶׁלּוֹ, כִּי אֵין נוֹתְנִים לְאָדָם יוֹתֵר מֵעֶרֶךְ כֹּחוֹתָיו וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (כְּתוּבּוֹת סז. א) לְפוּם גַּמְלָא שִׁיחֲנָא, וּמֵאַחַר שֶׁנִּיתַּן לוֹ חוֹם טִבְעִי חָזָק מִסְתָּמָא נִיתְּנוּ לוֹ כֹּחוֹת רוּחָנִים גַּם כֵּן חֲזָקִים שֶׁיּוּכַל לְהִתְגַּבֵּר עַל הַחוֹם הַטִּבְעִי שֶׁלּוֹ.\nקִיצּוּר.\nטֶבַע הָאָדָם לִתְלוֹת סִבַּת רָעָתוֹ וְחֶסְרוֹנוֹתָיו בְּזוּלָתוֹ וְסִבַּת טוֹבוֹתָיו וּמַעֲלוֹתָיו בְּעַצְמוֹ, אַהֲבַת עַצְמוֹ סִבַּת הַטָּעוּת וּמְקוֹר הַמּוּמִין, הַהִצְטַדְּקוּת בְּסִבַּת הַגְבָּרַת חוֹם הַטִּבְעֵי שֶׁקֶר, מַעֲלַת הָאָדָם עַל הַמַּלְאָכִים."],[4401900064,"וּבֵיאוּר הָעִנְיָן הוּא דְּהִנֵּה בֶּאֱמֶת אֵינוֹ מוּבָן כְּלָלוּת הָעִנְיָן מַה שֶּׁיֵּשׁ בְּכֹחַ הַנֶּפֶשׁ הָאֱלֹקִית לְהִתְגַּבֵּר עַל הַנֶּפֶשׁ הַבַּהֲמִית,\nדְּהִנֵּה כְּתִיב (מִשְׁלֵי יח. יז) צַדִּיק הָרִאשׁוֹן בְּרִיבוֹ וּפֵירֵשׁ בִּמְצוּדַת דָּוִד כִּי יוּכַל לְהַטְעִים דְּבָרָיו וּלְהַכְנִיסָם בַּלֵּב הוֹאִיל וְלֹא אָמַר מִי בְּחִילּוּף, דְּכַאֲשֶׁר שְׁנַיִם הַחֲלוּקִים בְּטַעֲנוֹתֵיהֶם בָּאִים כְּאֶחָד הִנֵּה טַעֲנָתוֹ שֶׁל כָּל אֶחָד נֶחֱלֶשֶׁת מִטַּעֲנַת זוּלָתוֹ, אֲבָל כַּאֲשֶׁר הוּא רִאשׁוֹן יָכוֹל הוּא לְהַטְעִים דְּבָרָיו לְהַכְנִיסָם בְּלֵב הַשּׁוֹמֵעַ שֶׁאֵין מִי שֶׁיְּנַגֵּד לוֹ וְגַם יַחֲלִישׁ טַעֲנָתוֹ,\nוְכֵן הוּא בְּנֶפֶשׁ הָאֱלֹקִית וְנֶפֶשׁ הַבַּהֲמִית שֶׁהֵם מְנַגְּדִים בְּעִנְיְנֵיהֶם, וְהַנֶּפֶשׁ הַבַּהֲמִית הִיא בְהָאָדָם מִתְּחִלַּת בְּרִיאָתוֹ וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (סַנְהֶדְרִין צא. ב) מֵאֵימָתַי יֵצֶר הָרָע שׁוֹלֵט בָּאָדָם כו' מִשַּׁעַת יְצִיאָה, וּבְמִדְרָשׁ רַבָּה (נֹחַ פַּרְשָׁה ל\"ד. יב) דָּרַשׁ מִנְּעוּרָיו מִשָּׁעָה שֶׁנִּנְעָר לָצֵאת מִמְּעֵי אִמּוֹ. וְהַנֶּפֶשׁ הָאֱלֹקִית נִכְנָס בּוֹ כְּשֶׁהוּא בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד, שֶׁאָז נַעֲשֶׂה מְחוּיָּיב בְּמִצְוֹת. וְכִדְאִיתָא בְּמִדְרָשׁ רַבָּה (קֹהֶלֶת) עַל פָּסוּק (קֹהֶלֶת ד. יג) טוֹב יֶלֶד מִסְכֵּן וְחָכָם מִמֶּלֶךְ זָקֵן וּכְסִיל, טוֹב יֶלֶד מִסְכֵּן וְחָכָם זֶה יֵצֶר טוֹב, וְלָמָּה נִקְרָא שְׁמוֹ יֶלֶד כִּי אֵין מִזְדַּוֵּוג לְאָדָם אֶלָּא מִבֶּן י\"ג שָׁנָה וּלְמַעְלָה כו' מִמֶּלֶךְ זָקֵן וּכְסִיל זֶה יֵצֶר הָרָע כו' וְלָמָּה קוֹרֵא אוֹתוֹ זָקֵן שֶׁהוּא מִזְדַּוֵּוג לוֹ מִיַּלְדוּתוֹ וְעַד זִקְנָתוֹ, וְכֵן הוּא בְּזֹהַר וַיֵּשֶׁב (קעט. א),\nוַהֲגַם דְּבִגְמָרָא וּבְמִדְרָשׁ (פַּרְשַׁת נֹחַ הַנַ\"ל) אִיתָא נְשָׁמָה מֵאֵימָתַי נִיתְּנָה בְּאָדָם כו' מִשַּׁעַת פְּקִידָה (וְעַיֵּן שָׁם בְּמַתְּנוֹת כְּהֻנָּה) זֶהוּ רַק שֶׁנִּיתְּנָה בּוֹ אֲבָל אֵינָהּ פּוֹעֶלֶת עַד הֱיוֹתוֹ בֶּן י\"ג שָׁנָה, אִם כֵּן הֲרֵי הַנֶּפֶשׁ הַבַּהֲמִית אַקְדְּמֵיהּ טַעֲנָתֵיהּ.\n<b>וְכֵן</b> מִצַּד הַגּוּף הַגַּשְׁמִי, הֲרֵי כָּל עִנְיְנֵי הַתַּאֲוָה בַּאֲכִילָה וּשְׁתִיָּה וּשְׁאָר הַתַּעֲנוּגִים קְרוֹבִים לְהַיֶּלֶד יוֹתֵר וּמִתְרַגֵּל בָּהֶם וְהָרְגִילוּת מִשְׁתָּרֶשֶׁת בּוֹ בִּמְאוֹד, וּבִפְרָט בִּהְיוֹתוֹ בִּסְבִיבָה לֹא טוֹבָה הַנִּמְשָׁכִים אַחֲרֵי הַגַּשְׁמִיּוּת וְהַחוּמְרִיּוּת, הִנֵּה כָּל הָעִנְיָנִים הַלֹּא טוֹבִים אוֹ הָרָעִים שֶׁהִתְרַגֵּל בָּהֶם נִטְבָּעִים בּוֹ, כְּמַאֲמָר הֶרְגֵּל נַעֲשֶׂה טֶבַע אוֹ טֶבַע שֵׁנִי, שֶׁקָּשֶׁה בִּמְאֹד לְהִפָּטֵר מֵהֶם,\nוְהַנֶּפֶשׁ הָאֱלֹקִית עֲדַיִין טֶרֶם הִתְאַחֲזָה בּוֹ בְּהִתְיַישְּׁבוּת, אִם כֵּן הֲרֵי הַנֶּפֶשׁ הַבַּהֲמִית הוּא חָזָק הַרְבֵּה יוֹתֵר מֵהַנֶּפֶשׁ הָאֱלֹקִית, דְּלָכֵן הִנֵּה הַנֶּפֶשׁ הַבַּהֲמִית נִקְרָא מֶלֶךְ זָקֵן, דִּלְבַד זֹאת דְּהִקְדִּים טַעֲנָתֵיהּ וּמוֹשֵׁל בְּכָל עִנְיְנֵי הַגּוּף, הִנֵּה הוּא זָקֵן וְרָגִיל אֵיךְ לְפַתּוֹת בְּנֵי אָדָם וְלַהֲסִיתָם לִהְיוֹת נִמְשָׁכִים אַחֲרֵי הַגַּשְׁמִיּוּת וְהַחוּמְרִיּוּת, וְהַנֶּפֶשׁ הָאֱלֹקִית הִנֵּה לְבַד זֹאת שֶׁהִיא יֶלֶד לְפִי עֶרֶךְ קְדִימָתוֹ שֶׁל הַנֶּפֶשׁ הַבַּהֲמִית, הִנֵּה עוֹד זֹאת הוּא מִסְכֵּן בְּעֵינֵי בְּנֵי אָדָם, שֶׁהֲרֵי כָּל עִנְיָנוֹ הוּא עִנְיַן הָרוּחָנִיּוּת וְהָאָדָם שֶׁנִּמְשָׁךְ אַחֲרֵי הַגַּשְׁמִיּוּת וְהוּרְגַּל בְּעִנְיְנֵי עוֹלָם הַחוּמְרִיּוּת נִרְאֶה לוֹ כָּל עִנְיָן רוּחָנִי לְמִסְכֵּנוּת, כִּי הָעִיקָּר אֶצְלוֹ הֵם עִנְיָנִים הַגַּשְׁמִים וְזֶה הוּא הָעֲשִׁירוּת וְהַחֲשִׁיבוּת שֶׁלּוֹ, אִם כֵּן הֲרֵי הַנֶּפֶשׁ הַבַּהֲמִית הוּא חָזָק יוֹתֵר מֵהַנֶּפֶשׁ הָאֱלֹקִית וְאִם כֵּן נִפְלָא הַדָּבָר בִּמְאֹד אֵיךְ יֵשׁ כֹּחַ בְּנֶפֶשׁ הָאֱלֹקִית לְהִתְגַּבֵּר עַל הַנֶּפֶשׁ הַבַּהֲמִית,\nוּכְמוֹ כֵן מִצַּד שָׁרְשָׁן, הֲרֵי יָדוּעַ דְּשֹׁרֶשׁ הַנֶּפֶשׁ הַבַּהֲמִית הוּא מֵעוֹלָם הַתֹּהוּ וְשֹׁרֶשׁ הַנֶּפֶשׁ הָאֱלֹקִית מֵעוֹלָם הַתִּקּוּן וְתֹהוּ קָדַם אֶל הַתִּקּוּן, וּכְמוֹ שֶׁכָּתוּב (בְּרֵאשִׁית לו. לא) וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל, וְהֵן ז' מַלְכִין קַדְמָאִין דְּתֹהוּ דְּקָדְמוּ אֶל הַתִּקּוּן, וּמִכָּל זֶה לִכְאוֹרָה אֵינוֹ מוּבָן אֵיךְ יֵשׁ כֹּחַ בְּנֶפֶשׁ הָאֱלֹקִית לְהִתְגַּבֵּר עָלָיו. אַךְ הָעִנְיָן הוּא דְּהִנֵּה בֶּאֱמֶת הַנֶּפֶשׁ הָאֱלֹקִית בְּשָׁרְשׁוֹ קָדוּם אֶל הַנֶּפֶשׁ הַבַּהֲמִית. דְּהִנֵּה כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר י פֶּרֶק ב) דְּסֵדֶר הִשְׁתַּלְשְׁלוּת שָׁרְשׁוֹ בִּלְמַעְלָה מִסֵּדֶר הִשְׁתַּלְשְׁלוּת בִּבְחִינַת פְּנִימִית הַמַּקִּיף דַּוְקָא, כְּמוֹ כֵן הוּא בִּבְחִינַת הַתֹּהוּ וְתִקּוּן, דְּתִקּוּן שָׁרְשׁוֹ בְּעַצְמוּת אוֹר אֵין סוֹף לְמַעְלָה מִשֹּׁרֶשׁ הַתֹּהוּ, וְזֶהוּ מַה שֶּׁבֶּאֱמֶת הָיָה יַעֲקֹב הַבְּכוֹר, וְכַיָּדוּעַ דְּיַעֲקֹב וְעֵשָׂו הֵן תֹּהוּ וְתִקּוּן וְעֵשָׂו נוֹלַד קוֹדֶם שֶׁזֶּהוּ כְּמוֹ שֶׁעוֹלָם הַתֹּהוּ קָדַם לָבֹא לְעוֹלָם הַתִּקּוּן. אַךְ זֶהוּ בִּבְחִינַת לֵידָה וְהִתְגַּלּוּת לְבָד, אֲבָל בֶּאֱמֶת הָיָה יַעֲקֹב הַבְּכוֹר וּכְמוֹ שֶׁפֵּירֵשׁ רַשִׁ\"י בְּפַרְשַׁת תּוֹלְדוֹת עַל פָּסוּק וְיָדוֹ אֹחֶזֶת בַּעֲקֵב עֵשָׂו (בְּרֵאשִׁית כה. כו) מָשָׁל לִשְׁפוֹפֶרֶת נִכְנָס רִאשׁוֹן יוֹצֵא אַחֲרוֹן, דְּיַעֲקֹב נוֹצַר מִטִּפָּה הָרִאשׁוֹנָה, וְהַיְינוּ דִּבְשָׁרְשׁוֹ יַעֲקֹב שֶׁהוּא בְּחִינַת הַתִּקּוּן שָׁרְשׁוֹ לְמַעְלָה מֵעֵשָׂו בְּחִינַת הַתֹּהוּ,\nוְכֵן הוּא בְּנֶפֶשׁ הָאֱלֹקִית וְנֶפֶשׁ הַבַּהֲמִית, דְּהַנֶּפֶשׁ הָאֱלֹקִית שָׁרְשׁוֹ לְמַעְלָה מִנֶּפֶשׁ הַבַּהֲמִית, וְעַל יְדֵי זֶה יֵשׁ לוֹ כֹּחַ לְהִתְגַּבֵּר עַל הַנֶּפֶשׁ הַבַּהֲמִית מִצַּד שֶׁנִּמְשָׁךְ לוֹ כֹּחַ עַל זֶה מִשָּׁרְשׁוֹ הַקָּדוּם, דְּלִהְיוֹת שָׁרְשׁוֹ לְמַעְלָה מִשֹּׁרֶשׁ הַנֶּפֶשׁ הַבַּהֲמִית הֲרֵי בְּמֵילָא יֵשׁ בְּכֹחוֹ לְהִתְגַּבֵּר עָלָיו, אַף גַּם שֶׁהַנֶּפֶשׁ הַבַּהֲמִית קָדוּם לָבֹא וְלִפְעוֹל בְּגוּף הָאָדָם, מִכָּל מָקוֹם מֵאַחַר שֶׁשָּׁרְשׁוֹ קָדוּם אֵלָיו, הֲרֵי יֵשׁ בְּכֹחוֹ לְהִתְגַּבֵּר עָלָיו.\nקִיצּוּר.\nהַנֶּפֶשׁ הַבַּהֲמִית שֶׁשָּׁרְשׁוֹ מֵהַתֹּהוּ בָּא אֶל הָאָדָם קוֹדֶם לַנֶּפֶשׁ הָאֱלֹקִית שֶׁשָּׁרְשׁוֹ מֵהַתִּקּוּן, וּמִשְׁתָּרֵשׁ בְּהֶרְגֵּלִים גּוּפְנִים הַנִּמְשָׁכִים בְּטִבְעָם אֶל הַחוּמְרִיּוּת, תֹּהוּ קָדַם אֶל הַתִּקּוּן בְּהִתְגַּלּוּת, וּבְשָׁרְשָׁם הַתִּקּוּן קָדַם, לָכֵן בְּכֹחַ הַנֶּפֶשׁ הָאֱלֹקִית לְהִתְגַּבֵּר עַל הַנֶּפֶשׁ הַבַּהֲמִית."],[4401900065,"<h2>מַאֲמָר יד.</h2>\nוּבָזֶה יוּבַן מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (נִדָּה ל. ב) מַשְׁבִּיעִין אוֹתוֹ תְּהִי צַדִּיק וְאַל תְּהִי רָשָׁע, דִּשְׁבוּעָה זוֹ בָּאָה אַחֲרֵי שֶׁמְּלַמְּדִין אוֹתוֹ אֶת הַתּוֹרָה כוּלָּהּ,\nוּכְתִיב (יְשַׁעְיָה נז. טז) וּנְשָׁמוֹת אֲנִי עָשִׂיתִי וְאָמַר רַבֵּינוּ נִשְׁמָתוֹ עֵדֶן (סֵפֶר שֶׁל בֵּינוֹנִים בְּפֶרֶק א-ב)\nשֶׁהֵן שְׁתֵּי נְפָשׁוֹת, נֶפֶשׁ אַחַת מִצַּד הַקְּלִיפָּה וְסִטְרָא אָחֳרָא וְהִיא הַמִּתְלַבֶּשֶׁת בְּדַם הָאָדָם לְהַחֲיוֹת הַגּוּף וּכְדִכְתִיב כִּי נֶפֶשׁ הַבָּשָׂר בַּדָּם הִיא וּמִמֶּנָּה בָּאוֹת כָּל הַמִּדּוֹת רָעוֹת מֵאַרְבַּע יְסוֹדוֹת רָעִים שֶׁבָּהּ, דְּהַיְינוּ כַּעַס וְגַאֲוָה מִיסוֹד הָאֵשׁ שֶׁנִּגְבַּהּ לְמַעְלָה וְתַאֲוַת הַתַּעֲנוּגִים מִיסוֹד הַמַּיִם כִּי הַמַּיִם מַצְמִיחִים כָּל מִינֵי תַעֲנוּג וְהוֹלֵלוּת וְלֵיצָנוּת וְהִתְפָּאֲרוּת וּדְבָרִים בְּטֵלִים מִיסוֹד הָרוּחַ וְעַצְלוּת וְעַצְבוּת מִיסוֹד הֶעָפָר, וְגַם מִדּוֹת טוֹבוֹת שֶׁבְּטֶבַע כָּל יִשְׂרָאֵל בְּתוֹלְדוֹתָם כְּמוֹ רַחֲמָנוּת וּגְמִילוּת חֲסָדִים בָּאוֹת מִמֶּנָּה, כִּי בְּיִשְׂרָאֵל נֶפֶשׁ זוֹ דִקְלִיפָּה הִיא מִקְּלִיפַּת נוֹגַהּ שֶׁיֵּשׁ בָּהּ גַּם כֵּן טוֹב וְהִיא מִסּוֹד עֵץ הַדַּעַת טוֹב וָרָע,\nוְנֶפֶשׁ הַשֵּׁנִית בְּיִשְׂרָאֵל הִיא חֵלֶק אֱלֹקַהּ מִמַּעַל מַמָּשׁ כְּמוֹ שֶׁכָּתוּב וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים וְאַתָּה נְפַחְתָּהּ בִּי וּכְמוֹ שֶׁכָּתוּב בְּזֹהַר מַאן דְּנָפַח מִתּוֹכֵיהּ נָפַח פֵּירוּשׁ מִתּוֹכִיּוּתוֹ וּמִפְּנִימִיּוּתוֹ שֶׁתּוֹכִיּוּת וּפְנִימִיּוּת הַחַיּוּת שֶׁבָּאָדָם מוֹצִיא בִּנְפִיחָתוֹ בְּכֹחַ,\nכַּךְ עַל דֶּרֶךְ מָשָׁל נִשְׁמוֹת יִשְׂרָאֵל עָלוּ בְּמַחֲשָׁבָה כְּדִכְתִיב בְּנִי בְכוֹרִי יִשְׂרָאֵל, בָּנִים אַתֶּם לַה' אֱלֹקֵיכֶם, פֵּירוּשׁ כְּמוֹ שֶׁהַבֵּן נִמְשָׁךְ מִמּוֹחַ הָאָב כַּךְ כַּבְיָכוֹל נִשְׁמַת כָּל אִישׁ יִשְׂרָאֵל נִמְשָׁכָה מִמַּחֲשַׁבְתּוֹ וְחָכְמָתוֹ יִתְבָּרֵךְ דְּאִיהוּ חַכִּים וְלָא בְחָכְמָה יְדִיעָא אֶלָּא הוּא וְחָכְמָתוֹ אֶחָד,\nוְזֶהוּ וּנְשָׁמוֹת אֲנִי עָשִׂיתִי דְּקָאֵי עַל הַנֶּפֶשׁ הָאֱלֹקִית וְהַנֶּפֶשׁ הַבַּהֲמִית, וְאֶת הַנֶּפֶשׁ הָאֱלֹקִית מְלַמְּדִין אֶת הַתּוֹרָה כּוּלָּהּ וְאוֹתָהּ הוּא שֶׁמַּשְׁבִּיעִין תְּהִי צַדִּיק וְאַל תְּהִי רָשָׁע, דְּלִכְאוֹרָה אֵינוֹ מוּבָן מַהוּ עִנְיַן הַשְּׁבוּעָה שֶׁמַּשְׁבִּיעִין אֶת הַנֶּפֶשׁ הָאֱלֹקִית עַל הַנֶּפֶשׁ הַבַּהֲמִית, דְּזֶה שֶׁאֶפְשָׁר לִהְיוֹת רָשָׁע חַס וְשָׁלוֹם זֶהוּ מִצַּד הַנֶּפֶשׁ הַבַּהֲמִית, שֶׁמִּמֶּנָּה בָּאוֹת כָּל הַמִּדּוֹת רָעוֹת בְּכַעַס גַּאֲוָה וְתַאֲוַת הַתַּעֲנוּגִים, הוֹלֵלוּת וְלֵיצָנוּת הִתְפָּאֲרוּת וּדְבָרִים בְּטֵלִים עַצְלוּת וְעַצְבוּת, וְאִם כֵּן מַהוּ הַשְּׁבוּעָה שֶׁמַּשְׁבִּיעִין אֶת הַנֶּפֶשׁ הָאֱלֹקִית עַל זֶה.\n<b>אַךְ</b> הָעִנְיָן הוּא דִּשְׁבוּעָה הוּא לְשׁוֹן שׂוֹבַע, דְּהַשּׂוֹבַע עִנְיָנוֹ הַנְּתִינַת כֹּחַ מַה שֶּׁנּוֹתְנִים מִלְמַעְלָה לְהָאָדָם, שֶׁיּוּכַל לַעֲבוֹד אֶת עֲבוֹדָתוֹ בְּלִימּוּד הַתּוֹרָה וְקִיּוּם הַמִּצְוֹת. כְּמוֹ בְּגַשְׁמִיּוּת כְּשֶׁהָאָדָם שָׂבֵעַ, הִנֵּה לְבַד שֶׁהוּא חָזָק בְּכֹחוֹ הִנֵּה רוּחוֹ טוֹבָה עָלָיו וּכְמוֹ שֶׁכָּתוּב (יִרְמְיָה מד. יז) וַנִּשְׂבַּע לֶחֶם וַנִּהְיֶה טוֹבִים, כֵּן הוּא בְּרוּחָנִיּוּת שֶׁהַשּׂוֹבַע הוּא הַנְּתִינַת כֹּחַ מִלְמַעְלָה, וְזֶהוּ מַה שֶּׁמַּשְׁבִּיעִין אוֹתוֹ, מֶען מַאכְט אִיהם זַאט, בְּמַה שֶּׁנּוֹתְנִין לוֹ כֹּחַ מִשָּׁרְשׁוֹ וּמְקוֹרוֹ הַקָּדוּם שֶׁיּוּכַל לְהִתְגַּבֵּר עַל הַנֶּפֶשׁ הַבַּהֲמִית וְלֹא יִהְיֶה רָשָׁע.\n<b>וְזֶהוּ</b> גַם כֵּן עִנְיַן הַשְּׁבוּעָה עַל פִּי פָשׁוּט, דְּכַאֲשֶׁר אָדָם נִשְׁבָּע עַל אֵיזֶה דָבָר לַעֲשׂוֹתוֹ, הַיְינוּ גַּם אִם יִהְיוּ לוֹ מְנִיעוֹת וְעִכּוּבִים עַל זֶה לֹא יוֹעִיל שׁוּם דָּבָר וּמוּכְרָח הוּא לַעֲשׂוֹתוֹ וְהַיְינוּ עַל יְדֵי הִתְגַּבְּרוּת כֹּחַ מֵהַכֹּחוֹת הַנֶּעֱלָמִים וְכֹחוֹת עַצְמִים שֶׁלּוֹ, שֶׁעַל כֹּחוֹת עַצְמִים אֵין שׁוּם מְנִיעָה וְעִיכּוּב, וּכְמַאֲמָר אֵין לְךָ דָבָר הָעוֹמֵד בִּפְנֵי הָרָצוֹן, וּכְמוֹ כֵן הוּא עִנְיַן הַשְּׁבוּעָה שֶׁמַּשְׁבִּיעִין אֶת הַנֶּפֶשׁ הָאֱלֹקִית, הַיְינוּ שֶׁיִּתְגַּלּוּ הַכֹּחוֹת הַנֶּעֱלָמִים שֶׁבּוֹ מִצַּד שָׁרְשׁוֹ הַקָּדוּם, שֶׁעַל יְדֵי זֶה לֹא יִהְיֶה שׁוּם מְנִיעָה וְעִיכּוּב מִצַּד הַנֶּפֶשׁ הַבַּהֲמִית, כִּי יִתְגַּבֵּר עָלָיו.\n<b>וְאִם</b> כֵּן בָּטְלָה הַטַּעֲנָה מַה שֶּׁהַחוֹם הַטִּבְעִי שֶׁלּוֹ חָזָק, מֵאַחַר שֶׁהַנֶּפֶשׁ הָאֱלֹקִית הוּא קָדוּם וּלְמַעְלָה בְּשָׁרְשׁוֹ מֵהַנֶּפֶשׁ הַבַּהֲמִית וְיֵשׁ בּוֹ מִשָּׁרְשׁוֹ הַקָּדוּם, אִם כֵּן בְּכֹחַ זֶה יָכוֹל לְהִתְגַּבֵּר עַל הַנֶּפֶשׁ הַבַּהֲמִית, אֲפִילוּ יִהְיֶה חָזָק בְּיוֹתֵר, דְּכָל עִנְיַן הַחִיזּוּק שֶׁלּוֹ הוּא מִצַּד שָׁרְשׁוֹ הָרִאשׁוֹן בַּתֹּהוּ וּמִצַּד שָׁרְשׁוֹ בִּקְלִיפַּת נוֹגַהּ, וְאִם כֵּן הַנֶּפֶשׁ הָאֱלֹקִית דְּשָׁרְשׁוֹ קָדוּם יוֹתֵר לְמַעְלָה מִבְּחִינַת הַתֹּהוּ הֲרֵי יֵשׁ בּוֹ כֹּחַ וְחוֹזֶק גָּדוֹל לְהִתְגַּבֵּר עָלָיו, וְכַאֲשֶׁר הַחוֹם הַטִּבְעִי שֶׁלּוֹ חָזָק וַדַּאי גַּם הַנֶּפֶשׁ הָאֱלֹקִית שֶׁלּוֹ חָזָק יוֹתֵר,\nאֶלָּא שֶׁזֶּה תָּלוּי בִּבְחִירַת הָאָדָם, שֶׁאִם רְצוֹנוֹ בֶּאֱמֶת לִבְלִי לָסוּר מִדֶּרֶךְ ה' הֲרֵי הוּא מְעוֹרֵר בְּעַצְמוֹ אֶת הַכֹּחַ הֶחָזָק שֶׁל הַנֶּפֶשׁ הָאֱלֹקִית וְאָז הֲרֵי הוּא מִתְגַּבֵּר עַל הַנֶּפֶשׁ הַבַּהֲמִית, וְזֶה שֶׁאֵינוֹ יָכוֹל לַעֲמוֹד נֶגֶד הִתְגַּבְּרוּת הַחוֹם הַטִּבְעִי שֶׁל הַנֶּפֶשׁ הַבַּהֲמִית, הוּא רַק מִפְּנֵי שֶׁאֵינוֹ מְעוֹרֵר אֶת הַכֹּחוֹת דְּנֶפֶשׁ הָאֱלֹקִית, כִּי מִלְמַעְלָה נִיתַּן לוֹ כֹּחַ לַעֲמוֹד נֶגֶד הַנֶּפֶשׁ הַבַּהֲמִית וּלְהִתְגַּבֵּר עָלָיו, רַק בּוֹ הַדָּבָר תָּלוּי שֶׁצָּרִיךְ לְעוֹרֵר אֶת הַכֹּחַ הֶחָזָק דְּנֶפֶשׁ הָאֱלֹקִית.\nקִיצּוּר.\nהַנֶּפֶשׁ הַבַּהֲמִית שָׁרְשָׁהּ בַּתֹּהוּ וּבִקְלִיפַּת נוֹגַהּ, וּמִמֶּנָּה בָּאוֹת הַמִּדּוֹת הָרָעוֹת דְּכַעַס גַּאֲוָה וְתַאֲוַת הַתַּעֲנוּגִים הוֹלֵלוּת לֵיצָנוּת הִתְפָּאֲרוּת דְּבָרִים בְּטֵלִים עַצְלוּת וְעַצְבוּת וְהַמִּדּוּת רַחֲמָנוּת וּגְמִילוּת חֲסָדִים. וְהַנֶּפֶשׁ הָאֱלֹקִית שָׁרְשָׁהּ לְמַעְלָה מִתֹּהוּ חֵלֶק אֱלֹקַהּ מִמַּעַל מַמָּשׁ, הַשְּׁבוּעָה הִיא הַנְּתִינַת כֹּחַ לְעוֹרֵר כֹּחוֹת הַנֶּעֱלָמִים לְהִתְגַּבֵּר עַל הַנֶּפֶשׁ הַבַּהֲמִית."],[4401900066,"וְהַטַּעֲנָה הַשֵּׁנִית מַה שֶּׁפְּלוֹנִי הֱסִיתוֹ כו' אֵינָהּ טַעֲנָה אֲמִיתִּית שֶׁהֲרֵי בֶּאֱמֶת צָרִיךְ לְהִתְרַחֵק מֵאִישׁ רָע וְרָשָׁע וְלֹא יִתְחַבֵּר אֵלָיו, כִּי הַרְבֵּה חֲבֵרוּת עוֹשָׂה, וַחֲבֵרִים טוֹבִים מְבִיאִים טוֹבָה הַרְבֵּה אֶל הָאָדָם, כִּי מִלְּבַד שֶׁהַלִּימּוּד טוֹב עִם חָבֵר, כְּמוֹ שֶׁכָּתוּב (קֹהֶלֶת ד. ט) טוֹבִים הַשְּׁנַיִם מִן הָאֶחָד וּכְמוֹ שֶׁדָּרְשׁוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (בְּרָכוֹת סג. ב) עַל פָּסוּק חֶרֶב אֶל הַבַּדִּים כו' (יִרְמְיָה נ. לו) הִנֵּה לְבַד זֹאת מַה שֶּׁיְּדַבְּרוּ יִרְאֵי ה' אִישׁ אֶל רֵעֵהוּ זֶה פּוֹעֵל הַרְבֵּה מְאֹד, כִּי אֵין אָדָם רוֹאֶה נִגְעֵי עַצְמוֹ מִצַּד אַהֲבַת עַצְמוֹ שֶׁעַל כָּל פְּשָׁעִים תְּכַסֶּה אַהֲבָה מַה שֶּׁאוֹהֵב אֶת עַצְמוֹ, וְאֵינוֹ רוֹאֶה הַפְּשָׁעִים שֶׁלּוֹ, וַחֲבֵרוֹ רוֹאֶה וְיוֹדֵעַ יוֹתֵר מִמֶּנּוּ וּמוֹכִיחוֹ עַל זֶה וְגַם מְדַבֵּר עַל לִבּוֹ אֵיךְ שֶׁלֹּא טוֹב לַעֲשׂוֹת כַּאֲשֶׁר עָשָׂה וְזֶה כָּל הָאָדָם שֶׁיֵּלֵךְ בְּדֶרֶךְ הַטּוֹב וְהַיָּשָׁר, וְכָל זֶה פּוֹעֵל עַל הָאָדָם הַרְבֵּה טוֹבָה.\n<b>וּלְעוּמַּת</b> זֶה חָבֵר רָע פּוֹעֵל הַרְבֵּה לְרָעָה, שֶׁמְּסִיתוֹ וּמַטֵּהוּ מִדֶּרֶךְ הַטּוֹב וְהַיָּשָׁר וְגוֹרֵם שֶׁיַּעֲשֶׂה דְבָרִים אֲשֶׁר מֵעַצְמוֹ בֶּאֱמֶת לֹא הָיָה עוֹשֶׂה דְבָרִים כָּאֵלּוּ כַּאֲשֶׁר אָנוּ רוֹאִים זֶה בְּחוּשׁ בְּהַרְבֵּה בְּנֵי אָדָם שֶׁהָיוּ טוֹבִים מִצַּד עַצְמָם וְעַל יְדֵי הִתְחַבְּרוּתָם לַאֲנָשִׁים רָעִים נַעֲשִׂים רָעִים וְחַטָּאִים רַחֲמָנָא לִצְּלָן, וְעַל זֶה נִצְטַוִּינוּ בְּמִשְׁנָה דְאָבוֹת (פֶּרֶק א) קְנֵה לְךָ חָבֵר, הַיְינוּ חָבֵר טוֹב, שֶׁהַרְבֵּה טוֹבָה תְּקַבֵּל מֵאִתּוֹ וּלְהֵיפֶךְ הַרְחֵק מִשָּׁכֵן רָע, וְאַל תִּתְחַבֵּר לָרָשָׁע, וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (סוּכָּה נו. ב) אוֹי לָרָשָׁע וְאוֹי לִשְׁכֵנוֹ, וּכְמוֹ שֶׁפֵּרֵשׁ רַשִׁ\"י עַל פָּסוּק וַיִּקַּח קֹרַח (בַּמִּדְבָּר לח. א), וְכָל שֶׁכֵּן כְּשֶׁיִּהְיֶה חָבֵר אֵלָיו שֶׁגּוֹרֵם לוֹ רָעָה הַרְבֵּה, וְאִם כֵּן הֲרֵי הוּא מִתְחַיֵּיב בְּנַפְשׁוֹ עַל זֶה שֶׁהִתְחַבֵּר לָרָשָׁע וּבַמֶּה הוּא מַצְדִּיק אֶת עַצְמוֹ,\nרַק בְּהַחֵטְא הָרִאשׁוֹן שֶׁעָשָׂה מַה שֶּׁהִתְחַבֵּר אֵלָיו שֶׁאֵין זֶה הַצְדָּקָה כְּלָל, כִּי אִם מַה שֶּׁמַּטְעֶה אֶת עַצְמוֹ מִצַּד אַהֲבַת עַצְמוֹ הֲרֵי הוּא מְחַפֵּשׂ וּמוֹצֵא לְהַצְדִּיק אֶת עַצְמוֹ בְּדִבְרֵי שֶׁקֶר, וּבַדָּבָר שֶׁבָּזֶה עַצְמוֹ הוּא אָשֵׁם אֲשֶׁר חָטָא בָּזֶה. וּפְעוּלַּת הַהַצְדָּקָה הַלֵּזּוּ שֶׁמַּצְדִּיק אֶת עַצְמוֹ הוּא שֶׁאֵין תְּשׁוּבָתוֹ כִּדְבָעֵי לְמֶהֱוֵי, הֵן בִּתְשׁוּבַת הַמִּשְׁקָל הַיְינוּ לְצַעֵר וּלְסַגֵּף אֶת עַצְמוֹ כְּעֶרֶךְ הַתַּעֲנוּג שֶׁהָיָה לוֹ, מֵאַחַר שֶׁחוֹשֵׁב שֶׁלֹּא הָיָה אָשֵׁם בָּזֶה כָּל כַּךְ, אִם כֵּן אֵינוֹ צָרִיךְ לְצַעֵר אֶת עַצְמוֹ כָּל כַּךְ בִּתְשׁוּבָתוֹ, וּבִפְרָט בְּעֶצֶם הַתְּשׁוּבָה הֲרֵי זֶה נוֹגֵעַ הַרְבֵּה, שֶׁאֵין הַחֲרָטָה עַל הֶעָבָר וְהַקַּבָּלָה עַל לְהַבָּא אֲמִיתִּית כָּל כַּךְ, כִּי הַחֲרָטָה וְהַקַּבָּלָה תְּלוּיוֹת בִּמְרִירוּת נַפְשׁוֹ, דְּכַאֲשֶׁר מִתְמַרְמֵר בְּנַפְשׁוֹ מְאֹד עַל הַחֵטְא וְהֶעָוֹן, אָז הוּא מִתְחָרֵט בֶּאֱמֶת וְעוֹקֵר רְצוֹנוֹ לְגַמְרֵי מִזֶּה וּמִמֵּילָא הַקַּבָּלָה עַל לְהַבָּא אֲמִיתִּית, אֲבָל עַל יְדֵי שֶׁמַּצְדִּיק אֶת עַצְמוֹ הֲרֵי אֵין מְרִירוּת נַפְשׁוֹ גְּדוֹלָה כָּל כַּךְ, מֵאַחַר שֶׁמּוֹצֵא זְכוּת עַל עַצְמוֹ, וּמֵאַחַר שֶׁהַמְּרִירוּת אֵינָהּ גְּדוֹלָה כָּל כַּךְ מִמֵּילָא הַחֲרָטָה וְהַקַּבָּלָה אֵינָם אֲמִיתִּים,\nוְאִם כֵּן הֲרֵי הַהַצְדָּקָה הַזֹּאת חוֹשֶׂכֶת מִמֶּנּוּ טוֹבָה הַרְבֵּה בְּעֶצֶם תְּשׁוּבָתוֹ וּבְשִׁינּוּי מַהוּתוֹ (שֶׁעַל יְדֵי הַתְּשׁוּבָה אֲמִיתִּית מִתְהַפֵּךְ מַהוּתוֹ מֵרָשָׁע לַצַּדִּיק, דְּבֶאֱמֶת מִשְׁתַּנֶּה מַהוּתוֹ וְנַעֲשֶׂה רָחוֹק מִכָּל הַדְּבָרִים הַהֲפָכִים מֵאֱלֹקוּת, וְכַאֲשֶׁר אֵין תְּשׁוּבָתוֹ אֲמִיתִּית מִמֵּילָא גַּם כֵּן אֵינוֹ מִשְׁתַּנֶּה וּמִתְרַחֵק מֵהָרָע כָּל כַּךְ),\nוַהֲרֵי זֶה כְּמוֹ עִנְיַן הַשְּׁטוּת שֶׁקָּדַם לִדְבַר עֲבֵירָה, אֶלָּא שֶׁהַשְּׁטוּת הַהִיא הֵבִיאָה שֶׁיִּכָּשֵׁל בִּדְבַר הָעֲבֵירָה, וְהַשְּׁטוּת שֶׁמַּצְדִּיק אֶת עַצְמוֹ הוּא הַגּוֹרֵם שֶׁתְּשׁוּבָתוֹ לֹא תִהְיֶה נְכוֹנָה כָּל כַּךְ כִּדְבָעֵי לְמֶהֱוֵי, וּבִפְרָט אֶחָד הֲרֵי זֶה יוֹתֵר גָרוּעַ מִשְּׁטוּת הַקּוֹדֵם, כִּי הֲרֵי לְאַחַר שֶׁכְּבָר עָבַר עֲבֵירָה רַחֲמָנָא לִצְּלָן כְּשֶׁעוֹשֶׂה תְשׁוּבָה מֵעוּמְקָא דְלִיבָּא הֲרֵי אָמְרוּ (בְּרָכוֹת לד. ב) מָקוֹם שֶׁבַּעֲלֵי תְשׁוּבָה עוֹמְדִים צַדִּיקִים גְּמוּרִים אֵינָן עוֹמְדִין, וַהֲרֵי הַשְּׁטוּת הַזֶּה מוֹנֵעַ אוֹתוֹ מִזֶּה, אִם כֵּן הֲרֵי שְׁטוּת זֶה עוֹד גָּרוּעַ יוֹתֵר שֶׁחוֹשֵׂךְ וּמוֹנֵעַ אוֹתוֹ מִטּוֹבָה הַרְבֵּה, שֶׁעַל יְדֵי תְשׁוּבָתוֹ הָאֲמִיתִּית הָיָה בָא לְמַעֲלָה וּמַדְרֵיגָה גָּבוֹהַּ מְאֹד.\nקִיצּוּר.\nחָבֵר טוֹב מְסַיֵּיעַ לִמְצוֹא מוּמֵי הָרוּחַ וּמוֹעִיל לַעֲקוֹר הַדֵּעוֹת וּמִדּוֹת רָעוֹת וּלְהַקְנוֹת הַטּוֹבוֹת, וְחָבֵר רָע גּוֹרֵם הַשְׁרָשַׁת הַיְדִיעוֹת וּמִדּוֹת רָעוֹת. הַהִצְטַדְּקוּת בַּהֲסָתַת זוּלָתוֹ סִיבָּה שֶׁאֵין תְּשׁוּבָה שְׁלֵימָה, וּשְׁטוּתוֹ גְרוּעָה מִשְּׁטוּת הַגּוֹרֵם עֲבֵירָה."],[4401900067,"<h2>מַאֲמָר טו.</h2>\nוְהִנֵּה הָאָדָם בַּאֲשֶׁר הוּא אָדָם צָרִיךְ לָדַעַת וְכָל אָדָם שֶׁיֵּשׁ לוֹ מוֹחַ בְּקָדְקֳדוֹ יוֹדֵעַ, אֲשֶׁר הָאָדָם הוּא בְּחִיר הַנִּבְרָאִים אֲשֶׁר בָּרָא וְיָצַר הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא לְבָד בִּצְבָא הָאָרֶץ אֶלָּא גַּם בִּצְבָא הַשָּׁמַיִם, וְהוּא (הָאָדָם) בְּרִיאָה הַתִּיכוֹנִית מִכָּל הַנִּבְרָאִים כּוּלָּם, הַיְינוּ הֵן מֵהַנִּבְרָאִים הָעֶלְיוֹנִים וְהֵן מֵהַנִּבְרָאִים הַתַּחְתּוֹנִים, דְּהִנֵּה כָּל הַנִּבְרָאִים אֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא וְהָאָדָם בִּכְלָל הֵם בַּעֲלֵי גוּף וָנֶפֶשׁ, אֲשֶׁר בָּזֶה שָׁוִים הֵמָּה צְבָא הָאָרֶץ עִם צְבָא הַשָּׁמַיִם, דְּעִם הֱיוֹת אֲשֶׁר צְבָא הַשָּׁמַיִם חָלוּק מִצְּבָא הָאָרֶץ, דִּצְבָא הָאָרֶץ בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם מֵהַרְכָּבַת הַד' יְסוֹדוֹת אֵשׁ רוּחַ מַיִם עָפָר, וּצְבָא הַשָּׁמַיִם בָּרָא אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא רַק מֵהַרְכָּבַת שְׁנֵי יְסוֹדוֹת אֵשׁ וָרוּחַ כְּמוֹ שֶׁכָּתוּב עוֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לוֹהֵט, בְּכָל זֶה הִנֵּה בָּזֶה מִשְׁתַּוִּים צְבָא הַשָּׁמַיִם וּצְבָא הָאָרֶץ שֶׁהֵם בַּעֲלֵי גוּף וָנֶפֶשׁ, וְהַיְינוּ דְּעִם הֱיוֹת דִּצְבָא הַשָּׁמַיִם בְּרָאָם מֵהַיְסוֹדוֹת הַדַּקִּים דְּאֵשׁ וָרוּחַ, בְּכָל זֶה הִנֵּה גַּם הֵם בַּעֲלֵי גוּף, וּצְבָא הָאָרֶץ עִם הֱיוֹת שֶׁבְּרָאָם בְּהַרְכָּבַת הַיְסוֹדוֹת מַיִם וְעָפָר גַּם כֵּן בְּכָל זֶה הִנֵּה גַּם הֵם בַּעֲלֵי נֶפֶשׁ, וְרַק הַהֶבְדֵּל הוּא בְּטִבְעָם, דְּטִבְעֵי צְבָא הַשָּׁמַיִם הוּא בְּהַגְבָּרַת הַצּוּרָה עַל הַחוֹמֶר, וְטִבְעֵי צְבָא הָאָרֶץ בְּטֶבַע תּוֹלְדוֹתָם בְּהַגְבָּרַת הַחוֹמֶר עַל הַצּוּרָה.\n<b>וְהִנֵּה</b> הַגּוּף וְהַנֶּפֶשׁ מַקְבִּילִים וּמַתְאִימִים זֶה לָזֶה, וְהַיְינוּ דְּעִם הֱיוֹת אֲשֶׁר הַנֶּפֶשׁ וְהַגּוּף הִנֵּה מִצַּד מַהוּתָם הָעַצְמִי הֵם הֲפָכִים זֶה מִזֶּה, דְּהַנֶּפֶשׁ הוּא רוּחָנִי וְהַגּוּף גַּשְׁמִי, וְרוּחָנִי וְגַשְׁמִי בְּמַהוּתָם הָעַצְמִי הֲרֵי הֵם הֲפָכִים זֶה מִזֶּה, בְּכָל זֶה הִנֵּה הַנֶּפֶשׁ וְהַגּוּף מַקְבִּילִים וּמַתְאִימִים זֶה לָזֶה, דְּזוֹהִי אַחַת מֵהַפְּלִיאוֹת דִּפְלִיאוֹת תְּמִים דֵּעִים יִתְבָּרֵךְ וְיִתְעַלֶּה בְּעִנְיַן בְּרִיאָה יֵשׁ מֵאַיִן וְהִתְחַבְּרוּתָן שֶׁהוּא רַק בְּחֵיק הַבּוֹרֵא בָּרוּךְ הוּא שֶׁמַּפְלִיא לַעֲשׂוֹת מְקַשֵּׁר רוּחָנִיּוּת בְּגַשְׁמִיּוּת בְּאוֹפֶן הַמַּקְבִּיל וּמַתְאִים כְּאִלּוּ הָיוּ לַאֲחָדִים מִתְּחִלַּת יְצִירָתָם בְּמַהוּתָם הָעַצְמִי, וְלָכֵן הִנֵּה הַנֶּפֶשׁ וְהַגּוּף נִקְרָאִים אוֹר וּכְלִי, דְּהַנֶּפֶשׁ הוּא אוֹר וְהַגּוּף הוּא כְלִי.\n<b>וְהִנֵּה</b> גּוּף הָאָדָם שִׁינָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹפֶן יְצִירָתוֹ מִיצִירַת גּוּפוֹת שְׁאָר הַנִּבְרָאִים אֲשֶׁר בָּרָא וְיָצַר הַקָּדוֹשׁ בָּרוּךְ הוּא, דְּכָל הַנְּבִרָאִים הִנֵּה כְּשֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ הַמַּאֲמָר הַשַּׁיָּיךְ לְהַנִּבְרָאִים הָהֵם, מִיָּד נִבְרָא גוּפָם וְנִכְנְסָה בָהֶם נַפְשָׁם וּשְׁנֵיהֶם (הַגּוּף וְהַנֶּפֶשׁ) כְּאֶחָד יָצְאוּ עַל פְּנֵי הָאֲדָמָה, כְּמוֹ בְּיוֹם ג' כְּשֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְּרִי עוֹשֶׂה פְּרִי לְמִינוֹ אֲשֶׁר זַרְעוֹ בוֹ עַל הָאָרֶץ וַיְהִי כֵן, הוֹצִיאָה הָאָרֶץ אֶת הָעֲשָׂבִים וְאֶת הָאִילָנוֹת כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁהֵם עִם נֶפֶשׁ הַצּוֹמַחַת שֶׁבָּהֶם, וְכֵן גַּם בְּבַעֲלֵי חַיִּים הוֹצִיאָה אוֹתָם הָאָרֶץ כְּמוֹ שֶׁהֵם חַיִּים וְגַם הַמַּיִם שָׁרְצוּ כֵן שֶׁרֶץ נֶפֶשׁ חַיָּה, וְהַיְינוּ דְּכָל הַנִּבְרָאִים הִנֵּה אוֹפֶן יְצִירָתָם בְּרָאָם הַקָּדוֹשׁ בָּרוּךְ הוּא הַגּוּף עִם הַנֶּפֶשׁ הַחִיּוּנִית אֲשֶׁר בְּתוֹכָם יַחַד,\nמַה שֶּׁאֵין כֵּן אוֹפֶן יְצִירַת הָאָדָם שִׁינָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בְּרִיאָתוֹ, שֶׁבָּרָא תְּחִלָּה אֶת גּוּפוֹ בִּפְנֵי עַצְמוֹ עָפָר מִן הָאֲדָמָה בְּלִי שׁוּם נֶפֶשׁ חִיּוּנִית בְּתוֹכוֹ. וּכְמוֹ שֶׁכָּתוּב וַיִּיצֶר ה' אֱלֹקִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה, דְּמִתְּחִלָּה הָיָה גוֹלֶם, וְאַחַר כַּךְ וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, וְהַיְינוּ שֶׁלֹּא יָצָא גוּפוֹ מִן הָאָרֶץ עִם הָרוּחַ חַיִּים שֶׁבּוֹ כְּמוֹ שֶׁהָיָה בְּכָל הַנִּבְרָאִים, אֶלָּא דִּתְחִלָּה בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת גּוּפוֹ וּבָרָא אוֹתוֹ מִן הַחוֹמֶר הַיּוֹתֵר עָב וְגַס שֶׁהוּא דוֹמֵם. וְזֶהוּ עָפָר מִן הָאֲדָמָה, וְהָיָה גוֹלֶם בְּלִי שׁוּם חַיּוּת, דְּהָוֵי שִׁפְלוּת גְּדוֹלָה לְהָאָדָם לְעוּמַּת שְׁאָר הַבְּרוּאִים, דְּעִם הֱיוֹת דְּהַכֹּל הָיָה מִן הֶעָפָר, אֲבָל עִם זֶה הִנֵּה אוֹפֶן יְצִירָתָם שֶׁיָּצְאוּ גוּפָם וְנַפְשָׁם כְּאֶחָד, וְהָאָדָם הִנֵּה תְּחִלָּה הָיָה גוֹלֶם וְרַק אַחַר כַּךְ וַיִּפַּח נִשְׁמַת חַיִּים,\nוְצָרִיךְ לְהָבִין מִפְּנֵי מָה שִׁינָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹפֶן יְצִירַת גּוּף הָאָדָם מִגּוּפוֹת שְׁאָרֵי הַנִּבְרָאִים, דְּלִכְאוֹרָה הִנֵּה הַשִּׁינּוּי הוּא לִגְרִיעוּתָא, שֶׁהֲרֵי כָּל הַבְּרוּאִים, עִם הֱיוֹת שֶׁיְּצִירָתָם הִיא מִן הֶעָפָר, אֲבָל עִם זֶה לֹא נִרְאוּ בְּנַוְולוּתָם בִּהְיוֹתָם גּוֹלָמִים כִּי אִם בִּהְיוֹת גּוּפָם וְנַפְשָׁם כְּאֶחָד, וְהָאָדָם הִנֵּה אוֹפֶן יְצִירָתוֹ אֲשֶׁר תְּחִלָּה נִרְאָה בְּנַוְולוּתוֹ בִּהְיוֹתוֹ גוֹלֶם, וְרַק אַחֲרֵי כֵן הִפִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא נִשְׁמַת חַיִּים, וְאַחַר כָּל זֶה הִנֵּה הָאָדָם דַּוְקָא הוּא בְּחִיר הַנִּבְרָאִים וְהַבְּרִיאָה הַתִּיכוֹנִית בְּכָל הַבְּרִיאָה כוּלָּהּ.\nקִיצּוּר.\nכָּל הַנִּבְרָאִים צְבָא הַשָּׁמַיִם וּצְבָא הָאָרֶץ בַּעֲלֵי גוּף וָנֶפֶשׁ הֵמָּה, צְבָא הַשָּׁמַיִם שֶׁיְּצִירָתָם מִיסוֹדוֹת הַדַּקִּים דְּאֵשׁ וָרוּחַ טִבְעָם בְּהַגְבָּרַת הַצּוּרָה עַל הַחוֹמֶר, וּצְבָא הָאָרֶץ שֶׁיְּצִירָתָם גַּם מִיסוֹדוֹת הַגַּסִּים טֶבַע תּוֹלְדוֹתָם בְּהַגְבָּרַת הַחוֹמֶר עַל הַצּוּרָה, גּוּף וָנֶפֶשׁ אוֹר וּכְלִי מַתְאִימִים, הַקָּדוֹשׁ בָּרוּךְ הוּא שִׁינָּה אוֹפֶן יְצִירַת גּוּף הָאָדָם."],[4401900068,"וְהִנֵּה טַעַם וְסִבַּת הַדָּבָר מַה שֶּׁהַקָּדוֹשׁ בָּרוּךְ הוּא שִׁינָּה אוֹפֶן יְצִירַת גּוּף הָאָדָם מֵאוֹפֶן יְצִירַת גּוּפוֹת כָּל הַבַּעֲלֵי חַיִּים, דְּכָל הַבַּעֲלֵי חַיִּים בְּקוֹמָתָן נִבְרְאוּ וּבְצִבְיוֹנָן נִבְרְאוּ וְהָאָדָם נִבְרָא עָפָר מִן הָאֲדָמָה, דִּתְחִלָּה נִבְרָא גוּפוֹ וְאַחַר כֵּן נִיתְּנָה בוֹ נִשְׁמָתוֹ, אֵינוֹ לִגְרִיעוּתָא אֶלָּא אַדְרַבָּא הִיא לְמַעֲלִיּוּתָא, וְגַם זֶה מַה שֶּׁהָאָדָם נִבְרָא מֵעָפָר מִן הָאֲדָמָה מוֹרֶה עַל גּוֹדֶל הַפְלָאַת מַעֲלַת נִשְׁמַת אָדָם.\n<b>וְהָעִנְיָן</b> הוּא דְּהִנֵּה בְּהַד' חֲלוּקּוֹת שֶׁבָּהֶם נֶחְלְקוּ כָּל הַנִּבְרָאִים וְהֵם דּוֹמֵם צוֹמֵחַ חַי וּמְדַבֵּר, הִנֵּה הַחֵלֶק הַיּוֹתֵר גָּרוּעַ וְשָׁפָל הוּא חֵלֶק הַדּוֹמֵם וְהַחֵלֶק הַיּוֹתֵר נַעֲלֶה וּמְשׁוּבָּח הוּא חֵלֶק הַמְדַבֵּר, וְלִהְיוֹת כִּי הָאָדָם שֶׁהוּא הַמְעוּלֶּה וּבְחִיר הַנִּבְרָאִים הִנֵּה אוֹפֶן יְצִירַת גּוּפוֹ הוּא בְּשִׁינּוּי מֵאוֹפֶן יְצִירַת גּוּפוֹת שְׁאָרֵי הַבַּעֲלֵי חַיִּים, וְגַם גּוּף וְעֶצֶם הַחוֹמֶר אֲשֶׁר מִמֶּנּוּ בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת גּוּף הָאָדָם עָפָר מִן הָאֲדָמָה הַגַּס בְּיוֹתֵר מוֹרֶה עַל נִשְׁמַת הָאָדָם שֶׁהִיא בְּתַכְלִית הָרוֹמְמוּת, כְּהַכְּלָל הַיָּדוּעַ דְּכָל הַגָּבוֹהַּ גָּבוֹהַּ בְּיוֹתֵר יוֹרֵד לְמַטָּה מַּטָּה יוֹתֵר, וּכְמוֹ בְּגַשְׁמִיּוּת אָנוּ רוֹאִים בְּכוֹתֶל אֲבָנִים דִּכְשֶׁהָאֲבָנִים שֶׁבְּתַחְתִּית הַכּוֹתֶל נוֹפְלִים הִנֵּה הֵם בְּקֵירוּב אֶל הַכּוֹתֶל וּכְשֶׁנּוֹפְלִים הָאֲבָנִים שֶׁבְּרֹאשׁ הַכּוֹתֶל הֵם בְּרִיחוּק מִן הַכּוֹתֶל, וְכָל אֶבֶן שֶׁהִיא גָבוֹהַּ גָּבוֹהַּ יוֹתֵר הִנֵּה כְּשֶׁנּוֹפֶלֶת הִיא בְּרִיחוּק מִן הַכּוֹתֶל בְּיוֹתֵר,\nוְכֵן בְּרוּחָנִיּוּת בְּעִנְיַן הַנְּשָׁמוֹת וְהַנְּפָשׁוֹת בְּנִשְׁמַת כָּל חַי, דְּלִהְיוֹת דְּנִשְׁמַת הָאָדָם הִיא גָבוֹהַּ גָּבוֹהַּ בְּיוֹתֵר לָכֵן הִנֵּה נָתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא גּוּף מֵחוֹמֶר עָב וְגַס בְּיוֹתֵר, לְפִי שֶׁבְּכֹחוֹ לְבָרֵר וּלְזַכֵּךְ אֶת הַחוֹמֶר הַיּוֹתֵר עָב וְהַגַּס בְּיוֹתֵר,\nוְלָכֵן אָנוּ רוֹאִים בְּמוּחָשׁ בְּטִבְעֵי בְּנֵי אָדָם, דְּיֵשׁ כָּאֵלּוּ שֶׁהֵם בַּעֲלֵי מִדּוֹת רָעוֹת רַחֲמָנָא לִצְּלָן יוֹתֵר הַרְבֵּה מֵחַיּוֹת רָעוֹת הַדּוֹרְסוֹת וְטוֹרְפוֹת וַחֲכָמִים הֵמָּה לְהָרַע לְהָעִיק לְזוּלָתָם, מַאכֶען עֶנְג אוּן שְׁלֶעכְט דֶעם צְוֵוייטֶען, וְגוֹזְלִים וְרוֹצְחִים בִּכְדֵי לְמַלֹּאות תַּאֲוַת נַפְשָׁם, דְּעַל הָרוֹב הוּא מִצַּד הַנְּטִיּוֹת הָרָעוֹת שֶׁל הַגּוּף, וּנְטִיּוֹת הָרָעוֹת שֶׁל הַגּוּף פּוֹעֲלוֹת לְרָעָה עַל נַפְשָׁם, הַיְינוּ הַגְבָּרַת הַגּוּף עַל הַנֶּפֶשׁ שֶׁיַּשְׂכִּיל וְיִתְחַכֵּם אֵיךְ לְהָפִיק מְזִמּוֹתָיו בִּגְזֵילָה וּרְצִיחָה, אֲבָל הַנֶּפֶשׁ מִצַּד עַצְמָהּ הִיא בְּתַכְלִית הַמַּעֲלָה, וּבִיכוֹלֶת הָאָדָם לַעֲלוֹת בְּעִילּוּי אַחַר עִילּוּי בְּמַעֲשֵׂה הַטּוֹב וּלְהַגִּיעַ לְדַרְגוֹת רוּחָנִיּוֹת הַנַּעֲלוֹת בְּיוֹתֵר, וּכְהַמַּעֲשֶׂה הַמּוּבָא בְּרֵאשִׁית חָכְמָה (שַׁעַר הָאַהֲבָה פֶּרֶק ד) בְּאֶחָד שֶׁבָּא מֵעוֹמֶק הַשִּׁפְלוּת הָרוּחָנִית לְמַעֲלַת הָרוּם הָרוּחָנִי.\n<b>וּבָזֶה</b> יוּבַן מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (חֲגִיגָה טז. א) שִׁשָּׁה דְבָרִים נֶאֶמְרוּ בִּבְנֵי אָדָם שְׁלֹשָׁה כְּמַלְאֲכֵי הַשָּׁרֵת שְׁלֹשָׁה כַּבְּהֵמָה, וְהַיְינוּ דְּהָאָדָם הִנֵּה מִצַּד טֶבַע גּוּפוֹ וּנְטִיּוֹתָיו הוּא כִּבְהֵמָה, וְהָאָדָם שֶׁעוֹשֶׂה מַעֲשֵׂה בְהֵמָה הֲרֵי הוּא גָרוּעַ מִן הַבְּהֵמָה, דִּבְהֵמָה אֵין לָהּ דַּעַת וְאָדָם יֵשׁ לוֹ דַעַת, וּמִצַּד טֶבַע נַפְשׁוֹ וּנְטִיּוֹתָיו הוּא כְּמַלְאֲכֵי הַשָּׁרֵת, שֶׁיָּכוֹל לְהַגִּיעַ לְהַדַּרְגּוֹת הָרוּחָנִיּוֹת הַנַּעֲלוֹת בְּיוֹתֵר, וְהָאָדָם כְּשֶׁעוֹלֶה בְּמַעֲלַת הַדַּעַת הוּא גָבוֹהַּ בְּמַעֲלָה מִמַּלְאֲכֵי הַשָּׁרֵת, דְּמַלְאֲכֵי הַשָּׁרֵת הִנֵּה עֲמִידָתָם בְּעוֹלָם רוּחָנִי, וּכְמַאֲמָר כְּלוּם יֵצֶר הָרָע יֵשׁ בָּכֶם, אֲבָל הָאָדָם שֶׁהוּא בָּעוֹלָם הַזֶּה הַגַּשְׁמִי וּמַשְׂכִּיל בְּהָעִנְיָנִים הַיּוֹתֵר נַעֲלִים בְּהַשָּׂגוֹת אֱלֹקוּת וְהַשָּׂגָתוֹ זֹאת פּוֹעֶלֶת בּוֹ רָצוֹא וּתְשׁוּקָה לְהִדָּבֵק בֵּאלֹקוּת הֲרֵי הוּא לְמַעְלָה יוֹתֵר מִמַּלְאֲכֵי הַשָּׁרֵת, כִּי בַּעֲבוֹדָתוֹ זֹאת הֲרֵי הוּא מַעֲלֶה אֶת הַגַּשְׁמִיּוּת דְּעוֹלָם הַזֶּה,\nוּמֵהַאי טַעְמָא הִנֵּה נִשְׁתַּנָּה אוֹפֶן יְצִירַת גּוּף הָאָדָם מִיצִירַת שְׁאָר הַבַּעֲלֵי חַיִּים וְגוּפוֹ הוּא מֵהַחוֹמֶר הָעָב וְגַס בְּיוֹתֵר, לִהְיוֹת דִּבְכֹחַ נִשְׁמָתוֹ לְהָאִיר גַּם אֶת הַחֹשֶׁךְ הַגַּס וּלְאַהֲפָכָא חֲשׁוֹכָא שֶׁל הַגּוּף הַגַּס לִנְהוֹרָא, לִהְיוֹת כִּי זֶהוּ תַּכְלִית הַכַּוָּונָה בִּבְרִיאַת הָאָדָם וִירִידַת נִשְׁמָתוֹ לָעוֹלָם הַזֶּה.\nקִיצּוּר.\nכָּל הַגָּבוֹהַּ בְּיוֹתֵר יוֹרֵד לְמַטָּה בְּיוֹתֵר, הָאֶבֶן שֶׁהִיא בְּתַחְתִּית הַכּוֹתֶל כְּשֶׁנּוֹפֶלֶת הִיא סְמוּכָה לַכּוֹתֶל וַאֲשֶׁר בְּרֹאשׁ הַכּוֹתֶל בִּנְפִילָתָהּ הִיא בְּרִיחוּק מִן הַכּוֹתֶל. הַנְּטִיּוֹת הַגּוּפְנִיּוֹת שֶׁבָּאָדָם גְּרוּעִים מֵהַבַּעֲלֵי חַיִּים, וְהַנְּטִיּוֹת הַנַּפְשִׁיּוֹת נַעֲלוֹת מִבְּמַלְאֲכֵי הַשָּׁרֵת, וּבִיכָלְתּוֹ לְאַהֲפָכָא חֲשׁוֹכָא לִנְהוֹרָא."],[4401900069,"וְזֶהוּ מַעֲלַת עוֹלָם הַזֶּה הַגַּשְׁמִי לְגַבֵּי עוֹלָמוֹת הָעֶלְיוֹנִים הָרוּחָנִים, וּמַעֲלַת יְרִידַת הַנְּשָׁמָה בְּהִתְלַבְּשׁוּתָהּ בְּגוּף גַּשְׁמִי וְנֶפֶשׁ הַטִּבְעִי לְגַבֵּי מַעֲלַת עֲמִידָתָהּ בְּגַן עֵדֶן בְּתַכְלִית הַיִּחוּד וְהַבִּיטּוּל לֵאלֹקוּת, וּכְמוֹ שֶׁכָּתַב רַבֵּינוּ נִשְׁמָתוֹ עֵדֶן (סֵפֶר שֶׁל בֵּינוֹנִים פֶּרֶק ל\"ו) שֶׁתַּכְלִית בְּרִיאַת עוֹלָם הַזֶּה הוּא שֶׁנִּתְאַוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לִהְיוֹת לוֹ דִּירָה בַּתַּחְתּוֹנִים, דְּזֶהוּ עִנְיַן הִשְׁתַּלְשְׁלוּת הָעוֹלָמוֹת וִירִידָתָם מִמַּדְרֵיגָה לְמַדְרֵיגָה עַל יְדֵי רִיבּוּי לְבוּשִׁים הַמַּסְתִּירִים הָאוֹר וְהַחַיּוּת שֶׁמִּמֶּנּוּ יִתְבָּרֵךְ, עַד שֶׁנִּבְרָא עוֹלָם הַזֶּה הַגַּשְׁמִי וְהַחוּמְרִי מַמָּשׁ, וְהוּא הַתַּחְתּוֹן בְּמַדְרֵיגָה שֶׁאֵין תַּחְתּוֹן לְמַטָּה מִמֶּנּוּ בְּעִנְיַן הֶסְתֵּר אוֹרוֹ יִתְבָּרֵךְ וְחֹשֶׁךְ כָּפוּל וּמְכוּפָּל, עַד שֶׁהוּא מָלֵא קְלִיפּוֹת וְסִטְרָא אָחֳרָא שֶׁהֵן נֶגֶד ה' מַמָּשׁ לוֹמַר אֲנִי וְאַפְסִי עוֹד, וְהַיְינוּ דְּתַכְלִית כָּל הַהִשְׁתַּלְשְׁלוּת שֶׁל הָעוֹלָמוֹת הָרוּחָנִים הוּא בִּשְׁבִיל עוֹלָם הַזֶּה הַתַּחְתּוֹן, לְפִי שֶׁכַּךְ עָלָה בִרְצוֹנוֹ יִתְבָּרֵךְ לִהְיוֹת נַחַת רוּחַ לְפָנָיו יִתְבָּרֵךְ כַּד אִתְכַּפְיָא סִטְרָא אָחֳרָא וְאִתְהַפְּכָא חֲשׁוֹכָא לִנְהוֹרָא, וּבִשְׁבִיל זֶה נִיתַּן לְאָדָם הַכֹּחַ וְהָעוֹז שֶׁיּוּכַל לְהִתְגַּבֵּר גַּם עַל הַנֶּפֶשׁ הַבַּהֲמִית,\nוּכְלָלוּת עֲבוֹדָה זוֹ דְּבֵירוּר וְזִיכּוּךְ הַגּוּף וְנֶפֶשׁ הַבַּהֲמִית הוּא בְּדֶרֶךְ מִלְחָמָה, וְהָאָדָם צָרִיךְ לָדַעַת כִּי הַנֶּפֶשׁ הַבַּהֲמִית וְהַיֵּצֶר הָרָע הֵם שׂוֹנְאָיו הַיּוֹתֵר גְּדוֹלִים וַחֲפֵצִים בְּמִיתָתוֹ הָרוּחָנִית, וּבָאִים עָלָיו בְּעַרְמוּמִיּוּת לְפַתּוֹתוֹ בְּחֶלְקַת לְשׁוֹנָם וּבְחָכְמָה גְדוֹלָה מִתְנַכְּלִים אֵלָיו לְהַדִּיחוֹ מִדֶּרֶךְ הַחַיִּים הָאֲמִיתִּים בִּשְׁמִירַת הַתּוֹרָה וְהַמִּצְוֹת עַל יְדֵי כַּמָּה עִנְיְנֵי הֶיתֵּר לְמַלֹּאות תַּאֲוַת נַפְשׁוֹ, וּלְאַט לְאַט מַדִּיחִים אוֹתוֹ מִן הַהֶיתֵּר גָּמוּר אֶל הַהֶיתֵּר שֶׁל בְּדִיעֲבַד, עַד שֶׁמַּרְגִּילִים אוֹתוֹ בְּכַמָּה מִינֵי תַאֲווֹת, וּמְפַתְּחִים וּמַרְגִּילִים בּוֹ אֶת כֹּחַ הַמִּתְאַוֶּה מִבְּלִי שֶׁיּוּכַל לְהַעֲמִיד עַל עַצְמוֹ מִבְּלִי לְהַבִּיט אוֹ גַם לְהִסְתַּכֵּל בְּמַה שֶּׁאֵין צְרִיכִים לִרְאוֹת, וְהָעַיִן רוֹאָה וְהַלֵּב חוֹמֵד וְנֶחְלְשׁוּ כֹּחוֹתָיו הָרוּחָנִים לַעֲצוֹר בְּעַד הֲמוֹן רְצוֹנוֹתָיו הַגּוּפְנִים וְנוֹפֵל רַחֲמָנָא לִצְּלָן חָלָל בִּידֵי הַיֵּצֶר הָרָע וְהַנֶּפֶשׁ הַבַּהֲמִית.\n<b>וַאֲשֶׁר</b> עַל כֵּן הִנֵּה כְּלָלוּת הָעֲבוֹדָה בְּבֵירוּר וְזִיכּוּךְ הַגּוּף צְרִיכָה לִהְיוֹת בְּדֶרֶךְ מִלְחָמָה לְנַגֵּד לָהֶם, אֲשֶׁר בְּכָל דָּבָר וְעִנְיָן אֲשֶׁר הַיֵּצֶר הָרָע אוֹמֵר הֵן יֹאמַר הוּא לַאו לְעַצְמוֹ, וּבְכָל דָּבָר וְעִנְיָן אֲשֶׁר הַיֵּצֶר הָרָע אוֹמֵר לַאו יֹאמַר הוּא לְעַצְמוֹ הֵן, אֲשֶׁר בְּהַהִתְנַגְּדוּת הַכְּלָלִית הַלֵּזּוּ הוּא מוֹדִיעַ לְהַיֵּצֶר הָרָע שֶׁהוּא שׂוֹנְאוֹ וַאֲשֶׁר יִלְחוֹם עִמָּדוֹ,\nוְאַחַת מִטַּכְסִיסֵי הַמִּלְחָמָה הוּא הַשִּׂימַת לֵב עַל עִנְיָנִים קַלֵּי הָעֶרֶךְ, כִּי הַנִּצָחוֹן אֵינוֹ תָּלוּי בְּהַגְּבוּרָה דְּרִיבּוּי אֲנָשִׁים וְרִיבּוּי כְּלֵי זַיֵּין בִּלְבָד, אֶלָּא הָעִיקָּר הוּא הַהַמְצָאוֹת שִׂכְלִיּוֹת אֵיךְ לְהַטְעוֹת אֶת הַמְנַגֵּד וּלְהוֹלִיכוֹ שׁוֹלָל, וְלִפְעָמִים הִנֵּה בְּהַמְצָאָה שִׂכְלִית שֶׁל עַרְמוּמִיּוּת מְנַצְּחִים הַרְבֵּה יוֹתֵר מִבִּגְבוּרָה שֶׁל רִיבּוּי אֲנָשִׁים וְרִיבּוּי כְּלֵי זַיֵּין, וְכֵן הוּא בְּמִלְחָמָה הָרוּחָנִית, דְּהַתַּאֲווֹת וַעֲבֵירוֹת הֵם הַכְּלֵי זַיֵּין וְהַגְּבוּרָה שֶׁל הַיֵּצֶר הָרָע, וּשְׁטוּתֵי הַהִצְטַדְּקוּת מַה שֶּׁהָאָדָם מַצְדִּיק אֶת עַצְמוֹ הֵן הֵמָּה הַהַמְצָאָה שִׂכְלִית שֶׁל הַיֵּצֶר הָרָע וְהַנֶּפֶשׁ הַבַּהֲמִית בְּעַרְמוּמִיּוּת גְּדוֹלָה, לִלְכּוֹד חַס וְשָׁלוֹם בְּכֹחַ גַּם אֵלּוּ אֲשֶׁר בְּעִנְיְנֵי תַאֲוָה וַעֲבֵירָה אִי אֶפְשָׁר לְהַחֲטִיאָם,\nוַאֲשֶׁר עַל כֵּן הִנֵּה גַּם מִי שֶׁהוּא צַדִּיק גָּמוּר יָכוֹל לִמְצוֹא בְעַצְמוֹ שְׁטוּתִים כָּאֵלּוּ שֶׁעִם הֱיוֹת שֶׁהֵם דַּקִּים וְלֹא הֵבִיאוּ אוֹתוֹ לַעֲבוֹר עֲבֵירָה בְּפוֹעַל מַמָּשׁ חַס וְשָׁלוֹם, עִם כָּל זֶה הִנֵּה חֶסְרוֹנוֹת הַדַּקִּים גַּם כֵּן עוֹמְדִים בְּרוּמוֹ שֶׁל עוֹלָם וְגוֹרְמִים דְּבָרִים רָעִים מְאֹד, עַל דֶּרֶךְ מָשָׁל מִי שֶׁלּוֹמֵד תּוֹרָה הַרְבֵּה, הִנֵּה גַּם אִם לוֹמֵד לִשְׁמָהּ וּמִתְפַּלֵּל בְּכַוָּונַת הַלֵּב בְּטוּב טַעַם וָדַעַת וּבִדְבֵיקוּת נִפְלָאָה עַד שֶׁיָּבֹא לִבְחִינַת צִמָּאוֹן גָּדוֹל כָּל כַּךְ עַד שֶׁתִּגְעַל הַנֶּפֶשׁ אֶת הַבָּשָׂר, הִנֵּה כְּשֶׁמַּחֲזִיק טוֹבָה לְעַצְמוֹ וְכָל שֶׁכֵּן כְּשֶׁבָּא לִכְלַל גֵּיאוּת הִנֵּה גֵּיאוּת אָדָם תַּשְׁפִּילֶנּוּ כָּל כַּךְ עַד שֶׁנֶּאֱבָד כָּל הַטּוֹב שֶׁעָשָׂה.\nקִיצּוּר.\nהָאָדָם צָרִיךְ לָדַעַת כִּי הַנֶּפֶשׁ הַבַּהֲמִית וְהַיֵּצֶר הָרָע הֵם שׂוֹנְאָיו בְּנֶפֶשׁ, וְעוֹלָם הַזֶּה הַגַּשְׁמִי הוּא תַּכְלִית הַהִשְׁתַּלְשְׁלוּת, וַעֲבוֹדָתוֹ לַהֲפוֹךְ הַחֹשֶׁךְ לָאוֹר צְרִיכָה לִהְיוֹת בְּדֶרֶךְ מִלְחָמָה בְּשִׂימַת לֵב גַּם עַל דְּבָרִים קַלֵּי הָעֶרֶךְ, עֲבֵירָה תַּאֲוָה, וּשְׁטוּתֵי הַהִצְטַדְּקוּת קָשֶׁה מֵהֶם, כְּמוֹ הַגַּאֲוָה שֶׁמְּאַבֵּד גַּם הַמְעוּלֶּה בְּתוֹרָה וּמִצְוֹת."],[4401900070,"וְהִנֵּה מִי שֶׁלּוֹמֵד תּוֹרָה וְגַם עוֹסֵק בַּעֲבוֹדָה וּלְעֵת מִן הָעִתִּים הוּא תּוֹעֶה בִּדְרָכָיו וְהַנְהָגוֹתָיו לְהַצְדִּיק אֶת עַצְמוֹ בְּסִבַּת הַסְּבִיבָה וְהַזּוּלַת, הִנֵּה הוּא גָרוּעַ יוֹתֵר מֵאָדָם פָּשׁוּט שֶׁאֵינוֹ לוֹמֵד תּוֹרָה וְאֵין לוֹ שׁוּם מוּשָּׂג בְּעִנְיְנֵי עֲבוֹדָה, שֶׁהֲרֵי עַל הָאִישׁ הַפָּשׁוּט יֵשׁ לִימּוּד זְכוּת עַל כָּל פָּנִים, שֶׁהֲרֵי אֵינוֹ בַּעַל תּוֹרָה, וְגַם הוּא בְעַצְמוֹ לֹא קִלְקֵל אֶת עַצְמוֹ וּבַמֶּה יֹאבַד זְכוּתוֹ בְּמַה שֶּׁנּוֹלַד כַּךְ שֶׁכְּלֵי שִׂכְלוֹ אֵינָם מְקַבְּלִים שֵׂכֶל הַתּוֹרָה, וּמַה שֶּׁהוּא יָכוֹל הֲרֵי הוּא עוֹשֶׂה, אוּן דָאס ווָאס עֶר קֶען הֵן אִין דִּבּוּר אוּן הֵן אִין מַעֲשֶׂה טוּט עֶר, אוּן דֶער אוֹפֶן הָעֲשִׂיָּה שֶׁלּוֹ אִיז מִיט אַ פְּשִׁיטוּת אוּן תְּמִימוּת, שֶׁמִּתְפַּלֵּל עַל דֶּרֶךְ הַפָּשׁוּט עַל כָּל פָּנִים וְאוֹמֵר תְּהִלִּים הֲגַם שֶׁאֵינוֹ יוֹדֵעַ פֵּירוּשָׁם, וְשׁוֹמֵעַ לִימּוּד מִשְׁנָיוֹת וְעֵין יַעֲקֹב וּפִרְקֵי אָבוֹת, וּמַה לּוֹ לַעֲשׂוֹת שֶׁאֵין מוֹחוֹ תּוֹפֵס אֶת הַשִּׂכְלִים,\nוּבֶאֱמֶת הִנֵּה לְבַד מַעֲלַת הַתְּמִימוּת וְהַפַּשְׁטוּת שֶׁיֵּשׁ בַּאֲנָשִׁים פְּשׁוּטִים, שֶׁתְּפִלָּתָם וַאֲמִירַת הַתְּהִלִּים הֲגַם שֶׁאֵינָם יוֹדְעִים פֵּירוּשָׁם הוּא בִּתְמִימוּת וּפַשְׁטוּת הַבָּאָה מִצַּד הָאֱמוּנָה פְשׁוּטָה הַקְּבוּעָה בְּלֵב כָּל אֶחָד מִיִּשְׂרָאֵל בְּטֶבַע תּוֹלַדְתּוֹ, הִנֵּה מִצַּד מַעֲלַת הָעֲבוֹדָה בַּעֲבוֹדַת ה' הִנֵּה גַּם בָּזֶה גָּדְלָה עֲבוֹדָתָם שֶׁל אֲנָשִׁים הַפְּשׁוּטִים עַל עֲבוֹדָתָם שֶׁל לוֹמְדֵי תוֹרָה, וּבִפְרָט בַּעֲלֵי תוֹרָה וְעוֹסְקִים בַּעֲבוֹדָה שֶׁבְּלֵב, דְּהָאִישׁ הַפָּשׁוּט הִנֵּה מֵאַחַר שֶׁאֵינוֹ מֵבִין מַה שֶּׁהוּא אוֹמֵר בִּתְפִלָּתוֹ וּבְמִזְמוֹרֵי תְהִלִּים הֲרֵי זֶה אֶצְלוֹ בְּלִי שׁוּם הַנָּאָה כְּלָל, כִּי אִם כָּל זֶה אֶצְלוֹ בְּדֶרֶךְ קַבָּלַת עוֹל לְבָד, שֶׁהֲרֵי אֵינוֹ מֵבִין כְּלָל שֶׁיִּהְיֶה לוֹ תַּעֲנוּג מֵהֲבָנַת פֵּירוּשׁ הַמִּלּוֹת,\nוְאֵינוֹ דוֹמֶה כְּלָל לְבֶן תּוֹרָה הַיּוֹדֵעַ לֹא רַק פֵּירוּשׁ הַדִּבּוּרִים שֶׁהוּא מִתְפַּלֵּל וְשֶׁהוּא אוֹמֵר בְּמִזְמוֹרֵי תְהִלִּים, אֶלָּא שֶׁהוּא מִתְעַנֵּג עַל הֲבָנַת הַהַשְׂכָּלָה שֶׁבְּדִבּוּרֵי הַתְּפִלָּה וּמִזְמוֹרֵי תְהִלִּים, וּבִפְרָט הָעוֹסֵק בַּעֲבוֹדָה שֶׁבְּלֵב בִּתְפִלָּה בִּמְתִינוּת וּמִתְבּוֹנֵן בְּהָעִנְיָנִים בְּהַעֲמָקַת הַדַּעַת, הֲרֵי הוּא בָּא לִכְלַל דְּבֵקוּת בְּעִנְיְנֵי הַהַשְׂכָּלָה שֶׁהוּא מַשִּׂיג, דְּכַךְ הִיא הַמִּדָּה בְּבַעֲלֵי הַשָּׂגָה, דִּכְשֶׁמִּתְבּוֹנֵן בְּהַעֲמָקַת הַדַּעַת בְּהַשָּׂגָתוֹ אָז בָּא לִדְבֵקוּת נִפְלָאָה בְּתַעֲנוּג עָצוּם, וְחָכְמַת אָדָם תָּאִיר פָּנָיו, דְּרוּחוֹ טוֹבָה עָלָיו בִּמְאוֹד עַל גּוֹדֶל יְדִיעָתוֹ, וְתִפְאֶרֶת לוֹ מִבְּנֵי אָדָם שֶׁהַכֹּל מְשַׁבְּחִים אוֹתוֹ שֶׁהוּא בֶּן תּוֹרָה וּמַשְׂכִּיל בְּהַשָּׂגוֹת אֱלֹקוּת,\nמַה שֶּׁאֵין כֵּן אִישׁ הַפָּשׁוּט שֶׁאֵינוֹ יוֹדֵעַ גַּם פְּשׁוּטֵי פֵּירוּשׁ הַמִּלּוֹת, הִנֵּה לֹא זוֹ בִּלְבָד שֶׁאֵין לוֹ שׁוּם תַּעֲנוּג בָּזֶה, אֶלָּא אַדְרַבָּא מִצְטַעֵר בְּצַעַר גָּדוֹל מִזֶּה עַצְמוֹ שֶׁאֵינוֹ יוֹדֵעַ פֵּירוּשׁ הַמִּלּוֹת וְלִבּוֹ נִשְׁבָּר בְּקִרְבּוֹ מִגּוֹדֶל שִׁפְלוּתוֹ בְּעֵינֵי עַצְמוֹ, עֶר אִיז זֵייעֶר אַרָאפְּגֶעפַאלֶען בַּיי זִיךְ אוּן נִידֶערְשְׁלָאגֶען פוּן דֶעם ווָאס עֶר אִיז אַזוֹי אוּמְווִיסֶענְד, וּבוּשָׁה תְּכַסֶּה פָנָיו, וּבִפְרָט כַּאֲשֶׁר טוֹעֶה בְּאֵיזֶה תְפִלָּה אוֹ בְּאֵיזֶה פָּסוּק וּפִזְמוֹן שֶׁהוּא לְסִבַּת הֶעְדֵּר יְדִיעָתוֹ בְּפֵירוּשָׁם, וְנִמְצָאִים אֵלּוּ הַמְבַיְּישִׁים אוֹתוֹ, בְּכָל זֶה הִנֵּה מִתְאַמֵּץ לְהִתְפַּלֵּל וְלוֹמַר תְּהִלִּים בְּקוֹל וּבִנְעִימָה, דְּאֵין זֶה אֶלָּא מִפְּנֵי הַתְּמִימוּת וְיִרְאַת שָׁמַיִם שֶׁעוֹשֶׂה הַכֹּל בְּקַבָּלַת עוֹל מַלְכוּת שָׁמַיִם.\nקִיצּוּר.\nמַעֲלַת אוֹפֶן עֲבוֹדַת ה' שֶׁל אִישׁ פָּשׁוּט בְּדֶרֶךְ קַבָּלַת עוֹל, עַל עֲבוֹדָתוֹ שֶׁל בֶּן תּוֹרָה, וּבִפְרָט הָעוֹסֵק בַּעֲבוֹדָה שֶׁבְּלֵב, שֶׁיֵּשׁ לָהֶם תַּעֲנוּג מִידִיעוֹתֵיהֶם וּבָאִים לִידֵי דְבֵקוּת, וְהָאִישׁ הַפָּשׁוּט לְבַד שֶׁהוּא בְצַעַר עַל הֶעְדֵּר יְדִיעָתוֹ הִנֵּה הוּא מִתְבַּיֵּישׁ."],[4401900071,"וְהִנֵּה הַבֶּן תּוֹרָה שֶׁהוּא לוֹמֵד תּוֹרָה בְּעִיּוּן גָּדוֹל, לָדַעַת אֶת דְּבַר הַהֲלָכָה שֶׁהוּא לוֹמֵד בְּכָל פְּרָטֵי דִינֶיהָ דָּבָר דָּבָר עַל אוֹפַנּוֹ בְּטוּב טַעַם וָדַעַת בְּכַמָּה שִׁיטּוֹת הָרִאשׁוֹנִים וּמְחַדֵּשׁ חִידּוּשִׁים בִּסְבָרוֹת יְשָׁרוֹת, וְגַם הָעוֹסֵק בַּעֲבוֹדָה שֶׁבְּלֵב בַּאֲרִיכוּת הַהִתְבּוֹנְנוּת בְּעֵת הַתְּפִלָּה בְּהָעִנְיָנִים דִּפְנִימִיּוּת הַתּוֹרָה אֲשֶׁר לָמַד, וְהַיְינוּ שֶׁהָעִנְיָן נִרְגָּשׁ בִּפְנִימִיּוּתוֹ וּמוּנָּח אֶצְלוֹ בְּהַנָּחָה טוֹבָה, דֶער עִנְיָן ווֶערְט בַּיי אִיהם דֶערְהֶערְט אוּן לֵייגְט זִיךְ בַּיי אִיהם גוּט אָפּ, דִּבְהֶרְגֵּשׁ זֶה וּבְהַנָּחָה זוֹ נַעֲשָׂה דְּבֵקוּת הָעִנְיָן בְּמוֹחוֹ וְהוּא נִדְבָּק בְּהָעִנְיָן.\n<b>דְּהִנֵּה</b> אָנוּ רוֹאִים בְּחוּשׁ שֶׁיֵּשׁ שְׁנֵי אוֹפַנִּים בְּעִיּוּן הַמּוּשְׂכָּלוֹת, דְּיֵשׁ מִי שֶׁלּוֹמֵד אֵיזֶה סוּגְיָא, בֵּין בְּגַלְיָא שֶׁבַּתּוֹרָה בֵּין בִּפְנִימִיּוּת הַתּוֹרָה, וְלִימּוּדוֹ הוּא בְּעִיּוּן רַב, וְטֶבַע הָעִיּוּן הוּא טֶבַע הַדְּבֵקוּת, שֶׁבְּעֵת עִיּוּנוֹ הֲרֵי הוּא מִתְיַיחֵד וְדָבוּק עִם אוֹתָהּ הַהַשְׂכָּלָה שֶׁהוּא מְעַיֵּין בָּהּ, אֲבָל כָּל זֶה הוּא רַק בְּשָׁעָה שֶׁהוּא מְעַיֵּין בְּהָעִנְיָן, אֲבָל לְאַחַר שֶׁלָּמַד אֶת הָעִנְיָן וֶהֱבִינוֹ הֵיטֵב וּמְפַנֶּה דַעְתּוֹ לִלְמוֹד סוּגְיָא אַחֶרֶת, הִנֵּה נִשְׁכְּחָה מֵאִתּוֹ אוֹתָהּ הָעַמְקוּת שֶׁהָיְתָה לוֹ בְּשַׁעַת עִיּוּנוֹ,\nאֲבָל כַּאֲשֶׁר עִנְיַן הַשָּׂגָתוֹ הוּא בְּאוֹפֶן כָּזֶה שֶׁעוֹמֶק הָעִנְיָן הוּא אֶצְלוֹ בְּהַנָּחָה טוֹבָה, הִנֵּה הַדְּבֵקוּת הִיא בְּאוֹפֶן מוּשְׂכָּל רִאשׁוֹן, שֶׁהוּא תָּמִיד בְּאוֹפֶן בְּהִירִי, דְּזוֹהִי עֲבוֹדָה גְדוֹלָה בַּעֲבוֹדַת הַלֵּב בַּאֲרִיכוּת הַהִתְבּוֹנְנוּת בִּתְפִלָּה,\nהִנֵּה כַּאֲשֶׁר מַחֲזִיק טוֹבָה לְעַצְמוֹ בְּזֶה שֶׁבָּחַר לוֹ הָעֲבוֹדָה בִּשְׁקִידַת לִימּוּד הַתּוֹרָה וַאֲשֶׁר עוֹסֵק בַּעֲבוֹדָה שֶׁבְּלֵב וְכָל שֶׁכֵּן כְּשֶׁמִּתְיַיהֵר, הֲרֵי הוּא כּוֹרֶה שׁוּחָה לְעַצְמוֹ וְנוֹפֵל בָּהּ, וּכְמוֹ הַנּוֹפֵל בְּבוֹר שַׁחַת שֶׁנִּשְׁפָּל גּוּפוֹ מִשְּׁאָר הָאָדָם שֶׁעוֹמֵד אוֹ הוֹלֵךְ עַל פְּנֵי הָאֲדָמָה, כֵּן הַנּוֹפֵל בְּגַאֲוָה הֲרֵי הוּא נוֹפֵל בִּנְפִילָה עֲצוּמָה גְּרוּעָה הַרְבֵּה יוֹתֵר מֵאָדָם פָּשׁוּט, שֶׁהוּא רַחֲמָנָא לִצְּלָן חֲסַר דֵּיעָה, וְלֹא זוֹ בִּלְבָד שֶׁאֵין תּוֹרָתוֹ כְּלוּם, אֶלָּא שֶׁגַּם תְּפִלָּתוֹ בַּאֲרִיכוּת הַהִתְבּוֹנְנוּת אֵינָהּ בְּעֶרֶךְ מַעֲלַת אִישׁ הַפָּשׁוּט הַמִּתְפַּלֵּל וְאוֹמֵר מִזְמוֹרֵי תְהִלִּים בְּדֶרֶךְ קַבָּלַת עוֹל.\n<b>וְזֶהוּ</b> שֶׁאָמַר הַכָּתוּב (מִשְׁלֵי כט. כג) גַּאֲוַת אָדָם תַּשְׁפִּלֶנּוּ דְּהַגַּאֲוָה עוֹשֶׂה אֶת הָאָדָם לְשָׁפָל, וְחֵטְא הַגַּאֲוָה פּוֹגֵם בְּב' אוֹתִיּוֹת רִאשׁוֹנוֹת דְּשֵׁם הוי' י\"ה, כִּי גַּאֲוָה עוֹלֶה מִסְפָּרוֹ ט\"ו כְּמִסְפַּר י\"ה, שֶׁהַפְּגַם מַגִּיעַ לִבְחִינַת י\"ה, אֲשֶׁר מִזֶּה יוּבַן עִנְיַן נְפִילָתוֹ שֶׁלֹּא בְּעֶרֶךְ עֲבוֹדָתוֹ כְּלָל, שֶׁהֲרֵי עֲבוֹדָתוֹ הִיא עַל יְדֵי בְּחִינַת חָכְמָה וּבִינָה שֶׁבְּנַפְשׁוֹ שֶׁהֵם גַּם כֵּן נֶגֶד י\"ה, אָמְנָם זֶהוּ בְּחִינַת י\"ה שֶׁבְּנֶפֶשׁ הָאָדָם, וְהַפְּגַם שֶׁפּוֹגֵם עַל יְדֵי גַאֲוָה הֲרֵי הוּא פּוֹגֵם בִּבְחִינַת י\"ה שֶׁלְּמַעְלָה שֶׁאֵינוֹ בְּעֶרֶךְ כְּלָל לְגַבֵּי מוֹחִין שֶׁבָּאָדָם, שֶׁהֲרֵי כְּלָלוּת הַהִשְׁתַּלְשְׁלוּת לֹא נִבְרָא אֶלָּא מִבְּחִינַת ה' אַחֲרוֹנָה, וּבְיוּ\"ד נִבְרָא עוֹלָם הַבָּא שֶׁהוּא תַּשְׁלוּם שָׂכָר עַל עֲבוֹדָה נְקִיָּה, וְהוּא בִּשְׁאָט נַפְשׁוֹ שֶׁמִּתְיַיהֵר הֲרֵי הוּא פּוֹגֵם בְּי\"ה כו'.\n<b>וְהִנֵּה</b> גַּם אִם לֹא הִגִּיעַ לְמַדְרֵיגָה שְׁפֵילָה כָּזוֹ לִהְיוֹת מִתְיַיהֵר בְּפוֹעַל מַמָּשׁ, אֶלָּא שֶׁמַּחֲזִיק טוֹבָה לְעַצְמוֹ, הֲרֵי זֶה גַּם כֵּן גָּרוּעַ מְאֹד וּפָחוּת יוֹתֵר מֵהָאִישׁ הַפָּשׁוּט הַנַ\"ל, שֶׁמִּלְּבַד זֹאת דְּאִישׁ הַפָּשׁוּט הִנֵּה זֶה מַה שֶּׁמִּתְפַּלֵּל וְאוֹמֵר מִזְמוֹרֵי תְהִלִּים, הִנֵּה זֶהוּ כָּל כֹּחוֹ, דְּמֵאַחַר שֶׁאֵינוֹ מֵבִין הִנֵּה מַה יָּכוֹל לַעֲשׂוֹת עוֹד. הִנֵּה לְבַד זֹאת הֲרֵי גוּף וְעֶצֶם עֲבוֹדָתוֹ הוּא בְּדֶרֶךְ קַבָּלַת עוֹל, וְנוֹדָע כִּי הָעֲבוֹדָה דְקַבָּלַת עוֹל מַלְכוּת שָׁמַיִם הִיא עֲבוֹדָה נַעֲלֵית וּגְבוֹהָה בְּיוֹתֵר, דְּלָכֵן קָדְמָה שְׁמַע לִוְהָיָה אִם שָׁמֹעַ בִּכְדֵי שֶׁיְּקַבֵּל עוֹל מַלְכוּת שָׁמַיִם תְּחִלָּה שֶׁזֶּהוּ יְסוֹד וְשֹׁרֶשׁ הָעֲבוֹדָה, וּכְמוֹ שֶׁעַל הַיְסוֹד עוֹמֵד כָּל הַבִּנְיָן, כֵּן קַבָּלַת עוֹל מַלְכוּת שָׁמַיִם הוּא יְסוֹד לְכָל הָעֲבוֹדָה,\nוְזֶה שֶׁמַּחֲזִיק טוֹבָה לְעַצְמוֹ הִנֵּה מַרְאֶה שֶׁכָּל עֲבוֹדָתוֹ הוּא שֶׁעוֹבֵד אֶת עַצְמוֹ, וַהֲרֵי זֶה כְּמוֹ כָּל הַתַּעֲנוּגִים וְהַתַּאֲווֹת שֶׁעוֹשֶׂה גִּין עַצְמוֹ, כְּמוֹ בְּתַאֲווֹת אֲכִילָה וּשְׁתִיָּה וְשֵׁינָה שֶׁמֵּאַחַר שֶׁמַּחֲזִיק טוֹבָה לְעַצְמוֹ הֲרֵי מְהַפֵּךְ כָּל הָעֲבוֹדָה לְהַנָּאָתוֹ וּלְאַהֲבַת עַצְמוֹ, וּמִלְּבַד שֶׁלְּפִי זֶה הָעֲבוֹדָה אֵינָהּ עֲבוֹדָה כְּלָל, הֲרֵי הוּא פּוֹגֵם נַפְשׁוֹ וּמְלַכְלֵךְ אֶת עַצְמוֹ מְאֹד, וְהָרְבָב שֶׁעַל בֶּגֶד חָשׁוּב הֲרֵי הוּא גָּרוּעַ יוֹתֵר מֵעַל גַּבֵּי בֶּגֶד פָּשׁוּט, וְכֵן יוּבַן בַּנִּמְשָׁל שֶׁמַּה שֶּׁאֵצֶל הָאָדָם הַפָּשׁוּט אֵינוֹ נֶחְשָׁב כְּלָל לְחֵטְא וְעָוֹן, הִנֵּה לְגַבֵּי הַתַּלְמִיד חָכָם שֶׁלּוֹמֵד וּמִתְפַּלֵּל בִּדְבֵקוּת נֶחְשָׁב לְעָוֹן פְּלִילִי, וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (יְבָמוֹת קכט. ב) שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַקְדֵּק עִם סְבִיבָיו כְּחוּט הַשְּׂעָרָה, וּכְמוֹ שֶׁכָּתוּב (תְּהִלִּים נ. ג) וּסְבִיבָיו נִשְׂעֲרָה מְאֹד,\nוְגַם עַל פִּי הַשֵּׂכֶל הַפָּשׁוּט יוּבַן, שֶׁהֲרֵי אִישׁ הֲמוֹנִי יָכוֹל לַעֲשׂוֹת כַּמָּה דְבָרִים מֵחֲמַת הֶעְדֵּר יְדִיעָתוֹ וַהֲבָנָתוֹ, אֲבָל הַתַּלְמִיד חָכָם יוֹדֵעַ הֵיטֵב אֵיךְ לְהִזָּהֵר, וְעוֹנֶשׁ הַיּוֹדֵעַ לְגַבֵּי שֶׁאֵינוֹ יוֹדֵעַ מוּבָן לַכֹּל שֶׁגָּדוֹל יוֹתֵר הַרְבֵּה מְאֹד, וְגַם יֵשׁ דְּבָרִים שֶׁלְּגַבֵּי הַפָּשׁוּט אִם עָשָׂה כֵן אֵינוֹ מִתְחַלֵּל שֵׁם שָׁמַיִם עַל יָדוֹ מַה שֶׁאֵין כֵּן הַתַּלְמִיד חָכָם, וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (יוֹמָא פו, א) כְּגוֹן אֲנָא אִי שָׁקִילְנָא בִּשְׂרָא מִטַּבְּחָא כו' וְכֵן בִּדְבָרִים שֶׁבֵּין אָדָם לַמָּקוֹם, וְעַל זֶה כִּוְּונוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַקְדֵּק עִם סְבִיבָיו כו'.\nקִיצּוּר.\nהַלּוֹמֵד תּוֹרָה בְּעִיּוּן גָּדוֹל וְהָעוֹסֵק בַּעֲבוֹדָה שֶׁבְּלֵב בַּאֲרִיכוּת הַהִתְבּוֹנְנוּת בִּתְפִלָּה בְּהַשָּׂגָה אֱלֹקִית, עַד שֶׁהָעִנְיָן הוּנַּח אֶצְלוֹ בִּדְבֵקוּת בְּמוּשְׂכָּל רִאשׁוֹן, אִם מַחֲזִיק טוֹבָה לְעַצְמוֹ גָּרוּעַ מֵחֲסַר דֵּעָה, הַמִּתְגָּאֶה פּוֹגֵם בְּי\"ה, קַבָּלַת עוֹל מַלְכוּת שָׁמַיִם יְסוֹד הָעֲבוֹדָה."],[4401900072,"<h2>מַאֲמָר טז.</h2>\nוְהִנֵּה הַגּוֹרֵם אֶת הַיְרִידָה הַגְּדוֹלָה שֶׁל הַבֶּן תּוֹרָה וְהָעוֹסֵק בַּעֲבוֹדָה שֶׁבְּלֵב בְּזֶה שֶׁמִּתְגָּאֶה אוֹ אַף גַּם שֶׁמַּחֲזִיק טוֹבָה לְעַצְמוֹ הוּא הַשְּׁטוּת, כִּי כָּל עִנְיַן הַגֵּאוּת הוּא שְׁטוּת נִפְלָא וּכְמַאֲמָר כָּל גֵּיא שׁוֹטֶה, כִּי עַל מֶה וְלָמָּה יִתְגָּאֶה, אִם מִפְּנֵי הֲבָנַת הַשֵּׂכֶל הֲרֵי אֵין זֶה מִשֶּׁלּוֹ כְּלָל, וְזֶה נִכְלָל בִּכְלַל מַאֲמַר הַמִּשְׁנָה בְּמִילֵּי דְאָבוֹת (פֶּרֶק ג) תֶּן לוֹ מִשֶּׁלּוֹ שֶׁאַתָּה וְשֶׁלָּךְ שֶׁלּוֹ, וּכְמוֹ שֶׁאָנוּ אוֹמְרִים אַתָּה חוֹנֵן לְאָדָם דַּעַת, שֶׁזֶּה נִיתָּן מִלְמַעְלָה, וְאִם מִפְּנֵי הַתְמָדַת לִמּוּדוֹ יָכוֹל לִהְיוֹת שֶׁטִּבְעוֹ כַּךְ מִפְּנֵי טֶבַע הַמָּרָה שְׁחוֹרָה, וַאֲפִילוּ אִם זֶהוּ עַל יְדֵי עֲבוֹדָה הֲרֵי הוּא יִתְבָּרֵךְ הוּא הַנּוֹתֵן לְךָ כֹּחַ לַעֲשׂוֹת חָיִל, וְכֵן בַּעֲבוֹדָה שֶׁבְּלֵב בְּאַהֲבָה וּדְבֵקוּת הֲרֵי נוֹתְנִים לוֹ הַכֹּחַ עַל זֶה מִלְמַעְלָה, וְלָמָה הָאָדָם הַשְּׁפַל אִישִׁים יִתְגָּאֶה בְּדָבָר שֶׁאֵינוֹ שֶׁלּוֹ כְּלָל,\nוְזֶהוּ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (אָבוֹת פֶּרֶק ב) אִם לָמַדְתָּ תּוֹרָה הַרְבֵּה אַל תַּחֲזֵק טוֹבָה לְעַצְמָךְ, וַהֲגַם שֶׁשָּׁם אָמְרוּ כִּי לְכַךְ נוֹצָרְתָּ זֶהוּ טַעַם שֵׁנִי, וְהַיְינוּ כִּי טַעַם הָרִאשׁוֹן אֵינוֹ מַסְפִּיק כָּל כַּךְ, כִּי הָאָדָם הוּא בַּעַל בְּחִירָה וְעִם הֱיוֹת שֶׁנִּיתַּן לוֹ הַכֹּחַ לְהָבִין וּלְהַשְׂכִּיל וְלַעֲבוֹד אֶת ה' מִכָּל מָקוֹם יָכוֹל לִבְחוֹר שֶׁלֹּא יִלְמוֹד וְלֹא יִתְפַּלֵּל בְּכַוָּונַת הַלֵּב, וְלָזֶה אָמַר כִּי לְכַךְ נוֹצָרְתָּ שֶׁתְּחִלַּת יְצִירַת הָאָדָם הוּא בִּשְׁבִיל זֶה,\nוּכְמוֹ שֶׁכָּתוּב בְּרֵאשִׁית בָּרָא וְאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בִּשְׁבִיל הַתּוֹרָה שֶׁנִּקְרֵאת רֵאשִׁית וּבִשְׁבִיל יִשְׂרָאֵל שֶׁנִּקְרְאוּ רֵאשִׁית, וְהַיְינוּ שֶׁיִּתְעַלּוּ עַל יְדֵי הַתּוֹרָה שֶׁהִיא חָכְמָתוֹ וּרְצוֹנוֹ יִתְבָּרֵךְ,\nוְכִדְאִיתָא בְּזֹהַר תְּלַת קִשְׁרִין מִתְקַשְּׁרָאִין דָּא בְּדָא יִשְׂרָאֵל מִתְקַשְּׁרָאִין בְּאוֹרַיְיתָא וְאוֹרַיְיתָא בְּקוּדְשָׁא בְּרִיךְ הוּא, שֶׁעַל יְדֵי אֶמְצָעִיּוּת הַתּוֹרָה מִתְקַשְּׁרִין נִשְׁמוֹת יִשְׂרָאֵל לֵאלֹקוּת, וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (זֹהַר חֵלֶק ג יא. ב) עַל פָּסוּק עֲשָׂרָה עֲשָׂרָה הַכַּף שֶׁעֲשֶׂרֶת הַדִּבְּרוֹת מְכֻוָּונִים נֶגֶד עֲשָׂרָה מַאֲמָרוֹת\nוְאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (שַׁבָּת פח. א) שֶׁתְּנַאי הִתְנָה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית אִם יְקַיְּימוּ יִשְׂרָאֵל אֶת תּוֹרָתִי מוּטָב וּבְאִם לַאו יַחֲזוֹר אֶת הָעוֹלָם לְתֹהוּ וָבֹהוּ וְאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (שְׁמוֹת רַבָּה פַּרְשָׁה מ\"ח) עַל פָּסוּק אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם אֵלֶּה בִּזְכוּת מִי נִבְרְאוּ וּבִזְכוּת מִי עוֹמְדִין, בִּזְכוּת אֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל, וְאֵלֶּה בִּזְכוּת מִי הֵם עוֹמְדִין בִּזְכוּת אֵלֶּה הָעֵדוֹת וְהַחֻקִּים וְהַמִּשְׁפָּטִים,\nוְלָכֵן אָמְרוּ כִּי לְכַךְ נוֹצָרְתָּ, כִּי עִיקַּר בְּרִיאַת הָאָדָם הוּא בִּשְׁבִיל הַתּוֹרָה, וּכְמוֹ שֶׁכָּתוּב (קֹהֶלֶת יב. יג) סוֹף דָּבָר הַכֹּל נִשְׁמָע אֶת הָאֱלֹקִים יְרָא וְאֶת מִצְוֹתָיו שְׁמוֹר כִּי זֶה כָּל הָאָדָם, וְאִם כֵּן כְּשֶׁעוֹשֶׂה הַדָּבָר שֶׁבִּשְׁבִיל כַּךְ נִבְרָא אֵין לוֹ לְהַחֲזִיק טוֹבָה לְעַצְמוֹ, וּכְמוֹ כֵן בַּעֲבוֹדָתוֹ כְּשֶׁבָּא לִידֵי אַהֲבָה וּדְבֵקוּת אֵין לוֹ לְהַחֲזִיק טוֹבָה לְעַצְמוֹ, אַחֲרֵי שֶׁזֶּה תַּכְלִית בְּרִיאָתוֹ בָּעוֹלָם, שֶׁזֶּהוּ תַּכְלִיתוֹ שֶׁיִּתְעַלֶּה עַל יְדֵי הַתּוֹרָה וְהָעֲבוֹדָה כַּנַ\"ל וּכְמוֹ שֶׁנִּתְבָּאֵר (מַאֲמָר א פֶּרֶק ג-ד) בְּעִנְיַן תַּכְלִית כָּל בְּרִיאָה,\nוְאַדְרַבָּא מִזֶּה שֶׁמַּחֲזִיק טוֹבָה לְעַצְמוֹ שֶׁנִּיכָּר מִזֶּה שֶׁלֹּא פָעַל בַּעֲבוֹדָתוֹ לִהְיוֹת בִּבְחִינַת בִּיטּוּל, הֲרֵי לֹא הִגִּיעַ אֶל הַתַּכְלִית הַנִּרְצָה, צָרִיךְ לְהִתְמַרְמֵר בְּנַפְשׁוֹ עַל זֶה מֵאַחַר שֶׁלֹּא בָא לְתַכְלִית כַּוָּונַת בְּרִיאָתוֹ אִם כֵּן בִּשְׁבִיל מָה נִבְרָא בָּעוֹלָם וּמַה מַּעֲשֵׂהוּ,\nוּבִפְרָט אִם אֵינוֹ נִזְהָר בְּאֵיזֶה דְבָרִים, אֲפִילוּ דְּבָרִים קַלִּים שֶׁלְּפִי מַעֲלָתוֹ גְּדוֹלִים הֵמָּה כַּנַ\"ל (מַאֲמָר טו פֶּרֶק ה), וְכָל שֶׁכֵּן אִם יֵשׁ בָּהֶם חִלּוּל הַשֵּׁם חַס וְשָׁלוֹם הֲרֵי טוֹב לוֹ שֶׁלֹּא נִבְרָא, וְאִם לֹא הָיָה עוֹסֵק בַּתּוֹרָה וַעֲבוֹדָה הָיָה יוֹתֵר טוֹב שֶׁלֹּא הָיָה חִילּוּל הַשֵּׁם עַל כָּל פָּנִים, וְכָל זֶה הוּא מִפְּנֵי עֲבוֹדָתוֹ שֶׁאֵינָהּ אֲמִיתִּית, שֶׁאִם הָיְתָה אֲמִיתִּית אָז הָיָה פּוֹעֵל הַבִּיטּוּל בְּנַפְשׁוֹ שֶׁלֹּא הָיָה מַחֲזִיק טוֹבָה לְעַצְמוֹ כְּלָל וּכְלָל, וְכָל שֶׁכֵּן שֶׁהָיָה זָהִיר בְּכָל הַפְּרָטִים בְּתַכְלִית.\n<b>וְהִנֵּה</b> זֶהוּ כְּשֶׁהָרוּחַ שְׁטוּת מְסִיתוֹ שֶׁיִּתְגָּאֶה מִלִּימּוּדוֹ אוֹ יַחֲזִיק טוֹבָה לְעַצְמוֹ.\nקִיצּוּר.\nהַגֵּיאוּת הִיא שְׁטוּת, דְּהַהַשְׂכָּלָה וְהַהֲבָנָה בְּלִימּוּד הַתּוֹרָה וְהַכֹּחַ בַּעֲבוֹדַת ה' הוּא מֵאִתּוֹ יִתְבָּרֵךְ וּבִשְׁבִיל זֶה הָיְתָה בְּרִיאָתוֹ, וּבָזֶה שֶׁמַּחֲזִיק טוֹבָה לְעַצְמוֹ נִיכָּר שֶׁלֹּא הִגִּיעַ אֶל הַתַּכְלִית הָאֲמִיתִּי, וְהַמִּתְגָּאֶה מְחַלֵּל שֵׁם שָׁמַיִם."],[4401900073,"וְהִנֵּה זֶהוּ הַהֶפְרֵשׁ בֵּין שְׁטוּתֵי הַגַּאֲוָה שְׁטוּתֵי הַחֲזָקַת טוֹבָה לְעַצְמוֹ שְׁטוּתֵי הַהִצְטַדְּקוּת לִשְׁטוּתֵי עֲבֵירָה, דְּעִם הֱיוֹת אֲשֶׁר שְׁטוּתֵי הַגַּאֲוָה וְהַחֲזָקַת טוֹבָה וְהַהִצְטַדְּקוּת אֵינָם בָּעִנְיָנִים כָּאֵלּוּ כְּמוֹ שֶׁהוּא בְּעִנְיְנֵי עֲבֵירָה רַחֲמָנָא לִצְּלָן שֶׁהֵם בְּכַמָּה אִיסּוּרִים חֲמוּרִים, בְּכָל זֶה הִנֵּה שְׁטוּתֵי הַהִצְטַדְּקוּת הַחֲזָקַת הַטּוֹבָה וְהַגַּאֲוָה חֲמוּרִים הַרְבֵּה יוֹתֵר בָּזֶה שֶׁהֵם גּוֹרְמִים הֶזֵּיקוֹת יוֹתֵר גְּדוֹלִים מִשְּׁטוּתֵי הָעֲבֵירָה,\nדְּאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (סוֹטָה ג. א) אֵין אָדָם עוֹבֵר עֲבֵירָה אֶלָּא אִם כֵּן נִכְנַס בּוֹ רוּחַ שְׁטוּת, דִּשְׁטוּת הַלֵּזּוּ הִיא בְּכַמָּה אוֹפַנִּים שׁוֹנִים וּמְשׁוּנִּים לְפִי טִבְעֵי בְּנֵי אָדָם, אֲבָל יוֹדֵעַ הוּא שֶׁעָבַר עֲבֵירָה וְדָבָר זֶה נוֹגֵעַ לוֹ, עֶר ווֵייסְט אַז עֶר הָאט גֶעטָאן דָאס ווָאס מֶען טָאר נִיט אוּן דָאס פַארְדְרִיסְט אִיהם, דִּנְגִיעָה זוֹ מַה שֶּׁהַדָּבָר נוֹגֵעַ לוֹ הָוֵי תְּנוּעָה דִתְשׁוּבָה, וְעִם הֱיוֹת שֶׁעֲדַיִין אֵינָהּ תְּשׁוּבָה אֲמִיתִּית אֲבָל בְּכָל זֶה הֲרֵי הוּא מִתְחָרֵט עַל הֶעָבָר, וּבְהִתְעוֹרְרוּת רוּחַ מִמָּרוֹם, אוֹ בְּעֵת רָצוֹן כְּמוֹ בְּחֹדֶשׁ אֱלוּל יְמֵי הַסְּלִיחוֹת רֹאשׁ הַשָּׁנָה וַעֲשֶׂרֶת יְמֵי תְשׁוּבָה מִתְעוֹרֵר בִּתְשׁוּבָה,\nמַה שֶּׁאֵין כֵּן בִּשְׁטוּתֵי הַהִצְטַדְּקוּת, הִנֵּה לֹא זוֹ בִּלְבָד שֶׁאֵינוֹ מוֹדֶה בְּחֶטְאוֹ וּפִשְׁעוֹ, הִנֵּה עוֹד זֹאת שֶׁהוּא תּוֹלֶה בַּאֲחֵרִים כְּמוֹ בְּהַסְּבִיבָה אוֹ בְּזוּלָתוֹ, הֲרֵי לֹא זוֹ בִּלְבָד מַה שֶּׁאֵינוֹ גַם מְהַרְהֵר בְּעִנְיַן הַתְּשׁוּבָה, אֶלָּא עוֹד חוֹטֵא וּפוֹשֵׁעַ בְּהַאֲשִׁימוֹ אֶת זוּלָתוֹ וְהַסְּבִיבָה, דַּהֲרֵי גַּם בְּזֶה שֶׁהוּא בָחַר בִּסְבִיבָה כָּזוֹ וַחֲבֵרִים כָּאֵלּוּ הֲרֵי אַשְׁמָתוֹ וּפִשְׁעוֹ הִיא, וְאִם כֵּן חֲמוּרָה שְׁטוּת הַהִצְטַדְּקוּת מִשְּׁטוּת הָעֲבֵירָה,\nוּלְמַעְלָה מִשְּׁטוּת הַהִצְטַדְּקוּת הִיא שְׁטוּת הַחֲזָקַת טוֹבָה לְעַצְמוֹ, שֶׁהִיא עוֹד גְּרוּעָה מִשְּׁטוּת הַהִצְטַדְּקוּת בָּזֶה שֶׁעִנְיַן הַהִצְטַדְּקוּת הוּא רַק עַל סִיבַּת הַדָּבָר אֲבָל עֶצֶם הַדָּבָר הוּא גַם כֵּן יוֹדֵעַ דְּאֵינוֹ טוֹב וְצָרִיךְ תִּקּוּן, וְרַק מַצְדִּיק עַצְמוֹ דְּזֶה מַה שֶּׁהוּא לֹא טוֹב אֵינוֹ מִצַּד עַצְמוֹ כְּמוֹ בְּעוֹבֵר עֲבֵירָה אֶלָּא שֶׁזֶּה בְּסִבַּת הַזּוּלַת, אֲבָל בְּעֶצֶם הָעִנְיָן הוּא מוֹדֶה שֶׁהוּא לֹא טוֹב וְצָרִיךְ תִּקּוּן, אֲבָל בְּהַחֲזָקַת טוֹבָה לְעַצְמוֹ הֲרֵי הוּא חוֹשֵׁב שֶׁהוּא טוֹב בְּכָל עִנְיָנָיו, וְלֹא זוֹ בִּלְבָד שֶׁאֵינוֹ צָרִיךְ תִּקּוּן אֶלָּא עוֹד מַחֲזִיק טוֹבָה לְעַצְמוֹ,\nוּלְמַעְלָה מִזֶּה הַמִּתְגָּאֶה בְּתוֹרָתוֹ וּבַעֲבוֹדָתוֹ שֶׁהוּא גָרוּעַ מִן הַמַּחֲזִיק טוֹבָה לְעַצְמוֹ, דְּהַמַּחֲזִיק טוֹבָה לְעַצְמוֹ הוּא מַה שֶּׁלֹּא הִגִּיעַ אֶל הַתַּכְלִית הָאֲמִיתִּי הַיְינוּ תַּכְלִית בְּרִיאָתוֹ בָּעוֹלָם וְלֹא לְתַכְלִית כַּוָּונַת הָעֲבוֹדָה שֶׁהוּא עִנְיַן הַבִּיטּוּל, אֲבָל גַּאֲוָה הִיא עֲבֵירָה וּפוֹגֶמֶת בְּב' אוֹתִיּוֹת רִאשׁוֹנוֹת י\"ה דְּשֵׁם הוי' וְגוֹרֵם רָעָה לְעַצְמוֹ לְאַבֵּד כִּשְׁרוֹנוֹתָיו וְחוּשֵׁי נַפְשׁוֹ.\n<b>דְּהִנֵּה</b> כַּאֲשֶׁר כְּלֵי שִׂכְלוֹ רְחָבִים לְהָבִין דָּבָר מִתּוֹךְ דָּבָר, הָרוּחַ שְׁטוּת מְסִיתוֹ לָמָּה לְּךָ לְיַיגֵּעַ עַצְמְךָ וּלְהַטְרִיחַ כָּל כַּךְ אֶת שִׂכְלְךָ בְּעֵסֶק הַתּוֹרָה, הֲלֹא כְּלֵי שִׂכְלְךָ רְחָבִים וְכַמָּה שֶׁתַּעֲסוֹק מַסְפִּיק לְךָ, אֲשֶׁר בֶּאֱמֶת אֵינוֹ כֵן, שֶׁהֲרֵי לֹא יָגַעְתִּי וּמָצָאתִי אַל תַּאֲמִין (מְגִילָּה ו. ב), וּבִלְתִּי עֲבוֹדָה וִיגִיעָה אִי אֶפְשָׁר בְּשׁוּם אוֹפֶן בָּעוֹלָם שֶׁיַּשִּׂיג, וַאֲפִילוּ כְּלִי שִׂכְלוֹ רְחָבִים וְקַלִּים לְהָבִין מִכָּל מָקוֹם צָרִיךְ עֵסֶק וִיגִיעָה וְאֵינוֹ נַעֲשֶׂה חָכָם מֵאֵלָיו וּמִמֵּילָא, וְאִם כְּלֵי שִׂכְלוֹ בֶּאֱמֶת רְחָבִים וְקַלִּים אִם הָיָה עוֹסֵק הַרְבֵּה הָיָה בָא לְמַדְרֵיגָה הַיּוֹתֵר נַעֲלָה, מַה שֶּׁאֵין כֵּן כְּשֶׁאֵינוֹ עוֹסֵק אֶלָּא מִיעוּט זְמַן אֵינוֹ מַגִּיעַ גַּם כַּמָּה שֶׁשִּׂכְלוֹ מַגִּיעַ, וְכָל זֶה הוּא מֵחֲמַת הָרוּחַ שְׁטוּת שֶׁמְּכַסֶּה עַל הָאֱמֶת וְהִתְבָּרֵךְ בִּלְבָבוֹ שֶׁבִּמְעַט זְמַן וּבִמְעַט יְגִיעָה יַגִּיעַ מַה שֶּׁחֲבֵרוֹ יַגִּיעַ כְּשֶׁיַּעֲסוֹק זְמַן הַרְבֵּה, וְאִם כִּי לוּ יְהִי כִדְבָרָיו, לָמָּה יִשְׁכַּח שֶׁהוּא בִּזְמַן הַרְבֵּה הָיָה מַגִּיעַ יוֹתֵר וְיוֹתֵר, וּבֶאֱמֶת גַּם זֶה טָעוּת אֶצְלוֹ שֶׁהֲרֵי לֹא יָגַעְתִּי וּמָצָאתִי אַל תַּאֲמִין,\nוְכֵן יֵשׁ שְׁטוּתִים כָּאֵלּוּ שֶׁנִּדְמֶה שֶׁכָּבֵד לְפָנָיו מִפְּנֵי בְּרִיאוּת גּוּפוֹ וְכַדּוֹמֶה בִּפְרָטֵי הַחוּשִׁים שֶׁקָּשֶׁה עָלָיו לְיַיגֵּעַ הַמּוֹחַ אוֹ מֵחֲמַת הַבָּטַת הָעֵינַיִם, שֶׁכָּל זֶה הוּא שֶׁקֶר מוּחְלָט, שֶׁהֲרֵי חָשׁ בְּרֹאשׁוֹ יַעֲסוֹק בַּתּוֹרָה כו' חָשׁ בְּכָל גּוּפוֹ יַעֲסוֹק בַּתּוֹרָה (עֵירוּבִין נד. א) שֶׁנֶּאֱמַר וּלְכָל בְּשָׂרוֹ מַרְפֵּא (מִשְׁלֵי ד. כב), אִם כֵּן אֵין זֹאת כִּי אִם שֶׁהָרוּחַ שְׁטוּת מַנְהִיגוֹ בְּדֶרֶךְ לֹא טוֹבָה, עַד שֶׁעוֹשֶׂה הִיפּוּךְ הַשֵּׂכֶל לְגַמְרֵי, מִלְּבַד שֶׁזֶּהוּ הֵיפֶךְ רְצוֹן הַבּוֹרֵא שֶׁלְּכַךְ נוֹצָרְתָּ לַעֲסוֹק בַּתּוֹרָה וַעֲבוֹדָה וּלְהַגִּיעַ בְּעֶזְרָתוֹ יִתְבָּרֵךְ אֶל הַתַּכְלִית הָאֲמִיתִּית.\nקִיצּוּר.\nהַחוֹטֵא יוֹדֵעַ כִּי הוּא הָאָשֵׁם, בְּצַעֲרוֹ נִיכָּר חֲרָטָתוֹ וּמְהַרְהֵר בִּתְשׁוּבָה. הַמִּצְטַדֵּק אֵינוֹ מְהַרְהֵר בִּתְשׁוּבָה אֲבָל יוֹדֵעַ שֶׁצָּרִיךְ תִּיקּוּן. הַמַּחֲזִיק טוֹבָה לְעַצְמוֹ אֵינוֹ מַכִּיר בְּחֶסְרוֹנוֹ וַאֲשֶׁר צָרִיךְ תִּקּוּן. הַמִּתְגָּאֶה פּוֹגֵם בְּי\"ה וּמְאַבֵּד כִּשְׁרוֹנוֹתָיו."],[4401900074,"<h2>מַאֲמָר יז.</h2>\nוְהִנֵּה הַבַּעֲלֵי עֲסָקִים שֶׁעוֹסְקִים כָּל יְמֵיהֶם בְּעֵסֶק מַשָּׂא וּמַתָּן וְאֵינָם שַׁיָּיכִים לְעִנְיָנִים אֲחֵרִים, כְּמוֹ לְהִתְאַוּוֹת תַּאֲוָה וּלְהִתְעַנֵּג בְּתַעֲנוּגִים גַּשְׁמִים, אֲשֶׁר הָעֵסֶק בְּמַשָּׂא וּמַתָּן מִצַּד עַצְמוֹ הוּא הֶיתֵּר, וְיֵשׁ בּוֹ צוֹרֶךְ, וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בְּמִשְׁנָה (אָבוֹת פֶּרֶק ב) יָפֶה תַּלְמוּד תּוֹרָה עִם דֶּרֶךְ אֶרֶץ כו', אָמְנָם יֵשׁ בָּזֶה כַּמָּה שְׁטוּתִים מִצַּד הַיֵּצֶר הַמַּעֲבִירִים אֶת הָאָדָם עַל דַּעְתּוֹ וְעַל דַּעַת קוֹנוֹ, וְהַיְינוּ עִנְיַן רִיבּוּי הַטִּרְדָא בְּעֵסֶק, שֶׁמּוּטְרָד בָּזֶה יוֹמָם וָלַיְלָה עַד שֶׁמּוֹנֵעַ אוֹתוֹ מִלִּימּוּד הַתּוֹרָה וּמִלְּהִתְפַּלֵּל בְּצִבּוּר וּלְכַוֵּין פֵּירוּשׁ הַמִּלּוֹת עַל פִּי פָּשׁוּט עַל כָּל פָּנִים, מִפְּנֵי שֶׁמְּדַמֶּה בְנַפְשׁוֹ שֶׁעַל יְדֵי זֶה שֶׁיִּתְעַכֵּב בִּתְפִלָּה לִשְׁמוֹעַ בְּאָזְנָיו מַה שֶּׁהוּא מוֹצִיא בְּפִיו בְּכַוָּונָה פְשׁוּטָה כַּנַ\"ל וּלְהִתְפַּלֵּל בְּצִבּוּר וּלְהִתְעַכֵּב זְמַן בְּלִימּוּד הַתּוֹרָה עַל יְדֵי זֶה יַפְסִיד שֶׁלֹּא יִקְנֶה וְיִמְכּוֹר בָּעֵת הַהִיא, וּבֶאֱמֶת זוֹהִי שְׁטוּת נִפְלָא,\nדְּכַאֲשֶׁר הָאָדָם יָשִׂים לִבּוֹ וְדַעְתּוֹ לִרְאוֹת אֶת הַנַּעֲשֶׂה אִתּוֹ וּבִכְלָלוּת הָעוֹלָם, הֲלֹא יִרְאֶה לָעֵינַיִם אֲשֶׁר כַּמָּה פְעָמִים יֵלֵךְ בְּדַרְכֵי הַמִּסְחָר וְיִשְׁמוֹר הַדְּבָרִים בְּעִתָּם וּבִזְמַנָּם וְיִתְעַסֵּק הַרְבֵּה וְלֹא יַרְוִיחַ מְאוּמָה אוֹ גַם יַפְסִיד, וּבִמְעַט זְמַן וּבְמִיעוּט עֵסֶק יַרְוִיחַ, וְאִם כֵּן מִי יֹאמַר אֲשֶׁר בְּהָעַכָּבָה יַפְסִיד אוּלַי יוֹתֵר טוֹב לְפָנָיו שֶׁלֹּא יַרְבֶּה בְּהִתְעַסְּקוּת וּבְעֶזְרַת הַשֵּׁם יִתְבָּרֵךְ יַרְוִיחַ בִּמְעַט זְמַן, וְכַאֲשֶׁר עוֹד יִתְבָּאֵר לְקַמָּן.\n<b>וּבִפְרָט</b> אִם לֹא הָיָה שׁוֹכֵחַ עַל ה' אֲשֶׁר הוּא הַנּוֹתֵן לוֹ כֹּחַ לַעֲשׂוֹת חַיִל וּבִרְכַּת ה' דַּוְקָא הִיא תַעֲשִׁיר, וְעֶצֶם הָעֵסֶק הוּא רַק בְּדֶרֶךְ עֲשִׂיַּית כְּלִי בְּמַה שֶּׁתִּשְׁרֶה הַבְּרָכָה, אֲבָל הָעִיקָּר הוּא בִּרְכַּת ה', אִם כֵּן הֲלֹא צָרִיךְ לִהְיוֹת מָסוּר לַה' (דַארְף עֶר דָאךְ זַיְין אִיבֶּערְגֶעגֶעבֶּען דֶער עִיקָּר צוּ אֱלֹקוּת) שֶׁהוּא הַזָּן וּמְפַרְנֵס אוֹתוֹ, וְרַק צְרִיכִים כְּלִי לָזֶה וְהוּא הָעֵסֶק, אֲבָל דַּי בְּמִיעוּט הִתְעַסְּקוּת גַּם כֵּן.\n<b>וְהָעִנְיָן</b> הוּא דְּהִנֵּה כְּתִיב (דְּבָרִים טו. ח) וּבֵרַכְךָ ה' אֱלֹקֶיךָ בְּכֹל אֲשֶׁר תַּעֲשֶׂה, וְצָרִיךְ לְהָבִין לָמָּה צְרִיכִים הָעֲשִׂיָּה וְהָעֵסֶק כְּלָל מֵאַחַר שֶׁהַבְּרָכָה מֵאֵת ה' תָּבֹא אִם כֵּן גַּם בְּלִי עֵסֶק וְהִשְׁתַּדְּלוּת כְּלָל תָּבֹא בִּרְכַּת ה', וּמִמַּה שֶּׁאוֹמֵר בְּכֹל אֲשֶׁר תַּעֲשֶׂה מַשְׁמָע שֶׁצָּרִיךְ לִהְיוֹת עֲשִׂיָּה וְעֵסֶק, וּבְיוֹתֵר אֵינוֹ מוּבָן לְפִי מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (בֵּיצָה טז. א) כָּל מְזוֹנוֹתָיו שֶׁל אָדָם קְצוּבִים לוֹ מֵרֹאשׁ הַשָּׁנָה עַד יוֹם הַכִּפּוּרִים, וְאִם כֵּן מַהוּ הַצּוֹרֶךְ לַעֲסוֹק בְּאֵיזֶה מַשָּׂא וּמַתָּן אוֹ אוּמָּנוּת שֶׁעַל יְדֵי זֶה יִתְפַּרְנֵס, הֲלֹא וַדַּאי מַה שֶּׁנִּקְצְבָה לוֹ פַּרְנָסָה בְּחֶסֶד עֶלְיוֹן יוּמְשַׁךְ לוֹ וְלָמָּה צָרִיךְ עֵסֶק וְהִשְׁתַּדְּלוּת בָּזֶה, גַּם צָרִיךְ לְהָבִין מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (רֹאשׁ הַשָּׁנָה טז. א) אָדָם נִידּוֹן בְּכָל יוֹם וְאֵיךְ יִתַּוֵּוךְ זֶה עִם מַאֲמָר הַנַ\"ל דִּמְזוֹנוֹתָיו קְצוּבִים לוֹ מֵרֹאשׁ הַשָּׁנָה כו', דְּוַדַּאי גַּם רַבִּי יוֹסֵי שֶׁאוֹמֵר דְּאָדָם נִידּוֹן בְּכָל יוֹם מוֹדֶה דְּהַדִּין וּמִשְׁפָּט הוּא בְּרֹאשׁ הַשָּׁנָה וְאָז נִקְצָב לוֹ כָּל הִצְטָרְכוּתוֹ בְּבָנֵי חַיֵּי וּמְזוֹנֵי, וְאִם כֵּן מַהוּ עִנְיַן הַדִּין וּמִשְׁפָּט שֶׁבְּכָל יוֹם.\n<b>וְגַם</b> צָרִיךְ לְהָבִין מַה שֶּׁאָנוּ מְבַקְשִׁים בְּכָל יוֹם בִּשְׁמוֹנֶה עֶשְׂרֵה עַל פַּרְנָסָה וּרְפוּאָה וכו' הֲלֹא כָּל זֶה נִקְצַב מֵרֹאשׁ הַשָּׁנָה כו'. וּבְזֹהַר (חֵלֶק ב סב. ב) אִיתָא דְּרַב יֵיבָא סָבָא הָיָה מִתְפַּלֵּל בְּכָל יוֹם קוֹדֶם הָאֲכִילָה עַל מְזוֹנוֹ שֶׁיִּנָּתֵן לוֹ, גַּם אַף שֶׁהָיָה מְזוֹנוֹ כְּבָר מוּכָן לְפָנָיו. דְּאַף עַל גַּב דַּהֲוָה לֵיהּ לְמֵיכְלָא לָא הֲוִי מְתַקֵּן לֵיהּ עַד דְּשָׁאִיל לֵיהּ מִבֵּי מַלְכָּא בִּצְלוֹתָא, וְצָרִיךְ לְהָבִין מַהוּ עִנְיַן תְּפִלָּה זוֹ.\nקִיצּוּר.\nשְׁטוּתֵי בַּעֲלֵי הָעֲסָקִים שֶׁאֵינָם קוֹבְעִים עִתִּים לַתּוֹרָה וּמֵהֶם שֶׁבִּלְתִּי מִתְפַּלְלִים בְּצִבּוּר, שׁוֹכְחִים עַל הָעִיקָּר דְּבִרְכַּת ה' הִיא תַעֲשִׁיר, סְתִירַת הַמַּאֲמָרִים דִּמְזוֹנוֹת קְצוּבִים מֵרֹאשׁ הַשָּׁנָה וְאָדָם נִידּוֹן בְּכָל יוֹם."]]});
